		}
		buProfileCalc.varProfileRunSettings.activeOPIndex = 0;
		clsFiles.OpenMachineConfig(AppPath.MachineSimConfig + "\\Machine.bumachdef", ref ccVars.SimMachine);
		if (viewportSimilasyon == null)
		{
			EyeCreateProps eyeCreateProps2 = new EyeCreateProps();
			eyeCreateProps2.ShowToolBar = false;
			eyeCreateProps2.ShowViewCube = false;
			eyeCreateProps2.ShowCoordinateArrow = false;
