			viewportSimilasyon.ProgressBar.Visible = false;
			viewportSimilasyon.WaitCursorMode = waitCursorType.Never;
		}
		if (viewportCommon == null)
		{
			CreateModelProperties createModelProperties = new CreateModelProperties();
			createModelProperties.CoordinateSystemIconVisible = false;
			createModelProperties.OriginSymbolVisible = true;
			createModelProperties.ViewCubeIconVisible = true;
			createModelProperties.OrigineCaptionVisible = false;
			createModelProperties.ToolBorVisible = false;
			createModelProperties.BottomColor = Color.LightGray;
			createModelProperties.MiddleColor = Color.WhiteSmoke;
			createModelProperties.TopColor = Color.LightGray;
			createModelProperties.PanMouseButtons.Button = mouseButtonsZPR.Middle;
			createModelProperties.PanMouseButtons.ModifierKey = devDept.Eyeshot.Control.modifierKeys.None;
			createModelProperties.RotateMouseButtons.Button = mouseButtonsZPR.Middle;
			createModelProperties.RotateMouseButtons.ModifierKey = devDept.Eyeshot.Control.modifierKeys.Ctrl;
			createModelProperties.ZoomMouseButtons.Button = mouseButtonsZPR.Middle;
			createModelProperties.ZoomMouseButtons.ModifierKey = devDept.Eyeshot.Control.modifierKeys.Shift;
			clsInit.cVector5.CreateModelControl(ref viewportCommon, clsVar.UnlockKey, createModelProperties);
			new EyeCreateProps();
			viewportCommon.Dock = DockStyle.Fill;
			viewportCommon.ProgressBar.Visible = false;
			viewportCommon.WaitCursorMode = waitCursorType.Never;
		}
		if (viewportBottom == null)
		{
			CreateModelProperties createModelProperties2 = new CreateModelProperties();
			createModelProperties2.CoordinateSystemIconVisible = false;
			createModelProperties2.OriginSymbolVisible = false;
			createModelProperties2.ViewCubeIconVisible = false;
			createModelProperties2.OrigineCaptionVisible = false;
			createModelProperties2.ToolBorVisible = false;
			createModelProperties2.BottomColor = Color.LightGray;
			createModelProperties2.MiddleColor = Color.WhiteSmoke;
			createModelProperties2.TopColor = Color.LightGray;
			createModelProperties2.PanMouseButtons.Button = mouseButtonsZPR.Middle;
			createModelProperties2.PanMouseButtons.ModifierKey = devDept.Eyeshot.Control.modifierKeys.None;
			createModelProperties2.RotateMouseButtons.Button = mouseButtonsZPR.Middle;
			createModelProperties2.RotateMouseButtons.ModifierKey = devDept.Eyeshot.Control.modifierKeys.Ctrl;
			createModelProperties2.ZoomMouseButtons.Button = mouseButtonsZPR.Middle;
			createModelProperties2.ZoomMouseButtons.ModifierKey = devDept.Eyeshot.Control.modifierKeys.Shift;
			createModelProperties2.DisplayType = displayType.Flat;
			createModelProperties2.ProjetionType = projectionType.Orthographic;
			clsInit.cVector5.CreateModelControl(ref viewportBottom, clsVar.UnlockKey, createModelProperties2);
		}
		for (int i = 0; i <= viewportSimilasyon.Layers.Count - 1; i++)
		{
			viewportSimilasyon.Layers[i].Visible = true;
		}
		viewportSimilasyon.Layers.Add(new Layer("Profile", Color.Gray));
		viewportSimilasyon.Layers.Add(new Layer("Operation", Color.Cyan));
		viewportSimilasyon.Layers.Add(new Layer("Cam", Color.Red));
		viewportSimilasyon.Layers.Add(new Layer("SupportBlock", Color.Lime));
		viewportSimilasyon.Layers.Add(new Layer("Drawing", Color.Black));
		viewportSimilasyon.Layers.Add(new Layer("Machine", Color.DarkOrange));
		viewportSimilasyon.Layers.Add(new Layer("Clamper", Color.Blue));
		viewportCommon.Layers.Add(new Layer("Profile", Color.Gray));
		viewportCommon.Layers.Add(new Layer("Operation", Color.Cyan));
		viewportCommon.Layers.Add(new Layer("Cam", Color.Red));
		viewportCommon.Layers.Add(new Layer("SupportBlock", Color.Lime));
		viewportCommon.Layers.Add(new Layer("Drawing", Color.Black));
		viewportCommon.Layers.Add(new Layer("Machine", Color.DarkOrange));
		viewportCommon.Layers.Add(new Layer("Clamper", Color.Blue));
		viewportSimilasyon.TempEntities.Clear();
		viewportSimilasyon.ActiveViewport.DisplayMode = displayType.Flat;
		if (viewportSimilasyon.Blocks.Count > 1)
		{
			for (int num = viewportSimilasyon.Blocks.Count - 1; num >= 1; num--)
			{
				viewportSimilasyon.Blocks.RemoveAt(num);
			}
		}
		List<Entity> ClamperEntities = new List<Entity>();
		List<Entity> list = new List<Entity>();
		if (ccVars.SimMachine == null)
		{
			ccVars.SimMachine = new MachineDef();
		}
		if (ccVars.SimMachine != null)
		{
			if (ccVars.SimMachine.Clampers.Count <= 0)
			{
				ClamperData3D clamperData3D = new ClamperData3D();
				clamperData3D.Width = buProfileCalc.varProfileClamperSettings.ClamperWidth;
				clsInit.cProfile.Clamper3D(0.0, 1, activeProfile.FirstItem.Width, activeProfile.FirstItem.Height, clamperData3D, ref ClamperEntities);
			}
			else
			{
				for (int j = 0; j <= ccVars.SimMachine.Clampers.Count - 1; j++)
				{
					for (int k = 0; k <= ccVars.SimMachine.Clampers[j].Entities.Count - 1; k++)
					{
						Entity entity = buVector5.CopyEntities(ccVars.SimMachine.Clampers[j].Entities[k]);
						CustomData customData = new CustomData();
						customData.typeDefination = entityTypeDefination.Clamper;
						entity.EntityData = customData;
						if (clsVar.varRuntime.MetricUnit == 1)
						{
							entity.Scale(buSystem.MmToInchRatio);
						}
						entity.Regen(new RegenParams(buSystem.RegenDeviation, viewportSimilasyon));
						ClamperEntities.Add(entity);
					}
				}
			}
			if (ClamperEntities.Count > 0)
			{
				for (int l = 0; l <= ClamperEntities.Count - 1; l++)
				{
					string text = "Clamper";
					if (l > 0)
					{
						text += l;
					}
					if ((ccVars.SimMachine.Clampers.Count > 0) & (l <= ccVars.SimMachine.Clampers.Count - 1))
					{
						text = ccVars.SimMachine.Clampers[l].PartName;
					}
					Block block = new Block(text);
					Entity entity2 = buVector5.CopyEntities(ClamperEntities[l]);
					entity2.Color = Color.DarkOrange;
					if (l <= ccVars.SimMachine.Clampers.Count - 1)
					{
						entity2.Color = ccVars.SimMachine.Clampers[l].Color;
					}
					entity2.ColorMethod = colorMethodType.byEntity;
					entity2.Regen(0.1);
					block.Entities.Add(entity2);
					viewportSimilasyon.Blocks.Add(block);
					if ((ccVars.SimMachine.Clampers.Count > 0) & (l <= ccVars.SimMachine.Clampers.Count - 1))
					{
						text = ccVars.SimMachine.Clampers[l].PartName + "Ghost";
					}
					block = new Block(text);
					entity2 = buVector5.CopyEntities(ClamperEntities[l]);
					entity2.Color = Color.FromArgb(buProfileCalc.varProfileSettings.GhostClamperTransparency, buProfileCalc.varProfileSettings.GhostClamperColor);
					entity2.ColorMethod = colorMethodType.byEntity;
					block.Entities.Add(entity2);
					viewportSimilasyon.Blocks.Add(block);
					if ((ccVars.SimMachine.Clampers.Count > 0) & (l <= ccVars.SimMachine.Clampers.Count - 1))
					{
						text = ccVars.SimMachine.Clampers[l].PartName + "Collision";
					}
					block = new Block(text);
					entity2 = buVector5.CopyEntities(ClamperEntities[l]);
					entity2.Color = Color.FromArgb(200, Color.Red);
					entity2.ColorMethod = colorMethodType.byEntity;
					entity2.Regen(0.1);
					block.Entities.Add(entity2);
					viewportSimilasyon.Blocks.Add(block);
				}
			}
			if (ccVars.SimMachine.MachineParts.Count > 0)
			{
				for (int m = 0; m <= ccVars.SimMachine.MachineParts.Count - 1; m++)
				{
					for (int n = 0; n <= ccVars.SimMachine.MachineParts[m].Entities.Count - 1; n++)
					{
						Entity entity3 = buVector5.CopyEntities(ccVars.SimMachine.MachineParts[m].Entities[n]);
						CustomData customData2 = new CustomData();
						customData2.typeDefination = entityTypeDefination.MachineParts;
						customData2.EntityName = ccVars.SimMachine.MachineParts[m].PartName;
						entity3.EntityData = customData2;
						if (clsVar.varRuntime.MetricUnit == 1)
						{
							entity3.Scale(buSystem.MmToInchRatio);
						}
						entity3.Regen(new RegenParams(buSystem.RegenDeviation, viewportSimilasyon));
						list.Add(entity3);
					}
				}
			}
			if (list.Count > 0)
			{
				for (int num2 = 0; num2 <= list.Count - 1; num2++)
				{
					string text2 = ((CustomData)list[num2].EntityData).EntityName;
					if (text2.Length == 0)
					{
						text2 = "Block" + num2;
					}
					Block block2 = new Block(text2);
					Entity entity4 = buVector5.CopyEntities(list[num2]);
					entity4.Color = Color.Linen;
					entity4.Regen(0.1);
					if (num2 <= ccVars.SimMachine.MachineParts.Count - 1)
					{
						int alpha = 255;
						if ((ccVars.SimMachine.MachineParts[num2].Transparency >= 0) & (ccVars.SimMachine.MachineParts[num2].Transparency <= 255))
						{
							alpha = ccVars.SimMachine.MachineParts[num2].Transparency;
						}
						entity4.Color = Color.FromArgb(alpha, ccVars.SimMachine.MachineParts[num2].Color);
					}
					entity4.ColorMethod = colorMethodType.byEntity;
					block2.Entities.Add(entity4);
					block2.Entities.Regen();
					viewportSimilasyon.Blocks.Add(block2);
				}
			}
		}
		viewportSimilasyon.WorkCompleted += viewportSimilasyon_WorkCompleted;
		viewportSimilasyon.WorkCancelled += viewportSimilasyon_WorkCancelled;
		viewportSimilasyon.WorkFailed += viewportSimilasyon_WorkFailed;
		viewportSimilasyon.MouseDown += viewportSimilasyon_MouseDown;
