		viewportSimilasyon.TextStyles.Add(item);
		viewportCommon.TextStyles.Add(item);
		frmSim.pnl_viewport.Controls.Add(viewportSimilasyon);
		timSim.Tick += Sim_Tick;
		timSim.Interval = 20;
