	public void Init_Tick(object sender, EventArgs e)
	{
		AppPath.Help = AppPath.Help ?? "";
		AppPath.HelpImages += "\\Profile";
		timInit.Enabled = false;
		SetLenguages();
		threadProfile = new Thread(ThreadCalculationLoop);
		threadProfile.Start();
	}

	public void ProfileTreeUpdate()
	{
		if (!clsItem.FrmProfileJob.chk_selectmode.Checked)
		{
			clsItem.FrmProfileJob.mnu_remove.Text = buLangTranslate.preDef.Operation + " " + buLangTranslate.preDef.Delete;
		}
		else
		{
			clsItem.FrmProfileJob.mnu_remove.Text = buLangTranslate.preDef.Selected + " " + buLangTranslate.preDef.Operation + " " + buLangTranslate.preDef.Delete;
		}
