	public void ProfileErrorWarningAdd()
	{
		buString5.GetFontFromName(buProfileCalc.varProfileVisualSettings.TreeMessageFontName, buProfileCalc.varProfileVisualSettings.TreeOPFontSize + 1.0, Bold: true);
		Font fontFromName = buString5.GetFontFromName(buProfileCalc.varProfileVisualSettings.TreeMessageFontName, buProfileCalc.varProfileVisualSettings.TreeOPFontSize + 2.0, Bold: true);
		buString5.GetFontFromName(buProfileCalc.varProfileVisualSettings.TreeMessageFontName, buProfileCalc.varProfileVisualSettings.TreeOPFontSize + 1.0, Bold: true);
		double factor = 0.8;
		if (activeProfile.FirstItem == null || clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes.Count <= 0)
		{
			return;
		}
		TreeNodeSettings treeNodeSettings = clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0] as TreeNodeSettings;
		bool flag = false;
		if (treeNodeSettings.Nodes != null && treeNodeSettings.Nodes.Count > 0)
		{
			for (int i = 0; i <= treeNodeSettings.Nodes.Count - 1; i++)
			{
				TreeNodeSettings treeNodeSettings2 = treeNodeSettings.Nodes[i] as TreeNodeSettings;
				if (!(treeNodeSettings2.Command == "warning"))
				{
				}
				if (treeNodeSettings2.Command == "error")
				{
					flag = true;
					treeNodeSettings2.Nodes.Clear();
					for (int j = 0; j <= activeProfile.FirstItem.errorAllList.Count - 1; j++)
					{
						TreeNodeSettings node = new TreeNodeSettings(activeProfile.FirstItem.errorAllList[j])
						{
							ImageIndex = 38,
							SelectedImageIndex = 38,
							Tag = "0",
							ClassIndex = 0,
							ClassSubIndex = -1,
							ClassSubSubIndex = -1,
							Command = "error",
							Name = activeProfile.FirstItem.errorAllList[j],
							Info = "",
							ForeColor = buImage5.ColorToneChange(buProfileCalc.varProfileVisualSettings.TreeOPErrorColor, factor),
							NodeFont = fontFromName,
							Index = -1,
							Checked = false,
							OldImageIndex = 38
						};
						treeNodeSettings2.Nodes.Add(node);
					}
				}
			}
		}
		if (!flag & (activeProfile.FirstItem.errorAllList.Count > 0))
		{
			TreeNode treeNode = new TreeNodeSettings(buLangTranslate.preDef.Error)
			{
				ImageIndex = 38,
				SelectedImageIndex = 38,
				Tag = "0",
				ClassIndex = 0,
				ClassSubIndex = -1,
				ClassSubSubIndex = -1,
				Command = "error",
				Name = buLangTranslate.preDef.Error,
				Info = "",
				ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPErrorColor,
				NodeFont = fontFromName,
				Index = -1,
				Checked = false,
				OldImageIndex = 38
			};
			treeNodeSettings.Nodes.Add(treeNode);
			for (int k = 0; k <= activeProfile.FirstItem.errorAllList.Count - 1; k++)
			{
				TreeNodeSettings node2 = new TreeNodeSettings(activeProfile.FirstItem.errorAllList[k])
				{
					ImageIndex = 38,
					SelectedImageIndex = 38,
					Tag = "0",
					ClassIndex = 0,
					ClassSubIndex = -1,
					ClassSubSubIndex = -1,
					Command = "error",
					Name = activeProfile.FirstItem.errorAllList[k],
					Info = "",
					ForeColor = buImage5.ColorToneChange(buProfileCalc.varProfileVisualSettings.TreeOPErrorColor, factor),
					NodeFont = fontFromName,
					Index = -1,
					Checked = false,
					OldImageIndex = 38
				};
				treeNode.Nodes.Add(node2);
			}
		}
	}

	public void ProfileTree_AfterSelect(object sender, TreeViewEventArgs e)
	{
		if (ccVars.Pages.Count == 0)
		{
			return;
		}
		TreeView treeView = (TreeView)sender;
		TreeNodeSettings treeNodeSettings = (TreeNodeSettings)treeView.SelectedNode;
		if (((clsItem.FrmProfileJob.tree_jobs.Nodes != null) & (clsItem.FrmProfileJob.tree_jobs.SelectedNode != null)) && clsItem.FrmProfileJob.tree_jobs.SelectedNode.Parent != null)
		{
			for (int i = 0; i <= clsItem.FrmProfileJob.tree_jobs.Nodes.Count - 1; i++)
			{
				clsItem.FrmProfileJob.tree_jobs.Nodes[i].ForeColor = Color.Black;
				if (clsItem.FrmProfileJob.tree_jobs.Nodes[i].Nodes != null)
				{
					for (int j = 0; j <= clsItem.FrmProfileJob.tree_jobs.Nodes[i].Nodes.Count - 1; j++)
					{
						clsItem.FrmProfileJob.tree_jobs.Nodes[i].Nodes[j].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemColor;
					}
				}
			}
		}
		switch (treeNodeSettings.Command)
		{
		case "profileitemfirst":
			SelProfileTreeIndex = 0;
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex != 0 && ((ccVars.Action != actionTypeBU.None) & !ProfileTempVars.OperationEditing))
			{
				doReset();
			}
			if (activeProfile.FirstItem != null)
			{
				clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
				if (clsItem.FrmProfileJob.tree_jobs.SelectedNode != null)
				{
					clsItem.FrmProfileJob.tree_jobs.SelectedNode.ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
					buProfileCalc.varProfileSettings.XDirRefType = activeProfile.FirstItem.XReferanceLocation;
				}
				clsInit.appProfile.doSetActiveProfile(0);
				buProfileCalc.varProfileRunSettings.activeOPIndex = -1;
			}
			profileOperation_0 = null;
			break;
		case "profileitemsecond":
			SelProfileTreeIndex = 1;
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex != 1 && ((ccVars.Action != actionTypeBU.None) & !ProfileTempVars.OperationEditing))
			{
				doReset();
			}
			if (activeProfile.SecondItem != null)
			{
				clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
				if (clsItem.FrmProfileJob.tree_jobs.SelectedNode != null)
				{
					clsItem.FrmProfileJob.tree_jobs.SelectedNode.ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
					buProfileCalc.varProfileSettings.XDirRefType = activeProfile.SecondItem.XReferanceLocation;
				}
				clsInit.appProfile.doSetActiveProfile(1);
				buProfileCalc.varProfileRunSettings.activeOPIndex = -1;
			}
			profileOperation_0 = null;
			break;
		case "profileop":
			profileOperation_0 = null;
			if ((treeNodeSettings.ClassIndex >= 0) & (treeNodeSettings.ClassSubIndex >= 0))
			{
				if (buProfileCalc.varProfileRunSettings.activeProfileIndex != treeNodeSettings.ClassIndex)
				{
					clsInit.appProfile.doSetActiveProfile(treeNodeSettings.ClassIndex);
				}
				SelProfileTreeIndex = buProfileCalc.varProfileRunSettings.activeProfileIndex;
				clsInit.appProfile.doSetActiveProfileOP(treeNodeSettings.ClassIndex, treeNodeSettings.ClassSubIndex);
				if ((treeNodeSettings.ClassIndex == 0) & (activeProfile.FirstItem != null))
				{
					if (treeNodeSettings.ClassSubIndex <= activeProfile.FirstItem.Operations.Count - 1)
					{
						profileOperation_0 = activeProfile.FirstItem.Operations[treeNodeSettings.ClassSubIndex];
					}
					clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
					buProfileCalc.varProfileSettings.XDirRefType = activeProfile.FirstItem.XReferanceLocation;
					if (ProfileTempVars.OperationEditing && ((buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeOPIndex >= 0)))
					{
						doEditOperation(buProfileCalc.varProfileRunSettings.activeProfileIndex, buProfileCalc.varProfileRunSettings.activeOPName);
					}
				}
				if ((treeNodeSettings.ClassIndex == 1) & (activeProfile.SecondItem != null))
				{
					if (treeNodeSettings.ClassSubIndex <= activeProfile.SecondItem.Operations.Count - 1)
					{
						profileOperation_0 = activeProfile.SecondItem.Operations[treeNodeSettings.ClassSubIndex];
					}
					clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
					buProfileCalc.varProfileSettings.XDirRefType = activeProfile.SecondItem.XReferanceLocation;
					if (ProfileTempVars.OperationEditing && ((buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeOPIndex >= 0)))
					{
						doEditOperation(buProfileCalc.varProfileRunSettings.activeProfileIndex, buProfileCalc.varProfileRunSettings.activeOPName);
					}
				}
			}
			ProfileTree_OpColorUpdate();
			if (buProfileCalc.varProfileSettings.MultipleEdit & ProfileTempVars.OperationEditing)
			{
				doAddSelectedOperations();
			}
			break;
		}
	}

	public void ProfileTree_AfterCheck(object sender, TreeViewEventArgs e)
	{
		if (ccVars.Pages.Count == 0)
		{
			return;
		}
		TreeNodeSettings treeNodeSettings = (TreeNodeSettings)e.Node;
		if (Changing || treeNodeSettings == null)
		{
			return;
		}
		bool selected = treeNodeSettings.Checked;
		string command = treeNodeSettings.Command;
		string text = command;
		if (text == "profileitem")
		{
			if (treeNodeSettings.ClassIndex < 0)
			{
			}
		}
		else
		{
			if (!(text == "profileop"))
			{
				return;
			}
			if (treeNodeSettings.ClassIndex == 0 && activeProfile.FirstItem != null && ((treeNodeSettings.ClassSubIndex >= 0) & (treeNodeSettings.ClassSubIndex <= activeProfile.FirstItem.Operations.Count - 1)))
			{
				activeProfile.FirstItem.Operations[treeNodeSettings.ClassSubIndex].Selected = selected;
				DrawActiveProfile();
				if (buProfileCalc.varProfileSettings.MultipleEdit)
				{
					doAddSelectedOperations();
				}
			}
			if (treeNodeSettings.ClassIndex == 1 && activeProfile.SecondItem != null && ((treeNodeSettings.ClassSubIndex >= 0) & (treeNodeSettings.ClassSubIndex <= activeProfile.SecondItem.Operations.Count - 1)))
			{
				activeProfile.SecondItem.Operations[treeNodeSettings.ClassSubIndex].Selected = selected;
				DrawActiveProfile();
				if (buProfileCalc.varProfileSettings.MultipleEdit)
				{
					doAddSelectedOperations();
				}
			}
		}
	}

	public void ProfileTree_KeyDown(object sender, KeyEventArgs e)
	{
		if (e.KeyCode == Keys.Delete && ((buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeProfileIndex <= 1)))
		{
			if (buProfileCalc.varProfileRunSettings.activeOPIndex != -1)
			{
				cmdMenuCommand(clsItem.FrmProfileJob.mnu_remove, null);
			}
			else
			{
				cmdMenuCommand(clsItem.FrmProfileJob.mnu_deleteprofile, null);
			}
		}
		if (e.KeyCode == Keys.E && ((buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeProfileIndex <= 1)))
		{
			if (buProfileCalc.varProfileRunSettings.activeOPIndex != -1)
			{
				cmdMenuCommand(clsItem.FrmProfileJob.mnu_edit, null);
			}
			else
			{
				cmdMenuCommand(clsItem.FrmProfileJob.mnu_editprofile, null);
			}
		}
		if (e.KeyCode == Keys.C && ((buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeProfileIndex <= 1)))
		{
			if (buProfileCalc.varProfileRunSettings.activeOPIndex != -1)
			{
				cmdMenuCommand(clsItem.FrmProfileJob.mnu_copy, null);
			}
			else
			{
				cmdMenuCommand(clsItem.FrmProfileJob.mnu_copyprofile, null);
			}
		}
		if (e.KeyCode == Keys.M && ((buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeProfileIndex <= 1)) && buProfileCalc.varProfileRunSettings.activeOPIndex >= 0)
		{
			cmdMenuCommand(clsItem.FrmProfileJob.mnu_move, null);
		}
	}

