	public void ProfileTree_OpColorUpdate()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		TreeNodeSettings treeNodeSettings = clsItem.FrmProfileJob.tree_jobs.Nodes[0] as TreeNodeSettings;
		if (!((treeNodeSettings.Nodes != null) & (buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeProfileIndex <= treeNodeSettings.Nodes.Count - 1)) || treeNodeSettings.Nodes == null)
		{
			return;
		}
		for (int i = 0; i <= treeNodeSettings.Nodes.Count - 1; i++)
		{
			for (int j = 0; j <= treeNodeSettings.Nodes[i].Nodes.Count - 1; j++)
			{
				treeNodeSettings.Nodes[i].Nodes[j].ForeColor = Color.Black;
				if (j <= profileItem.Operations.Count - 1)
				{
					if (profileItem.Operations[j].infoList.Count > 0)
					{
						treeNodeSettings.Nodes[i].Nodes[j].ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPInfoColor;
					}
					if (profileItem.Operations[j].warningList.Count > 0)
					{
						treeNodeSettings.Nodes[i].Nodes[j].ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPWarningColor;
					}
					if (profileItem.Operations[j].errorList.Count > 0)
					{
						treeNodeSettings.Nodes[i].Nodes[j].ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPErrorColor;
					}
				}
				if ((i == buProfileCalc.varProfileRunSettings.activeProfileIndex) & (j == buProfileCalc.varProfileRunSettings.activeOPIndex))
				{
					treeNodeSettings.Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[j].ForeColor = buProfileCalc.varProfileVisualSettings.TreeOPSelectedColor;
				}
			}
		}
	}

	public void DepthDGV_CellValueChanged(object sender, DataGridViewCellEventArgs e)
	{
		try
		{
			if (!ProfileTempVars.DepthInited)
			{
				return;
			}
			ProfileTempVars.DepthForced = true;
			ProfileTempVars.DepthInited = false;
			ProfileTempVars.OperationDepths.Clear();
			ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			shapeUpdateArg.Command = "DepthChanged";
			for (int i = 0; i <= clsItem.FrmProfileDepths.DGV_Depths.Rows.Count - 1; i++)
			{
				DepthPositions depthPositions = new DepthPositions();
				bool flag = false;
				for (int j = 1; j <= clsItem.FrmProfileDepths.DGV_Depths.Columns.Count - 1; j++)
				{
					if (j == 1)
					{
						if (!buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString()))
						{
							flag = true;
						}
						else
						{
							depthPositions.TopPosition = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString());
						}
					}
					if (j == 2)
					{
						if (!buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString()))
						{
							flag = true;
						}
						else
						{
							if ((buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Top) | (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Back) | (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Free))
							{
								depthPositions.Depth = 0.0 - double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString());
								depthPositions.BottomPosition = depthPositions.TopPosition - Math.Abs(depthPositions.Depth);
							}
							if ((buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Front) | (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Bottom))
							{
								depthPositions.Depth = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString());
								depthPositions.BottomPosition = depthPositions.TopPosition + Math.Abs(depthPositions.Depth);
							}
						}
					}
					if (j == 3)
					{
						depthPositions.PeckingUp = bool.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString());
					}
					if (j == 4)
					{
						if (!buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString()))
						{
							flag = true;
						}
						else
						{
							depthPositions.PeckingUpDistance = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString());
						}
					}
					if (j == 5)
					{
						if (!buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString()))
						{
							flag = true;
						}
						else
						{
							depthPositions.PlungeFeed = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString());
						}
					}
					if (j == 6)
					{
						if (!buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString()))
						{
							flag = true;
						}
						else
						{
							depthPositions.SpindleSpeed = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString());
						}
					}
					if (j == 7)
					{
						if (!buNumeric5.IsNumeric(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString()))
						{
							flag = true;
						}
						else
						{
							depthPositions.Wait = double.Parse(clsItem.FrmProfileDepths.DGV_Depths.Rows[i].Cells[j].Value.ToString());
						}
					}
				}
				if (!flag)
				{
					ProfileTempVars.OperationDepths.Add(depthPositions);
				}
			}
			OnlineOperation(null, shapeUpdateArg, null);
			ProfileTempVars.DepthInited = true;
		}
		catch (Exception)
		{
		}
	}

