	public void DepthsFill(buEyeBaseVer5.Apps.ProfileOperationData OPData)
	{
		ProfileTempVars.DepthInited = false;
		clsItem.FrmProfileDepths.DGV_Depths.Rows.Clear();
		for (int i = 0; i <= OPData.DepthValues.Count - 1; i++)
		{
			object[] values = AddNewDepthRow(i + 1, OPData.DepthValues[i].TopPosition, Math.Abs(OPData.DepthValues[i].Depth), OPData.DepthValues[i].PeckingUp, OPData.DepthValues[i].PeckingUpDistance, OPData.DepthValues[i].PlungeFeed, OPData.DepthValues[i].SpindleSpeed, OPData.DepthValues[i].Wait);
			clsItem.FrmProfileDepths.DGV_Depths.Rows.Add(values);
		}
		ProfileTempVars.DepthInited = true;
	}

	public object[] AddNewDepthRow(int index, double pos, double depth, bool pecking, double peckingup, double plunge, double spindle, double wait)
	{
		return new object[8]
		{
			index,
			Math.Round(pos, 3),
			Math.Round(depth, 3),
			pecking,
			Math.Round(peckingup, 3),
			Math.Round(plunge, 3),
			Math.Round(spindle, 3),
			Math.Round(wait, 3)
		};
	}

	public void PlaneTypesSelectedIndexChanged(object sender, EventArgs e)
	{
		ProfileTempVars.PlaneInited = false;
		if ((clsItem.FrmProfilePlanes.lst_types.SelectedIndex >= 0) & (clsItem.FrmProfilePlanes.lst_types.SelectedIndex <= selectedPlanes.Count - 1))
		{
			ProfileTempVars.PlaneSelectedIndex = clsItem.FrmProfilePlanes.lst_types.SelectedIndex;
			clsItem.FrmProfilePlanes.spn_angle.Value = (decimal)selectedPlanes[ProfileTempVars.PlaneSelectedIndex].Angle;
			clsItem.FrmProfilePlanes.spn_y.Value = (decimal)selectedPlanes[ProfileTempVars.PlaneSelectedIndex].pntPlane.Y;
			clsItem.FrmProfilePlanes.spn_z.Value = (decimal)selectedPlanes[ProfileTempVars.PlaneSelectedIndex].pntPlane.Z;
			if ((ProfileTempVars.PlaneSelectedIndex >= 0) & (ProfileTempVars.PlaneSelectedIndex <= selectedPlanes.Count - 1))
			{
				buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = new SelectedPlaneInfo(selectedPlanes[ProfileTempVars.PlaneSelectedIndex]);
				buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane)selectedPlanes[ProfileTempVars.PlaneSelectedIndex].refPlane.Clone();
				DrawPlaneDepth(CleanAll: true, DrawPlanes: true, DrawDepths: false);
				PlaneCommandOnline();
			}
		}
		ProfileTempVars.PlaneInited = true;
		viewportBottom.Invalidate();
	}

	public void DepthClick(object sender, EventArgs e)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		Control control = sender as Control;
		if (control.Name == clsItem.FrmProfileDepths.btn_depthadd.Name)
		{
			if (ProfileTempVars.CreatingOperation.OperationData.DepthValues.Count <= 0)
			{
				DepthPositions depthPositions = new DepthPositions();
				if ((buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Top) | (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Free))
				{
					depthPositions.TopPosition = profileItem.Height;
					depthPositions.Depth = -5.0;
				}
				if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Back)
				{
					depthPositions.TopPosition = 0.0;
					depthPositions.Depth = -5.0;
				}
				if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Front)
				{
					depthPositions.TopPosition = 0.0 - profileItem.Width;
					depthPositions.Depth = 5.0;
				}
				if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Bottom)
				{
					depthPositions.TopPosition = 0.0;
					depthPositions.Depth = 5.0;
				}
				object[] values = AddNewDepthRow(1, depthPositions.TopPosition, depthPositions.Depth, buProfileCalc.varProfileSettings.AutoPeckingAddDefault, buProfileCalc.varProfileSettings.AutoPeckingUpDefaultDistance, 0.0, 0.0, 0.0);
				clsItem.FrmProfileDepths.DGV_Depths.Rows.Add(values);
			}
			else
			{
				DepthPositions depthPositions2 = ProfileTempVars.CreatingOperation.OperationData.DepthValues[ProfileTempVars.CreatingOperation.OperationData.DepthValues.Count - 1];
				if ((buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Top) | (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Back) | (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Free))
				{
					depthPositions2.TopPosition -= 5.0;
				}
				if ((buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Front) | (buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Bottom))
				{
					depthPositions2.TopPosition += 5.0;
				}
				object[] values2 = AddNewDepthRow(ProfileTempVars.CreatingOperation.OperationData.DepthValues.Count + 1, depthPositions2.TopPosition, depthPositions2.Depth, buProfileCalc.varProfileSettings.AutoPeckingAddDefault, buProfileCalc.varProfileSettings.AutoPeckingUpDefaultDistance, 0.0, 0.0, 0.0);
				clsItem.FrmProfileDepths.DGV_Depths.Rows.Add(values2);
			}
			DepthDGV_CellValueChanged(null, null);
		}
		if (control.Name == clsItem.FrmProfileDepths.btn_depthdelete.Name && buString5.MessageBoxQuestion(buLangTranslate.preSentences.DoYouWanttoDeleteDepth) == DialogResult.Yes && ((ProfileTempVars.DepthSelectedIndex >= 0) & (ProfileTempVars.DepthSelectedIndex <= clsItem.FrmProfileDepths.DGV_Depths.Rows.Count - 1)))
		{
			clsItem.FrmProfileDepths.DGV_Depths.Rows.RemoveAt(ProfileTempVars.DepthSelectedIndex);
			ProfileTempVars.DepthForced = true;
			DepthDGV_CellValueChanged(null, null);
		}
		if (control.Name == clsItem.FrmProfileDepths.btn_depthcalculate.Name)
		{
			ProfileTempVars.DepthForced = false;
			ShapeUpdateArg data = new ShapeUpdateArg(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			OnlineOperation(null, data, null);
			ProfileTempVars.DepthInited = true;
		}
		if (control.Name == clsItem.FrmProfileDepths.btn_depthopen.Name)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathDepths;
			openFileDialog.Filter = "buCad/Cam Plane File (*.budepths)|*.budepths";
			openFileDialog.FilterIndex = 1;
			if (openFileDialog.ShowDialog() == DialogResult.OK)
			{
				ProfileTempVars.OperationDepths.Clear();
				OPData.DepthValues.Clear();
				DepthPositions.OpenFile(ref OPData.DepthValues, openFileDialog.FileName);
				DepthsFill(OPData);
				buProfileCalc.varProfileRunSettings.pathDepths = buFile5.GetPath(openFileDialog.FileName);
				ProfileTempVars.DepthForced = true;
				DepthDGV_CellValueChanged(null, null);
				SaveByTick = true;
			}
		}
		if (control.Name == clsItem.FrmProfileDepths.btn_depthsave.Name)
		{
			SaveFileDialog saveFileDialog = new SaveFileDialog();
			saveFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathDepths;
			saveFileDialog.Filter = "buCad/Cam Plane File (*.budepths)|*.budepths";
			saveFileDialog.FilterIndex = 1;
			if (saveFileDialog.ShowDialog() == DialogResult.OK)
			{
				DepthPositions.SaveFile(ProfileTempVars.CreatingOperation.OperationData.DepthValues, saveFileDialog.FileName);
				buProfileCalc.varProfileRunSettings.pathDepths = buFile5.GetPath(saveFileDialog.FileName);
				SaveByTick = true;
			}
		}
	}

	public void PlaneClick(object sender, EventArgs e)
	{
		Control control = sender as Control;
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		if (control.Name == clsItem.FrmProfilePlanes.btn_addplane.Name)
		{
			F_PlaneList f_PlaneList = new F_PlaneList();
			f_PlaneList.PropertiesForm.FormCloseMode = FormCloseModeType.Dispose;
			f_PlaneList.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
			f_PlaneList.pntMinProfile = buVector5.ToPoint3D(profileItem.ProfileMinPoint);
			f_PlaneList.pntMaxProfile = buVector5.ToPoint3D(profileItem.ProfileMaxPoint);
			f_PlaneList.VarUcs = buProfileCalc.varUCSData;
			f_PlaneList.PlaneThinkness = buProfileCalc.varProfileSettings.PlaneThickness;
			f_PlaneList.Init();
			f_PlaneList.ShowDialog();
			if (f_PlaneList.PropertiesForm.Result == DialogResult.OK)
			{
				AddPlane(f_PlaneList.Plane);
				ProfileTempVars.PlaneSelectedIndex = selectedPlanes.Count - 1;
				clsItem.FrmProfilePlanes.lst_types.SelectedIndex = ProfileTempVars.PlaneSelectedIndex;
			}
		}
		if ((control.Name == clsItem.FrmProfilePlanes.btn_angminus.Name) | (control.Name == clsItem.FrmProfilePlanes.btn_angplus.Name) | (control.Name == clsItem.FrmProfilePlanes.btn_yminus.Name) | (control.Name == clsItem.FrmProfilePlanes.btn_yplus.Name) | (control.Name == clsItem.FrmProfilePlanes.btn_zminus.Name) | (control.Name == clsItem.FrmProfilePlanes.btn_zplus.Name))
		{
			if (control.Name == clsItem.FrmProfilePlanes.btn_angminus.Name)
			{
				clsItem.FrmProfilePlanes.spn_angle.Value = clsItem.FrmProfilePlanes.spn_angle.Value - (decimal)ProfileTempVars.PlaneIncrement;
			}
			if (control.Name == clsItem.FrmProfilePlanes.btn_angplus.Name)
			{
				clsItem.FrmProfilePlanes.spn_angle.Value = clsItem.FrmProfilePlanes.spn_angle.Value + (decimal)ProfileTempVars.PlaneIncrement;
			}
			if (control.Name == clsItem.FrmProfilePlanes.btn_yminus.Name)
			{
				clsItem.FrmProfilePlanes.spn_y.Value = clsItem.FrmProfilePlanes.spn_y.Value - (decimal)ProfileTempVars.PlaneIncrement;
			}
			if (control.Name == clsItem.FrmProfilePlanes.btn_yplus.Name)
			{
				clsItem.FrmProfilePlanes.spn_y.Value = clsItem.FrmProfilePlanes.spn_y.Value + (decimal)ProfileTempVars.PlaneIncrement;
			}
			if (control.Name == clsItem.FrmProfilePlanes.btn_zminus.Name)
			{
				clsItem.FrmProfilePlanes.spn_z.Value = clsItem.FrmProfilePlanes.spn_z.Value - (decimal)ProfileTempVars.PlaneIncrement;
			}
			if (control.Name == clsItem.FrmProfilePlanes.btn_zplus.Name)
			{
				clsItem.FrmProfilePlanes.spn_z.Value = clsItem.FrmProfilePlanes.spn_z.Value + (decimal)ProfileTempVars.PlaneIncrement;
			}
			PlaneCommandOnline();
		}
		if (control.Name == clsItem.FrmProfilePlanes.lbl_01.Name)
		{
			ProfileTempVars.PlaneIncrement = 0.1;
			PlaneIncrementSelect();
		}
		if (control.Name == clsItem.FrmProfilePlanes.lbl_05.Name)
		{
			ProfileTempVars.PlaneIncrement = 0.5;
			PlaneIncrementSelect();
		}
		if (control.Name == clsItem.FrmProfilePlanes.lbl_1.Name)
		{
			ProfileTempVars.PlaneIncrement = 1.0;
			PlaneIncrementSelect();
		}
		if (control.Name == clsItem.FrmProfilePlanes.lbl_5.Name)
		{
			ProfileTempVars.PlaneIncrement = 5.0;
			PlaneIncrementSelect();
		}
		if (control.Name == clsItem.FrmProfilePlanes.lbl_10.Name)
		{
			ProfileTempVars.PlaneIncrement = 10.0;
			PlaneIncrementSelect();
		}
		if (control.Name == clsItem.FrmProfilePlanes.btn_delete.Name && buString5.MessageBoxQuestion(AppLanguage.CadCamMessages[97]) == DialogResult.Yes && ((ProfileTempVars.PlaneSelectedIndex >= 0) & (ProfileTempVars.PlaneSelectedIndex <= selectedPlanes.Count - 1)))
		{
			RemovePlane(ProfileTempVars.PlaneSelectedIndex);
		}
		if (control.Name == clsItem.FrmProfilePlanes.btn_open.Name)
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathPlanes;
			openFileDialog.Filter = "buCad/Cam Plane File (*.buplane)|*.buplane";
			openFileDialog.FilterIndex = 1;
			openFileDialog.Multiselect = false;
			if (openFileDialog.ShowDialog() == DialogResult.OK)
			{
				buProfileCalc.varProfileRunSettings.pathPlanes = buFile5.GetPath(openFileDialog.FileName);
				buFile5.OpenPlaneFile(openFileDialog.FileName, ref selectedPlanes);
				clsItem.FrmProfilePlanes.lst_types.Items.Clear();
				for (int i = 0; i <= selectedPlanes.Count - 1; i++)
				{
					clsItem.FrmProfilePlanes.lst_types.Items.Add(selectedPlanes[i].Explanation);
				}
				ProfileTempVars.PlaneInited = true;
			}
		}
		if (control.Name == clsItem.FrmProfilePlanes.btn_save.Name)
		{
			SaveFileDialog saveFileDialog = new SaveFileDialog();
			saveFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathPlanes;
			saveFileDialog.Filter = "buCad/Cam Plane File (*.buplane)|*.buplane";
			saveFileDialog.FilterIndex = 1;
			if (saveFileDialog.ShowDialog() == DialogResult.OK)
			{
				buFile5.SavePlaneFile(saveFileDialog.FileName, selectedPlanes);
				buProfileCalc.varProfileRunSettings.pathPlanes = buFile5.GetPath(saveFileDialog.FileName);
			}
		}
	}

	public void RemovePlane(int indexPlane, bool OnlyDrawing = false)
	{
		if (!((indexPlane >= 0) & (indexPlane <= selectedPlanes.Count - 1)))
		{
			return;
		}
		viewportBottom.Entities.ClearSelection();
		for (int i = 0; i <= viewportBottom.Entities.Count - 1; i++)
		{
			if (viewportBottom.Entities[i].EntityData != null && viewportBottom.Entities[i].EntityData is CustomData)
			{
				CustomData customData = viewportBottom.Entities[i].EntityData as CustomData;
				if ((customData.typeDefination == entityTypeDefination.Plane) & (customData.RefIndex == indexPlane))
				{
					viewportBottom.Entities[i].Selected = true;
				}
			}
		}
		viewportBottom.Entities.DeleteSelected();
		if (!OnlyDrawing)
		{
			selectedPlanes.RemoveAt(indexPlane);
			clsItem.FrmProfilePlanes.lst_types.Items.RemoveAt(indexPlane);
			indexPlane--;
		}
		viewportBottom.Invalidate();
	}

	public void AddPlane(SelectedPlaneInfo P, bool OnlyDrawing = false)
	{
		selectedPlanes.Add(new SelectedPlaneInfo(P));
		ProfileTempVars.PlaneInited = true;
		if (!OnlyDrawing)
		{
			clsItem.FrmProfilePlanes.lst_types.Items.Add(P.Explanation);
		}
	}

	public void FillPlanes()
	{
		ProfileTempVars.PlaneInited = false;
		clsItem.FrmProfilePlanes.lst_types.Items.Clear();
		for (int i = 0; i <= selectedPlanes.Count - 1; i++)
		{
			clsItem.FrmProfilePlanes.lst_types.Items.Add(selectedPlanes[i].Explanation);
		}
		ProfileTempVars.PlaneInited = true;
	}

	public void PlaneIncrementSelect()
	{
		clsItem.FrmProfilePlanes.lbl_01.BackColor = Color.PowderBlue;
		clsItem.FrmProfilePlanes.lbl_05.BackColor = Color.PowderBlue;
		clsItem.FrmProfilePlanes.lbl_1.BackColor = Color.PowderBlue;
		clsItem.FrmProfilePlanes.lbl_5.BackColor = Color.PowderBlue;
		clsItem.FrmProfilePlanes.lbl_10.BackColor = Color.PowderBlue;
		if (ProfileTempVars.PlaneIncrement != 0.1)
		{
			if (ProfileTempVars.PlaneIncrement != 0.5)
			{
				if (ProfileTempVars.PlaneIncrement != 1.0)
				{
					if (ProfileTempVars.PlaneIncrement != 5.0)
					{
						clsItem.FrmProfilePlanes.lbl_10.BackColor = Color.Gold;
					}
					else
					{
						clsItem.FrmProfilePlanes.lbl_5.BackColor = Color.Gold;
					}
				}
				else
				{
					clsItem.FrmProfilePlanes.lbl_1.BackColor = Color.Gold;
				}
			}
			else
			{
				clsItem.FrmProfilePlanes.lbl_05.BackColor = Color.Gold;
			}
		}
		else
		{
			clsItem.FrmProfilePlanes.lbl_01.BackColor = Color.Gold;
		}
	}

	public void PlaneValueChanged(object sender, EventArgs e)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem != null && ProfileTempVars.PlaneInited && ((ProfileTempVars.PlaneSelectedIndex >= 0) & (ProfileTempVars.PlaneSelectedIndex <= selectedPlanes.Count - 1)))
		{
			SelectedPlaneInfo P = selectedPlanes[ProfileTempVars.PlaneSelectedIndex];
			P.pntPlane.Y = (double)clsItem.FrmProfilePlanes.spn_y.Value;
			P.pntPlane.Z = (double)clsItem.FrmProfilePlanes.spn_z.Value;
			P.Angle = (double)clsItem.FrmProfilePlanes.spn_angle.Value;
			clsInit.cProfile.CreatePlane(P.PlaneType, 0, Create: false, profileItem.ProfileMinPoint, profileItem.ProfileMaxPoint, buProfileCalc.varProfileSettings.PlaneThickness, buProfileCalc.varUCSData, ref P);
			buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = P;
			buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane)P.refPlane.Clone();
			DrawPlaneDepth(CleanAll: false, DrawPlanes: true, DrawDepths: false);
		}
	}

	public void DrawPlaneDepth(bool CleanAll, bool DrawPlanes, bool DrawDepths)
	{
		bool flag = false;
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; i++)
		{
			if (!clsInit.cVector5.IsLayerNameAvailable(viewportBottom.Layers, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Name))
			{
				Layer item = new Layer(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Name, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Color);
				viewportBottom.Layers.Add(item);
			}
		}
		if (!CleanAll)
		{
			for (int j = 0; j <= viewportBottom.Entities.Count - 1; j++)
			{
				if (viewportBottom.Entities[j].EntityData != null && viewportBottom.Entities[j].EntityData is CustomData)
				{
					CustomData customData = viewportBottom.Entities[j].EntityData as CustomData;
					if ((customData.typeDefination == entityTypeDefination.Plane) | (customData.typeDefination == entityTypeDefination.Operation) | (customData.typeDefination == entityTypeDefination.None))
					{
						viewportBottom.Entities[j].Selected = true;
					}
				}
			}
			viewportBottom.Entities.DeleteSelected();
			if (viewportBottom.Entities.Count == 0)
			{
				for (int k = 0; k <= profileItem.Drawings.Count - 1; k++)
				{
					if (profileItem.Drawings[k].SolidEntity != null)
					{
						Entity entity = buVector5.CopyEntities(profileItem.Drawings[k].SolidEntity);
						entity.Color = Color.FromArgb(70, entity.Color);
						viewportBottom.Entities.Add(entity);
					}
				}
				flag = true;
			}
		}
		else
		{
			viewportBottom.Entities.Clear();
			for (int l = 0; l <= profileItem.Drawings.Count - 1; l++)
			{
				if (profileItem.Drawings[l].SolidEntity != null)
				{
					Entity entity2 = buVector5.CopyEntities(profileItem.Drawings[l].SolidEntity);
					entity2.Color = Color.FromArgb(70, entity2.Color);
					viewportBottom.Entities.Add(entity2);
				}
			}
			flag = true;
		}
		if (DrawPlanes)
		{
			if (buProfileCalc.varProfileRunSettings.OPData != null && buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo != null)
			{
				if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityPlane != null)
				{
					Entity entity3 = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityPlane);
					entity3.LayerName = "Default";
					entity3.ColorMethod = colorMethodType.byEntity;
					entity3.Color = Color.FromArgb(200, Color.Lime);
					entity3.Regen(buSystem.RegenDeviation);
					CustomData customData2 = new CustomData();
					customData2.typeDefination = entityTypeDefination.Plane;
					customData2.RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index;
					entity3.EntityData = customData2;
					entity3.Selected = true;
					viewportBottom.Entities.Add(entity3);
				}
				if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityXVector != null)
				{
					Entity entity4 = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityXVector);
					entity4.LayerName = "Default";
					entity4.ColorMethod = colorMethodType.byEntity;
					entity4.Color = Color.FromArgb(255, Color.Red);
					entity4.Selectable = true;
					entity4.Regen(buSystem.RegenDeviation);
					CustomData customData3 = new CustomData();
					customData3.typeDefination = entityTypeDefination.Plane;
					customData3.RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index;
					entity4.EntityData = customData3;
					viewportBottom.Entities.Add(entity4);
				}
				if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityYVector != null)
				{
					Entity entity5 = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityYVector);
					entity5.LayerName = "Default";
					entity5.ColorMethod = colorMethodType.byEntity;
					entity5.Color = Color.FromArgb(255, Color.Green);
					entity5.Regen(buSystem.RegenDeviation);
					entity5.Selectable = true;
					CustomData customData4 = new CustomData();
					customData4.typeDefination = entityTypeDefination.Plane;
					customData4.RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index;
					entity5.EntityData = customData4;
					viewportBottom.Entities.Add(entity5);
				}
				if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityZVector != null)
				{
					Entity entity6 = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityZVector);
					entity6.LayerName = "Default";
					entity6.ColorMethod = colorMethodType.byEntity;
					entity6.Color = Color.FromArgb(255, Color.Blue);
					entity6.Selectable = true;
					entity6.Regen(buSystem.RegenDeviation);
					CustomData customData5 = new CustomData();
					customData5.typeDefination = entityTypeDefination.Plane;
					customData5.RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index;
					entity6.EntityData = customData5;
					viewportBottom.Entities.Add(entity6);
				}
				if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityBall != null)
				{
					Entity entity7 = buVector5.CopyEntities(buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityBall);
					entity7.LayerName = "Default";
					entity7.ColorMethod = colorMethodType.byEntity;
					entity7.Color = Color.FromArgb(255, Color.Gray);
					entity7.Regen(buSystem.RegenDeviation);
					CustomData customData6 = new CustomData();
					customData6.typeDefination = entityTypeDefination.Plane;
					customData6.RefIndex = buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.Index;
					entity7.EntityData = customData6;
					viewportBottom.Entities.Add(entity7);
				}
				viewportBottom.ZoomFit(selectedOnly: true, 5);
			}
			if (flag)
			{
				if (buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo.entityPlane == null)
				{
					viewportBottom.SetView(viewType.vcFrontFaceTopLeft);
					viewportBottom.ZoomFit(5);
				}
				else
				{
					viewportBottom.SetView(viewType.Left);
					viewportBottom.ZoomFit(5);
					if (!(buProfileCalc.varProfileRunSettings.OPData.selectedPlane.Equation.Y > 0.0))
					{
						if (buProfileCalc.varProfileRunSettings.OPData.selectedPlane.Equation.Y <= 0.0)
						{
							viewportBottom.RotateCamera(new Vector3D(-1.0, 0.0, 0.0), new Vector3D(-0.95, 0.05, 0.05));
						}
					}
					else
					{
						viewportBottom.RotateCamera(new Vector3D(-1.0, 0.0, 0.0), new Vector3D(-0.95, 0.05, -0.05));
					}
					viewportBottom.ZoomFit(selectedOnly: true, 5);
				}
			}
		}
		if (DrawDepths)
		{
			if (ProfileTempVars.CreatingOperation != null)
			{
				for (int m = 0; m <= ProfileTempVars.CreatingOperation.EntityMultiSolidDepth.Count - 1; m++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(ProfileTempVars.CreatingOperation.EntityMultiSolidDepth[m], ref copiedEntity);
					CustomData customData7 = new CustomData();
					customData7.typeDefination = entityTypeDefination.Operation;
					copiedEntity.EntityData = customData7;
					viewportBottom.Entities.Add(copiedEntity);
				}
			}
			if (flag)
			{
				viewportBottom.SetView(viewType.Left);
				viewportBottom.ZoomFit(5);
			}
		}
		viewportBottom.Invalidate();
	}

	public void PlaneCommandOnline()
	{
		if (ccVars.Action != actionTypeBU.None && FrmOperationList != null && buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedPlane == planeBoxNames.Free)
		{
			ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			shapeUpdateArg.Command = "PlaneChanged";
			OnlineOperation(null, shapeUpdateArg, null);
		}
	}

	public bool cmdAddProfile(buEyeBaseVer5.Apps.ProfileItem profile, bool BoxProfile = false)
	{
		try
		{
			if (ccVars.Pages[ccVars.Pages.Count - 1].Layers.Count < 2)
			{
				buString5.MessageBoxWarning(AppLanguage.CadCamMessages[100]);
				return false;
			}
			if (!(ccVars.Pages[ccVars.Pages.Count - 1].Layers[1].Name != ProfileTempVars.LayerNameProfile))
			{
				if (FrmProfile == null)
				{
					FrmProfile = new buEyeBaseVer5.Forms.Profile.F_ProfileAdd();
					FrmProfile.EditDxf += doEditDxf;
				}
				FrmProfile.MaterialIndex = clsVar.varInterface.MaterialSkinIndex;
				FrmProfile.Materials.Clear();
				for (int i = 0; i <= ccVars.Textures.Count - 1; i++)
				{
					MaterialSkin item = new MaterialSkin(ccVars.Textures[i].Name, ccVars.Textures[i].Specular);
					FrmProfile.Materials.Add(item);
				}
				FrmProfile.RigthProfile = buProfileCalc.varProfileSettings.RightProfileActive;
				FrmProfile.ProfileSet = new buEyeBaseVer5.Apps.ProfileSettings(buProfileCalc.varProfileSettings);
				if (SelProfileTreeIndex != 0)
				{
					if (SelProfileTreeIndex == 1)
					{
						FrmProfile.ProfileSet.XDirRefType = LeftRightType.Right;
					}
				}
				else
				{
					FrmProfile.ProfileSet.XDirRefType = LeftRightType.Left;
				}
				buProfileCalc.varProfileRunSettings.ProfileType = ProfileNewType.Drawing;
				if (BoxProfile)
				{
					buProfileCalc.varProfileRunSettings.ProfileType = ProfileNewType.Rectangle;
				}
				FrmProfile.ProfileRunTimeSet = new buEyeBaseVer5.Apps.ProfileRuntimeSettings(buProfileCalc.varProfileRunSettings);
				if (profile != null)
				{
					FrmProfile.ProfileRunTimeSet.ProfileLength = profile.Length;
					FrmProfile.ProfileRunTimeSet.NewProfileWidth = profile.Width;
					FrmProfile.ProfileRunTimeSet.NewProfileHeight = profile.Height;
					FrmProfile.ProfileRunTimeSet.NewProfileThickness = profile.Thickness;
					buProfileCalc.varProfileRunSettings.ProfileType = profile.ProfileType;
				}
				FrmProfile.StartPosition = FormStartPosition.CenterParent;
				FrmProfile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
				FrmProfile.Init(profile, BoxProfile);
				FrmProfile.ShowDialog();
				if (FrmProfile.PropertiesForm.Result != DialogResult.OK)
				{
					return false;
				}
				activeOP = null;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
				buProfileCalc.varProfileSettings.MaterialTranspancy = FrmProfile.ProfileSet.MaterialTranspancy;
				buProfileCalc.varProfileRunSettings = new buEyeBaseVer5.Apps.ProfileRuntimeSettings(FrmProfile.ProfileRunTimeSet);
				buProfileCalc.varProfileSettings = new buEyeBaseVer5.Apps.ProfileSettings(FrmProfile.ProfileSet);
				buEyeBaseVer5.Apps.ProfileItem Profile = new buEyeBaseVer5.Apps.ProfileItem(FrmProfile.Profile);
				Profile.ClamperSettings = new buEyeBaseVer5.Apps.ProfileClamperSettings(buProfileCalc.varProfileClamperSettings);
				if (!buProfileCalc.varProfileSettings.RightProfileActive)
				{
					Profile.XReferanceLocation = LeftRightType.Left;
				}
				buProfileCalc.varProfileRunSettings.LastLoadedProfileName = Profile.FileNameFull;
				SaveByTick = true;
				Profile.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
				if (profile != null)
				{
					doCreateProfile(ref Profile, isNewProfile: true);
				}
				else
				{
					doCreateProfile(ref Profile, isNewProfile: true);
					clsInit.appCommand.cmdViewZoomFit();
				}
				clsItem.ModelMainPreview.ZoomFit();
				if (buProfileCalc.varProfileSettings.AutoOpenLastLoadedProfile | buProfileCalc.varProfileSettings.AutoOpenLastLoadedProfileAndOperations)
				{
					SaveProfileJobFile(AppPath.Base + "\\AutoSave\\LastProfile.buprofile", Profile, AddRecent: false);
				}
				DrawActiveProfile();
				DrawPreview(Profile, new List<Entity>());
				doCheckProfileError();
				return true;
			}
			buString5.MessageBoxWarning(AppLanguage.CadCamMessages[99]);
			return false;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, text);
			return false;
		}
	}

