	public void cmdShapes(actionTypeBU action)
	{
		if (okCommandWithTwoDataEventHandler_0 != null)
		{
			okCommandWithTwoDataEventHandler_0("ShapeCommand", null);
		}
		if (FrmOperationList.viewportLayout.Layers.Count != ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count)
		{
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; i++)
			{
				FrmOperationList.viewportLayout.Layers.AddOrReplace(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i]);
			}
		}
		if ((FrmOperationList.pnl_model.Controls.Count == 0) | (FrmOperationList.pnl_model.Controls.Count == 3))
		{
			FrmOperationList.pnl_model.Controls.Add(FrmOperationList.viewportLayout);
		}
		if (buProfileCalc.varProfileSettings.UseAlwaysPocketForCam)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.isShapePocket = true;
		}
		if (buProfileCalc.varProfileSettings.UseAlwaysInsideContourForCam)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Offsets.ClosedContour = CamClosedContourType.Inner;
		}
		if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextString.Length == 0)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextString = "Text";
		}
		if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextHeight == 0.0)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextHeight = 10.0;
		}
		if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextWidth == 0.0)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextWidth = 100.0;
		}
		if (buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextDepth == 0.0)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextDepth = 2.0;
		}
		buProfileCalc.varProfileRunSettings.ShapeDataParameters.ShapeGroup = ShapeGroup.Shape;
		buProfileCalc.varProfileRunSettings.ShapeDataParameters.ShapeType = clsInit.cProfile.ActionToShapeType(action);
		if (action == actionTypeBU.profileHole)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.isTapping = false;
		}
		if (action == actionTypeBU.profileTapping)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.isTapping = true;
		}
		if (action == actionTypeBU.profileText)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextIsWire = false;
			shapeCreateParameters_0.entitiesCurveList = new List<EntitiesList>();
		}
		if (action == actionTypeBU.profileWireText)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.TextIsWire = true;
			shapeCreateParameters_0.entitiesCurveList = new List<EntitiesList>();
		}
		buProfileCalc.varProfileRunSettings.ShapeDataParameters.UpdateEditOperationWithoutOk = buProfileCalc.varProfileSettings.OperationEditChangeWithoutOk;
		ProfileTempVars.CamAssinged = false;
		if (ProfileTempVars.OperationEditing)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.Priority = OPPriority;
			ProfileTempVars.CamAssinged = true;
		}
		else
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.Priority = 0;
		}
		if (ccVars.toolActive.Geometry.GeometryType == ToolType.Saw)
		{
			if (toolBase5_0 == null || toolBase5_0.Geometry.GeometryType == ToolType.Saw)
			{
				for (int j = 0; j <= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1; j++)
				{
					if (ccVars.Tools[ccVars.ToolGroupIndex].Tools[j].Geometry.GeometryType != ToolType.Saw)
					{
						ccVars.toolActive = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[j]);
						j = ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count;
					}
				}
			}
			else
			{
				ccVars.toolActive = new ToolBase5(toolBase5_0);
			}
		}
		FillPlanes();
		ProfileTempVars.PlaneInited = true;
		ProfileTempVars.DepthInited = true;
		FrmOperationList.PropertiesForm.TopMost = true;
		FrmOperationList.PropertiesForm.FormPosition = FormStartPosition.Manual;
		FrmOperationList.StartPosition = FormStartPosition.Manual;
		FrmOperationList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		FrmOperationList.Top = 50;
		FrmOperationList.Left = 1500;
		FrmOperationList.Width = 380;
		FrmOperationList.TopMost = true;
		FrmOperationList.ShowTool = true;
		FrmOperationList.Tools.Clear();
		for (int k = 0; k <= ccVars.Tools[ccVars.ToolGroupIndex].Tools.Count - 1; k++)
		{
			FrmOperationList.Tools.Add(new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[k]));
			if (!ProfileTempVars.OperationEditing && action != actionTypeBU.profileNotch && ccVars.toolActive.Data.Name == ccVars.Tools[ccVars.ToolGroupIndex].Tools[k].Data.Name)
			{
				ccVars.toolActive = new ToolBase5(ccVars.Tools[ccVars.ToolGroupIndex].Tools[k]);
			}
		}
		FrmOperationList.activeTool = new ToolBase5(ccVars.toolActive);
		FrmOperationList.viewportLayout.Entities.Clear();
		FrmOperationList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		if (clsItem.FrmMain != null)
		{
			FrmOperationList.Owner = clsItem.FrmMain;
		}
		if (ProfileTempVars.PatternDxfOperation)
		{
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.pntBase.X = Math.Round(ProfileTempVars.PntPatternDxf.X, 3);
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.pntBase.Y = Math.Round(ProfileTempVars.PntPatternDxf.Y, 3);
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.pntBase.Z = Math.Round(ProfileTempVars.PntPatternDxf.Y, 3);
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.objectAlignment = ObjectAlignment.TopLeft;
			buProfileCalc.varProfileRunSettings.ShapeDataParameters.selectedCorner = CornerLocation.LeftTop;
		}
		ProfileTempVars.PatternDxfOperation = false;
		FrmOperationList.ClosePageAfterOk = false;
		OPData.Array.CircularEnable = false;
		OPData.Array.LineerEnable = false;
		OPData.Mirror.MirrorEnable = false;
		OPData.CamParMilling = new camParameters5(buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars);
		FrmOperationList.Init();
		FrmOperationList.StartPosition = FormStartPosition.CenterParent;
		if (buProfileCalc.varProfileSettings.OperationWindow == ProfileOperationWindowType.FormPage)
		{
			FrmOperationList.Show();
		}
		FrmOperationList.Top = 50;
		FrmOperationList.Left = Screen.PrimaryScreen.Bounds.Width - FrmOperationList.Width;
	}

