	public void cmdOperation(actionTypeBU action, bool NewOperation = false, ProfileNotchOperationType NotchType = ProfileNotchOperationType.Side)
	{
		if (!((activeProfile.FirstItem == null) & (activeProfile.SecondItem == null)))
		{
			if (action != actionTypeBU.profileFreeDraw)
			{
				buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
				if (profileItem != null)
				{
					if (NewOperation)
					{
						buProfileCalc.varProfileRunSettings.OPData.CamParNotch.Notch.NotchCutType = ProfileNotchCutType.BySaw;
						buProfileCalc.varProfileRunSettings.OPData.Mirror.MirrorEnable = false;
						buProfileCalc.varProfileRunSettings.OPData.Array.CircularEnable = false;
						buProfileCalc.varProfileRunSettings.OPData.Array.LineerEnable = false;
						ToolChangeForced = false;
						buProfileCalc.varProfileRunSettings.OPData.Array.LineerEnable = false;
						buProfileCalc.varProfileRunSettings.OPData.Array.CircularEnable = false;
						buProfileCalc.varProfileRunSettings.OPData.Mirror.MirrorEnable = false;
					}
					ignoreOnlineChange = false;
					if (NewOperation)
					{
						operationEditIndex = -1;
					}
					buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailWidth = profileItem.Length;
					buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailHeight = profileItem.Width;
					buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailDepth = profileItem.Height;
					cntCreateOperation = 0;
					ccVars.Action = action;
					if (!ProfileTempVars.OperationEditing)
					{
						ProfileTempVars.DepthForced = false;
					}
					if (action != actionTypeBU.profileNotch)
					{
						cmdShapes(action);
					}
					else
					{
						cmdNotch(action, NotchType);
					}
				}
			}
			else
			{
				cmdDrawEditor();
			}
		}
		else
		{
			buString5.MessageBoxWarning(buProfile.LangProfileMessage[31]);
		}
	}

	public void cmdAddFromList()
	{
		if (clsItem.FrmFromFile == null)
		{
			clsItem.FrmFromFile = new F_AddFromFile();
		}
		clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
		clsItem.FrmFromFile.Path = clsVar.varEditorRuntimeSet.pathFromFile;
		clsItem.FrmFromFile.KeepRatio = clsVar.varEditorRuntimeSet.FromFileKeepRatio;
		clsItem.FrmFromFile.ExtensionList.Clear();
		clsItem.FrmFromFile.ExtensionList.Add(".dxf");
		clsItem.FrmFromFile.ExtensionList.Add(".dwg");
		clsItem.FrmFromFile.ExtensionList.Add(".bucad5");
		clsItem.FrmFromFile.Init();
		clsItem.FrmFromFile.ShowDialog();
		if (clsItem.FrmFromFile.PropertiesForm.Result == DialogResult.OK)
		{
			clsVar.varEditorRuntimeSet.pathFromFile = clsItem.FrmFromFile.Path;
			clsVar.varEditorRuntimeSet.FromFileKeepRatio = clsItem.FrmFromFile.KeepRatio;
			List<buEntity> list = new List<buEntity>();
			for (int i = 0; i <= clsItem.FrmFromFile.viewport.Entities.Count - 1; i++)
			{
				buEntity copiedEntity = null;
				buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[i], ref copiedEntity);
				list.Add(copiedEntity);
			}
			if (list.Count <= 0)
			{
				buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			}
			else
			{
				doAddExternalEntities(list, Template: false, FileOpen: false);
			}
			clsInit.appEditor.SaveEditorFile();
		}
	}

	public void cmdAddFromFile()
	{
		OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.InitialDirectory = clsVar.varEditorRuntimeSet.pathFromFile;
		openFileDialog.Filter = "Dxf Files (*.dxf)|*.dxf|Dwg Files (*.dwg)|*.dwg|buCad Files (*.bucad5)|*.bucad5";
		openFileDialog.FilterIndex = 1;
		if (openFileDialog.ShowDialog() == DialogResult.OK)
		{
			clsVar.varEditorRuntimeSet.pathFromFile = buFile5.GetPath(openFileDialog.FileName);
			SaveProfileFile();
			FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
			List<Entity> EntityList = new List<Entity>();
			if (fileInfo.Extension.ToLower() == ".dxf")
			{
				buFile5.OpenDxfDwg(ref EntityList, openFileDialog.FileName);
			}
			if (fileInfo.Extension.ToLower() == ".dwg")
			{
				buFile5.OpenDxfDwg(ref EntityList, openFileDialog.FileName);
			}
			List<buEntity> list = new List<buEntity>();
			for (int i = 0; i <= EntityList.Count - 1; i++)
			{
				buEntity copiedEntity = null;
				buEntity.Copy(EntityList[i], ref copiedEntity);
				list.Add(copiedEntity);
			}
			if (list.Count <= 0)
			{
				buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			}
			else
			{
				doAddExternalEntities(list, Template: false, FileOpen: false);
			}
		}
	}

	public void cmdDrawEditor()
	{
		try
		{
			if (clsItem.frmEditor == null)
			{
				clsItem.frmEditor = new F_Editor();
			}
			clsVar.varEditorRuntimeSet.isSketchMode = false;
			clsVar.varEditorRuntimeSet.isSewingMode = false;
			clsItem.frmEditor = new F_Editor();
			clsItem.frmEditor.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.frmEditor.entitiesExisting.Clear();
			if (ProfileTempVars.OperationEditing && activeOP != null && activeOP.EntityMultiXYPlane.Count > 0)
			{
				for (int i = 0; i <= activeOP.EntityMultiXYPlane.Count - 1; i++)
				{
					Entity copiedEntity = null;
					buEntity.Copy(activeOP.EntityMultiXYPlane[i], ref copiedEntity);
					copiedEntity.LayerName = "Default";
					clsItem.frmEditor.entitiesExisting.Add(copiedEntity);
				}
			}
			clsItem.frmEditor.Init();
			clsItem.frmEditor.ShowDialog(clsItem.FrmMain);
			List<buEntity> list = new List<buEntity>();
			for (int j = 0; j <= clsItem.frmEditor.viewport.Entities.Count - 1; j++)
			{
				buEntity copiedEntity2 = null;
				buEntity.Copy(clsItem.frmEditor.viewport.Entities[j], ref copiedEntity2);
				if ((copiedEntity2 != null) & (clsItem.frmEditor.viewport.Entities[j] is ICurve))
				{
					list.Add(copiedEntity2);
				}
			}
			if (list.Count <= 0)
			{
				buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
			}
			else
			{
				doAddExternalEntities(list, Template: false, FileOpen: false);
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdLibrary()
	{
		try
		{
			DirectoryInfo directoryInfo = new DirectoryInfo(clsVar.varLibrary.pathLibrary);
			if (!directoryInfo.Exists)
			{
				clsVar.varLibrary.pathLibrary = AppPath.Base + "\\Library";
			}
			clsInit.appCommand.cmdLibDraw();
			if (clsItem.FrmLibraryDraw.PropertiesForm.Result == DialogResult.OK)
			{
				SketchAnalyseData AnalyseData = new SketchAnalyseData();
				clsInit.appEditor.AnalyseSketchEntity(clsLibrary.LibraryEntities, new SketchAnalyseSetData(0.0), ref AnalyseData);
				List<buEntity> copiedEntities = new List<buEntity>();
				if (AnalyseData.AnalyseEntities.Count > 0)
				{
					buEntity.Copy(AnalyseData.AnalyseEntities, ref copiedEntities);
				}
				if (copiedEntities.Count <= 0)
				{
					buString5.MessageBoxWarning(AppLanguage.CadCamMessages[121]);
				}
				else
				{
					doAddExternalEntities(copiedEntities, Template: false, FileOpen: false);
				}
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdMacro()
	{
		try
		{
			buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
			if (profileItem == null)
			{
				return;
			}
			AppPath.Macro = buProfileCalc.varProfileRunSettings.pathMacro;
			frmMacro.pnl_viewport.Controls.Add(viewportCommon);
			frmMacro.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
			frmMacro.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			frmMacro.Item = new buEyeBaseVer5.Apps.ProfileItem(profileItem);
			frmMacro.Item.Operations.Clear();
			if (frmMacro.Operations.Count > 0)
			{
				buEyeBaseVer5.Apps.ProfileOperation.Copy(frmMacro.Operations, ref frmMacro.Item.Operations);
			}
			frmMacro.Init();
			frmMacro.ShowDialog();
			if (frmMacro.PropertiesForm.Result != DialogResult.OK)
			{
				return;
			}
			buProfileCalc.varProfileRunSettings.pathMacro = AppPath.Macro;
			frmMacro.pnl_viewport.Controls.Clear();
			new ToolBase5(ccVars.toolActive);
			for (int i = 0; i <= frmMacro.Item.Operations.Count - 1; i++)
			{
				list_0.Clear();
				if (frmMacro.Item.Operations[i].Action != actionTypeBU.profileNotch)
				{
					clsInit.cProfile.ProfileCamDataToCamParameter(frmMacro.Item.Operations[i].CamOPData, ref frmMacro.Item.Operations[i].OperationData.CamParMilling);
				}
				else
				{
					clsInit.cProfile.ProfileCamDataToCamParameter(frmMacro.Item.Operations[i].CamOPData, ref frmMacro.Item.Operations[i].OperationData.CamParNotch);
				}
				buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane)frmMacro.Item.Operations[i].OperationData.selectedPlane.Clone();
				string toolName = frmMacro.Item.Operations[i].OperationData.ToolName;
				bool flag;
				if (!(flag = clsInit.cVector5.FindToolWithToolName(ccVars.Tools, frmMacro.Item.Operations[i].OperationData.ToolName, ref ccVars.toolActive)) & (frmMacro.Item.Operations[i].OperationData.ToolDiameter > 0.0))
				{
					flag = clsInit.cVector5.FindToolWithDiameter(ccVars.Tools, frmMacro.Item.Operations[i].OperationData.ToolDiameter, ref ccVars.toolActive);
				}
				if (!flag)
				{
					clsInit.cVector5.FindToolSmallMillingDiameter(ccVars.Tools, ref ccVars.toolActive);
				}
				if ((ccVars.toolActive.Geometry.GeometryType == ToolType.Saw) & (frmMacro.Item.Operations[i].OperationData.Action != actionTypeBU.profileNotch))
				{
					clsInit.cVector5.FindToolSmallMillingDiameter(ccVars.Tools, ref ccVars.toolActive);
				}
				if ((ccVars.toolActive.Geometry.GeometryType != ToolType.Saw) & (frmMacro.Item.Operations[i].OperationData.Action == actionTypeBU.profileNotch))
				{
					frmMacro.Item.Operations[i].Tool = new ToolBase5(ccVars.toolActive);
					for (int j = 0; j <= ccVars.Tools.Count - 1; j++)
					{
						for (int k = 0; k <= ccVars.Tools[j].Tools.Count - 1; k++)
						{
							if (ccVars.Tools[j].Tools[k].Geometry.GeometryType == ToolType.Saw)
							{
								ccVars.toolActive = new ToolBase5(ccVars.Tools[j].Tools[k]);
								frmMacro.Item.Operations[i].ToolNotch = new ToolBase5(ccVars.toolActive);
							}
						}
					}
				}
				ProfileTempVars.CamAssinged = true;
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.SpindleSpeed = ccVars.toolActive.CamData.SpindleSpeed;
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Feed = ccVars.toolActive.CamData.FeedSpeed;
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Plunge = ccVars.toolActive.CamData.PlungeSpeed;
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Finish = ccVars.toolActive.CamData.FinishSpeed;
				if (frmMacro.Item.Operations[i].OperationData.OperationType == ProfileOperationTypes.FreeDraw)
				{
					entSelected = new List<Entity>();
					buEntity.Copy(frmMacro.Item.Operations[i].EntityMultiContour, ref entSelected);
					Point3D MinPoint = new Point3D();
					Point3D MaxPoint = new Point3D();
					clsInit.cVector5.BoxSizeCalculate(entSelected, ref MinPoint, ref MaxPoint);
					buProfileCalc.varProfileRunSettings.FreeDrawOrjinalHeight = MaxPoint.Y - MinPoint.Y;
					buProfileCalc.varProfileRunSettings.FreeDrawOrjinalWidth = MaxPoint.X - MinPoint.X;
				}
				ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg();
				shapeUpdateArg.Finished = true;
				shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
				shapeUpdateArg.Parameters.selectedCorner = frmMacro.Item.Operations[i].OperationData.Corner;
				shapeUpdateArg.Parameters.objectAlignment = frmMacro.Item.Operations[i].OperationData.Alignment;
				shapeUpdateArg.Tool = new ToolBase5(ccVars.toolActive);
				shapeUpdateArg.ToolName = ccVars.toolActive.Data.Name;
				shapeUpdateArg.ToolChangeForced = true;
				shapeUpdateArg.OpenFile = true;
				shapeUpdateArg.NotOriginalTool = !flag;
				shapeUpdateArg.Parameters.Priority = frmMacro.Item.Operations[i].Priority;
				if (!frmMacro.Item.Operations[i].Enable)
				{
					shapeUpdateArg.CommandList.Add("ForceDisable");
				}
				UndoDontProfile = true;
				OPPriority = frmMacro.Item.Operations[i].Priority;
				buShape Item = new buShape();
				Item.BasePoint = new Point3D(frmMacro.Item.Operations[i].OperationData.basePosition.X, Math.Abs(frmMacro.Item.Operations[i].OperationData.basePosition.Y), frmMacro.Item.Operations[i].OperationData.basePosition.Z);
				if (buCompare5.EQ(Item.BasePoint.X, 0.0) & buCompare5.EQ(Item.BasePoint.Y, 0.0) & buCompare5.EQ(Item.BasePoint.Y, 0.0))
				{
					Item.BasePoint.X = frmMacro.Item.Operations[i].OperationData.Position.X;
					Item.BasePoint.Y = frmMacro.Item.Operations[i].OperationData.Position.Y;
					Item.BasePoint.Z = frmMacro.Item.Operations[i].OperationData.Position.Z;
					Item.Corner = CornerLocation.LeftTop;
				}
				clsInit.cVector5.CoordinateFromPlaneAndCorner(new SizeObject(profileItem.Length, profileItem.Width, profileItem.Height), frmMacro.Item.Operations[i].OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(frmMacro.Item.Operations[i].OperationData.selectedPlaneName), ref Item, ref frmMacro.Item.Operations[i].OperationData.Position, shapeCreateParameters_0.SingX, shapeCreateParameters_0.SingY);
				if (frmMacro.Item.Operations[i].Enable)
				{
					OnlineOperation(null, shapeUpdateArg, frmMacro.Item.Operations[i].OperationData);
				}
				if (!flag)
				{
					list_0.Add(buLangTranslate.preSentences.SavedOperationToolNotAvailableInRecentToolList + " " + buLangTranslate.preDef.Tool + " = " + toolName);
				}
				if (list_0.Count > 0)
				{
					for (int l = 0; l <= list_0.Count - 1; l++)
					{
					}
				}
				UndoDontProfile = false;
			}
			OPPriority = 0;
			DrawActiveProfile();
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void cmdEngraving()
	{
		if ((activeProfile.FirstItem == null) & (activeProfile.SecondItem == null))
		{
			return;
		}
		if (clsItem.FrmFromFile == null)
		{
			clsItem.FrmFromFile = new F_AddFromFile();
		}
		clsItem.FrmFromFile.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		clsItem.FrmFromFile.StartPosition = FormStartPosition.CenterParent;
		clsItem.FrmFromFile.Path = buProfileCalc.varProfileRunSettings.pathEngraving;
		clsItem.FrmFromFile.KeepRatio = buProfileCalc.varProfileRunSettings.EngravingKeepRatio;
		clsItem.FrmFromFile.ExtensionList.Clear();
		clsItem.FrmFromFile.ExtensionList.Add(".stl");
		clsItem.FrmFromFile.ExtensionList.Add(".step");
		clsItem.FrmFromFile.ExtensionList.Add(".stp");
		clsItem.FrmFromFile.ExtensionList.Add(".iges");
		clsItem.FrmFromFile.ExtensionList.Add(".igs");
		clsItem.FrmFromFile.Init();
		clsItem.FrmFromFile.ShowDialog();
		if (clsItem.FrmFromFile.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		list_1.Clear();
		list_1 = new List<Entity>();
		for (int i = 0; i <= clsItem.FrmFromFile.viewport.Entities.Count - 1; i++)
		{
			Entity copiedEntity = null;
			if (!(clsItem.FrmFromFile.viewport.Entities[i] is Mesh))
			{
				if (clsItem.FrmFromFile.viewport.Entities[i] is Brep)
				{
					Mesh item = ((Brep)clsItem.FrmFromFile.viewport.Entities[i]).ConvertToMesh();
					list_1.Add(item);
				}
			}
			else
			{
				buEntity.Copy(clsItem.FrmFromFile.viewport.Entities[i], ref copiedEntity);
				list_1.Add(copiedEntity);
			}
		}
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(list_1, ref MinPoint, ref MidPoint, ref MaxPoint);
		clsInit.cVector5.Move(0.0 - MidPoint.X, 0.0 - MidPoint.Y, 0.0 - MinPoint.Z, ref list_1);
		buProfileCalc.varProfileRunSettings.pathEngraving = clsItem.FrmFromFile.Path;
		buProfileCalc.varProfileRunSettings.EngravingKeepRatio = clsItem.FrmFromFile.KeepRatio;
		if (list_1.Count > 0)
		{
			clsInit.cVector5.BoxSizeCalculate(list_1[0], ref MinPoint, ref MidPoint, ref MaxPoint);
			clsVar5.ShapeDataParameters.EngravingWidth = MaxPoint.X - MinPoint.X;
			clsVar5.ShapeDataParameters.EngravingHeight = MaxPoint.Y - MinPoint.Y;
			clsVar5.ShapeDataParameters.EngravingDepth = MaxPoint.Z - MinPoint.Z;
			if (clsItem.FrmEngraveList == null)
			{
				clsItem.FrmEngraveList = new F_EngraveList();
				CreateModelProperties Properties = new CreateModelProperties();
				clsInit.appCommand.EyeParameterToCreateModelProperties(clsVar.varPreviewViewport, clsVar.varMouse, ref Properties);
				Properties.CoordinateSystemIconVisible = false;
				Properties.ViewCubeIconVisible = false;
				Properties.OrigineCaptionVisible = false;
				Properties.ToolBorVisible = false;
				Properties.OrigineSymbol = originSymbolStyleType.CoordinateSystem;
				Properties.OriginSymbolVisible = false;
				Properties.OrigineSize = 3;
				clsItem.FrmEngraveList.viewportLayout = clsInit.cVector5.CreateModelControl(clsVar.UnlockKey, Properties);
				clsItem.FrmEngraveList.viewportLayout.CompileUserInterfaceElements();
				for (int j = 0; j <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; j++)
				{
					clsItem.FrmEngraveList.viewportLayout.Layers.AddOrReplace(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[j]);
				}
			}
			clsVar5.ShapeDataParameters.ShapeGroup = ShapeGroup.Engraving;
			clsItem.FrmEngraveList.parShape = new ShapeRuntimeData(clsVar5.ShapeDataParameters);
			clsItem.FrmEngraveList.selectedShape = new buShapeEngrave(clsVar5.ShapeDataParameters.EngravingDepth, clsVar5.ShapeDataParameters.EngravingWidth, clsVar5.ShapeDataParameters.EngravingHeight, list_1[0]);
			clsItem.FrmEngraveList.selectedShape.CamPar = new camParameters5();
			clsItem.FrmEngraveList.CamPar = new camParameters5();
			clsItem.FrmEngraveList.PropertiesForm.TopMost = true;
			clsItem.FrmEngraveList.PropertiesForm.FormPosition = FormStartPosition.Manual;
			clsItem.FrmEngraveList.StartPosition = FormStartPosition.Manual;
			clsItem.FrmEngraveList.TopMost = true;
			if (clsItem.FrmEngraveList.pnl_model.Controls.Count == 0)
			{
				clsItem.FrmEngraveList.pnl_model.Controls.Add(clsItem.FrmEngraveList.viewportLayout);
			}
			clsItem.FrmEngraveList.viewportLayout.Entities.Clear();
			clsItem.FrmEngraveList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			if (clsItem.FrmMain != null)
			{
				clsItem.FrmEngraveList.Owner = clsItem.FrmMain;
			}
			clsItem.FrmEngraveList.Width = 410;
			if (list_1.Count <= 0)
			{
			}
			buEntity.Copy(list_1, ref clsVar5.shapeCreatePar.entitiesEngraving);
			clsItem.FrmEngraveList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
			clsItem.FrmEngraveList.Init();
			clsItem.FrmEngraveList.StartPosition = FormStartPosition.CenterParent;
			clsItem.FrmEngraveList.Show();
			clsItem.FrmEngraveList.Top = 20;
			clsItem.FrmEngraveList.Left = Screen.PrimaryScreen.Bounds.Width - clsItem.FrmEngraveList.Width;
		}
		SaveByTick = true;
	}

	public void cmdMenuCommand(object sender, EventArgs e)
	{
		string text = "";
		if (!(sender is Control))
		{
			if (sender is ToolStripMenuItem)
			{
				ToolStripMenuItem toolStripMenuItem = sender as ToolStripMenuItem;
				text = toolStripMenuItem.Name;
			}
		}
		else
		{
			Control control = sender as Control;
			text = control.Name;
		}
		if (text == clsItem.FrmProfileJob.mnu_addprofile.Name)
		{
			if (ProfileTempVars.OperationEditing)
			{
				clsInit.appCommand.Reset();
			}
			cmdAddProfile(null);
		}
		if (text == clsItem.FrmProfileJob.mnu_addboxprofile.Name)
		{
			if (ProfileTempVars.OperationEditing)
			{
				clsInit.appCommand.Reset();
			}
			cmdAddProfile(null, BoxProfile: true);
		}
		if (text == clsItem.FrmProfileJob.mnu_disableprofile.Name)
		{
			ProfileTreeUpdate();
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 && activeProfile.FirstItem != null)
			{
				doEnableDisableProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex, Status: false);
			}
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && activeProfile.SecondItem != null)
			{
				doEnableDisableProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex, Status: false);
			}
			DrawActiveProfile();
			ProfileTreeUpdate();
		}
		if (text == clsItem.FrmProfileJob.mnu_enableprofile.Name)
		{
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 && activeProfile.FirstItem != null)
			{
				doEnableDisableProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex, Status: true);
			}
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && activeProfile.SecondItem != null)
			{
				doEnableDisableProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex, Status: true);
			}
			DrawActiveProfile();
			ProfileTreeUpdate();
		}
		if (text == clsItem.FrmProfileJob.mnu_deleteprofile.Name)
		{
			if (ProfileTempVars.OperationEditing)
			{
				clsInit.appCommand.Reset();
			}
			if (activeProfile != null && buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0 && buString5.MessageBoxQuestion(buProfile.LangProfileMessage[19]) == DialogResult.Yes)
			{
				doDeleteProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex);
			}
		}
		if (text == clsItem.FrmProfileJob.mnu_editprofile.Name)
		{
			if (ProfileTempVars.OperationEditing)
			{
				clsInit.appCommand.Reset();
			}
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0)
			{
				doEditProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex);
			}
		}
		if (text == clsItem.FrmProfileJob.mnu_renameprofile.Name)
		{
			if (ProfileTempVars.OperationEditing)
			{
				clsInit.appCommand.Reset();
			}
			DialogBoxText dialogBoxText = new DialogBoxText();
			dialogBoxText.Caption = buLangTranslate.preDef.Profile + " " + AppLanguage.CadCamDynamic[40];
			dialogBoxText.Text = buLangTranslate.preDef.Profile + " " + AppLanguage.CadCamDynamic[40];
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex >= 0)
			{
				dialogBoxText.Init(activeProfile.FirstItem.ItemName);
				dialogBoxText.ShowDialog();
				if (dialogBoxText.Result == DialogResult.OK)
				{
					activeProfile.FirstItem.ItemName = dialogBoxText.Value;
					((TreeNodeSettings)clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex]).Text = buProfileCalc.ProfileToString(activeProfile.FirstItem);
					((TreeNodeSettings)clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex]).Info = dialogBoxText.Value;
				}
			}
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex >= 1)
			{
				dialogBoxText.Init(activeProfile.SecondItem.ItemName);
				dialogBoxText.ShowDialog();
				if (dialogBoxText.Result == DialogResult.OK)
				{
					activeProfile.SecondItem.ItemName = dialogBoxText.Value;
					((TreeNodeSettings)clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex]).Text = buProfileCalc.ProfileToString(activeProfile.SecondItem);
					((TreeNodeSettings)clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex]).Info = dialogBoxText.Value;
				}
			}
		}
		if ((text == clsItem.FrmProfileJob.btn_add.Name) | (text == clsItem.FrmProfileJob.mnu_add.Name))
		{
			cmdOperationMenu();
		}
		if (text == clsItem.FrmProfileJob.mnu_copyprofile.Name)
		{
			if (!((buProfileCalc.varProfileRunSettings.activeProfileIndex == 0) & (activeProfile.FirstItem != null)))
			{
				if (((buProfileCalc.varProfileRunSettings.activeProfileIndex == 1) & (activeProfile.SecondItem != null)) && buString5.MessageBoxQuestion(buProfile.LangProfileMessage[37]) == DialogResult.Yes)
				{
					if (clsItem.FrmProfileJob.chk_selectmode.Checked)
					{
						buEyeBaseVer5.Apps.ProfileItem profileItem = null;
						if (activeProfile.FirstItem != null)
						{
							profileItem = new buEyeBaseVer5.Apps.ProfileItem(activeProfile.SecondItem);
							clsInit.cProfile.CopyJustProfileProperties(activeProfile.FirstItem, ref activeProfile.SecondItem);
						}
						buEyeBaseVer5.Apps.ProfileItem profileItem2 = new buEyeBaseVer5.Apps.ProfileItem(activeProfile.SecondItem);
						profileItem2.XReferanceLocation = LeftRightType.Left;
						profileItem2.Operations.Clear();
						for (int i = 0; i <= activeProfile.SecondItem.Operations.Count - 1; i++)
						{
							if (!activeProfile.SecondItem.Operations[i].Selected)
							{
								continue;
							}
							if (buProfileCalc.varProfileSettings.LeftToRightCopyRotateKeyHole && activeProfile.SecondItem.Operations[i].OperationData.OperationType == ProfileOperationTypes.Barrel)
							{
								activeProfile.SecondItem.Operations[i].OperationData.BarelData.BarrelAngle = activeProfile.SecondItem.Operations[i].OperationData.BarelData.BarrelAngle + 180.0;
								if (activeProfile.SecondItem.Operations[i].OperationData.BarelData.BarrelAngle >= 360.0)
								{
									activeProfile.SecondItem.Operations[i].OperationData.BarelData.BarrelAngle -= 360.0;
								}
							}
							if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile)
							{
								activeProfile.SecondItem.Operations[i].CamOPData.directionContour = buConversion5.ChangeClockDirection(activeProfile.SecondItem.Operations[i].CamOPData.directionContour);
							}
							profileItem2.Operations.Add(activeProfile.SecondItem.Operations[i]);
						}
						SaveProfileJobFile(AppPath.Base + "\\temp.job", profileItem2, AddRecent: false);
						bool jobOpenClearAllProfiles = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
						buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
						OpenProfileJobFile(AppPath.Base + "\\temp.job", AddOperations: true, CreateProfile: true, OnlyDrawing: false, ref activeProfile.FirstItem, AddRecent: false);
						activeProfile.FirstItem.ItemName = activeProfile.FirstItem.ItemName + "_Copy";
						for (int j = 0; j <= activeProfile.FirstItem.Operations.Count - 1; j++)
						{
							activeProfile.FirstItem.Operations[j].Name = activeProfile.FirstItem.Operations[j].Name + "_Copy";
						}
						buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = jobOpenClearAllProfiles;
						if (profileItem != null)
						{
							activeProfile.SecondItem = new buEyeBaseVer5.Apps.ProfileItem(profileItem);
						}
					}
					else
					{
						buEyeBaseVer5.Apps.ProfileItem profileItem3 = null;
						if (activeProfile.FirstItem != null)
						{
							profileItem3 = new buEyeBaseVer5.Apps.ProfileItem(activeProfile.SecondItem);
							clsInit.cProfile.CopyJustProfileProperties(activeProfile.FirstItem, ref activeProfile.SecondItem);
						}
						activeProfile.SecondItem.XReferanceLocation = LeftRightType.Left;
						for (int k = 0; k < activeProfile.SecondItem.Operations.Count - 1; k++)
						{
							if (buProfileCalc.varProfileSettings.LeftToRightCopyRotateKeyHole && activeProfile.SecondItem.Operations[k].OperationData.OperationType == ProfileOperationTypes.Barrel)
							{
								activeProfile.SecondItem.Operations[k].OperationData.BarelData.BarrelAngle = activeProfile.SecondItem.Operations[k].OperationData.BarelData.BarrelAngle + 180.0;
								if (activeProfile.SecondItem.Operations[k].OperationData.BarelData.BarrelAngle >= 360.0)
								{
									activeProfile.SecondItem.Operations[k].OperationData.BarelData.BarrelAngle -= 360.0;
								}
							}
							if (buProfileCalc.varProfileSettings.ChangeCwCCWDirForRightRefProfile)
