		}
		if (text == clsItem.FrmProfileJob.mnu_redraw.Name)
		{
			DrawActiveProfile();
			DrawPreview(new List<Entity>());
			ProfileTreeUpdate();
		}
		if (text == clsItem.FrmProfileJob.mnu_simulation.Name)
		{
			clsInit.appProfile.cmdSimulation(TopMost: false);
		}
	}

