	public void cmdPlaneList()
	{
		F_SelectedPlanes f_SelectedPlanes = new F_SelectedPlanes();
		for (int i = 0; i <= selectedPlanes.Count - 1; i++)
		{
			f_SelectedPlanes.Planes.Add(new SelectedPlaneInfo(selectedPlanes[i]));
			if (selectedPlanes[i].refPlane.Equation == buProfileCalc.varProfileRunSettings.OPData.selectedPlane.Equation)
			{
				f_SelectedPlanes.SelectedPlane = i;
			}
		}
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		if (profileItem.Drawings != null)
		{
			for (int j = 0; j <= profileItem.Drawings.Count - 1; j++)
			{
				Entity entity = buVector5.CopyEntities(profileItem.Drawings[j].SolidEntity);
				entity.ColorMethod = colorMethodType.byEntity;
				entity.Color = Color.FromArgb(180, Color.DarkGray);
				entity.LayerName = "Default";
				f_SelectedPlanes.PreviewEnts.Add(entity);
			}
		}
		f_SelectedPlanes.pathString = buProfileCalc.varProfileRunSettings.pathPlanes;
		f_SelectedPlanes.UcsData = buProfileCalc.varUCSData;
		f_SelectedPlanes.PlaneThickess = buProfileCalc.varProfileSettings.PlaneThickness;
		f_SelectedPlanes.Init();
		f_SelectedPlanes.TopMost = true;
		f_SelectedPlanes.ShowDialog();
		if (f_SelectedPlanes.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		buProfileCalc.varProfileRunSettings.pathPlanes = f_SelectedPlanes.pathString;
		selectedPlanes.Clear();
		selectedPlanes = new List<SelectedPlaneInfo>();
		for (int k = 0; k <= f_SelectedPlanes.Planes.Count - 1; k++)
		{
			selectedPlanes.Add(new SelectedPlaneInfo(f_SelectedPlanes.Planes[k]));
		}
		if (f_SelectedPlanes.Planes.Count > 0 && f_SelectedPlanes.SelectedPlane >= 0)
		{
			if (profileItem.selectedFreePlanes.Count <= 0)
			{
				SelectedPlaneInfo item = new SelectedPlaneInfo(f_SelectedPlanes.Planes[f_SelectedPlanes.SelectedPlane]);
				profileItem.selectedFreePlanes.Add(item);
			}
			else
			{
				SelectedPlaneInfo item2 = new SelectedPlaneInfo(f_SelectedPlanes.Planes[f_SelectedPlanes.SelectedPlane]);
				profileItem.selectedFreePlanes.Clear();
				profileItem.selectedFreePlanes.Add(item2);
			}
			buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane)f_SelectedPlanes.Planes[f_SelectedPlanes.SelectedPlane].refPlane.Clone();
			buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = new SelectedPlaneInfo(f_SelectedPlanes.Planes[f_SelectedPlanes.SelectedPlane]);
		}
		SaveByTick = true;
		if (ccVars.Action != actionTypeBU.None)
		{
			ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg();
			shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			OnlineOperation(null, shapeUpdateArg, null);
		}
	}

