	public void cmdCopyPattern()
	{
		try
		{
			F_ProfilePatternCopy f_ProfilePatternCopy = new F_ProfilePatternCopy();
			f_ProfilePatternCopy.Pattern = new ProfilePatternCopy(buProfileCalc.varProfileRunSettings.PatternCopyDistance, buProfileCalc.varProfileRunSettings.PatternCopyCutSpace, buProfileCalc.varProfileRunSettings.PatternCopyCount);
			f_ProfilePatternCopy.ShowSeperators = buProfileCalc.varProfileRunSettings.PatternShowSeperators;
			f_ProfilePatternCopy.Init();
			f_ProfilePatternCopy.StartPosition = FormStartPosition.CenterParent;
			f_ProfilePatternCopy.ShowDialog();
			if (f_ProfilePatternCopy.Properties.Result == DialogResult.OK)
			{
				double num = (f_ProfilePatternCopy.Pattern.Distance + f_ProfilePatternCopy.Pattern.CutSpace) * (double)f_ProfilePatternCopy.Pattern.Count;
				if (num > activeProfile.FirstItem.Length)
				{
					DialogResult dialogResult = buString5.MessageBoxQuestion(buProfile.LangProfileMessage[23]);
					if (dialogResult != DialogResult.Yes)
					{
						return;
					}
				}
				if (profileOperation_0 != null && f_ProfilePatternCopy.Pattern.Distance < profileOperation_0.MaxPoint.X)
				{
					DialogResult dialogResult2 = buString5.MessageBoxQuestion(buLangTranslate.preSentencesProfile.PatternLengthisLowerThenOperationMaxX);
					if (dialogResult2 != DialogResult.Yes)
					{
						return;
					}
				}
				buProfileCalc.varProfileRunSettings.PatternShowSeperators = f_ProfilePatternCopy.ShowSeperators;
				buProfileCalc.varProfileRunSettings.PatternCopyDistance = f_ProfilePatternCopy.Pattern.Distance;
				buProfileCalc.varProfileRunSettings.PatternCopyCutSpace = f_ProfilePatternCopy.Pattern.CutSpace;
				buProfileCalc.varProfileRunSettings.PatternCopyCount = f_ProfilePatternCopy.Pattern.Count;
				if (buProfileCalc.varProfileRunSettings.PatternCopyCutSpace == 0.0)
				{
					buProfileCalc.varProfileRunSettings.PatternShowSeperators = false;
				}
				doPatternCopy();
			}
			f_ProfilePatternCopy.Dispose();
			GC.Collect();
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

