	public void cmdSimulation(bool TopMost, bool ManuelSim = false, bool ReCalculate = false)
	{
		try
		{
			int num = 0;
			if ((buProfileCalc.varProfileRunSettings.activeProfileIndex == 0) & (activeProfile.FirstItem == null))
			{
				return;
			}
			if (activeProfile.FirstItem != null)
			{
				num += activeProfile.FirstItem.Operations.Count;
			}
			if (activeProfile.SecondItem != null)
			{
				num += activeProfile.SecondItem.Operations.Count;
			}
			if (num != 0)
			{
				buEyeBaseVer5.Apps.ProfileItem Item = activeProfile.FirstItem;
				buEyeBaseVer5.Apps.ProfileItem Item2 = activeProfile.SecondItem;
				bool flag = false;
				bool flag2 = false;
				bool gCodeToSim = false;
				if (Item != null && Item.Enable && Item.Operations.Count > 0)
				{
					flag = true;
					if (!Item.isGCodeCreated | Item.IsClamperDone)
					{
						gCodeToSim = true;
					}
				}
				if (Item2 != null && Item2.Enable && Item2.Operations.Count > 0)
				{
					flag2 = true;
					if (!Item2.isGCodeCreated | Item2.IsClamperDone)
					{
						gCodeToSim = true;
					}
				}
				if (!(!flag && !flag2))
				{
					if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 && !flag)
					{
						buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
					}
					if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && !flag2)
					{
						buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
					}
					List<buEyeBaseVer5.Apps.ProfileClamper> list = new List<buEyeBaseVer5.Apps.ProfileClamper>();
					CollCheckIndex = 0;
					if (flag && !flag2 && Item.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
					{
						Item.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
					}
					if (!flag && flag2 && Item2.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
					{
						Item2.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
					}
					if (flag && flag2)
					{
						Item.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper / 2;
						Item2.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper / 2;
					}
					if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && Item2 == null)
					{
						if (Item == null)
						{
							buString5.MessageBoxWarning(buProfile.LangProfileMessage[38]);
							return;
						}
						buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
					}
					if (frmSim == null)
					{
						frmSim = new F_ProfileSim();
					}
					if (!(Item == null && Item2 == null))
					{
						if (flag && flag2)
						{
							buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
						}
						viewportSimilasyon.Entities.ClearSelection();
						cmdOnlineSimulationStart();
						listToCheck1.Clear();
						listToCheck2.Clear();
						listToCheck3.Clear();
						listToCheck4.Clear();
						if (flag)
						{
							Item.isCollisionOnlineAvailable = false;
							if (Item.CalculationData.Count == 0)
							{
								ManuelSim = false;
							}
							for (int i = 0; i <= Item.Drawings.Count - 1; i++)
							{
								if (Item.Drawings[i].SolidEntity != null)
								{
									Entity entity = buVector5.CopyEntities(Item.Drawings[i].SolidEntity);
									entity.Translate(Item.TotalOffset.X, Item.TotalOffset.Y, Item.TotalOffset.Z);
									entity.Regen(0.1);
									listToCheck3.Add(entity);
								}
							}
						}
						if (flag2)
						{
							Item2.isCollisionOnlineAvailable = false;
							if (Item2.CalculationData.Count == 0)
							{
								ManuelSim = false;
							}
							for (int j = 0; j <= Item2.Drawings.Count - 1; j++)
							{
								if (Item2.Drawings[j].SolidEntity != null)
								{
									double num2 = buProfileCalc.varProfileSettings.MachineLength - Item2.Length;
									Entity entity2 = buVector5.CopyEntities(Item2.Drawings[j].SolidEntity);
									entity2.Translate(Item2.TotalOffset.X + num2, Item2.TotalOffset.Y, Item2.TotalOffset.Z);
									entity2.Regen(0.1);
									listToCheck3.Add(entity2);
								}
							}
						}
						if (!ManuelSim)
						{
							if (!(flag && flag2))
							{
								if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0 && flag)
								{
									if (Item.Operations.Count > 0)
									{
										int num3 = 0;
										if (Item.CalculationData.Count > 0 && Item.CalculationData[0].calcOperations.Count > 0)
										{
											num3 = Item.CalculationData[0].calcOperations[0].Clampers.Count;
										}
										bool flag3 = false;
										flag3 = (((!Item.IsClamperDone || num3 == 0) | buProfileCalc.varProfileSettings.CalculateClamperEveryTime) ? true : false);
										if (!doCalculateAll(ref Item, flag3, Cam: true, gCodeToSim))
										{
											return;
										}
									}
									SimIndex = 0;
									if (Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count <= 0)
									{
										list.Clear();
										for (int k = 0; k <= buProfileCalc.varProfileSettings.ProfileMaxClamper - 1; k++)
										{
											list.Add(new buEyeBaseVer5.Apps.ProfileClamper(Convert.ToDouble(k + 1) * 300.0));
										}
									}
									else
									{
										list = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers;
									}
									ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
								}
								if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && flag2)
								{
									if (Item2.Operations.Count > 0)
									{
										bool flag4 = false;
										flag4 = ((!Item2.IsClamperDone | (Item2.Operations[0].Clampers.Count == 0) | buProfileCalc.varProfileSettings.CalculateClamperEveryTime) ? true : false);
										if (!doCalculateAll(ref Item2, flag4, Cam: true, gCodeToSim))
										{
											return;
										}
									}
									SimIndex = 0;
									if (Item2.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count <= 0)
									{
										list.Clear();
										for (int l = 0; l <= buProfileCalc.varProfileSettings.ProfileMaxClamper - 1; l++)
										{
											list.Add(new buEyeBaseVer5.Apps.ProfileClamper(Convert.ToDouble(l + 1) * 300.0));
										}
									}
									else
									{
										list = Item2.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers;
									}
									ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
								}
							}
							else
							{
								Item.MaxClamperNumber = Clampers.Count / 2;
								Item2.MaxClamperNumber = Clampers.Count / 2;
								bool clamper = true;
								if (Item.IsClamperDone & Item2.IsClamperDone)
								{
									clamper = false;
								}
								if (ReCalculate)
								{
									clamper = true;
								}
								bool flag5 = doCalculateAll(ref Item, clamper, Cam: true, gCodeToSim);
								bool flag6 = false;
								if ((Item2 != null) & buProfileCalc.varProfileSettings.RightProfileActive)
								{
									flag6 = doCalculateAll(ref Item2, clamper, Cam: true, gCodeToSim);
								}
								if (flag5 || flag6)
								{
									if (!flag5)
									{
										buString5.MessageBoxWarning(buLangTranslate.preDef.First + " " + buLangTranslate.preDef.Profile + " " + buProfile.LangProfileMessage[10]);
									}
									if (!flag6)
									{
										buString5.MessageBoxWarning(buLangTranslate.preDef.Second + " " + buLangTranslate.preDef.Profile + " " + buProfile.LangProfileMessage[10]);
									}
									list = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[0].Clampers;
								}
							}
						}
						if (activeProfile.GCodes == null)
						{
							activeProfile.GCodes = new ArrayList();
						}
						activeProfile.GCodes.Clear();
						doSetMissingClampers(ref Item, ref Item2);
						if (flag)
						{
							activeProfile.GCodes.AddRange(Item.GCodeList);
						}
						if (flag2)
						{
							activeProfile.GCodes.AddRange(Item2.GCodeList);
						}
						BasicCollsionControl(ref Item);
						BasicCollsionControl(ref Item2);
						DrawSimulationEntities(Item, Item2, -1, list);
						frmSim.Properties.FormCloseMode = FormCloseModeType.Invisible;
						frmSim.Properties.FormPosition = FormStartPosition.CenterScreen;
						frmSim.TopMost = TopMost;
						frmSim.StartPosition = FormStartPosition.CenterScreen;
						frmSim.Init();
						if (!frmSim.Visible)
						{
							frmSim.ShowDialog();
						}
						if (flag)
						{
							doCheckProfileWarnings(ref Item);
						}
						if (flag2)
						{
							doCheckProfileWarnings(ref Item2);
						}
						doCheckProfileError();
						ProfileTreeUpdate();
					}
					else
					{
						buString5.MessageBoxWarning(buProfile.LangProfileMessage[38]);
					}
				}
				else
				{
					buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.NoActiveProfile);
				}
			}
			else
			{
				buString5.MessageBoxWarning(buProfile.LangProfileMessage[10]);
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

