	public void cmdJobList()
	{
		if (Jobs == null)
		{
			Jobs = new List<buEyeBaseVer5.Apps.ProfileItem>();
		}
		if (Jobs.Count < 0)
		{
			return;
		}
		frmERPList.lst_items.Items.Clear();
		for (int i = 0; i <= Jobs.Count - 1; i++)
		{
			if (Jobs[i] != null)
			{
				frmERPList.lst_items.Items.Add(Jobs[i].ItemName);
			}
		}
		frmERPList.chk_deleteloaded.Checked = buProfileCalc.varProfileRunSettings.JobListDeleteLoaded;
		frmERPList.PropertiesForm.FormCloseMode = FormCloseModeType.Invisible;
		frmERPList.radio_rightholder.Visible = buProfileCalc.varProfileSettings.RightProfileActive;
		frmERPList.pathString = buProfileCalc.varProfileRunSettings.pathJobList;
		frmERPList.Init();
		if (!frmERPList.Visible)
		{
			frmERPList.ShowDialog();
		}
		if (frmERPList.PropertiesForm.Result != DialogResult.OK)
		{
			return;
		}
		SaveByTick = true;
		buProfileCalc.varProfileRunSettings.pathJobList = frmERPList.pathString;
		buProfileCalc.varProfileRunSettings.JobListDeleteLoaded = frmERPList.chk_deleteloaded.Checked;
		if ((frmERPList.SelectedJob >= 0) & (frmERPList.SelectedJob <= Jobs.Count - 1))
		{
			if (!frmERPList.isLeftHolder)
			{
				activeProfile.SecondItem = new buEyeBaseVer5.Apps.ProfileItem(Jobs[frmERPList.SelectedJob]);
				clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].ForeColor = Color.Red;
				buProfileCalc.varProfileSettings.XDirRefType = activeProfile.SecondItem.XReferanceLocation;
				clsInit.appProfile.doSetActiveProfile(1);
			}
			else
			{
				activeProfile.FirstItem = new buEyeBaseVer5.Apps.ProfileItem(Jobs[frmERPList.SelectedJob]);
				clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].ForeColor = Color.Red;
				buProfileCalc.varProfileSettings.XDirRefType = activeProfile.FirstItem.XReferanceLocation;
				clsInit.appProfile.doSetActiveProfile(0);
			}
			if (buProfileCalc.varProfileRunSettings.JobListDeleteLoaded)
			{
				Jobs.RemoveAt(frmERPList.SelectedJob);
			}
			DrawActiveProfile();
			ProfileTreeUpdate();
		}
	}

