	public void cmdInchToMm()
	{
		buMWProfileVars.varCamContour.buPar.InchToMm();
		buMWProfileVars.varCamRough.buPar.InchToMm();
		buProfileCalc.varProfileRunSettings.OPData.CamParMilling.InchToMm();
		buProfileCalc.varProfileRunSettings.OPData.CamParNotch.InchToMm();
		buProfileCalc.varProfileRunSettings.CamParNotch.InchToMm();
		buProfileCalc.varProfileRunSettings.ShapeDataParameters.InchToMm();
		buProfileCalc.varProfileRunSettings.OPData.InchToMm();
		ToolBase5.InchToMm(ref ccVars.Tools[0].Tools);
		buProfileCalc.varProfileRunSettings.ArrayData.LineerXDistance = Math.Round(buProfileCalc.varProfileRunSettings.ArrayData.LineerXDistance * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.ArrayData.LineerYDistance = Math.Round(buProfileCalc.varProfileRunSettings.ArrayData.LineerYDistance * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.MirrorData.MirrorDistance = Math.Round(buProfileCalc.varProfileRunSettings.MirrorData.MirrorDistance * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.NewProfileWidth = Math.Round(buProfileCalc.varProfileRunSettings.NewProfileWidth * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.NewProfileHeight = Math.Round(buProfileCalc.varProfileRunSettings.NewProfileHeight * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.NewProfileThickness = Math.Round(buProfileCalc.varProfileRunSettings.NewProfileThickness * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.FreeDrawOrjinalWidth = Math.Round(buProfileCalc.varProfileRunSettings.FreeDrawOrjinalWidth * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.FreeDrawOrjinalHeight = Math.Round(buProfileCalc.varProfileRunSettings.FreeDrawOrjinalHeight * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.PatternCopyDistance = Math.Round(buProfileCalc.varProfileRunSettings.PatternCopyDistance * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.PatternCopyCutSpace = Math.Round(buProfileCalc.varProfileRunSettings.PatternCopyCutSpace * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.TemplateOffset = Math.Round(buProfileCalc.varProfileRunSettings.TemplateOffset * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.ProfileLength = Math.Round(buProfileCalc.varProfileRunSettings.ProfileLength * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.SupportBlockZHeight = Math.Round(buProfileCalc.varProfileRunSettings.SupportBlockZHeight * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.SupportBlockY1Height = Math.Round(buProfileCalc.varProfileRunSettings.SupportBlockY1Height * buSystem.InchToMmRatio, 5);
		buProfileCalc.varProfileRunSettings.SupportBlockY2Height = Math.Round(buProfileCalc.varProfileRunSettings.SupportBlockY2Height * buSystem.InchToMmRatio, 5);
