	public void cmdDefaultValues()
	{
		if (AppSecurity.PasswordLevel >= 2)
		{
			if (buString5.MessageBoxQuestion(buLangTranslate.preSentences.DoyouWantToTurnDefaultValues) == DialogResult.Yes)
			{
				Directory.Delete(AppPath.Settings, recursive: true);
				Directory.CreateDirectory(AppPath.Settings);
				buFile5.CopyFilesRecursively(AppPath.DefaultParameter, AppPath.Settings);
			}
		}
		else
		{
			buString5.MessageBoxWarning(buLangTranslate.preSentences.LevelIsNotEnough);
		}
	}

	public void Checked_Checked(object sender, EventArgs e)
	{
		buProfileCalc.varProfileRunSettings.SelectMode = clsItem.FrmProfileJob.chk_selectmode.Checked;
		clsItem.FrmProfileJob.tree_jobs.CheckBoxes = buProfileCalc.varProfileRunSettings.SelectMode;
		if (clsItem.FrmProfileJob.tree_jobs.Nodes != null && clsItem.FrmProfileJob.tree_jobs.Nodes.Count >= 1)
		{
			clsItem.FrmProfileJob.tree_jobs.Nodes[0].Expand();
			if (clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes != null)
			{
				if (clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes.Count >= 1)
				{
					clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].Expand();
				}
				if (clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes.Count >= 2)
				{
					clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].Expand();
				}
			}
		}
		if (!clsItem.FrmProfileJob.chk_selectmode.Checked)
		{
			clsItem.FrmProfileJob.mnu_remove.Text = buLangTranslate.preDef.Delete + " " + buLangTranslate.preDef.Operation;
		}
		else
		{
			clsItem.FrmProfileJob.mnu_remove.Text = buLangTranslate.preDef.Delete + " " + buLangTranslate.preDef.Selected + " " + buLangTranslate.preDef.Operation;
		}
		if (!buProfileCalc.varProfileRunSettings.SelectMode)
		{
			Changing = true;
			doUnSelectProfile(buProfileCalc.varProfileRunSettings.activeProfileIndex);
			for (int i = 0; i <= clsItem.FrmProfileJob.tree_jobs.Nodes.Count - 1; i++)
			{
				clsItem.FrmProfileJob.tree_jobs.Nodes[i].Expand();
			}
			Changing = false;
		}
	}

	private void viewportSimilasyon_WorkCompleted(object sender, WorkCompletedEventArgs e)
	{
		try
		{
			if (clsInit.appProfile.timSim.Enabled)
			{
				isCollisionRunning = false;
				if (colDetect.Result == null)
				{
					viewportSimilasyon.TempEntities.Clear();
				}
				else if (colDetect.Result.Length != 0)
				{
					Class5.smethod_165((IList<CollisionResult>)colDetect.Result, this);
					timSim.Enabled = false;
					viewportSimilasyon.Invalidate();
				}
				CollCheckIndex++;
				if (CollCheckIndex >= 2)
				{
					CollCheckIndex = 0;
				}
			}
		}
		catch (Exception)
		{
		}
	}

	private void viewportSimilasyon_WorkFailed(object sender, WorkFailedEventArgs e)
	{
		isCollisionRunning = false;
		viewportSimilasyon.TempEntities.Clear();
	}

	private void viewportSimilasyon_WorkCancelled(object sender, EventArgs e)
	{
		isCollisionRunning = false;
		viewportSimilasyon.TempEntities.Clear();
	}

	public void DrawMacroEntities(buEyeBaseVer5.Apps.ProfileItem FirstProfile, bool cam = true, bool contour = true)
	{
		viewportCommon.Entities.Clear();
		CustomData customData = null;
		double num = 0.0;
		if (FirstProfile != null)
		{
			for (int i = 0; i <= FirstProfile.Drawings.Count - 1; i++)
			{
				if (FirstProfile.Drawings[i].SolidEntity != null)
				{
					Entity entity = buVector5.CopyEntities(FirstProfile.Drawings[i].SolidEntity);
					entity.Color = Color.FromArgb(buProfileCalc.varProfileSettings.MaterialTranspancy, FirstProfile.colorProfile);
					entity.ColorMethod = colorMethodType.byEntity;
					customData = new CustomData();
					customData.typeDefination = entityTypeDefination.Profile;
					customData.ActionName = "profile";
					customData.EntityName = "FirstProfile";
					customData.OriginalEntityIndex = viewportCommon.Entities.Count;
					entity.EntityData = customData;
					entity.Translate(FirstProfile.TotalOffset.X + num, FirstProfile.TotalOffset.Y, FirstProfile.TotalOffset.Z);
					entity.Regen(0.01);
					entity.LayerName = "Profile";
					viewportCommon.Entities.Add(entity);
				}
			}
			for (int j = 0; j <= FirstProfile.Operations.Count - 1; j++)
			{
				buEyeBaseVer5.Apps.ProfileOperation profileOperation = FirstProfile.Operations[j];
				if (profileOperation == null || profileOperation.EntityMultiSolidDepth == null)
				{
					continue;
				}
				for (int k = 0; k <= profileOperation.EntityMultiSolidDepth.Count - 1; k++)
				{
					Entity copiedEnt = null;
					buVector5.CopyEntities(profileOperation.EntityMultiSolidDepth[k], ref copiedEnt);
					((CustomData)copiedEnt.EntityData).OriginalEntityIndex = viewportCommon.Entities.Count;
					((CustomData)copiedEnt.EntityData).RefIndex = 0;
					((CustomData)copiedEnt.EntityData).Sequence = j;
					((CustomData)copiedEnt.EntityData).typeDefination = entityTypeDefination.Operation;
					copiedEnt.ColorMethod = colorMethodType.byEntity;
					copiedEnt.LineTypeMethod = colorMethodType.byEntity;
					if (!profileOperation.Enable)
					{
						copiedEnt.Color = Color.FromArgb(150, Color.Orange);
					}
					else
					{
						copiedEnt.Color = Color.FromArgb(150, Color.Cyan);
					}
					if (profileOperation.Error)
					{
						copiedEnt.Color = Color.FromArgb(180, Color.Red);
					}
					copiedEnt.LineWeight = 1f;
					copiedEnt.Translate(FirstProfile.TotalOffset.X + num, FirstProfile.TotalOffset.Y, FirstProfile.TotalOffset.Z);
					copiedEnt.Regen(0.01);
					copiedEnt.LayerName = "Operation";
					viewportCommon.Entities.Add(copiedEnt);
				}
				if (cam)
				{
					for (int l = 0; l <= profileOperation.EntityMultiCam.Count - 1; l++)
					{
						Entity copiedEntity = null;
						buEntity.Copy(profileOperation.EntityMultiCam[l], ref copiedEntity);
						((CustomData)copiedEntity.EntityData).OriginalEntityIndex = viewportCommon.Entities.Count;
						copiedEntity.ColorMethod = colorMethodType.byEntity;
						copiedEntity.LineTypeMethod = colorMethodType.byEntity;
						copiedEntity.Color = Color.Red;
						copiedEntity.LineWeight = 2f;
						copiedEntity.Translate(FirstProfile.TotalOffset.X + num, FirstProfile.TotalOffset.Y, FirstProfile.TotalOffset.Z);
						copiedEntity.Regen(0.01);
						copiedEntity.LayerName = "Cam";
						if (profileOperation.Action == actionTypeBU.profileNotch && profileOperation.EntityMultiCam[l].Info.Offset != null)
						{
							copiedEntity.Translate(profileOperation.EntityMultiCam[l].Info.Offset.X, profileOperation.EntityMultiCam[l].Info.Offset.Y, profileOperation.EntityMultiCam[l].Info.Offset.Z);
						}
						viewportCommon.Entities.Add(copiedEntity);
					}
				}
				if (contour)
				{
					for (int m = 0; m <= profileOperation.EntityMultiContour.Count - 1; m++)
					{
						Entity copiedEntity2 = null;
						buEntity.Copy(profileOperation.EntityMultiContour[m], ref copiedEntity2);
						((CustomData)copiedEntity2.EntityData).OriginalEntityIndex = viewportCommon.Entities.Count;
						copiedEntity2.ColorMethod = colorMethodType.byEntity;
						copiedEntity2.LineTypeMethod = colorMethodType.byEntity;
						copiedEntity2.Color = Color.Lime;
						copiedEntity2.LineWeight = 2f;
						copiedEntity2.Translate(FirstProfile.TotalOffset.X + num, FirstProfile.TotalOffset.Y, FirstProfile.TotalOffset.Z);
						copiedEntity2.Regen(0.01);
						copiedEntity2.LayerName = "Drawing";
						viewportCommon.Entities.Add(copiedEntity2);
					}
				}
			}
		}
		viewportCommon.Invalidate();
	}

	private void viewportSimilasyon_MouseDown(object sender, MouseEventArgs e)
	{
		if (e.Button != MouseButtons.Left || viewportSimilasyon.ActionMode != actionType.None || viewportSimilasyon.Viewports[0].ToolBar.Contains(e.Location))
		{
			return;
		}
		if (!buProfileCalc.varTemps.MeasureActive)
		{
			entityIndex = viewportSimilasyon.GetEntityUnderMouseCursor(e.Location);
		}
		if ((entityIndex < 0) & !buProfileCalc.varTemps.MeasureActive)
		{
			return;
		}
		if (entityIndex >= 0)
		{
			if (viewportSimilasyon.Entities[entityIndex].EntityData == null)
			{
				entityIndex = -1;
				return;
			}
			CustomData customData = (CustomData)viewportSimilasyon.Entities[entityIndex].EntityData;
			if (customData.typeDefination != entityTypeDefination.Clamper)
			{
				entityIndex = -1;
				return;
			}
		}
		viewportSimilasyon.ScreenToPlane(e.Location, planeActive, out point3D_0);
		if ((point3D_0 != null) & !buProfileCalc.varTemps.MeasureActive)
		{
			point3D_1 = new Point3D(point3D_0.X, point3D_0.Y, point3D_0.Z);
		}
		if (buProfileCalc.varTemps.MeasureActive & !buProfileCalc.varTemps.DrawMouseDown)
		{
			buProfileCalc.varTemps.DrawMouseDown = true;
			buProfileCalc.varTemps.pntMouseDown = new Point3D(point3D_0.X, point3D_0.Y, point3D_0.Z);
		}
	}

	private void viewportSimilasyon_MouseMove(object sender, MouseEventArgs e)
	{
		Point3D intPoint = new Point3D();
		viewportSimilasyon.ScreenToPlane(e.Location, planeActive, out intPoint);
		if (intPoint != null && frmSim != null && frmSim != null)
		{
			frmSim.lbl_x.Text = "X: " + intPoint.X.ToString("f3");
			frmSim.lbl_y.Text = "Y: " + intPoint.Y.ToString("f3");
			frmSim.lbl_z.Text = "Z: " + intPoint.Z.ToString("f3");
		}
		if ((e.Button != MouseButtons.Left || viewportSimilasyon.ActionMode != actionType.None || viewportSimilasyon.Viewports[0].ToolBar.Contains(e.Location)) & !buProfileCalc.varTemps.MeasureActive)
		{
			return;
		}
		if (entityIndex != -1 && ((e.Button == MouseButtons.Left) & !buProfileCalc.varTemps.MeasureActive))
		{
			Entity entity = viewportSimilasyon.Entities[entityIndex];
			buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
			viewportSimilasyon.ScreenToPlane(e.Location, new Plane(), out var intPoint2);
			if (intPoint2 != null)
			{
				if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
				{
					double num = profileItem.Length;
					if (!buProfileCalc.varProfileSettings.ClamperCanMoveInsideProfileLength)
					{
						num = buProfileCalc.varProfileSettings.MachineLength;
					}
					if ((intPoint2.X >= 0.0) & (intPoint2.X <= num))
					{
						if (point3D_0 != null)
						{
							Vector3D v = Vector3D.Subtract(new Point3D(intPoint2.X, 0.0, 0.0), new Point3D(point3D_0.X, 0.0, 0.0));
							entity.Translate(v);
						}
						viewportSimilasyon.Entities.Regen();
						viewportSimilasyon.Invalidate();
					}
				}
				if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
				{
					double num2 = buProfileCalc.varProfileSettings.MachineLength - profileItem.Length;
					if (!buProfileCalc.varProfileSettings.ClamperCanMoveInsideProfileLength)
					{
						num2 = 0.0;
					}
					if ((intPoint2.X >= num2) & (intPoint2.X <= buProfileCalc.varProfileSettings.MachineLength))
					{
						if (point3D_0 != null)
						{
							Vector3D v2 = Vector3D.Subtract(new Point3D(intPoint2.X, 0.0, 0.0), new Point3D(point3D_0.X, 0.0, 0.0));
							entity.Translate(v2);
						}
						viewportSimilasyon.Entities.Regen();
						viewportSimilasyon.Invalidate();
					}
				}
				point3D_0 = intPoint2;
			}
		}
		if (buProfileCalc.varTemps.MeasureActive & buProfileCalc.varTemps.DrawMouseDown)
		{
			DrawMeasureLine(intPoint, Finished: false);
		}
	}

	private void viewportSimilasyon_MouseUp(object sender, MouseEventArgs e)
	{
		if (entityIndex >= 0)
		{
			buEyeBaseVer5.Apps.ProfileItem curItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
			if ((viewportSimilasyon.Entities[entityIndex].EntityData != null) & (curItem.CalculationData.Count > 0))
			{
				CustomData customData = viewportSimilasyon.Entities[entityIndex].EntityData as CustomData;
				ProfileItemCalc CalcData = curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex];
				if ((customData.typeDefination == entityTypeDefination.Clamper) & (point3D_1 != null))
				{
					viewportSimilasyon.ScreenToPlane(e.Location, new Plane(), out point3D_2);
					_ = customData.RefIndex;
					if (point3D_2 != null)
					{
						ClamperMove(point3D_2.X - point3D_1.X, customData.RefIndex, ref curItem, ref CalcData, ClamperListUpdate: true);
					}
					return;
				}
			}
		}
		if (buProfileCalc.varTemps.MeasureActive & buProfileCalc.varTemps.DrawMouseDown)
		{
			viewportSimilasyon.ScreenToPlane(e.Location, planeActive, out point3D_2);
			DrawMeasureLine(point3D_2, Finished: true);
			buProfileCalc.varTemps.MeasureActive = false;
			buProfileCalc.varTemps.DrawMouseDown = false;
		}
		entityIndex = -1;
	}

