	public void DrawMeasureLine(Point3D pntMove, bool Finished)
	{
		if (viewportSimilasyon.Entities.Count > 0)
		{
			Entity entity = viewportSimilasyon.Entities[viewportSimilasyon.Entities.Count - 1];
			if (entity.EntityData != null && entity.EntityData is CustomData && ((((CustomData)entity.EntityData).typeDefination == entityTypeDefination.TempDraw) | (((CustomData)entity.EntityData).typeDefination == entityTypeDefination.TempText)))
			{
				viewportSimilasyon.Entities.RemoveAt(viewportSimilasyon.Entities.Count - 1);
			}
			entity = viewportSimilasyon.Entities[viewportSimilasyon.Entities.Count - 1];
			if (entity.EntityData != null && entity.EntityData is CustomData && ((((CustomData)entity.EntityData).typeDefination == entityTypeDefination.TempDraw) | (((CustomData)entity.EntityData).typeDefination == entityTypeDefination.TempText)))
			{
				viewportSimilasyon.Entities.RemoveAt(viewportSimilasyon.Entities.Count - 1);
			}
		}
		devDept.Eyeshot.Entities.Line line = new devDept.Eyeshot.Entities.Line(buProfileCalc.varTemps.pntMouseDown, new Point3D(pntMove.X, pntMove.Y, pntMove.Z));
		double num = clsInit.cVector5.PointAngle(new Point3D(pntMove.X, pntMove.Y, pntMove.Z), buProfileCalc.varTemps.pntMouseDown, planeActive);
		double num2 = num % 90.0;
		if (num2 < 2.0)
		{
		}
		line.Color = Color.Black;
		line.ColorMethod = colorMethodType.byEntity;
		line.LineWeight = 2f;
		line.LineWeightMethod = colorMethodType.byEntity;
		CustomData customData = new CustomData();
		customData.typeDefination = entityTypeDefination.TempDraw;
		line.EntityData = customData;
		viewportSimilasyon.Entities.Add(line);
		Text text = new Text(planeActive, pntMove, "  " + ((ICurve)line).Length().ToString("f2"), 20.0, Text.alignmentType.MiddleLeft);
		text.Color = Color.Black;
		text.ColorMethod = colorMethodType.byEntity;
		customData = new CustomData();
		customData.typeDefination = entityTypeDefination.TempText;
		text.EntityData = customData;
		viewportSimilasyon.Entities.Add(text);
		viewportSimilasyon.Invalidate();
	}

	public void Sim_Tick(object sender, EventArgs e)
	{
		try
		{
			if (isCollisionRunning)
			{
				return;
			}
			listToCheck2.Clear();
			listToCheck4.Clear();
			bool flag = false;
			ToolBase5 tool = new ToolBase5();
			int num = buProfileCalc.varProfileRunSettings.SimStep;
			if (frmSim.chk_collisiondetect.Checked && num < buProfileCalc.varProfileSettings.CollisionControlMinStep)
			{
				num = buProfileCalc.varProfileSettings.CollisionControlMinStep;
			}
			buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
			if (profileItem == null)
			{
				return;
			}
			if (SimIndex == 0)
			{
				list_4.Clear();
			}
			if (!((profileItem.CalculationData.Count > 0) & profileItem.Enable))
			{
				if (buProfileCalc.varProfileRunSettings.activeProfileIndex != 0 || activeProfile.SecondItem == null)
				{
					if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1 && activeProfile.FirstItem != null)
					{
						buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
					}
					SimIndex = -1;
					DeleteAllSimPartsFromViewport();
					if ((profileItem.CalculationData.Count > 0) & (buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeCalcDataIndex <= profileItem.CalculationData.Count - 1))
					{
						ProfileItemCalc profileItemCalc = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex];
						if (profileItemCalc.SimMoves.Count > 0)
						{
							Pnt6DSimMove pnt6DSimMove = new Pnt6DSimMove(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves.Count - 1]);
							pnt6DSimMove.A = 0.0;
							pnt6DSimMove.Z = 100.0;
							List<buEyeBaseVer5.Apps.ProfileClamper> list = new List<buEyeBaseVer5.Apps.ProfileClamper>();
							if (pnt6DSimMove.Clampers != null)
							{
								for (int i = 0; i <= pnt6DSimMove.Clampers.Count - 1; i++)
								{
									if (pnt6DSimMove.Clampers[i] > 0.0)
									{
										list.Add(new buEyeBaseVer5.Apps.ProfileClamper(pnt6DSimMove.Clampers[i]));
									}
								}
							}
							MoveSimPart(pnt6DSimMove, list, tool, profileItemCalc);
						}
					}
					timSim.Enabled = false;
					if (activeProfile.FirstItem != null)
					{
						activeProfile.FirstItem.isSimulationDone = true;
						activeProfile.FirstItem.isCollisionControlDone = frmSim.chk_collisiondetect.Checked;
					}
					if (activeProfile.SecondItem != null)
					{
						activeProfile.SecondItem.isSimulationDone = true;
						activeProfile.SecondItem.isCollisionControlDone = frmSim.chk_collisiondetect.Checked;
					}
					activeProfile.isSimulationDone = true;
				}
				else
				{
					buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
					SimIndex = 0;
				}
				return;
			}
			if (!((SimIndex >= 0) & (SimIndex < profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves.Count - 1)))
			{
				if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
				{
					if (activeProfile.FirstItem != null)
					{
						if (buProfileCalc.varProfileRunSettings.activeCalcDataIndex < profileItem.CalculationData.Count - 1)
						{
							buProfileCalc.varProfileRunSettings.activeCalcDataIndex++;
							SimIndex = 0;
							return;
						}
						buProfileCalc.varProfileRunSettings.activeCalcDataIndex = 0;
						activeProfile.FirstItem.isSimulationDone = true;
						activeProfile.FirstItem.isCollisionControlDone = frmSim.chk_collisiondetect.Checked;
					}
					if (activeProfile.SecondItem != null)
					{
						buProfileCalc.varProfileRunSettings.activeCalcDataIndex = 0;
						buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
						SimIndex = 0;
						return;
					}
				}
				if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
				{
					if (buProfileCalc.varProfileRunSettings.activeCalcDataIndex < profileItem.CalculationData.Count - 1)
					{
						buProfileCalc.varProfileRunSettings.activeCalcDataIndex++;
						SimIndex = 0;
						return;
					}
					if (activeProfile.FirstItem != null)
					{
						buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
					}
					if (activeProfile.SecondItem != null)
					{
						activeProfile.SecondItem.isSimulationDone = true;
						activeProfile.SecondItem.isCollisionControlDone = frmSim.chk_collisiondetect.Checked;
					}
				}
				ProfileItemCalc profileItemCalc2 = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex];
				if (profileItemCalc2.SimMoves.Count > 0)
				{
					Pnt6DSimMove pnt6DSimMove2 = new Pnt6DSimMove(profileItemCalc2.SimMoves[profileItemCalc2.SimMoves.Count - 1]);
					pnt6DSimMove2.A = 0.0;
					pnt6DSimMove2.Z = buProfileCalc.varProfileSettings.ParkPositionZ + ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + 100.0;
					List<buEyeBaseVer5.Apps.ProfileClamper> list2 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
					if (pnt6DSimMove2.Clampers != null)
					{
						for (int j = 0; j <= pnt6DSimMove2.Clampers.Count - 1; j++)
						{
							if (pnt6DSimMove2.Clampers[j] > 0.0)
							{
								list2.Add(new buEyeBaseVer5.Apps.ProfileClamper(pnt6DSimMove2.Clampers[j]));
							}
						}
					}
					if ((buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeCalcDataIndex <= profileItem.CalculationData.Count - 1))
					{
						MoveSimPart(pnt6DSimMove2, list2, tool, profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex]);
					}
				}
				SimIndex = -1;
				DeleteAllSimPartsFromViewport();
				viewportSimilasyon.Invalidate();
				timSim.Enabled = false;
				activeProfile.isSimulationDone = true;
				return;
			}
			viewportSimilasyon.TempEntities.Clear();
			if (viewportSimilasyon.Entities.Count > 0)
			{
				viewportSimilasyon.Entities.ClearSelection();
				for (int k = 0; k <= viewportSimilasyon.Entities.Count - 1; k++)
				{
					CustomData customData = viewportSimilasyon.Entities[k].EntityData as CustomData;
					if ((customData.typeDefination == entityTypeDefination.Temp) | (customData.typeDefination == entityTypeDefination.TempDraw) | (customData.typeDefination == entityTypeDefination.TempText))
					{
						viewportSimilasyon.Entities[k].Selected = true;
					}
				}
				viewportSimilasyon.Entities.DeleteSelected();
			}
			Pnt6DSimMove pnt6DSimMove3 = new Pnt6DSimMove(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[SimIndex]);
			if (pnt6DSimMove3.ToolName == null)
			{
				pnt6DSimMove3.ToolName = "";
			}
			for (int l = 0; l <= ccVars.Tools[0].Tools.Count - 1; l++)
			{
				if (ccVars.Tools[0].Tools[l].Data.Name == pnt6DSimMove3.ToolName)
				{
					tool = new ToolBase5(ccVars.Tools[0].Tools[l]);
				}
			}
			List<buEyeBaseVer5.Apps.ProfileClamper> list3 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
			if (pnt6DSimMove3.Clampers != null)
			{
				for (int m = 0; m <= pnt6DSimMove3.Clampers.Count - 1; m++)
				{
					if (pnt6DSimMove3.Clampers[m] > 0.0)
					{
						list3.Add(new buEyeBaseVer5.Apps.ProfileClamper(pnt6DSimMove3.Clampers[m]));
					}
				}
			}
			if (((list3.Count > 0) & (list_4.Count > 0)) && list3.Count == list_4.Count)
			{
				for (int n = 0; n <= list3.Count - 1; n++)
				{
					if (!buCompare5.EQ(list3[n].XPosition, list_4[n].XPosition, 0.01))
					{
						flag = true;
					}
				}
			}
			if (frmSim != null && frmSim.Visible)
			{
				frmSim.txt_simx.Text = pnt6DSimMove3.X.ToString("f3");
				frmSim.txt_simy.Text = pnt6DSimMove3.Y.ToString("f3");
				frmSim.txt_simz.Text = pnt6DSimMove3.Z.ToString("f3");
				frmSim.txt_sima.Text = pnt6DSimMove3.A.ToString("f3");
				frmSim.txt_simt.Text = pnt6DSimMove3.ToolNo.ToString("");
				frmSim.txt_simf.Text = pnt6DSimMove3.FeedRate.ToString("f1");
				frmSim.txt_sims.Text = pnt6DSimMove3.SpindleRpm.ToString();
				frmSim.txt_command.Text = pnt6DSimMove3.Command;
				frmSim.panel5.Refresh();
			}
			pnt6DSimMove3.Z += profileItem.SupportBlock.SupportBlockZHeight;
			pnt6DSimMove3.Y -= profileItem.SupportBlock.SupportBlockY2BackWidth;
			if (flag)
			{
				double[,] array = new double[list3.Count, 10];
				for (int num2 = 0; num2 <= list3.Count - 1; num2++)
				{
					List<double> Values = new List<double>();
					buNumeric5.DevideMinMaxValueByNumber(list_4[num2].XPosition, list3[num2].XPosition, 10, ref Values);
					for (int num3 = 0; num3 <= Values.Count - 1; num3++)
					{
						array[num2, num3] = Values[num3];
					}
				}
				if (array.Length > 0)
				{
					for (int num4 = 0; num4 < 10; num4 += 2)
					{
						List<buEyeBaseVer5.Apps.ProfileClamper> list4 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
						for (int num5 = 0; num5 <= list3.Count - 1; num5++)
						{
							list4.Add(new buEyeBaseVer5.Apps.ProfileClamper(array[num5, num4]));
						}
						if ((list4.Count > 0) & (buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeCalcDataIndex <= profileItem.CalculationData.Count - 1))
						{
							MoveSimPart(pnt6DSimMove3, list4, tool, profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex]);
						}
					}
				}
			}
			if ((buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeCalcDataIndex <= profileItem.CalculationData.Count - 1))
			{
				MoveSimPart(pnt6DSimMove3, list3, tool, profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex]);
			}
			if (list3.Count > 0)
			{
				list_4.Clear();
				list_4 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
				for (int num6 = 0; num6 <= list3.Count - 1; num6++)
				{
					list_4.Add(new buEyeBaseVer5.Apps.ProfileClamper(list3[num6]));
				}
			}
			if (!viewportSimilasyon.IsBusy & (CollCheckIndex == 0))
			{
				CollisionCheck();
			}
			if (!viewportSimilasyon.IsBusy & (CollCheckIndex >= 1))
			{
				CollisionCheckWithProfileAndHead();
			}
			viewportSimilasyon.Invalidate();
			bool flag2 = false;
			for (int num7 = SimIndex; num7 <= SimIndex + num; num7++)
			{
				if (num7 <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves.Count - 1)
				{
					if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[num7].isMCode)
					{
						flag2 = true;
					}
					if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[num7].Clampers != null && profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].SimMoves[num7].Clampers.Count > 0)
					{
						flag2 = true;
					}
				}
			}
			if (!flag2)
			{
				SimIndex += num;
			}
			else
			{
				SimIndex++;
			}
		}
		catch (Exception)
		{
			timSim.Enabled = false;
		}
	}

	public void DeleteSimulationTempEntities()
	{
		viewportSimilasyon.Entities.ClearSelection();
		for (int i = 0; i <= viewportSimilasyon.Entities.Count - 1; i++)
		{
			CustomData customData = viewportSimilasyon.Entities[i].EntityData as CustomData;
			if ((customData.typeDefination == entityTypeDefination.Temp) | (customData.typeDefination == entityTypeDefination.TempDraw) | (customData.typeDefination == entityTypeDefination.TempText))
			{
				viewportSimilasyon.Entities[i].Selected = true;
			}
		}
		viewportSimilasyon.Entities.DeleteSelected();
	}

	public void DrawSimulationEntities(buEyeBaseVer5.Apps.ProfileItem FirstProfile, buEyeBaseVer5.Apps.ProfileItem SecondProfile, int OperationIndex, List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList, double ProfileXOffset = 0.0, double RotateFirstProfile = 0.0, double RotateSecondProfile = 0.0)
	{
