	}

	public void DrawSimulationEntities(buEyeBaseVer5.Apps.ProfileItem FirstProfile, buEyeBaseVer5.Apps.ProfileItem SecondProfile, bool profile, bool support, bool operation, bool clamper, bool cam, bool machine, bool machinebody, bool contour, int OperationIndex, List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList, double ProfileXOffset = 0.0, double RotateFirstProfile = 0.0, double RotateSecondProfile = 0.0)
	{
		list_5.Clear();
		viewportSimilasyon.Entities.Clear();
		buProfileCalc.varProfileRunSettings.activeOPIndex = OperationIndex;
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		for (int i = 0; i <= ccVars.SimMachine.MachineParts.Count - 1; i++)
		{
			bool flag = true;
			if ((ccVars.SimMachine.MachineParts[i].PartName.ToLower().IndexOf("cover") >= 0) & !buProfileCalc.varProfileSettings.ShowCabinet)
			{
				flag = false;
			}
			if (!machinebody && ccVars.SimMachine.MachineParts[i].isBelongToBody)
			{
				flag = false;
			}
			if (flag)
			{
				for (int j = 0; j <= ccVars.SimMachine.MachineParts[i].Entities.Count - 1; j++)
				{
					buMachinePart buMachinePart2 = new buMachinePart(ccVars.SimMachine.MachineParts[i].PartName);
					buMachinePart2.ARotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.A;
					buMachinePart2.BRotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.B;
					buMachinePart2.CRotation = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.C;
					buMachinePart2.XMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.X;
					buMachinePart2.YMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.Y;
					buMachinePart2.ZMove = ccVars.SimMachine.MachineParts[i].MoveAxisPermision.Z;
					buMachinePart2.xRot = ccVars.SimMachine.MachineParts[i].RotationCenter.X;
					buMachinePart2.yRot = ccVars.SimMachine.MachineParts[i].RotationCenter.Y;
					buMachinePart2.zRot = ccVars.SimMachine.MachineParts[i].RotationCenter.Z;
					buMachinePart2.Color = ccVars.SimMachine.MachineParts[i].Color;
					buMachinePart2.ColorMethod = colorMethodType.byEntity;
					double dx = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.X + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.X;
					double dy = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.Y + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.Y;
					double dz = ccVars.SimMachine.MachineParts[i].PositionBaseOffset.Z + ccVars.SimMachine.MachineParts[i].PositionAuxOffset.Z;
					buMachinePart2.Translate(dx, dy, dz);
					buMachinePart2.Regen(new RegenParams(buSystem.RegenDeviation, viewportSimilasyon));
					CustomData customData = new CustomData();
					customData.typeDefination = entityTypeDefination.MachineBody;
					customData.OriginalEntityIndex = viewportSimilasyon.Entities.Count;
					customData.EntityName = ccVars.SimMachine.MachineParts[i].PartName;
					buMachinePart2.EntityData = customData;
					buMachinePart2.ColorMethod = colorMethodType.byEntity;
					buMachinePart2.Color = ccVars.SimMachine.MachineParts[i].Color;
					buMachinePart2.Regen(new RegenParams(0.01, viewportSimilasyon));
					buMachinePart2.LayerName = "Machine";
					viewportSimilasyon.Entities.Add(buMachinePart2);
					list_5.Add(viewportSimilasyon.Entities.Count - 1);
				}
			}
		}
		if (FirstProfile != null && FirstProfile.Enable)
		{
			DrawSimulationEntities(FirstProfile, 0, profile, support, operation, clamper, cam, machine, machinebody, contour, OperationIndex, ClamperList, ProfileXOffset, RotateFirstProfile);
		}
		if (SecondProfile != null && SecondProfile.Enable)
		{
			DrawSimulationEntities(SecondProfile, 1, profile, support, operation, clamper, cam, machine, machinebody, contour, OperationIndex, ClamperList, ProfileXOffset, RotateSecondProfile);
		}
		List<buEyeBaseVer5.Apps.ProfileClamper> list = new List<buEyeBaseVer5.Apps.ProfileClamper>();
		if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count <= 0)
		{
			if (ClamperList.Count > 0)
			{
				for (int k = 0; k <= ClamperList.Count - 1; k++)
				{
					list.Add(new buEyeBaseVer5.Apps.ProfileClamper(ClamperList[k]));
				}
			}
		}
		else
		{
			GProfileOperation gProfileOperation = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex];
			for (int l = 0; l <= gProfileOperation.Clampers.Count - 1; l++)
			{
				buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper(gProfileOperation.Clampers[l]);
				if (l == gProfileOperation.CollisionClamperIndex)
				{
					profileClamper.isCollision = gProfileOperation.isCollision;
				}
				list.Add(profileClamper);
			}
		}
		if (clamper && list.Count > 0)
		{
			for (int m = 0; m <= list.Count - 1; m++)
			{
				bool flag2 = false;
				bool flag3 = false;
				for (int n = 0; n <= viewportSimilasyon.Blocks.Count - 1; n++)
				{
					if (viewportSimilasyon.Blocks[n].Name == "Clamper")
					{
						flag2 = true;
					}
					if (viewportSimilasyon.Blocks[n].Name == "ClamperMove")
					{
						flag3 = true;
					}
				}
				if (flag2)
				{
					string text = "Clamper";
					if (list[m].isCollision)
					{
						text = "ClamperCollision";
					}
					buMachinePart buMachinePart3 = new buMachinePart(text);
					CustomData customData2 = new CustomData();
					customData2.typeDefination = entityTypeDefination.Clamper;
					customData2.EntityName = text + m;
					customData2.RefIndex = m;
					customData2.OriginalEntityIndex = viewportSimilasyon.Entities.Count;
					buMachinePart3.EntityData = customData2;
					buMachinePart3.XMove = true;
					buMachinePart3.YMove = true;
					buMachinePart3.xPos = list[m].XPosition;
					buMachinePart3.ColorMethod = colorMethodType.byEntity;
					buMachinePart3.LineTypeMethod = colorMethodType.byEntity;
					buMachinePart3.Color = Color.DarkOrange;
					buMachinePart3.LineWeight = 2f;
					buMachinePart3.LayerName = "Clamper";
					buMachinePart3.Regen(new RegenParams(0.01, viewportSimilasyon));
					viewportSimilasyon.Entities.Add(buMachinePart3);
					list_5.Add(viewportSimilasyon.Entities.Count - 1);
				}
				if (flag3)
				{
					string text2 = "ClamperMove";
					if (list[m].isCollision)
					{
						text2 = "ClamperMoveCollision";
					}
					buMachinePart buMachinePart4 = new buMachinePart(text2);
					CustomData customData3 = new CustomData();
					customData3.typeDefination = entityTypeDefination.Clamper;
					customData3.EntityName = text2 + m;
					customData3.RefIndex = m;
					customData3.OriginalEntityIndex = viewportSimilasyon.Entities.Count;
					buMachinePart4.EntityData = customData3;
					buMachinePart4.xPos = list[m].XPosition;
					buMachinePart4.yPos = 0.0 - profileItem.Height - 40.0;
					buMachinePart4.XMove = true;
					buMachinePart4.YMove = true;
					buMachinePart4.ColorMethod = colorMethodType.byEntity;
					buMachinePart4.LineTypeMethod = colorMethodType.byEntity;
					buMachinePart4.Color = Color.DarkRed;
					buMachinePart4.LineWeight = 2f;
					buMachinePart4.LayerName = "Clamper";
					buMachinePart4.Regen(new RegenParams(0.01, viewportSimilasyon));
					viewportSimilasyon.Entities.Add(buMachinePart4);
					list_5.Add(viewportSimilasyon.Entities.Count - 1);
				}
			}
		}
		MovePark();
		DrawGhostClamp(frmSim.selectedOP, frmSim.selectedCalcItem);
		viewportSimilasyon.Entities.Regen(new RegenOptions());
		viewportSimilasyon.Invalidate();
	}

	public void DrawSimulationEntities(buEyeBaseVer5.Apps.ProfileItem Item, int ProfileIndex, bool profile, bool support, bool operation, bool clamper, bool cam, bool machine, bool machinebody, bool contour, int OperationIndex, List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList, double ProfileXOffset = 0.0, double RotateProfile = 0.0)
	{
		double num = 0.0;
		double num2 = Item.Length;
		int cntProfile = 0;
		CustomData customData = null;
		clsInit.cProfile.TotalWidthOfProfile(ref Item, ref cntProfile);
		if (num2 > buProfileCalc.varProfileSettings.MachineLength)
		{
			num2 = buProfileCalc.varProfileSettings.MachineLength;
		}
		for (int i = 0; i <= cntProfile; i++)
		{
			if (buProfileCalc.varProfileRunSettings.activeOPIndex < 0 && Item.CalculationData.Count > 0 && Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count > 0)
			{
				buProfileCalc.varProfileRunSettings.activeOPIndex = 0;
			}
			if (Item.XReferanceLocation == LeftRightType.Right)
			{
				num = buProfileCalc.varProfileSettings.MachineLength - Item.Length;
			}
			if (support)
			{
				if (Item.SupportBlock.SupportBlockZHeight > 0.0)
				{
					double num3 = Item.Width + Item.SupportBlock.SupportBlockY1FrontWidth + Item.SupportBlock.SupportBlockY2BackWidth;
					CompositeCurve outer = CompositeCurve.CreateRectangle(Plane.YZ, num3, Item.SupportBlock.SupportBlockZHeight);
					devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer);
					Brep brep = region.ExtrudeAsBrep(new Vector3D(num2, 0.0, 0.0));
					brep.Color = Item.colorSupportBlock;
					brep.ColorMethod = colorMethodType.byEntity;
					brep.Translate(0.0, 0.0 - num3);
					customData = new CustomData();
					customData.typeDefination = entityTypeDefination.SupportBlock;
					customData.EntityName = "SupportBlock1_" + ProfileIndex;
					brep.EntityData = customData;
					brep.LayerName = "SupportBlock";
					double num4 = 0.0;
					if (Item.MultiplyProfile.ProfileMultiplyEnable)
					{
						if (Item.MultiplyProfile.ProfileMultiplyMirror)
						{
							if (i >= 1)
							{
								Plane plane = new Plane(new Point3D(0.0, (0.0 - Item.TotalWidth) / 2.0, 0.0), Vector3D.AxisZ, Vector3D.AxisX);
								Mirror xform = new Mirror(plane);
								brep.TransformBy(xform);
							}
						}
						else
						{
							num4 = (Item.Width + Item.MultiplyProfile.ProfileMultiplySpace) * (double)i;
						}
					}
					brep.Translate(num, 0.0 - num4);
					viewportSimilasyon.Entities.Add(brep);
				}
				if ((Item.SupportBlock.SupportBlockY1FrontWidth > 0.0) & (Item.SupportBlock.SupportBlockY1FrontHeight > 0.0))
				{
					double supportBlockY1FrontWidth = Item.SupportBlock.SupportBlockY1FrontWidth;
					CompositeCurve outer2 = CompositeCurve.CreateRectangle(Plane.YZ, supportBlockY1FrontWidth, Item.SupportBlock.SupportBlockY1FrontHeight);
					devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region(outer2);
					Brep brep2 = region2.ExtrudeAsBrep(new Vector3D(num2, 0.0, 0.0));
					brep2.Color = Item.colorSupportBlock;
					brep2.ColorMethod = colorMethodType.byEntity;
					brep2.Translate(0.0, 0.0 - Item.SupportBlock.SupportBlockY1FrontWidth - Item.SupportBlock.SupportBlockY2BackWidth - Item.Width, Item.SupportBlock.SupportBlockZHeight);
					customData = new CustomData();
					customData.typeDefination = entityTypeDefination.Clamper;
					customData.EntityName = "SupportBlock2_" + ProfileIndex;
					brep2.EntityData = customData;
					brep2.LayerName = "SupportBlock";
					double num5 = 0.0;
					if (Item.MultiplyProfile.ProfileMultiplyEnable)
					{
						if (Item.MultiplyProfile.ProfileMultiplyMirror)
						{
							if (i >= 1)
							{
								Plane plane2 = new Plane(new Point3D(0.0, (0.0 - Item.TotalWidth) / 2.0, 0.0), Vector3D.AxisZ, Vector3D.AxisX);
								Mirror xform2 = new Mirror(plane2);
								brep2.TransformBy(xform2);
							}
						}
						else
						{
							num5 = (Item.Width + Item.MultiplyProfile.ProfileMultiplySpace) * (double)i;
						}
					}
					brep2.Translate(num, 0.0 - num5);
					viewportSimilasyon.Entities.Add(brep2);
				}
				if ((Item.SupportBlock.SupportBlockY2BackWidth > 0.0) & (Item.SupportBlock.SupportBlockY2BackHeight > 0.0))
				{
					double supportBlockY2BackWidth = Item.SupportBlock.SupportBlockY2BackWidth;
					CompositeCurve outer3 = CompositeCurve.CreateRectangle(Plane.YZ, supportBlockY2BackWidth, Item.SupportBlock.SupportBlockY2BackHeight);
					devDept.Eyeshot.Entities.Region region3 = new devDept.Eyeshot.Entities.Region(outer3);
					Brep brep3 = region3.ExtrudeAsBrep(new Vector3D(num2, 0.0, 0.0));
					brep3.Color = Item.colorSupportBlock;
					brep3.ColorMethod = colorMethodType.byEntity;
					brep3.Translate(0.0, 0.0 - supportBlockY2BackWidth, Item.SupportBlock.SupportBlockZHeight);
					customData = new CustomData();
					customData.typeDefination = entityTypeDefination.Clamper;
					customData.EntityName = "SupportBlock3_" + ProfileIndex;
					brep3.EntityData = customData;
					brep3.LayerName = "SupportBlock";
					double num6 = 0.0;
					if (Item.MultiplyProfile.ProfileMultiplyEnable)
					{
						if (Item.MultiplyProfile.ProfileMultiplyMirror)
						{
							if (i >= 1)
							{
								Plane plane3 = new Plane(new Point3D(0.0, (0.0 - Item.TotalWidth) / 2.0, 0.0), Vector3D.AxisZ, Vector3D.AxisX);
								Mirror xform3 = new Mirror(plane3);
								brep3.TransformBy(xform3);
							}
						}
						else
						{
							num6 = (Item.Width + Item.MultiplyProfile.ProfileMultiplySpace) * (double)i;
						}
					}
					brep3.Translate(num, 0.0 - num6);
					viewportSimilasyon.Entities.Add(brep3);
				}
			}
			for (int j = 0; j <= Item.Drawings.Count - 1; j++)
			{
				if (!(Item.Drawings[j].SolidEntity != null && profile))
				{
					continue;
				}
				Entity entity = buVector5.CopyEntities(Item.Drawings[j].SolidEntity);
				entity.Translate(ProfileXOffset, 0.0);
				if (RotateProfile != 0.0)
				{
					entity.Rotate(buConversion5.DegreeToRadian(RotateProfile), Vector3D.AxisX, new Point3D(0.0, (0.0 - Item.Width) / 2.0, Item.Height / 2.0));
				}
				entity.Color = Color.FromArgb(buProfileCalc.varProfileSettings.MaterialTranspancy, Item.colorProfile);
				entity.ColorMethod = colorMethodType.byEntity;
				customData = new CustomData();
				customData.typeDefination = entityTypeDefination.Profile;
				customData.ActionName = "profile_" + ProfileIndex;
				customData.EntityName = "Item_" + ProfileIndex;
				customData.OriginalEntityIndex = viewportSimilasyon.Entities.Count;
				entity.EntityData = customData;
				double num7 = 0.0;
				if (Item.MultiplyProfile.ProfileMultiplyEnable)
				{
					if (Item.MultiplyProfile.ProfileMultiplyMirror)
					{
						if (i >= 1)
						{
							Plane plane4 = new Plane(new Point3D(0.0, (0.0 - Item.TotalWidth) / 2.0, 0.0), Vector3D.AxisZ, Vector3D.AxisX);
							Mirror xform4 = new Mirror(plane4);
							entity.TransformBy(xform4);
						}
					}
					else
					{
						num7 = (Item.Width + Item.MultiplyProfile.ProfileMultiplySpace) * (double)i;
					}
				}
				entity.Translate(Item.TotalOffset.X + num, Item.TotalOffset.Y - num7, Item.TotalOffset.Z);
				entity.Regen(0.01);
				entity.LayerName = "Profile";
				viewportSimilasyon.Entities.Add(entity);
			}
			if (Item.CalculationData.Count <= 0)
			{
				continue;
			}
			if (Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count <= 0)
			{
				if (Item.Operations.Count > 0)
				{
					_ = Item.Operations.Count;
				}
			}
			else
			{
				_ = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count;
			}
			for (int k = 0; k <= Item.CalculationData.Count - 1; k++)
			{
				if (Item.CalculationData[k].calcOperations.Count <= 0)
				{
					continue;
				}
				for (int l = 0; l <= Item.CalculationData[k].calcOperations.Count - 1; l++)
				{
					buEyeBaseVer5.Apps.ProfileOperation profileOperation = null;
					GProfileOperation gProfileOperation = Item.CalculationData[k].calcOperations[l];
					for (int m = 0; m <= Item.Operations.Count - 1; m++)
					{
						if (Item.Operations[m].ID == Item.CalculationData[k].calcOperations[l].ID)
						{
							profileOperation = Item.Operations[m];
						}
					}
					if (profileOperation == null)
					{
						continue;
					}
					if (operation)
					{
						for (int n = 0; n <= profileOperation.EntityMultiSolidDepth.Count - 1; n++)
						{
							Entity copiedEnt = null;
							buVector5.CopyEntities(profileOperation.EntityMultiSolidDepth[n], ref copiedEnt);
							((CustomData)copiedEnt.EntityData).OriginalEntityIndex = viewportSimilasyon.Entities.Count;
							((CustomData)copiedEnt.EntityData).RefIndex = 0;
							((CustomData)copiedEnt.EntityData).Sequence = l;
							((CustomData)copiedEnt.EntityData).GroupIdIndex = k;
							((CustomData)copiedEnt.EntityData).typeDefination = entityTypeDefination.Operation;
							copiedEnt.ColorMethod = colorMethodType.byEntity;
							copiedEnt.LineTypeMethod = colorMethodType.byEntity;
							if (!profileOperation.Enable)
							{
								copiedEnt.Color = Color.FromArgb(150, Color.Orange);
							}
							else
							{
								copiedEnt.Color = Color.FromArgb(150, Color.Cyan);
							}
							if (gProfileOperation.Error | gProfileOperation.isCollision)
