	public void DeleteAllSimPartsFromViewport()
	{
		for (int i = 0; i <= viewportSimilasyon.Entities.Count - 1; i++)
		{
			if (viewportSimilasyon.Entities[i].EntityData != null)
			{
				CustomData customData = viewportSimilasyon.Entities[i].EntityData as CustomData;
				if ((customData.typeDefination == entityTypeDefination.Tool) | (customData.typeDefination == entityTypeDefination.ToolParts))
				{
					viewportSimilasyon.Entities[i].Selected = true;
				}
			}
		}
		bool flag = false;
		for (int j = 0; j <= viewportSimilasyon.Blocks.Count - 1; j++)
		{
			if (viewportSimilasyon.Blocks[j].Name == "Tool")
			{
				flag = true;
			}
		}
		if (flag)
		{
			viewportSimilasyon.Blocks.Remove("Tool");
		}
		viewportSimilasyon.Entities.DeleteSelected();
		viewportSimilasyon.Invalidate();
	}

	public void SimMachinePartAdd(ToolBase5 Tool, KinematicBase5 Kinematic)
	{
		try
		{
			List<Mesh> refMeshes = new List<Mesh>();
			clsInit.appMW.CreateTool(Tool, ToolCut: true, Tool.Geometry.DrawLength, Tool.Geometry.DrawArbor, Tool.Geometry.DrawHolder, ref refMeshes);
			Block block = new Block("Tool");
			string_0 = Tool.Data.Name;
			new Mesh();
			if (refMeshes.Count != 1)
			{
				for (int i = 0; i <= refMeshes.Count - 1; i++)
				{
					refMeshes[i].ColorMethod = colorMethodType.byEntity;
					if (Tool.Geometry.GeometryType == ToolType.Saw)
					{
						refMeshes[i].Translate(0.0 + Kinematic.MovePartRuntimeOffset.X, 0.0 + Kinematic.MovePartRuntimeOffset.Y, Kinematic.MovePartRuntimeOffset.Z);
					}
					refMeshes[i].Regen(0.1);
					block.Entities.Add(refMeshes[i]);
				}
			}
			else
			{
				for (int j = 0; j <= refMeshes.Count - 1; j++)
				{
					refMeshes[j].ColorMethod = colorMethodType.byEntity;
					if (Tool.Geometry.GeometryType == ToolType.Saw)
					{
						refMeshes[j].Translate(0.0 + Kinematic.MovePartRuntimeOffset.X, 0.0 + Kinematic.MovePartRuntimeOffset.Y, Kinematic.MovePartRuntimeOffset.Z);
					}
					refMeshes[j].Regen(0.1);
					block.Entities.Add(refMeshes[j]);
				}
			}
			for (int num = viewportSimilasyon.Blocks.Count - 1; num >= 0; num--)
			{
				if (viewportSimilasyon.Blocks[num].Name == "Tool")
				{
					viewportSimilasyon.Blocks.RemoveAt(num);
				}
			}
			viewportSimilasyon.Blocks.Add(block);
			buTool buTool2 = new buTool("Tool");
			CustomData customData = new CustomData();
			customData.typeDefination = entityTypeDefination.Tool;
			buTool2.EntityData = customData;
			buTool2.CRotation = Tool.Limits.RotationC;
			buTool2.BRotation = Tool.Limits.RotationB;
			buTool2.ARotation = true;
			buTool2.Regen(new RegenParams(buSystem.RegenDeviation, viewportSimilasyon));
			viewportSimilasyon.Entities.Add(buTool2);
			list_5.Clear();
			for (int k = 0; k <= viewportSimilasyon.Entities.Count - 1; k++)
			{
				customData = viewportSimilasyon.Entities[k].EntityData as CustomData;
				if ((customData.typeDefination == entityTypeDefination.Tool) | (customData.typeDefination == entityTypeDefination.MachineParts) | (customData.typeDefination == entityTypeDefination.MachineBody) | (customData.typeDefination == entityTypeDefination.Clamper))
				{
					list_5.Add(k);
				}
			}
			viewportSimilasyon.Invalidate();
		}
		catch (Exception mSException)
		{
			string text = "Tool: " + Tool.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void CollisionCheck()
	{
		if ((listToCheck1.Count > 0) & (listToCheck2.Count > 0))
		{
			colDetect = new CollisionDetection(listToCheck1, listToCheck2, viewportSimilasyon.Blocks, firstOnly: false, collisionCheckType.OBWithSubdivisionTree);
			if (!isCollisionRunning && frmSim.chk_collisiondetect.Checked)
			{
				isCollisionRunning = true;
				viewportSimilasyon.StartWork(colDetect);
			}
		}
	}

	public void CollisionCheckWithProfileAndHead()
	{
		colDetect = new CollisionDetection(listToCheck3, listToCheck4, viewportSimilasyon.Blocks, firstOnly: false, collisionCheckType.OBWithSubdivisionTree);
		if (!isCollisionRunning && frmSim.chk_collisiondetect.Checked)
		{
			isCollisionRunning = true;
			viewportSimilasyon.StartWork(colDetect);
		}
	}

	public void MoveSimPart(Pnt6DSimMove PntMove, List<buEyeBaseVer5.Apps.ProfileClamper> ClampersPosition, ToolBase5 Tool, ProfileItemCalc ItemCalc)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		if (Tool != null && Tool.Data.Name != string_0)
		{
			DeleteAllSimPartsFromViewport();
			SimMachinePartAdd(Tool, ccVars.KinematicOrjinal);
		}
		if (ClampersPosition.Count > 0)
		{
			listToCheck1.Clear();
