	public void MovePark()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = null;
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == -1)
		{
			return;
		}
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
		{
			profileItem = activeProfile.FirstItem;
			if (profileItem == null || !profileItem.Enable)
			{
				return;
			}
		}
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
		{
			if (activeProfile.SecondItem == null)
			{
				return;
			}
			profileItem = activeProfile.SecondItem;
		}
		Pnt6DSimMove pntMove = new Pnt6DSimMove(buProfileCalc.varProfileSettings.ParkPositionX, buProfileCalc.varProfileSettings.ParkPositionY, buProfileCalc.varProfileSettings.ParkPositionZ + ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + 100.0, 0.0, 0.0, 0.0);
		MoveSimPart(pntMove, new List<buEyeBaseVer5.Apps.ProfileClamper>(), null, null);
	}

	public void BasicCollsionControl(ref buEyeBaseVer5.Apps.ProfileItem Item)
	{
		if (Item != null)
		{
			for (int i = 0; i <= Item.CalculationData.Count - 1; i++)
			{
				for (int j = 0; j <= Item.CalculationData[i].calcOperations.Count - 1; j++)
				{
					bool flag = false;
					GProfileOperation gProfileOperation = Item.CalculationData[i].calcOperations[j];
					ClamperLeftRightPars Calc = new ClamperLeftRightPars();
					doClamperOpLeftRightLimits(Item, Item.CalculationData[i], gProfileOperation, ref Calc, buProfileCalc.varProfileClamperSettings.ClamperWidth);
					gProfileOperation.Error = false;
					gProfileOperation.isCollision = false;
					gProfileOperation.CollisionClamperIndex = -1;
					double num = 0.0;
					if (gProfileOperation.OperationData.OperationType == ProfileOperationTypes.Notch)
					{
						buEyeBaseVer5.Apps.ProfileOperation foundOP = null;
						clsInit.cProfile.FindOperationFromCalculatedOperationsByID(Item, gProfileOperation.ID, ref foundOP);
						if ((gProfileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal || gProfileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side) && foundOP != null)
						{
							num = foundOP.ToolNotch.Geometry.Diameter / 2.0;
						}
					}
					if (gProfileOperation.SizePoint.MinPoint.Z + Item.SupportBlock.SupportBlockZHeight + num > buProfileCalc.varProfileClamperSettings.ClamperMaxHeight)
					{
						flag = true;
					}
					if (!(((Calc.LeftMinDis > 0.0) | (Calc.LeftMaxDis > 0.0) | (Calc.RightMinDis > 0.0) | (Calc.RightMaxDis > 0.0)) && !flag))
					{
						continue;
					}
					double minPointX = gProfileOperation.SizePoint.MinPoint.X;
					double maxPointX = gProfileOperation.SizePoint.MaxPoint.X;
					double num2 = Calc.LeftMinDis;
					double num3 = Calc.RightMinDis;
					if (Item.CalculationData[i].XReferanceLocation == LeftRightType.Right)
					{
						if (!buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
						{
							minPointX = buProfileCalc.varProfileSettings.MachineLength - Item.CalculationData[i].Length + gProfileOperation.SizePoint.MinPoint.X;
							maxPointX = buProfileCalc.varProfileSettings.MachineLength - Item.CalculationData[i].Length + gProfileOperation.SizePoint.MaxPoint.X;
							num3 = Calc.RightMinDis;
							num2 = Calc.LeftMinDis;
						}
						else
						{
							minPointX = buProfileCalc.varProfileSettings.MachineLength - gProfileOperation.SizePoint.MaxPoint.X;
							maxPointX = buProfileCalc.varProfileSettings.MachineLength - gProfileOperation.SizePoint.MinPoint.X;
							num2 = Calc.RightMinDis;
							num3 = Calc.LeftMinDis;
						}
					}
					for (int k = 0; k <= gProfileOperation.Clampers.Count - 1; k++)
					{
						if (clsInit.cProfile.isClamperInsideOperationRange(minPointX, maxPointX, num2 - 1.0, num3 - 1.0, gProfileOperation.Clampers[k].XPosition, buProfileCalc.varProfileClamperSettings.ClamperWidth))
						{
							gProfileOperation.Error = true;
							gProfileOperation.isCollision = true;
							gProfileOperation.CollisionClamperIndex = k;
						}
					}
				}
			}
		}
		frmSim.UpdateTreeOperation();
	}

	public void DrawPreview(List<Entity> TempEntities)
	{
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
		{
			DrawPreview(activeProfile.FirstItem, TempEntities);
		}
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
		{
			DrawPreview(activeProfile.SecondItem, TempEntities);
		}
	}

	public void DrawPreview(buEyeBaseVer5.Apps.ProfileItem Profile, List<Entity> TempEntities, bool isPreview = true)
	{
		if (CancelPreview)
		{
			return;
		}
		Design design = null;
		design = (isPreview ? clsItem.ModelMainPreview : frmERPList.viewportPort);
		if (design == null)
		{
			return;
		}
		design.Entities.Clear();
		design.Invalidate();
		if (Profile == null)
		{
			return;
		}
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; i++)
		{
			if (!clsInit.cVector5.IsLayerNameAvailable(design.Layers, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Name))
			{
				Layer item = new Layer(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Name, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Color);
				design.Layers.Add(item);
			}
		}
		for (int j = 0; j <= Profile.Drawings.Count - 1; j++)
		{
			if (Profile.Drawings[j].SolidEntity != null)
			{
				Entity entity = buVector5.CopyEntities(Profile.Drawings[j].SolidEntity);
				entity.Regen(buSystem.RegenDeviation);
				if (!isPreview)
				{
					entity.Color = Color.FromArgb(70, entity.Color);
				}
				design.Entities.Add(entity);
			}
		}
		for (int k = 0; k <= Profile.Operations.Count - 1; k++)
		{
			if (Profile.Operations[k].EntityMultiSolidDepth != null)
			{
				for (int l = 0; l <= Profile.Operations[k].EntityMultiSolidDepth.Count - 1; l++)
				{
					Entity entity2 = buVector5.CopyEntities(Profile.Operations[k].EntityMultiSolidDepth[l]);
					entity2.Color = buProfileCalc.varProfileSettings.PreviewDoneOperationColor;
					entity2.ColorMethod = colorMethodType.byEntity;
					design.Entities.Add(entity2);
				}
			}
		}
		if (buProfileCalc.varProfileSettings.ShowPreviewSides && isPreview && (buNumeric5.IsNumeric(Profile.Height.ToString()) & buNumeric5.IsNumeric(Profile.Width.ToString())))
		{
			if (buProfileCalc.varProfileSettings.YDirection != ProfileYAxisDirection.NegativeDirection)
			{
				Mesh mesh = Mesh.CreateBox(buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, Profile.Height + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight);
				mesh.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
				mesh.ColorMethod = colorMethodType.byEntity;
				mesh.Translate(0.0, 0.0 - buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
				design.Entities.Add(mesh);
				Mesh mesh2 = Mesh.CreateBox(2.0, Profile.Width + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight, buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
				mesh2.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
				mesh2.ColorMethod = colorMethodType.byEntity;
				mesh2.Translate(0.0, 0.0 - buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, 0.0 - buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
				design.Entities.Add(mesh2);
			}
			else
			{
				Mesh mesh3 = Mesh.CreateBox(buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness, Profile.Height + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight);
				mesh3.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
				mesh3.ColorMethod = colorMethodType.byEntity;
				design.Entities.Add(mesh3);
				Mesh mesh4 = Mesh.CreateBox(2.0, Profile.Width + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight, buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
				mesh4.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
				mesh4.ColorMethod = colorMethodType.byEntity;
				mesh4.Translate(0.0, 0.0 - (Profile.Width + buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingExtraHeight - buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness), 0.0 - buProfileCalc.varProfileSettings.ProfilePreviewRefDrawingThickness);
				design.Entities.Add(mesh4);
			}
		}
		for (int m = 0; m <= Profile.Drawings.Count - 1; m++)
		{
			design.Entities.Add(new LinearPath(Profile.Drawings[m].OutterPoints));
		}
		for (int n = 0; n <= Profile.Drawings.Count - 1; n++)
		{
			for (int num = 0; num <= Profile.Drawings[n].InnerPoints.Count - 1; num++)
			{
				design.Entities.Add(new LinearPath(Profile.Drawings[n].InnerPoints[num]));
			}
		}
		for (int num2 = 0; num2 <= TempEntities.Count - 1; num2++)
		{
			Entity entity3 = buVector5.CopyEntities(TempEntities[num2]);
			entity3.Color = buProfileCalc.varProfileSettings.PreviewActiveOperationColor;
			design.Entities.Add(entity3);
		}
		if (design.Viewports.Count > 0)
		{
			design.ActiveViewport.DisplayMode = displayType.Flat;
			design.ActiveViewport.Camera.ProjectionMode = projectionType.Orthographic;
			bool flag = false;
			if (buCompare5.EQ(design.ActiveViewport.Camera.Rotation.W, 1.0, 0.01) && buCompare5.EQ(design.ActiveViewport.Camera.Rotation.X, 0.0, 0.01) && buCompare5.EQ(design.ActiveViewport.Camera.Rotation.Y, 0.0, 0.01) && buCompare5.EQ(design.ActiveViewport.Camera.Rotation.Z, 0.0, 0.01))
			{
				flag = true;
			}
			if (!isPreview)
			{
				design.SetView(viewType.vcFrontFaceTopLeft);
			}
			else if (!flag)
			{
				viewType view = (viewType)Convert.ToInt32(buProfileCalc.varProfileSettings.PreviewViewType);
				design.SetView(view);
				design.RotateLeft(180.0);
				design.ZoomFit();
			}
			design.Invalidate();
		}
	}

	public void DrawMultiPreview(buEyeBaseVer5.Apps.ProfileItem Profile, List<Entity> TempEntities)
	{
		if (CancelPreview || Profile == null)
		{
			return;
		}
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; i++)
		{
			if (!clsInit.cVector5.IsLayerNameAvailable(clsItem.FrmPreviewMulti.viewport_preview.Layers, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Name))
			{
				Layer item = new Layer(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Name, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Color);
				clsItem.FrmPreviewMulti.viewport_preview.Layers.Add(item);
			}
		}
		clsItem.FrmPreviewMulti.viewport_preview.Entities.Clear();
		for (int j = 0; j <= Profile.Drawings.Count - 1; j++)
		{
			if (Profile.Drawings[j].SolidEntity != null)
			{
				Entity entity = buVector5.CopyEntities(Profile.Drawings[j].SolidEntity);
				entity.Regen(buSystem.RegenDeviation);
				clsItem.FrmPreviewMulti.viewport_preview.Entities.Add(entity);
			}
		}
		for (int k = 0; k <= Profile.Operations.Count - 1; k++)
		{
			for (int l = 0; l <= Profile.Operations[k].EntityMultiSolidDepth.Count - 1; l++)
			{
				Entity entity2 = buVector5.CopyEntities(Profile.Operations[k].EntityMultiSolidDepth[l]);
				entity2.Color = buProfileCalc.varProfileSettings.PreviewDoneOperationColor;
				entity2.ColorMethod = colorMethodType.byEntity;
				clsItem.FrmPreviewMulti.viewport_preview.Entities.Add(entity2);
			}
		}
		if (buProfileCalc.varProfileSettings.ShowPreviewSides && (buNumeric5.IsNumeric(activeProfile.FirstItem.Height.ToString()) & buNumeric5.IsNumeric(activeProfile.FirstItem.Width.ToString())))
		{
			Mesh mesh = Mesh.CreateBox(2.0, 2.0, activeProfile.FirstItem.Height + 10.0);
			mesh.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
			mesh.ColorMethod = colorMethodType.byEntity;
			clsItem.FrmPreviewMulti.viewport_preview.Entities.Add(mesh);
			Mesh mesh2 = Mesh.CreateBox(2.0, activeProfile.FirstItem.Width + 10.0, 2.0);
			mesh2.Color = buProfileCalc.varProfileSettings.PreviewSideColor;
			mesh2.ColorMethod = colorMethodType.byEntity;
			mesh2.Translate(0.0, 0.0 - (activeProfile.FirstItem.Width + 10.0 - 2.0), -2.0);
			clsItem.FrmPreviewMulti.viewport_preview.Entities.Add(mesh2);
		}
		for (int m = 0; m <= TempEntities.Count - 1; m++)
		{
			Entity entity3 = buVector5.CopyEntities(TempEntities[m]);
			entity3.Color = buProfileCalc.varProfileSettings.PreviewActiveOperationColor;
			clsItem.FrmPreviewMulti.viewport_preview.Entities.Add(entity3);
		}
		for (int n = 0; n < 3; n++)
		{
			clsItem.FrmPreviewMulti.viewport_preview.Viewports[n].DisplayMode = displayType.Flat;
			clsItem.FrmPreviewMulti.viewport_preview.Viewports[n].Camera.ProjectionMode = projectionType.Orthographic;
			clsItem.FrmPreviewMulti.viewport_preview.Viewports[n].ZoomFit();
			clsItem.FrmPreviewMulti.viewport_preview.Viewports[3].ZoomFit();
		}
		clsItem.FrmPreviewMulti.viewport_preview.Invalidate();
	}

	public void DrawActiveProfile()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem != null)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Clear();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			Transformation transformation = null;
			OriginSymbol originSymbol = null;
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
			{
				transformation = new Translation(0.0, 0.0) * new Rotation(-Math.PI / 2.0, Vector3D.AxisZ);
				originSymbol = new OriginSymbol(6, originSymbolStyleType.Ball, Color.Black, Color.Black, Color.Black, Color.Black, Color.Red, Color.Green, Color.Blue, "", "", "", "", visible: true, transformation, lighting: false);
				DrawActiveProfile(activeProfile.FirstItem, buProfileCalc.varProfileRunSettings.activeProfileIndex);
			}
			if ((buProfileCalc.varProfileRunSettings.activeProfileIndex == 1) & (activeProfile.SecondItem != null))
			{
				transformation = new Translation(activeProfile.SecondItem.Length, 0.0) * new Rotation(-Math.PI, Vector3D.AxisZ);
				originSymbol = new OriginSymbol(6, originSymbolStyleType.Ball, Color.Black, Color.Black, Color.Black, Color.Black, Color.Red, Color.Green, Color.Blue, "", "X", "Y", "Z", visible: true, transformation, lighting: false);
				DrawActiveProfile(activeProfile.SecondItem, buProfileCalc.varProfileRunSettings.activeProfileIndex);
			}
			UndoDontProfile = false;
			if (ProfileTempVars.MainBottomTabIndex != 0)
			{
				DrawPlaneDepth(CleanAll: true, DrawPlanes: false, DrawDepths: true);
			}
			else
			{
				DrawPlaneDepth(CleanAll: true, DrawPlanes: true, DrawDepths: false);
			}
			if (transformation != null && originSymbol != null)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.ActiveViewport.OriginSymbols[0] = originSymbol;
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.CompileUserInterfaceElements();
			}
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		}
	}

	public void DrawActiveProfile(buEyeBaseVer5.Apps.ProfileItem Item, int activeProfileIndex)
	{
		if (Item == null)
		{
			return;
		}
		UndoDontProfile = true;
		for (int i = 0; i <= Item.Drawings.Count - 1; i++)
		{
			CreateProfileEntity(ref Item.Drawings[i].SolidEntity, Item.TextureName, Item.ItemName, Item.Enable, Item.colorProfile);
		}
		if (((Item.LeftAngleEntity != null) & buProfileCalc.varProfileSettings.RemoveProfileAngle & buProfileCalc.varProfileSettings.ShowProfileAngleDrawing) && activeProfileIndex == 0)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.LeftAngleEntity);
		}
		if (((Item.RightAngleEntity != null) & buProfileCalc.varProfileSettings.RemoveProfileAngle & buProfileCalc.varProfileSettings.ShowProfileAngleDrawing) && activeProfileIndex == 1)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.RightAngleEntity);
		}
		if (Item.ProfileReferanceEntity != null)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.ProfileReferanceEntity);
		}
		if (Item.ProfileReferanceBottomEntity != null)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.ProfileReferanceBottomEntity);
		}
		if (Item.ProfileReferanceBackEntity != null)
		{
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Add(Item.ProfileReferanceBackEntity);
		}
		for (int j = 0; j <= Item.Operations.Count - 1; j++)
		{
			CreateOperationEntity(Item.Operations[j], j);
		}
		if (Item.auxEntities != null)
		{
			for (int k = 0; k <= Item.auxEntities.Count - 1; k++)
			{
				Entity entity = buVector5.CopyEntities(Item.auxEntities[k]);
				entity.LayerName = ProfileTempVars.LayerNameOperation;
				entity.Color = Color.Gold;
				entity.ColorMethod = colorMethodType.byEntity;
				entity.Regen(buSystem.RegenDeviation);
				ccVars.UndoDont = true;
				clsInit.appCommand.AddEntity(entity);
				ccVars.UndoDont = false;
			}
		}
	}

	public void CreateProfileEntity(ref Entity entProfile, string TextureName, string ProfileName, bool Enable, Color colorProfile)
	{
		entProfile.ColorMethod = colorMethodType.byEntity;
		if (clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ProfileTempVars.LayerNameProfile))
		{
			entProfile.LayerName = ProfileTempVars.LayerNameProfile;
		}
		if (TextureName.Length > 0 && clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, TextureName))
		{
			entProfile.LayerName = TextureName;
		}
		CustomData customData = null;
		if (entProfile.EntityData == null)
		{
			customData = new CustomData();
			customData.typeDefination = entityTypeDefination.Profile;
			customData.EntityName = ProfileName;
		}
		else if (!(entProfile.EntityData is CustomData))
		{
			customData = new CustomData();
			customData.typeDefination = entityTypeDefination.Profile;
			customData.EntityName = ProfileName;
		}
		else
		{
			customData = (CustomData)entProfile.EntityData;
		}
		if (customData.typeDefination == entityTypeDefination.Profile)
		{
			if (Enable)
			{
				entProfile.Color = Color.FromArgb(buProfileCalc.varProfileSettings.MaterialTranspancy, colorProfile);
			}
			else
			{
				entProfile.Color = Color.FromArgb(buProfileCalc.varProfileSettings.MaterialTranspancy, Color.PaleVioletRed);
			}
		}
		entProfile.Selectable = false;
		ProfileTempVars.LastCreatedProfileEntityName = customData.EntityName;
		ProfileTempVars.LastCreatedProfileEntityIndex = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count;
		entProfile.EntityData = customData;
		ccVars.UndoDont = true;
		clsInit.appCommand.AddEntity(entProfile);
		ccVars.UndoDont = false;
	}

	public void CreateOperationEntity(buEyeBaseVer5.Apps.ProfileOperation OP, int OPIndex)
	{
		if (OP.EntityMultiSolidDepth != null)
		{
			for (int i = 0; i <= OP.EntityMultiSolidDepth.Count - 1; i++)
			{
				Entity entity = buVector5.CopyEntities(OP.EntityMultiSolidDepth[i]);
				CustomData customData = new CustomData();
				customData.typeDefination = entityTypeDefination.ProfileOperation;
				customData.ID = OP.ID;
				customData.EntityName = OP.ProfileName;
				customData.ActionName = OP.Name;
				entity.EntityData = customData;
				if (clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ProfileTempVars.LayerNameOperation))
				{
					entity.LayerName = ProfileTempVars.LayerNameOperation;
					entity.ColorMethod = colorMethodType.byLayer;
				}
				if (!OP.Enable)
				{
					entity.Color = Color.Red;
					entity.ColorMethod = colorMethodType.byEntity;
				}
				entity.Regen(buSystem.RegenDeviation);
				ccVars.UndoDont = true;
				clsInit.appCommand.AddEntity(entity);
				ccVars.UndoDont = false;
			}
		}
		if (OP.EntityMultiContour != null)
		{
			for (int j = 0; j <= OP.EntityMultiContour.Count - 1; j++)
			{
				OP.EntityMultiContour[j].typeDefination = entityTypeDefination.ProfileOperation;
				OP.EntityMultiContour[j].Info.Data = OP.ProfileName;
				OP.EntityMultiContour[j].Info.RefIndex = OPIndex;
				OP.EntityMultiContour[j].Info.ID = OP.ID;
				Entity copiedEntity = null;
				buEntity.Copy(OP.EntityMultiContour[j], ref copiedEntity);
				if (copiedEntity != null)
				{
					CustomData customData2 = new CustomData();
					customData2.typeDefination = OP.EntityMultiContour[j].typeDefination;
					customData2.ID = OP.EntityMultiContour[j].Info.ID;
					customData2.EntityName = OP.ProfileName;
					customData2.ActionName = OP.Name;
					copiedEntity.EntityData = customData2;
					if (clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ProfileTempVars.LayerNameOperation))
					{
						copiedEntity.LayerName = ProfileTempVars.LayerNameContour;
						copiedEntity.ColorMethod = colorMethodType.byLayer;
					}
					copiedEntity.Regen(buSystem.RegenDeviation);
					ccVars.UndoDont = true;
					clsInit.appCommand.AddEntity(copiedEntity);
					ccVars.UndoDont = false;
				}
			}
		}
		if (OP.EntityMultiCam == null)
		{
			return;
		}
		for (int k = 0; k <= OP.EntityMultiCam.Count - 1; k++)
		{
			OP.EntityMultiCam[k].Info.Data = OP.ProfileName;
			OP.EntityMultiCam[k].Info.RefIndex = OPIndex;
			OP.EntityMultiCam[k].Info.ID = OP.ID;
			Entity copiedEntity2 = null;
			buEntity.Copy(OP.EntityMultiCam[k], ref copiedEntity2);
			if (OP.Action == actionTypeBU.profileNotch && OP.EntityMultiCam[k].Info.Offset != null)
			{
				copiedEntity2.Translate(OP.EntityMultiCam[k].Info.Offset.X, OP.EntityMultiCam[k].Info.Offset.Y, OP.EntityMultiCam[k].Info.Offset.Z);
			}
			CustomData customData3 = new CustomData();
			customData3.typeDefination = OP.EntityMultiCam[k].typeDefination;
			customData3.ID = OP.EntityMultiCam[k].Info.ID;
			customData3.EntityName = OP.ProfileName;
			customData3.ActionName = OP.Name;
			copiedEntity2.EntityData = customData3;
			if (clsInit.cVector5.IsLayerNameAvailable(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers, ProfileTempVars.LayerNameOperation))
			{
				copiedEntity2.LayerName = ProfileTempVars.LayerNameCam;
				copiedEntity2.ColorMethod = colorMethodType.byLayer;
			}
			copiedEntity2.Regen(buSystem.RegenDeviation);
			ccVars.UndoDont = true;
			clsInit.appCommand.AddEntity(copiedEntity2);
			ccVars.UndoDont = false;
		}
	}

	public void LoadLanguage()
	{
		try
		{
			List<string> list = new List<string>();
			FileInfo fileInfo = null;
			fileInfo = ((!clsVar.appModes_0.DeveloperPCMode) ? new FileInfo(AppPath.Language + "\\buProfile.lng") : new FileInfo("D:\\PCProjects\\Generation5\\CommonFolder\\Language\\buProfile.lng"));
			if (!fileInfo.Exists)
			{
				buLog.addLog("Profile Language", "Not Ok", MethodBase.GetCurrentMethod().Name);
				buString.MessageBoxError("Profile Language File Missing");
			}
			else
			{
				List<string> StringList = new List<string>();
				buFile.OpenFromFile(fileInfo.FullName, ref StringList);
				buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Status>", "</Status>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileStatus);
				buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Message>", "</Message>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileMessage);
				buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Captions>", "</Captions>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileCaptions);
				buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Command>", "</Command>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileCommands);
				buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<MainForm>", "</MainForm>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileMainForm);
				buString.GetItemsAccordingToTheLang(buString.ReadXmlItem("<Help>", "</Help>", StringList), clsVar.varRuntime.Language, ref buProfile.LangProfileHelp);
				StringList.Clear();
			}
			if (list.Count <= 0)
			{
			}
		}
		catch (Exception mSException)
		{
			_ = list_2[16];
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

