	public void OpenFilePreview(FileEventArg e)
	{
		try
		{
			FileInfo fileInfo = new FileInfo(e.FileName);
			if (!(fileInfo.Exists & openDialogCtrlPreview.chk_preview.Checked))
			{
				openDialogCtrlPreview.picture_preview.Image = null;
				return;
			}
			clsVar.PreviewLoaded = false;
			clsItem.ModelOpenPreview.Width = openDialogCtrlPreview.picture_preview.Width;
			clsItem.ModelOpenPreview.Height = openDialogCtrlPreview.picture_preview.Height;
			for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers.Count - 1; i++)
			{
				Layer layer = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i];
				if (!clsInit.cVector5.IsLayerNameAvailable(clsItem.ModelOpenPreview.Layers, ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Layers[i].Name))
				{
					Layer newItem = new Layer(layer.Name, layer.Color, layer.LineTypeName, layer.LineWeight, visible: true);
					clsItem.ModelOpenPreview.Layers.AddOrReplace(newItem);
				}
			}
			if (!(fileInfo.Extension.ToLower() == ".buprofile"))
			{
				return;
			}
			openDialogCtrlPreview.ShowLoading(Show: true);
			Application.DoEvents();
			new DrillJob();
			new ProfileBase();
			List<string> StringList = new List<string>();
			List<string> CalcList = new List<string>();
			List<string> CalcList2 = new List<string>();
			buFile5.OpenFromFile(fileInfo.FullName, ref StringList);
			List<Entity> list = new List<Entity>();
			List<Entity> refEntities = new List<Entity>();
			buStatics.ListToSpecificList("<FirstItem>", "</FirstItem>", AddStartEndKey: true, StringList, ref CalcList);
			buStatics.ListToSpecificList("<SecondItem>", "</SecondItem>", AddStartEndKey: true, StringList, ref CalcList2);
			if (CalcList.Count > 0)
			{
				List<List<string>> CalcList3 = new List<List<string>>();
				buStatics.ListToSpecificList("<SolidProfileEntities>", "</SolidProfileEntities>", AddStartEndKey: true, CalcList, ref CalcList3);
				if (CalcList3.Count > 0)
				{
					for (int j = 0; j <= CalcList3.Count - 1; j++)
					{
						List<List<string>> CalcList4 = new List<List<string>>();
						buStatics.ListToSpecificList("<buEntity>", "</buEntity>", AddStartEndKey: false, CalcList3[j], ref CalcList4);
						for (int k = 0; k <= CalcList4.Count - 1; k++)
						{
							buEntity buEntity2 = buEntity.Decode(CalcList4[k]);
							if (buEntity2 != null && buEntity2.Vertices.Count > 0)
							{
								Entity copiedEntity = null;
								buEntity.Copy(buEntity2, ref copiedEntity);
								if (copiedEntity != null)
								{
									copiedEntity.ColorMethod = colorMethodType.byEntity;
									copiedEntity.Color = Color.FromArgb(150, Color.Silver);
									copiedEntity.LayerName = "Default";
									list.Add(copiedEntity);
								}
							}
						}
					}
				}
				CalcList3 = new List<List<string>>();
				buStatics.ListToSpecificList("<SolidOperationEntities>", "</SolidOperationEntities>", AddStartEndKey: true, CalcList, ref CalcList3);
				if (CalcList3.Count > 0)
				{
					for (int l = 0; l <= CalcList3.Count - 1; l++)
					{
						List<List<string>> CalcList5 = new List<List<string>>();
						buStatics.ListToSpecificList("<buEntity>", "</buEntity>", AddStartEndKey: false, CalcList3[l], ref CalcList5);
						for (int m = 0; m <= CalcList5.Count - 1; m++)
						{
							buEntity buEntity3 = buEntity.Decode(CalcList5[m]);
							if (buEntity3 != null && buEntity3.Vertices.Count > 0)
							{
								Entity copiedEntity2 = null;
								buEntity.Copy(buEntity3, ref copiedEntity2);
								if (copiedEntity2 != null)
								{
									copiedEntity2.ColorMethod = colorMethodType.byEntity;
									copiedEntity2.Color = Color.FromArgb(255, Color.Cyan);
									copiedEntity2.LayerName = "Default";
									list.Add(copiedEntity2);
								}
							}
						}
					}
				}
			}
			if (CalcList2.Count > 0)
			{
				List<List<string>> CalcList6 = new List<List<string>>();
				buStatics.ListToSpecificList("<SolidProfileEntities>", "</SolidProfileEntities>", AddStartEndKey: true, CalcList2, ref CalcList6);
				if (CalcList6.Count > 0)
				{
					for (int n = 0; n <= CalcList6.Count - 1; n++)
					{
						List<List<string>> CalcList7 = new List<List<string>>();
						buStatics.ListToSpecificList("<buEntity>", "</buEntity>", AddStartEndKey: false, CalcList6[n], ref CalcList7);
						for (int num = 0; num <= CalcList7.Count - 1; num++)
						{
							buEntity buEntity4 = buEntity.Decode(CalcList7[num]);
