				calculationEventArg.ShowOnMainForm = true;
				calculationEventArg.ShowForm = false;
				clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
				List<string> CalcList2 = new List<string>();
				List<string> CalcList3 = new List<string>();
