				{
					activeProfile.FirstItem.isCollisionControlDone = false;
					activeProfile.FirstItem.isGCodeCreated = false;
					activeProfile.FirstItem.isGCodeSimMoveCreated = false;
					activeProfile.FirstItem.isSimulationDone = false;
					activeProfile.FirstItem.IsClamperDone = false;
					doCheckProfileWarnings(ref activeProfile.FirstItem);
				}
				if (activeProfile.SecondItem != null)
				{
					activeProfile.SecondItem.isCollisionControlDone = false;
					activeProfile.SecondItem.isGCodeCreated = false;
					activeProfile.SecondItem.isGCodeSimMoveCreated = false;
					activeProfile.SecondItem.isSimulationDone = false;
					activeProfile.SecondItem.IsClamperDone = false;
					doCheckProfileWarnings(ref activeProfile.SecondItem);
				}
				ProfileTreeUpdate();
			}
			doCheckProfileError();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			clsItem.FrmProgress.Visible = false;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, text);
		}
	}

	public void OpenProfileJobFile(List<string> SL, bool AddOperations, bool CreateProfile, bool OnlyDrawing, bool ShowProgress, ref buEyeBaseVer5.Apps.ProfileItem Profile)
	{
		try
		{
			List<string> list = new List<string>();
			Profile = new buEyeBaseVer5.Apps.ProfileItem();
			CalculationEventArg calculationEventArg = new CalculationEventArg();
			calculationEventArg.ActiveProgressPercentage = 25.0;
			calculationEventArg.Job = buLangTranslate.preDef.Profile + " " + buLangTranslate.preDef.Analysis;
			calculationEventArg.ShowOnMainForm = true;
			calculationEventArg.ShowForm = ShowProgress;
			clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
			ArrayList arrayList = new ArrayList();
			arrayList.AddRange(SL);
			buEyeBaseVer5.Apps.ProfileItem.Decode(arrayList, ref Profile);
			if (Profile.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
			{
				Profile.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
			}
			buProfileCalc.varProfileSettings.XDirRefType = Profile.XReferanceLocation;
			ProfileTempVars.SelectedOperations.Clear();
			if (ShowProgress)
			{
				if (clsItem.FrmProgress == null)
				{
					clsItem.FrmProgress = new F_ProgressCalculation();
				}
				clsItem.FrmProgress.TopMost = true;
				clsItem.FrmProgress.Show();
			}
			JobOpening = true;
			buProfileCalc.varProfileRunSettings.IncrementalMode = false;
			operationEditIndex = -1;
			calculationEventArg.ActiveProgressPercentage = 50.0;
			calculationEventArg.Job = buLangTranslate.preDef.Profile + " " + buLangTranslate.preDef.Drawing;
			clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
			for (int i = 0; i <= Profile.Drawings.Count - 1; i++)
			{
				Profile.Drawings[i].OutterPoints.Clear();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(Profile.Drawings[i].OutterEntitites, buSystem.RegenDeviation, ref Profile.Drawings[i].OutterPoints);
				clsInit.cVector5.CheckDuplicatedPointsWithPrevious(buSystem.resolutionCompare, ref Profile.Drawings[i].OutterPoints);
				calculationEventArg.OverallProgressPercentage = 25.0;
				clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
				Profile.Drawings[i].InnerPoints.Clear();
				for (int j = 0; j <= Profile.Drawings[i].InnerEntities.Count - 1; j++)
				{
					List<Point3D> Points = new List<Point3D>();
					clsInit.cVector5.EntitiesToPointsWithCamDirection(Profile.Drawings[i].InnerEntities[j], buSystem.RegenDeviation, ref Points);
					clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points);
					if (clsInit.cVector5.GetClockDirection(Points) == ClockDirectionType.CCW)
					{
						Points.Reverse();
					}
					clsInit.cVector5.CheckDuplicatedPointsWithPrevious(buSystem.resolutionCompare, ref Points);
					Profile.Drawings[i].InnerPoints.Add(Points);
				}
			}
			List<buEyeBaseVer5.Apps.ProfileOperation> CopiedOperation = new List<buEyeBaseVer5.Apps.ProfileOperation>();
			buEyeBaseVer5.Apps.ProfileOperation.Copy(Profile.Operations, ref CopiedOperation);
			if (CreateProfile)
			{
				Profile.Operations.Clear();
				if (Profile.Drawings.Count > 0)
				{
					doCreateProfile(ref Profile, isNewProfile: true);
				}
			}
			if (AddOperations)
			{
				ToolBase5 tool = new ToolBase5(ccVars.toolActive);
				for (int k = 0; k <= CopiedOperation.Count - 1; k++)
				{
					list_0.Clear();
					if (CopiedOperation[k].Action != actionTypeBU.profileNotch)
					{
						clsInit.cProfile.ProfileCamDataToCamParameter(CopiedOperation[k].CamOPData, ref CopiedOperation[k].OperationData.CamParMilling);
					}
					else
					{
						clsInit.cProfile.ProfileCamDataToCamParameter(CopiedOperation[k].CamOPData, ref CopiedOperation[k].OperationData.CamParNotch);
					}
					buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane)CopiedOperation[k].OperationData.selectedPlane.Clone();
					string toolName = CopiedOperation[k].OperationData.ToolName;
					bool flag;
					if (!(flag = clsInit.cVector5.FindToolWithToolName(ccVars.Tools, CopiedOperation[k].OperationData.ToolName, ref ccVars.toolActive)) & (CopiedOperation[k].OperationData.ToolDiameter > 0.0))
					{
						flag = clsInit.cVector5.FindToolWithDiameter(ccVars.Tools, CopiedOperation[k].OperationData.ToolDiameter, ref ccVars.toolActive);
					}
					if (!flag)
					{
						clsInit.cVector5.FindToolSmallMillingDiameter(ccVars.Tools, ref ccVars.toolActive);
					}
					if ((ccVars.toolActive.Geometry.GeometryType == ToolType.Saw) & (CopiedOperation[k].OperationData.Action != actionTypeBU.profileNotch))
					{
						clsInit.cVector5.FindToolSmallMillingDiameter(ccVars.Tools, ref ccVars.toolActive);
					}
					if ((ccVars.toolActive.Geometry.GeometryType != ToolType.Saw) & (CopiedOperation[k].OperationData.Action == actionTypeBU.profileNotch))
					{
						CopiedOperation[k].Tool = new ToolBase5(ccVars.toolActive);
						for (int l = 0; l <= ccVars.Tools.Count - 1; l++)
						{
							for (int m = 0; m <= ccVars.Tools[l].Tools.Count - 1; m++)
							{
								if (ccVars.Tools[l].Tools[m].Geometry.GeometryType == ToolType.Saw)
								{
									ccVars.toolActive = new ToolBase5(ccVars.Tools[l].Tools[m]);
									CopiedOperation[k].ToolNotch = new ToolBase5(ccVars.toolActive);
								}
							}
						}
					}
					ProfileTempVars.CamAssinged = true;
					buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.SpindleSpeed = ccVars.toolActive.CamData.SpindleSpeed;
					buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Feed = ccVars.toolActive.CamData.FeedSpeed;
					buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Plunge = ccVars.toolActive.CamData.PlungeSpeed;
					buProfileCalc.varProfileRunSettings.ShapeDataParameters.CamPars.Speeds.Finish = ccVars.toolActive.CamData.FinishSpeed;
					if (shapeCreateParameters_0.entitiesCurveList == null)
					{
						shapeCreateParameters_0.entitiesCurveList = new List<EntitiesList>();
					}
					shapeCreateParameters_0.entitiesCurveList.Clear();
					if (CopiedOperation[k].OperationData.OperationType == ProfileOperationTypes.FreeDraw)
					{
						Point3D MinPoint = new Point3D();
						Point3D MaxPoint = new Point3D();
						if (CopiedOperation[k].EntityMultiXYPlane.Count <= 0)
						{
							if (CopiedOperation[k].EntityMultiContour.Count > 0)
							{
								doAddExternalEntities(CopiedOperation[k].EntityMultiContour, Template: false, FileOpen: true);
								clsInit.cVector5.BoxSizeCalculate(CopiedOperation[k].EntityMultiContour, ref MinPoint, ref MaxPoint);
							}
						}
						else
						{
							doAddExternalEntities(CopiedOperation[k].EntityMultiXYPlane, Template: false, FileOpen: true);
							clsInit.cVector5.BoxSizeCalculate(CopiedOperation[k].EntityMultiXYPlane, ref MinPoint, ref MaxPoint);
						}
						buProfileCalc.varProfileRunSettings.FreeDrawOrjinalHeight = MaxPoint.Y - MinPoint.Y;
						buProfileCalc.varProfileRunSettings.FreeDrawOrjinalWidth = MaxPoint.X - MinPoint.X;
					}
					if (ProfileTempVars.TemplateMode & (activeItem != null))
					{
						if (Profile.Width > 0.0)
						{
							ProfileTempVars.TemplateYZScaleRatio = activeItem.Width / Profile.Width;
						}
						if (Profile.Length > 0.0)
						{
							ProfileTempVars.TemplateXScaleRatio = activeItem.Length / Profile.Length;
						}
						if (!((CopiedOperation[k].OperationData.selectedPlaneName == planeNames.Top) | (CopiedOperation[k].OperationData.selectedPlaneName == planeNames.Bottom)))
						{
							if (!((CopiedOperation[k].OperationData.selectedPlaneName == planeNames.Front) | (CopiedOperation[k].OperationData.selectedPlaneName == planeNames.Back)))
							{
								if (CopiedOperation[k].OperationData.selectedPlaneName == planeNames.Free)
								{
									CopiedOperation[k].OperationData.Position.X = Math.Round(CopiedOperation[k].OperationData.Position.X * ProfileTempVars.TemplateXScaleRatio, 5) + ProfileTempVars.TemplateXOffset;
								}
							}
							else
							{
								CopiedOperation[k].OperationData.Position.X = Math.Round(CopiedOperation[k].OperationData.Position.X * ProfileTempVars.TemplateXScaleRatio, 5) + ProfileTempVars.TemplateXOffset;
								CopiedOperation[k].OperationData.Position.Y = Math.Round(CopiedOperation[k].OperationData.Position.Y * ProfileTempVars.TemplateYZScaleRatio);
							}
						}
						else
						{
							CopiedOperation[k].OperationData.Position.X = Math.Round(CopiedOperation[k].OperationData.Position.X * ProfileTempVars.TemplateXScaleRatio, 5) + ProfileTempVars.TemplateXOffset;
							CopiedOperation[k].OperationData.Position.Y = Math.Round(CopiedOperation[k].OperationData.Position.Y * ProfileTempVars.TemplateYZScaleRatio);
						}
					}
					ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg();
					shapeUpdateArg.Finished = true;
					shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
					shapeUpdateArg.Parameters.selectedCorner = CopiedOperation[k].OperationData.Corner;
					shapeUpdateArg.Parameters.objectAlignment = CopiedOperation[k].OperationData.Alignment;
					shapeUpdateArg.Tool = new ToolBase5(ccVars.toolActive);
					shapeUpdateArg.ToolName = ccVars.toolActive.Data.Name;
					shapeUpdateArg.ToolChangeForced = true;
					shapeUpdateArg.OpenFile = true;
					shapeUpdateArg.NotOriginalTool = !flag;
					shapeUpdateArg.Parameters.Priority = CopiedOperation[k].Priority;
					if (!CopiedOperation[k].Enable)
					{
						shapeUpdateArg.CommandList.Add("ForceDisable");
					}
					UndoDontProfile = true;
					OPPriority = CopiedOperation[k].Priority;
					buShape Item = new buShape();
					Item.BasePoint = new Point3D(CopiedOperation[k].OperationData.basePosition.X, Math.Abs(CopiedOperation[k].OperationData.basePosition.Y), CopiedOperation[k].OperationData.basePosition.Z);
					if (buCompare5.EQ(Item.BasePoint.X, 0.0) & buCompare5.EQ(Item.BasePoint.Y, 0.0) & buCompare5.EQ(Item.BasePoint.Y, 0.0))
					{
						Item.BasePoint.X = CopiedOperation[k].OperationData.Position.X;
						Item.BasePoint.Y = CopiedOperation[k].OperationData.Position.Y;
						Item.BasePoint.Z = CopiedOperation[k].OperationData.Position.Z;
						Item.Corner = CornerLocation.LeftTop;
					}
					clsInit.cVector5.CoordinateFromPlaneAndCorner(new SizeObject(Profile.Length, Profile.Width, Profile.Height), CopiedOperation[k].OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(CopiedOperation[k].OperationData.selectedPlaneName), ref Item, ref CopiedOperation[k].OperationData.Position, shapeCreateParameters_0.SingX, shapeCreateParameters_0.SingY);
					OnlineOperation(null, shapeUpdateArg, CopiedOperation[k].OperationData);
					if (!flag)
					{
						list_0.Add(buLangTranslate.preSentences.SavedOperationToolNotAvailableInRecentToolList + " " + buLangTranslate.preDef.Tool + " = " + toolName);
					}
					if (list_0.Count > 0)
					{
						for (int n = 0; n <= list_0.Count - 1; n++)
						{
							list.Add(list_0[n] + " - " + (k + 1) + ". " + buLangTranslate.preDef.Operation + " - " + CopiedOperation[k].OperationData.OperationType);
						}
					}
					UndoDontProfile = false;
					calculationEventArg.Job = k + 1 + "." + buLangTranslate.preDef.Profile + " " + buLangTranslate.preDef.Calculating + " - " + buProfileCalc.OperationItemString(CopiedOperation[k]);
					calculationEventArg.ActiveProgressPercentage = (double)(k + 1) / (double)CopiedOperation.Count * 100.0;
					clsInit.appCommand.CalculationInProgressCmd(calculationEventArg);
				}
				OPPriority = 0;
				ProfileTempVars.TemplateMode = false;
				ProfileTempVars.CamAssinged = false;
				RearrangeOperationID();
				ccVars.toolActive = new ToolBase5(tool);
				if (list.Count > 0)
				{
					clsItem.FrmProgress.Visible = false;
					F_Warning f_Warning = new F_Warning();
					f_Warning.ShowOk = true;
					f_Warning.ShowReset = false;
					f_Warning.PropertiesForm.FormPosition = FormStartPosition.CenterScreen;
					f_Warning.lst_warnig.Font = new Font("Arial", 10f, FontStyle.Bold);
					f_Warning.Init(list);
					f_Warning.ShowDialog();
					if (f_Warning.PropertiesForm.Result != DialogResult.OK)
					{
						DrawPreview(new List<Entity>());
						return;
					}
				}
			}
			JobOpening = false;
			Profile.isCollisionControlDone = false;
			Profile.isGCodeCreated = false;
			Profile.isGCodeSimMoveCreated = false;
			Profile.isSimulationDone = false;
			Profile.IsClamperDone = false;
			doCheckProfileWarnings(ref Profile);
			clsInit.appCommand.CalculationInProgressReset(calculationEventArg);
			clsItem.FrmProgress.Visible = false;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, text);
		}
	}

	public void OperationListUpdate(buEyeBaseVer5.Apps.ProfileItem Profile, ref List<buEyeBaseVer5.Apps.ProfileOperation> OP)
	{
		for (int i = 0; i <= OP.Count - 1; i++)
