				buProfileCalc.varProfileRunSettings.FreeDrawOrjinalWidth = MaxPoint.X - MinPoint.X;
			}
			if (ProfileTempVars.TemplateMode & (activeItem != null))
			{
				if (Profile.Width > 0.0)
				{
					ProfileTempVars.TemplateYZScaleRatio = activeItem.Width / Profile.Width;
				}
				if (Profile.Length > 0.0)
				{
					ProfileTempVars.TemplateXScaleRatio = activeItem.Length / Profile.Length;
				}
				if (!((OP[i].OperationData.selectedPlaneName == planeNames.Top) | (OP[i].OperationData.selectedPlaneName == planeNames.Bottom)))
				{
					if (!((OP[i].OperationData.selectedPlaneName == planeNames.Front) | (OP[i].OperationData.selectedPlaneName == planeNames.Back)))
					{
						if (OP[i].OperationData.selectedPlaneName == planeNames.Free)
						{
							OP[i].OperationData.Position.X = Math.Round(OP[i].OperationData.Position.X * ProfileTempVars.TemplateXScaleRatio, 5) + ProfileTempVars.TemplateXOffset;
						}
