						OP[i].OperationData.Position.Y = Math.Round(OP[i].OperationData.Position.Y * ProfileTempVars.TemplateYZScaleRatio);
					}
				}
				else
				{
					OP[i].OperationData.Position.X = Math.Round(OP[i].OperationData.Position.X * ProfileTempVars.TemplateXScaleRatio, 5) + ProfileTempVars.TemplateXOffset;
					OP[i].OperationData.Position.Y = Math.Round(OP[i].OperationData.Position.Y * ProfileTempVars.TemplateYZScaleRatio);
