			OnlineOperation(null, shapeUpdateArg, OP[i].OperationData);
			if (!flag)
			{
				list_0.Add(buLangTranslate.preSentences.SavedOperationToolNotAvailableInRecentToolList + " " + buLangTranslate.preDef.Tool + " = " + toolName);
			}
			if (list_0.Count > 0)
			{
				for (int l = 0; l <= list_0.Count - 1; l++)
				{
				}
			}
			UndoDontProfile = false;
		}
	}

	public void AddRecentOpenFile(string FileName)
	{
		if (FileName != buProfileCalc.varProfileRunSettings.RecentOpenFile1)
		{
			if (buProfileCalc.varProfileRunSettings.RecentOpenFile6 != buProfileCalc.varProfileRunSettings.RecentOpenFile5)
			{
				buProfileCalc.varProfileRunSettings.RecentOpenFile6 = buProfileCalc.varProfileRunSettings.RecentOpenFile5;
			}
			if (buProfileCalc.varProfileRunSettings.RecentOpenFile5 != buProfileCalc.varProfileRunSettings.RecentOpenFile4)
			{
				buProfileCalc.varProfileRunSettings.RecentOpenFile5 = buProfileCalc.varProfileRunSettings.RecentOpenFile4;
			}
			if (buProfileCalc.varProfileRunSettings.RecentOpenFile4 != buProfileCalc.varProfileRunSettings.RecentOpenFile3)
			{
				buProfileCalc.varProfileRunSettings.RecentOpenFile4 = buProfileCalc.varProfileRunSettings.RecentOpenFile3;
			}
			if (buProfileCalc.varProfileRunSettings.RecentOpenFile3 != buProfileCalc.varProfileRunSettings.RecentOpenFile2)
			{
				buProfileCalc.varProfileRunSettings.RecentOpenFile3 = buProfileCalc.varProfileRunSettings.RecentOpenFile2;
			}
			if (buProfileCalc.varProfileRunSettings.RecentOpenFile2 != buProfileCalc.varProfileRunSettings.RecentOpenFile1)
			{
				buProfileCalc.varProfileRunSettings.RecentOpenFile2 = buProfileCalc.varProfileRunSettings.RecentOpenFile1;
			}
			if (FileName != buProfileCalc.varProfileRunSettings.RecentOpenFile1)
			{
				buProfileCalc.varProfileRunSettings.RecentOpenFile1 = FileName;
			}
		}
	}

	public void AddRecentSaveFile(string FileName)
	{
		if (FileName != buProfileCalc.varProfileRunSettings.RecentSaveFile1)
		{
			if (buProfileCalc.varProfileRunSettings.RecentSaveFile6 != buProfileCalc.varProfileRunSettings.RecentSaveFile5)
			{
				buProfileCalc.varProfileRunSettings.RecentSaveFile6 = buProfileCalc.varProfileRunSettings.RecentSaveFile5;
			}
