	public void SaveMacroFile(string FileName, buEyeBaseVer5.Apps.ProfileItem Profile)
	{
		int num = -2;
		if (Profile == null)
		{
			return;
		}
		ArrayList arrayList = new ArrayList();
		for (int i = 0; i <= Profile.Operations.Count - 1; i++)
		{
			arrayList.Add(buString5.SpaceChar(num + 2) + "<ProfileOperation>");
			arrayList.Add(buString5.SpaceChar(num + 4) + "<PrfOperation>");
			arrayList.AddRange(buEyeBaseVer5.Apps.ProfileOperation.ToDef(Profile.Operations[i], "", num + 6));
			if (Profile.Operations[i].OperationData.OperationType == ProfileOperationTypes.FreeDraw)
			{
				arrayList.Add(buString5.SpaceChar(num + 6) + "<ContourEntitites>");
				arrayList.AddRange(buEntity.ToDefEntity(Profile.Operations[i].EntityMultiContour, num + 8));
				arrayList.Add(buString5.SpaceChar(num + 6) + "</ContourEntitites>");
			}
			arrayList.Add(buString5.SpaceChar(num + 4) + "</PrfOperation>");
			arrayList.Add(buString5.SpaceChar(num + 2) + "</ProfileOperations>");
		}
		buFile5.SaveToFile(arrayList, FileName);
	}

	public void Open3DData(string FileName)
	{
		List<Entity> EntityList = new List<Entity>();
		List<Entity> refEntities = new List<Entity>();
		buFile5.OpenStep(ref EntityList, FileName);
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		new Point3D();
		clsInit.cVector5.BoxSizeCalculate(EntityList, ref MinPoint, ref MaxPoint);
		CreateProfileFromDataOptions createProfileFromDataOptions = new CreateProfileFromDataOptions();
		createProfileFromDataOptions.color = buProfileCalc.varProfileSettings.ProfileColor;
		createProfileFromDataOptions.Transparency = buProfileCalc.varProfileSettings.MaterialTranspancy;
		createProfileFromDataOptions.FileName = "111";
		createProfileFromDataOptions.FullName = FileName;
		createProfileFromDataOptions.Name = "1111";
		createProfileFromDataOptions.Length = MaxPoint.X - MinPoint.Y;
		createProfileFromDataOptions.NeededHeight = MaxPoint.Z - MinPoint.Z;
		createProfileFromDataOptions.NeededWidth = MaxPoint.Y - MinPoint.Y;
		createProfileFromDataOptions.SupportBlockY1Height = 0.0;
		createProfileFromDataOptions.SupportBlockY2Height = 0.0;
		createProfileFromDataOptions.SupportBlockZHeight = 0.0;
		createProfileFromDataOptions.SupportBlockY1Width = 0.0;
		createProfileFromDataOptions.SupportBlockY2Width = 0.0;
		createProfileFromDataOptions.SupportBlockZWidth = 0.0;
		createProfileFromDataOptions.NextFroupRules = SortingNextGroupFindRulesType.ClosestLength;
		createProfileFromDataOptions.MaxClamper = buProfileCalc.varProfileSettings.ProfileMaxClamper;
		buEyeBaseVer5.Apps.ProfileItem Profile = new buEyeBaseVer5.Apps.ProfileItem();
		if (!(EntityList[0] is Brep))
		{
			return;
		}
		Brep brep = EntityList[0] as Brep;
		brep.Regen(0.01);
		brep.Translate(0.0 - brep.BoxMin.X, 0.0 - brep.BoxMin.Y, 0.0 - brep.BoxMin.Z);
		brep.Regen(0.01);
		double num = 1.0;
		if ((brep.BoxMax.Z > 0.0) & (brep.BoxMax.Z < 1.0))
		{
			double num2 = 10.0 / brep.BoxMax.Z;
			if (num2 > 1.0 && num2 <= 10.0)
			{
				num = 10.0;
			}
			if (num2 > 10.0 && num2 <= 100.0)
			{
				num = 100.0;
			}
			if (num2 > 100.0 && num2 <= 1000.0)
			{
				num = 1000.0;
			}
		}
		if (num > 1.0)
		{
			brep.Scale(num);
			brep.Regen(0.01);
		}
		ccVars.Pages[ccVars.Pages.Count - 1].Form.viewportcad.Entities.Clear();
		for (int i = 0; i <= brep.Faces.Length - 1; i++)
		{
			Brep.Face face = brep.Faces[i];
			if (face.Surface == null || !(face.Surface.GetType() == typeof(PlanarSurf)))
			{
				if (face.Surface != null && face.Surface.GetType() == typeof(CylindricalSurf))
				{
					ICurve[] array = null;
					for (int j = 0; j <= face.Loops.Length - 1; j++)
					{
						array = new ICurve[face.Loops[j].Segments.Length];
						for (int k = 0; k <= face.Loops[j].Segments.Length - 1; k++)
						{
							Brep.OrientedEdge orientedEdge = face.Loops[j].Segments[k];
							Brep.Edge edge = brep.Edges[orientedEdge.CurveIndex];
							array[k] = edge.Curve;
						}
					}
					AnalyticSurf surface = face.Surface;
					Surface[] array2 = null;
					array2 = surface.GetSurface(array);
					if (array2 != null && array2.Length == 0)
					{
					}
				}
			}
			else
			{
				ICurve[] array3 = null;
				for (int l = 0; l <= face.Loops.Length - 1; l++)
				{
					array3 = new ICurve[face.Loops[l].Segments.Length];
					for (int m = 0; m <= face.Loops[l].Segments.Length - 1; m++)
					{
						Brep.OrientedEdge orientedEdge2 = face.Loops[l].Segments[m];
						Brep.Edge edge2 = brep.Edges[orientedEdge2.CurveIndex];
						array3[m] = edge2.Curve;
					}
					AnalyticSurf surface2 = face.Surface;
					Surface[] array4 = null;
					array4 = surface2.GetSurface(array3);
					if (array4 == null || array4.Length == 0 || !((((PlanarSurface)array4[0]).Plane.Equation.X == 1.0) | (((PlanarSurface)array4[0]).Plane.Equation.X == -1.0)))
					{
						continue;
					}
					array4[0].Regen(0.1);
					List<Entity> list = new List<Entity>();
					if (((Entity)array3[0]).Vertices[0].X < MinPoint.X + 60.0)
					{
						for (int n = 0; n <= array3.Length - 1; n++)
						{
							list.Add((Entity)array3[n]);
						}
					}
					List<Point3D> CopiedPnt = new List<Point3D>();
					if (list.Count <= 0)
					{
						continue;
					}
					buVector5.Add(((Entity)array3[0]).Vertices, ref CopiedPnt);
					for (int num3 = 1; num3 <= array3.Length - 1; num3++)
					{
						Entity entity = array3[num3] as Entity;
						if (!buCompare5.EQ(CopiedPnt[CopiedPnt.Count - 1], entity.Vertices[0]))
						{
							if (!buCompare5.EQ(CopiedPnt[CopiedPnt.Count - 1], entity.Vertices[entity.Vertices.Length - 1]))
							{
								if (num3 != 1)
								{
									continue;
								}
								CopiedPnt.Reverse();
								if (!buCompare5.EQ(CopiedPnt[CopiedPnt.Count - 1], entity.Vertices[0]))
								{
									if (buCompare5.EQ(CopiedPnt[CopiedPnt.Count - 1], entity.Vertices[entity.Vertices.Length - 1]))
									{
										List<Point3D> CopiedPnt2 = new List<Point3D>();
										buVector5.Add(entity.Vertices, ref CopiedPnt2);
										CopiedPnt2.Reverse();
										CopiedPnt.AddRange(CopiedPnt2);
									}
								}
								else
								{
									List<Point3D> CopiedPnt3 = new List<Point3D>();
									buVector5.Add(entity.Vertices, ref CopiedPnt3);
									CopiedPnt.AddRange(CopiedPnt3);
								}
							}
							else
							{
								List<Point3D> CopiedPnt4 = new List<Point3D>();
								buVector5.Add(entity.Vertices, ref CopiedPnt4);
								CopiedPnt4.Reverse();
								CopiedPnt.AddRange(CopiedPnt4);
							}
						}
						else
						{
							List<Point3D> CopiedPnt5 = new List<Point3D>();
							buVector5.Add(entity.Vertices, ref CopiedPnt5);
							CopiedPnt.AddRange(CopiedPnt5);
						}
					}
					if (CopiedPnt.Count >= 3 && buCompare5.EQ(CopiedPnt[CopiedPnt.Count - 1], CopiedPnt[0]))
					{
						clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref CopiedPnt);
						LinearPath item = new LinearPath(CopiedPnt);
						refEntities.Add(item);
					}
				}
			}
			if (face.Surface != null)
			{
			}
		}
		new MaterialBase5();
		if (refEntities.Count > 0)
		{
			clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisY, ref refEntities);
			clsInit.cVector5.Rotate(new Point3D(), -90.0, Vector3D.AxisZ, ref refEntities);
			CheckEntitesOption checkEntitesOption = new CheckEntitesOption();
			checkEntitesOption.CompositeCurveToEntities = false;
			clsInit.cVector5.CheckEntities(checkEntitesOption, ref refEntities);
			clsInit.cProfile.CreateProfileFromData(refEntities, createProfileFromDataOptions, ref Profile);
		}
		doCreateProfile(ref Profile, isNewProfile: true);
		clsInit.appCommand.cmdViewZoomFit();
		ccVars.Pages[ccVars.Pages.Count - 1].Form.viewportcad.Invalidate();
	}

