						{
							if (profileOperation.OperationData.selectedPlaneName == planeNames.Top)
							{
								profileOperation.OperationData.Position.Y = 0.0 - (Profile.Width - double.Parse(Value14));
								profileOperation.OperationData.basePosition.Y = Profile.Width - double.Parse(Value14);
							}
							if (profileOperation.OperationData.selectedPlaneName == planeNames.Bottom)
							{
								profileOperation.OperationData.Position.Y = 0.0 - Profile.Width - double.Parse(Value14);
								profileOperation.OperationData.basePosition.Y = Math.Abs(0.0 - Profile.Width - double.Parse(Value14));
							}
							if (profileOperation.OperationData.selectedPlaneName == planeNames.Front)
							{
								profileOperation.OperationData.Position.Z = Profile.Height + double.Parse(Value14);
								profileOperation.OperationData.basePosition.Z = Profile.Height + double.Parse(Value14);
								profileOperation.OperationData.Position.Y = 0.0 - Profile.Width;
								profileOperation.OperationData.basePosition.Y = 0.0 - Profile.Width;
							}
							if (profileOperation.OperationData.selectedPlaneName == planeNames.Back)
							{
								profileOperation.OperationData.Position.Z = Profile.Height - double.Parse(Value14);
								profileOperation.OperationData.basePosition.Z = Profile.Height - double.Parse(Value14);
							}
							if (profileOperation.OperationData.selectedPlaneName == planeNames.Free)
							{
								profileOperation.OperationData.Position.Y = Math.Abs(double.Parse(Value14));
								profileOperation.OperationData.basePosition.Y = Math.Abs(double.Parse(Value14));
							}
						}
					}
					if (list2[l][m].IndexOf("WSide") >= 0)
					{
						string Value15 = "";
