						}
					}
					if ((list2[l][m].IndexOf("WType") >= 0) & (list2[l][m].IndexOf("WTypeIndex") == -1))
					{
						string Value16 = "";
						buString5.ReadStringValue(list2[l][m], "WType", ref Value16);
						switch (Value16.Replace('"', ' ').Trim())
						{
						default:
							MessageBox.Show("Not Implemented Yet, Send sample file to Us");
							break;
						case "C":
							profileOperation = new buEyeBaseVer5.Apps.ProfileOperationCircle();
							profileOperation.Name = name;
							profileOperation.Priority = OPPriority;
							profileOperation.OperationData.Action = actionTypeBU.profileCircle;
