	public void RestoreFromFile(string FileName)
	{
		DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Backup);
		if (!directoryInfo.Exists)
		{
			return;
		}
		FileInfo fileInfo = new FileInfo(directoryInfo.FullName + "\\" + FileName + ".buBackup");
		if (fileInfo.Exists)
		{
			DirectoryInfo directoryInfo2 = new DirectoryInfo(AppPath.Backup + "\\Temp");
			if (!directoryInfo2.Exists)
			{
				directoryInfo2.Create();
			}
			buFile5.ExtractToFolder(directoryInfo2.FullName, fileInfo.FullName);
			DirectoryInfo directoryInfo3 = new DirectoryInfo(directoryInfo2.FullName + "\\PostProcessor");
			if (directoryInfo3.Exists)
			{
				buFile5.CopyFilesRecursively(directoryInfo3.FullName, AppPath.PostProcessor);
			}
			DirectoryInfo directoryInfo4 = new DirectoryInfo(directoryInfo2.FullName + "\\Kinematic");
			if (directoryInfo4.Exists)
			{
				buFile5.CopyFilesRecursively(directoryInfo4.FullName, AppPath.Kinematic);
			}
			DirectoryInfo directoryInfo5 = new DirectoryInfo(directoryInfo2.FullName + "\\Settings");
			if (directoryInfo5.Exists)
			{
				buFile5.CopyFilesRecursively(directoryInfo5.FullName, AppPath.Settings);
			}
			FileInfo fileInfo2 = new FileInfo(directoryInfo2.FullName + "\\mnbucfd.dll");
			if (fileInfo.Exists)
			{
				buFile5.CopyFileToFolder(fileInfo2.FullName, AppPath.Base);
			}
			directoryInfo2.Delete(recursive: true);
			buString5.MessageBoxInfo(AppLanguage.CadCamMessages[129]);
		}
	}

	public void CreateBackUp(string FileName)
	{
		DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Backup);
		if (!directoryInfo.Exists)
		{
			directoryInfo.Create();
		}
		directoryInfo = new DirectoryInfo(AppPath.Backup + "\\Temp");
		if (!directoryInfo.Exists)
		{
			directoryInfo.Create();
		}
		buFile5.CopyFilesRecursively(AppPath.Settings, directoryInfo.FullName + "\\Settings");
		FileInfo fileInfo = new FileInfo(ccVars.KinematicOrjinal.FileName);
		if (fileInfo.Exists)
		{
			buFile5.CopyFileToFolder(ccVars.KinematicOrjinal.FileName, directoryInfo.FullName + "\\Kinematic");
		}
		fileInfo = new FileInfo(ccVars.PostActive.FileName);
		if (fileInfo.Exists)
		{
			buFile5.CopyFileToFolder(ccVars.PostActive.FileName, directoryInfo.FullName + "\\PostProcessor");
		}
		fileInfo = new FileInfo(AppPath.Base + "\\mnbucfd.dll");
		if (fileInfo.Exists)
		{
			buFile5.CopyFileToFolder(fileInfo.FullName, directoryInfo.FullName);
		}
		string fileName = AppPath.Backup + "\\" + FileName + ".buBackup";
		FileInfo fileInfo2 = new FileInfo(fileName);
		if (fileInfo2.Exists)
		{
			fileInfo2.Delete();
		}
		buFile5.ZipFolderToFile(directoryInfo.FullName, fileInfo2.FullName);
		directoryInfo.Delete(recursive: true);
	}

	public void CreateArchive()
	{
		string text = buFile5.GetDesktopFolder() + "\\ProfileArchive";
		DirectoryInfo directoryInfo = new DirectoryInfo(text);
		if (directoryInfo.Exists)
		{
			Directory.Delete(directoryInfo.FullName, recursive: true);
			directoryInfo.Create();
		}
		else
		{
			Directory.CreateDirectory(text);
		}
		DirectoryInfo directoryInfo2 = new DirectoryInfo(AppPath.Settings);
		if (directoryInfo2.Exists)
		{
			Directory.CreateDirectory(text + "\\Settings");
			buFile5.CopyFilesRecursively(AppPath.Settings, text + "\\Settings");
		}
		FileInfo fileInfo = new FileInfo(ccVars.KinematicOrjinal.FileName);
		if (fileInfo.Exists)
		{
			buFile5.CopyFileToFolder(ccVars.KinematicOrjinal.FileName, text);
		}
		fileInfo = new FileInfo(ccVars.PostActive.FileName);
		if (fileInfo.Exists)
		{
			buFile5.CopyFileToFolder(ccVars.PostActive.FileName, text);
		}
		fileInfo = new FileInfo(AppPath.Base + "\\mnbucfd.dll");
		if (fileInfo.Exists)
		{
			buFile5.CopyFileToFolder(fileInfo.FullName, text);
		}
		string fileName = text + "\\LastProfile.buprofile";
		SaveProfileJobFile(fileName, AddRecent: false);
		Bitmap SSBmp = null;
		buImage5.GetScreenShot(clsItem.FrmMain, ref SSBmp);
		SSBmp?.Save(text + "\\ScreeenShot.bmp");
		string fileName2 = buFile5.GetDesktopFolder() + "\\ProfileArchive.zip";
		FileInfo fileInfo2 = new FileInfo(fileName2);
		if (fileInfo2.Exists)
		{
			fileInfo2.Delete();
		}
		buFile5.ZipFolderToFile(text, fileInfo2.FullName);
		directoryInfo.Delete(recursive: true);
		buString5.MessageBoxInfo(AppLanguage.CadCamMessages[126] + " - " + fileInfo2.FullName);
	}

