	public void OperationCommand(object Cmd)
	{
		operationEditIndex = -1;
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Circle)
		{
			cmdOperation(actionTypeBU.profileCircle, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Rectangle)
		{
			cmdOperation(actionTypeBU.profileRectangle, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Barrel)
		{
			cmdOperation(actionTypeBU.profileBarrel, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Ellipse)
		{
			cmdOperation(actionTypeBU.profileEllipse, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Slot)
		{
			cmdOperation(actionTypeBU.profileSlot, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Hole)
		{
			cmdOperation(actionTypeBU.profileHole, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Tapping)
		{
			cmdOperation(actionTypeBU.profileTapping, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Cut)
		{
			cmdOperation(actionTypeBU.profileCut, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Notch)
		{
			cmdOperation(actionTypeBU.profileNotch, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.RoundRectangle)
		{
			cmdOperation(actionTypeBU.profileRoundRectangle, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Text)
		{
			cmdOperation(actionTypeBU.profileText, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.WireText)
		{
			cmdOperation(actionTypeBU.profileWireText, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.FromFile)
		{
			cmdAddFromFile();
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.FromFileList)
		{
			cmdAddFromList();
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.FreeDraw)
		{
			cmdOperation(actionTypeBU.profileFreeDraw, NewOperation: true);
		}
		if ((ProfileOperationTypes)Cmd == ProfileOperationTypes.Library)
		{
			cmdLibrary();
		}
	}

	public void RearrangeOperationID()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem != null)
		{
			IDCounter = 1;
			for (int i = 0; i <= profileItem.Operations.Count - 1; i++)
			{
				profileItem.Operations[i].ID = IDCounter.ToString();
				IDCounter++;
			}
		}
	}

	public void ResetAllCalculationFlags()
	{
		if (activeProfile.FirstItem != null)
		{
			ResetCalculationFlags(isCollisionControlDone: false, isSimulationDone: false, IsClamperDone: false, isGCodeCreated: false);
			doCheckProfileWarnings(ref activeProfile.FirstItem);
		}
		if (activeProfile.SecondItem != null)
		{
			ResetCalculationFlags(isCollisionControlDone: false, isSimulationDone: false, IsClamperDone: false, isGCodeCreated: false);
			doCheckProfileWarnings(ref activeProfile.SecondItem);
		}
	}

	public void ResetCalculationFlags(bool isCollisionControlDone, bool isSimulationDone, bool IsClamperDone, bool isGCodeCreated)
	{
		if (activeProfile.FirstItem != null)
		{
			activeProfile.FirstItem.isCollisionControlDone = isCollisionControlDone;
			activeProfile.FirstItem.isSimulationDone = isSimulationDone;
			activeProfile.FirstItem.IsClamperDone = IsClamperDone;
			activeProfile.FirstItem.isGCodeCreated = isGCodeCreated;
			activeProfile.FirstItem.isGCodeSimMoveCreated = isGCodeCreated;
			activeProfile.FirstItem.isCollisionOnlineAvailable = false;
			activeProfile.FirstItem.isCollisionOfflineAvailable = false;
		}
		if (activeProfile.SecondItem != null)
		{
			activeProfile.SecondItem.isCollisionControlDone = isCollisionControlDone;
			activeProfile.SecondItem.isSimulationDone = isSimulationDone;
			activeProfile.SecondItem.IsClamperDone = IsClamperDone;
			activeProfile.SecondItem.isGCodeCreated = isGCodeCreated;
			activeProfile.SecondItem.isGCodeSimMoveCreated = isGCodeCreated;
			activeProfile.SecondItem.isCollisionOnlineAvailable = false;
			activeProfile.SecondItem.isCollisionOfflineAvailable = false;
		}
	}

	public string GetOperationInfo(GProfileOperation OP)
	{
		try
		{
			string text = "";
			text = text + OP.Name + Environment.NewLine;
			text = text + OP.OperationData.selectedPlaneName.ToString() + Environment.NewLine;
			return text + OP.Tool.Data.Name + " - T" + OP.Tool.Data.No + " - D : " + OP.Tool.Geometry.Diameter.ToString("f2");
		}
		catch (Exception)
		{
			return buLangTranslate.preDef.Error;
		}
	}

	public void ProfileOffsetCalculation(ref Point3D profileOffset, buEyeBaseVer5.Apps.ProfileItem Profile)
	{
		if (Profile != null)
		{
			if (buProfileCalc.varProfileSettings.XDirection == ProfileXAxisDirection.Left)
			{
				profileOffset.X = 0.0;
			}
			if (buProfileCalc.varProfileSettings.XDirection == ProfileXAxisDirection.Center)
			{
				profileOffset.X = (0.0 - Profile.Length) / 2.0;
			}
			if (buProfileCalc.varProfileSettings.XDirection == ProfileXAxisDirection.Rigth)
			{
				profileOffset.X = 0.0 - Profile.Length;
			}
			if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.PositiveDirection)
			{
				profileOffset.Y = 0.0;
			}
			if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.Center)
			{
				profileOffset.Y = (0.0 - Profile.Width) / 2.0;
			}
			if (buProfileCalc.varProfileSettings.YDirection == ProfileYAxisDirection.NegativeDirection)
			{
				profileOffset.Y = 0.0 - Profile.Width;
			}
		}
	}

	public void UndoGetBack()
	{
		if (UndoList.Count > 0)
		{
			UndoDontProfile = true;
			activeProfile = new ProfileBase(UndoList[UndoList.Count - 1]);
			DrawActiveProfile();
			DrawPreview(new List<Entity>());
			ProfileTreeUpdate();
			UndoList.RemoveAt(UndoList.Count - 1);
			UndoDontProfile = false;
		}
	}

	public void UndoBuffer()
	{
		if (buProfileCalc.varProfileSettings.UseUndoBuffer & !UndoDontProfile)
		{
			if (UndoList.Count > 20)
			{
				UndoList.RemoveAt(0);
			}
			if ((activeProfile.FirstItem != null) | (activeProfile.SecondItem != null))
			{
				UndoList.Add(new ProfileBase(activeProfile));
			}
		}
	}

	public void OperationToCam(ref buEyeBaseVer5.Apps.ProfileOperation OP, buEyeBaseVer5.Apps.ProfileItem Profile, List<buEntity> entCam, List<DepthPositions> calcDepth, int indexDepth, Vector3D VecTranslate, Vector3D VecDepth, double disMoveX, double disMoveY, double disMoveZ, bool MoveSmallSafe, int IndexRepeat, ref Point3D pntLastMoved)
	{
		if (entCam.Count == 0)
		{
			return;
		}
		if (OP.OperationData.OperationType != ProfileOperationTypes.Notch)
		{
			if (OP.OperationData.OperationType != ProfileOperationTypes.Tapping)
			{
				if (OP.Tool == null)
				{
					return;
				}
			}
			else if ((OP.Tool == null) | (OP.ToolAux == null))
			{
				return;
			}
		}
		else if (OP.ToolNotch == null)
		{
			return;
		}
		Point3D point3D = buVector5.ToPoint3D(OP.OperationData.Position);
		if (buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
		{
			point3D.X = OP.OperationData.Position.X;
			if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
			{
				point3D.X = Profile.Length - OP.OperationData.Position.X;
