			}
			if (OP.OperationData.selectedPlaneName == planeNames.Bottom && copiedEntities != null)
			{
				Vector3D vector3D5 = OP.OperationData.selectedPlane.AxisZ * (0.0 - OP.OperationData.CamParMilling.Distances.Safe);
