						buEntity buEntity17 = buVector5.CopyEntities(copiedEntities[0]);
						buEntity17.Translate(point3D.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
						buEntity17.Translate(0.0, VecDepth.Y + disMoveY, calcDepth[indexDepth].BottomPosition);
						Point3D point3D13 = new Point3D(buEntity17.StartPoint.X, buEntity17.StartPoint.Y, buEntity17.StartPoint.Z);
