						buEntity17.typeDefination = entityTypeDefination.CamPlunge;
						buEntity17.Info.CamID = IndexRepeat;
						buEntity17.Info.PlungeSpeed = calcDepth[indexDepth].PlungeFeed;
						buEntity17.Info.SpindleSpeed = calcDepth[indexDepth].SpindleSpeed;
						OP.EntityMultiCam.Add(buEntity17);
						pntLastMoved = buVector5.ToPoint3D(point3D13);
					}
				}
				else
				{
					Point3D point3D15 = new Point3D(copiedEntities[0].StartPoint.X, copiedEntities[0].StartPoint.Y, calcDepth[indexDepth].TopPosition);
					if (copiedEntities[0].sortDirection == entitySortDirection.Reverse)
					{
						point3D15 = new Point3D(copiedEntities[0].EndPoint.X, copiedEntities[0].EndPoint.Y, calcDepth[indexDepth].TopPosition);
					}
					buLine buLine13 = new buLine(new Point3D(point3D15.X + vector3D5.X, point3D15.Y + vector3D5.Y, point3D15.Z + vector3D5.Z), point3D15);
					buLine13.typeDefination = entityTypeDefination.CamPlunge;
					buEntity buEntity19 = buVector5.CopyEntities(buLine13);
					buEntity19.Translate(point3D.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
					buEntity19.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
					buEntity19.Info.PlungeSpeed = calcDepth[indexDepth].PlungeFeed;
					buEntity19.Info.SpindleSpeed = calcDepth[indexDepth].SpindleSpeed;
