		}
		OP.CamCalculation = new List<camTp>();
		clsInit.cCam5.camEntitiesToCamPoints(OP.EntityMultiCam, OP.OperationData.CamParMilling, OP.Tool, ref OP.CamCalculation);
	}

	public void OperationToCam(ref buEyeBaseVer5.Apps.ProfileOperation OP, buEyeBaseVer5.Apps.ProfileItem Profile, List<List<buEntity>> entCam, List<DepthPositions> calcDepth, int indexDepth, Vector3D VecTranslate, Vector3D VecDepth, double disMoveX, double disMoveY, double disMoveZ, bool MoveSmallSafe, int IndexRepeat, ref Point3D pntLastMoved)
	{
		if (entCam.Count == 0)
		{
			return;
		}
		Point3D point3D = buVector5.ToPoint3D(OP.OperationData.Position);
		if (buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
		{
			point3D.X = OP.OperationData.Position.X;
			if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
			{
				point3D.X = Profile.Length - OP.OperationData.Position.X;
			}
		}
		if (((OP.OperationData.selectedPlaneName == planeNames.Top) | (OP.OperationData.selectedPlaneName == planeNames.Bottom)) && buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
		{
			point3D.X = OP.OperationData.Position.X;
			if (buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
			{
				point3D.X = Profile.Length - OP.OperationData.Position.X;
			}
		}
		for (int i = 0; i <= entCam.Count - 1; i++)
		{
			if (entCam[i].Count <= 0)
			{
				continue;
			}
			List<buEntity> copiedEntities = new List<buEntity>();
			buEntity.Copy(entCam[i], ref copiedEntities);
