				{
					vector3D = OP.OperationData.selectedPlane.AxisZ * OP.OperationData.CamParMilling.Distances.Rapid;
				}
				double a = clsInit.cVector5.PointAngle(new Point3D(0.0 - VecDepth.X, 0.0 - VecDepth.Y, 0.0 - VecDepth.Z), new Point3D(), Plane.YZ) - 90.0;
				if (indexDepth != 0)
				{
