						buEntity2 = new buLine(pntLastMoved, point3D2);
						buEntity2.typeDefination = entityTypeDefination.CamPlunge;
						buEntity2.Orientation = new OrientationAngle(a, 0.0, 0.0);
						pntLastMoved = buVector5.ToPoint3D(point3D2);
						buEntity2.Info.CamID = IndexRepeat;
						OP.EntityMultiCam.Add(buEntity2);
