							buEntity13 = new buLine(point3D11, point3D10);
						}
						pntLastMoved = buVector5.ToPoint3D(point3D10);
						buEntity13.Orientation.A = -90.0;
						buEntity13.typeDefination = entityTypeDefination.CamPlunge;
						buEntity13.Info.CamID = IndexRepeat;
						OP.EntityMultiCam.Add(buEntity13);
					}
				}
				else
				{
					Point3D point3D12 = new Point3D(copiedEntities[0].StartPoint.X, calcDepth[indexDepth].TopPosition, copiedEntities[0].StartPoint.Z);
					if (copiedEntities[0].sortDirection == entitySortDirection.Reverse)
					{
						point3D12 = new Point3D(copiedEntities[0].EndPoint.X, calcDepth[indexDepth].TopPosition, copiedEntities[0].EndPoint.Z);
					}
					buLine buLine8 = new buLine(new Point3D(point3D12.X + vector3D4.X, point3D12.Y + vector3D4.Y, point3D12.Z + vector3D4.Z), point3D12);
					new CustomData();
					buLine8.typeDefination = entityTypeDefination.CamPlunge;
					buLine8.Orientation.A = -90.0;
					buEntity buEntity15 = buVector5.CopyEntities(buLine8);
					buEntity15.Translate(point3D.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
					buEntity15.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
					buEntity15.Info.CamID = IndexRepeat;
					OP.EntityMultiCam.Add(buEntity15);
				}
				for (int m = 0; m <= copiedEntities.Count - 1; m++)
				{
					buEntity buEntity16 = buVector5.CopyEntities(copiedEntities[m]);
					buEntity16.Translate(point3D.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
					buEntity16.Translate(0.0, calcDepth[indexDepth].TopPosition + VecDepth.Y, VecDepth.Z);
					buEntity16.Orientation.A = -90.0;
					buEntity16.Info.CamID = IndexRepeat;
					OP.EntityMultiCam.Add(buEntity16);
					pntLastMoved = buVector5.ToPoint3D(buEntity16.EndPoint);
					if (buEntity16.sortDirection == entitySortDirection.Reverse)
					{
						pntLastMoved = buVector5.ToPoint3D(buEntity16.StartPoint);
					}
				}
				if (indexDepth == calcDepth.Count - 1)
				{
					Point3D end4 = new Point3D(pntLastMoved.X + vector3D4.X, Profile.ProfileMaxPoint.Y + vector3D4.Y, pntLastMoved.Z + vector3D4.Z);
					buLine buLine9 = new buLine(pntLastMoved, end4);
					buLine9.typeDefination = entityTypeDefination.CamLeave;
					buLine9.Orientation.A = -90.0;
					buLine9.Info.CamID = IndexRepeat;
					OP.EntityMultiCam.Add(buLine9);
				}
			}
			if (OP.OperationData.selectedPlaneName != planeNames.Bottom || copiedEntities == null)
			{
				continue;
			}
			Vector3D vector3D5 = OP.OperationData.selectedPlane.AxisZ * (0.0 - OP.OperationData.CamParMilling.Distances.Safe);
			if (MoveSmallSafe)
			{
				vector3D5 = OP.OperationData.selectedPlane.AxisZ * (0.0 - OP.OperationData.CamParMilling.Distances.Rapid);
			}
			if (indexDepth != 0)
			{
				if ((indexDepth > 0) & (indexDepth <= calcDepth.Count - 1))
				{
					buEntity buEntity17 = buVector5.CopyEntities(copiedEntities[0]);
					buEntity17.Translate(point3D.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
					buEntity17.Translate(0.0, VecDepth.Y + disMoveY, calcDepth[indexDepth].BottomPosition);
					Point3D point3D13 = new Point3D(buEntity17.StartPoint.X, buEntity17.StartPoint.Y, buEntity17.StartPoint.Z);
					if (copiedEntities[0].sortDirection == entitySortDirection.Reverse)
					{
						point3D13 = new Point3D(buEntity17.EndPoint.X, buEntity17.EndPoint.Y, buEntity17.EndPoint.Z);
					}
					double num4 = Math.Abs(point3D13.Z - pntLastMoved.Z);
					Point3D point3D14 = new Point3D(point3D13.X, point3D13.Y, point3D13.Z);
					if (!(num4 > buProfileCalc.varProfileSettings.EachLayerSafeDistance))
					{
						buEntity17 = new buLine(pntLastMoved, point3D13);
					}
					else
					{
						point3D14 = new Point3D(point3D13.X, point3D13.Y, calcDepth[indexDepth].TopPosition - buProfileCalc.varProfileSettings.EachLayerSafeDistance);
						buEntity buEntity18 = new buLine(pntLastMoved, point3D14);
						buEntity18.typeDefination = entityTypeDefination.CamPlungeFast;
						buEntity18.Orientation = new OrientationAngle(buEntity17.Orientation);
						buEntity18.Info.CamID = IndexRepeat;
						OP.EntityMultiCam.Add(buEntity18);
						buEntity17 = new buLine(point3D14, point3D13);
					}
					buEntity17.typeDefination = entityTypeDefination.CamPlunge;
					buEntity17.Info.CamID = IndexRepeat;
					OP.EntityMultiCam.Add(buEntity17);
					pntLastMoved = buVector5.ToPoint3D(point3D13);
				}
			}
			else
			{
				Point3D point3D15 = new Point3D(copiedEntities[0].StartPoint.X, copiedEntities[0].StartPoint.Y, calcDepth[indexDepth].TopPosition);
				if (copiedEntities[0].sortDirection == entitySortDirection.Reverse)
				{
					point3D15 = new Point3D(copiedEntities[0].EndPoint.X, copiedEntities[0].EndPoint.Y, calcDepth[indexDepth].TopPosition);
				}
				buLine buLine10 = new buLine(new Point3D(point3D15.X + vector3D5.X, point3D15.Y + vector3D5.Y, point3D15.Z + vector3D5.Z), point3D15);
				buLine10.typeDefination = entityTypeDefination.CamPlunge;
				buEntity buEntity19 = buVector5.CopyEntities(buLine10);
				buEntity19.Translate(point3D.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
				buEntity19.Translate(0.0, VecDepth.Y + disMoveY, VecDepth.Z);
				buEntity19.Info.CamID = IndexRepeat;
				OP.EntityMultiCam.Add(buEntity19);
			}
			for (int n = 0; n <= copiedEntities.Count - 1; n++)
			{
				buEntity buEntity20 = buVector5.CopyEntities(copiedEntities[n]);
				buEntity20.Translate(point3D.X + disMoveX, VecTranslate.Y, VecTranslate.Z + disMoveZ);
				buEntity20.Translate(0.0, VecDepth.Y + disMoveY, calcDepth[indexDepth].BottomPosition);
				buEntity20.Info.CamID = IndexRepeat;
				OP.EntityMultiCam.Add(buEntity20);
				pntLastMoved = buVector5.ToPoint3D(buEntity20.EndPoint);
				if (buEntity20.sortDirection == entitySortDirection.Reverse)
				{
					pntLastMoved = buVector5.ToPoint3D(buEntity20.StartPoint);
				}
			}
			if (indexDepth == calcDepth.Count - 1)
			{
				Point3D end5 = new Point3D(pntLastMoved.X + vector3D5.X, pntLastMoved.Y + vector3D5.Y, Profile.ProfileMinPoint.Z + vector3D5.Z);
				buLine buLine11 = new buLine(pntLastMoved, end5);
				buLine11.typeDefination = entityTypeDefination.CamLeave;
				buLine11.Info.CamID = IndexRepeat;
				OP.EntityMultiCam.Add(buLine11);
			}
		}
		OP.CamCalculation = new List<camTp>();
		clsInit.cCam5.camEntitiesToCamPoints(OP.EntityMultiCam, OP.OperationData.CamParMilling, OP.Tool, ref OP.CamCalculation);
	}

	public void AllOperationToCam(ref buEyeBaseVer5.Apps.ProfileItem Profile)
	{
		new Pnt6DSimMove();
		for (int i = 0; i <= Profile.CalculationData.Count - 1; i++)
		{
			for (int j = 0; j <= Profile.CalculationData[i].calcOperations.Count - 1; j++)
			{
				if (!Profile.CalculationData[i].calcOperations[j].Enable)
				{
					continue;
				}
				GProfileOperation gProfileOperation = Profile.CalculationData[i].calcOperations[j];
				GProfileOperation CopiedOperation = null;
				GProfileOperation CopiedOperation2 = null;
				if (Profile.CalculationData[i].calcOperations[j].OperationData.selectedPlaneName != planeNames.Back)
				{
				}
				if (j < Profile.CalculationData[i].calcOperations.Count - 1)
				{
					GProfileOperation.Copy(Profile.CalculationData[i].calcOperations[j + 1], ref CopiedOperation);
				}
				if (j > 0)
				{
					GProfileOperation.Copy(Profile.CalculationData[i].calcOperations[j - 1], ref CopiedOperation2);
				}
				for (int num = gProfileOperation.EntityMultiCam.Count - 1; num >= 0; num--)
				{
					if (gProfileOperation.EntityMultiCam[num].typeDefination == entityTypeDefination.Temp)
					{
						gProfileOperation.EntityMultiCam.RemoveAt(num);
					}
				}
				if (Profile.CalculationData[i].calcOperations.Count != 1)
				{
					if (Profile.CalculationData[i].calcOperations.Count > 1 && Profile.CalculationData[i].calcOperations[j].OperationData.OperationType != ProfileOperationTypes.Notch)
					{
						int count = gProfileOperation.EntityMultiCam.Count;
						int num2 = 0;
						for (int k = 0; k <= count - 1; k++)
						{
							if (j == 0)
							{
								if (!(gProfileOperation.EntityMultiCam[k].typeDefination == entityTypeDefination.CamPlunge && num2 == 0))
								{
								}
								if (gProfileOperation.EntityMultiCam[k].typeDefination != entityTypeDefination.CamLeave)
								{
								}
							}
							if (j > 0)
							{
								if (!(gProfileOperation.EntityMultiCam[k].typeDefination == entityTypeDefination.CamPlunge && num2 == 0))
								{
								}
								if (gProfileOperation.EntityMultiCam[k].typeDefination != entityTypeDefination.CamLeave)
								{
								}
							}
						}
					}
				}
				else
				{
					int count2 = gProfileOperation.EntityMultiCam.Count;
					int num3 = 0;
					if (Profile.CalculationData[i].calcOperations[j].OperationData.OperationType != ProfileOperationTypes.Notch)
					{
						for (int l = 0; l <= count2 - 1; l++)
						{
							if (!(gProfileOperation.EntityMultiCam[l].typeDefination == entityTypeDefination.CamPlunge && num3 == 0))
							{
							}
							if (gProfileOperation.EntityMultiCam[l].typeDefination != entityTypeDefination.CamLeave)
							{
							}
						}
					}
				}
				if (j <= 0)
				{
				}
				if (gProfileOperation.OperationData.OperationType == ProfileOperationTypes.Notch)
				{
					if (CopiedOperation == null || gProfileOperation.CamCalculation == null || gProfileOperation.CamCalculation.Count <= 0)
					{
						continue;
					}
					camTp camTp2 = gProfileOperation.CamCalculation[gProfileOperation.CamCalculation.Count - 1];
					if (camTp2.CamPoints.Count <= 0)
					{
						continue;
					}
					TpPnt9D tpPnt9D = camTp2.CamPoints[camTp2.CamPoints.Count - 1].Points[camTp2.CamPoints[camTp2.CamPoints.Count - 1].Points.Count - 1];
					if (CopiedOperation.CamCalculation != null && CopiedOperation.CamCalculation.Count > 0)
					{
						TpPnt9D tpPnt9D2 = CopiedOperation.CamCalculation[0].CamPoints[0].Points[0];
						if (tpPnt9D.P9.A != tpPnt9D2.P9.A && !(tpPnt9D.P9.A > 0.0))
						{
						}
					}
				}
				else
				{
					gProfileOperation.CamCalculation = new List<camTp>();
					clsInit.cCam5.camEntitiesToCamPoints(gProfileOperation.EntityMultiCam, gProfileOperation.OperationData.CamParMilling, gProfileOperation.Tool, ref gProfileOperation.CamCalculation);
				}
			}
		}
	}

	public void NotchToCam(ref buEyeBaseVer5.Apps.ProfileOperation OP, buEyeBaseVer5.Apps.ProfileItem Profile, List<List<buEntity>> entCam)
	{
		if (entCam.Count == 0)
		{
			return;
		}
		OP.CamCalculation = new List<camTp>();
		for (int i = 0; i <= entCam.Count - 1; i++)
		{
			if (entCam[i] == null)
			{
				continue;
			}
			for (int j = 0; j <= entCam[i].Count - 1; j++)
			{
				buEntity item = buVector5.CopyEntities(entCam[i][j]);
				OP.EntityMultiCam.Add(item);
			}
			List<camTp> Cam = new List<camTp>();
			if (entCam.Count != 1)
			{
				if (i != 0)
				{
					clsInit.cCam5.camEntitiesToCamPoints(entCam[i], OP.OperationData.CamParNotch, OP.Tool, ref Cam);
				}
				else
				{
					clsInit.cCam5.camEntitiesToCamPoints(entCam[i], OP.OperationData.CamParNotch, OP.ToolNotch, ref Cam);
				}
				if (Cam.Count > 0)
				{
					OP.CamCalculation.Add(Cam[0]);
				}
				if (OP.CamCalculation.Count > 0 && OP.CamCalculation[0].CamPoints.Count > 0)
				{
					camTpPoint camTpPoint2 = OP.CamCalculation[0].CamPoints[0];
					camTpPoint camTpPoint3 = OP.CamCalculation[OP.CamCalculation.Count - 1].CamPoints[OP.CamCalculation[OP.CamCalculation.Count - 1].CamPoints.Count - 1];
					if (camTpPoint2.Points.Count > 0 && camTpPoint2.Points[0].P9.Z > Profile.Height)
					{
						camTpPoint2.Points[0].IsSafePosition = true;
					}
					if (camTpPoint3.Points.Count > 0 && camTpPoint3.Points[camTpPoint3.Points.Count - 1].P9.Z > Profile.Height)
					{
						camTpPoint3.Points[camTpPoint3.Points.Count - 1].IsSafePosition = true;
					}
				}
				continue;
			}
			clsInit.cCam5.camEntitiesToCamPoints(entCam[i], OP.OperationData.CamParNotch, OP.ToolNotch, ref OP.CamCalculation);
			if (OP.CamCalculation.Count > 0 && OP.CamCalculation[0].CamPoints.Count > 0)
			{
				camTpPoint camTpPoint4 = OP.CamCalculation[0].CamPoints[0];
				camTpPoint camTpPoint5 = OP.CamCalculation[OP.CamCalculation.Count - 1].CamPoints[OP.CamCalculation[OP.CamCalculation.Count - 1].CamPoints.Count - 1];
				if (camTpPoint4.Points.Count > 0 && camTpPoint4.Points[0].P9.Z > Profile.Height)
				{
					camTpPoint4.Points[0].IsSafePosition = true;
				}
				if (camTpPoint5.Points.Count > 0 && camTpPoint5.Points[camTpPoint5.Points.Count - 1].P9.Z > Profile.Height)
				{
					camTpPoint5.Points[camTpPoint5.Points.Count - 1].IsSafePosition = true;
				}
			}
		}
		if (OP.CamCalculation.Count > 0)
		{
			for (int k = 0; k <= OP.CamCalculation.Count - 1; k++)
			{
				TpPnt9D tpPnt9D = new TpPnt9D(OP.CamCalculation[k].CamPoints[0].Points[0]);
				tpPnt9D.EnableAxes.Z = false;
				TpPnt9D item2 = new TpPnt9D(OP.CamCalculation[k].CamPoints[0].Points[0]);
				OP.CamCalculation[k].CamPoints[0].Points[0] = tpPnt9D;
				OP.CamCalculation[k].CamPoints[0].Points.Insert(1, item2);
			}
		}
	}

	public void ClamperSetTrackValue()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem != null && ((clsInit.appProfile.SelectedClamperIndex >= 0) & (clsInit.appProfile.SelectedClamperIndex <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1)))
		{
			double num = 0.0;
			double num2 = 0.0;
			buEyeBaseVer5.Apps.ProfileClamper profileClamper = null;
			buEyeBaseVer5.Apps.ProfileClamper profileClamper2 = null;
			buEyeBaseVer5.Apps.ProfileClamper profileClamper3 = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[clsInit.appProfile.SelectedClamperIndex];
			if (clsInit.appProfile.SelectedClamperIndex > 0)
			{
				profileClamper = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[clsInit.appProfile.SelectedClamperIndex - 1];
			}
			if (clsInit.appProfile.SelectedClamperIndex < clsInit.appProfile.Clampers.Count - 1)
			{
				profileClamper2 = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[clsInit.appProfile.SelectedClamperIndex + 1];
			}
			num = ((profileClamper != null) ? (profileClamper.XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance) : clsInit.appProfile.Clampers[clsInit.appProfile.SelectedClamperIndex].MinPositionRange);
			num2 = ((profileClamper2 != null) ? (profileClamper2.XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth - buProfileCalc.varProfileClamperSettings.ClamperSafeDistance) : clsInit.appProfile.Clampers[clsInit.appProfile.SelectedClamperIndex].MaxPositionRange);
			frmSim.track_clamper.MinimumValue = num;
			frmSim.track_clamper.MaximumValue = num2;
			frmSim.track_clamper.Value = profileClamper3.XPosition;
			if (!ClamperUpdating)
			{
				clsInit.appProfile.ClamperUpdate(ClearList: false);
				clsInit.appProfile.DrawSimulationEntities(clsInit.appProfile.activeProfile.FirstItem, clsInit.appProfile.activeProfile.SecondItem, buProfileCalc.varProfileRunSettings.activeOPIndex, new List<buEyeBaseVer5.Apps.ProfileClamper>());
			}
		}
	}

	public void ClamperUpdate(bool ClearList)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		ClamperUpdating = true;
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
		{
			if (ClearList)
			{
				frmSim.dgv_clamper.Rows.Clear();
				if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count > 0)
				{
					int clamperIndex = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].ClamperIndex;
					if ((clamperIndex >= 0) & (clamperIndex <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists.Count - 1))
					{
						profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists[clamperIndex].Clear();
					}
					for (int i = 0; i <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1; i++)
					{
						frmSim.dgv_clamper.Rows.Add((i + 1).ToString(), "X: " + profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[i].XPosition.ToString("f2"));
						frmSim.dgv_clamper.Rows[frmSim.dgv_clamper.Rows.Count - 1].Height = 34;
						profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists[clamperIndex].Add(new buEyeBaseVer5.Apps.ProfileClamper(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[i]));
					}
				}
			}
			if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count == 0)
			{
				ClamperUpdating = false;
				return;
			}
			for (int j = 0; j <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1; j++)
			{
				if (!ClearList && j <= frmSim.dgv_clamper.Rows.Count - 1)
				{
					frmSim.dgv_clamper.Rows[j].Cells[1].Value = "X: " + profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[j].XPosition.ToString("f2");
				}
			}
		}
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
		{
			if (ClearList)
			{
				frmSim.dgv_clamper.Rows.Clear();
				if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count > 0)
				{
					int clamperIndex2 = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].ClamperIndex;
					if ((clamperIndex2 >= 0) & (clamperIndex2 <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists.Count - 1))
					{
						profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists[clamperIndex2].Clear();
					}
					for (int k = 0; k <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1; k++)
					{
						frmSim.dgv_clamper.Rows.Add((k + 1).ToString(), "X: " + profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[k].XPosition.ToString("f2"));
						frmSim.dgv_clamper.Rows[frmSim.dgv_clamper.Rows.Count - 1].Height = 34;
						profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists[clamperIndex2].Add(new buEyeBaseVer5.Apps.ProfileClamper(profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[k]));
					}
				}
			}
			if (profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count == 0)
			{
				return;
			}
			for (int l = 0; l <= profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1; l++)
			{
				if (!ClearList && l <= frmSim.dgv_clamper.Rows.Count - 1)
				{
					frmSim.dgv_clamper.Rows[l].Cells[1].Value = "X: " + profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[l].XPosition.ToString("f2");
				}
			}
		}
		for (int m = 0; m <= frmSim.dgv_clamper.Rows.Count - 1; m++)
		{
			frmSim.dgv_clamper.Rows[m].DefaultCellStyle.BackColor = Color.WhiteSmoke;
			if (clsInit.appProfile.SelectedClamperIndex == m)
			{
				frmSim.dgv_clamper.Rows[m].DefaultCellStyle.BackColor = Color.LightSteelBlue;
			}
		}
		ClamperSetTrackValue();
		frmSim.SelectClamperGrid(clsInit.appProfile.SelectedClamperIndex);
		ClamperUpdating = false;
	}

	public void ClamperMoveBwdFwd(double Value)
	{
		buEyeBaseVer5.Apps.ProfileItem Item = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (Item == null)
		{
			return;
		}
		double num = buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
		if (!((SelectedClamperIndex >= 0) & (SelectedClamperIndex <= Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1)))
		{
			return;
		}
		int selectedClamperIndex = SelectedClamperIndex;
		buEyeBaseVer5.Apps.ProfileClamper.Copy(Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers, ref clsInit.appProfile.ClampersOldPosBeforeMove);
		if (!(Value > 0.0))
		{
			if (Value < 0.0)
			{
				double xPosition = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex].XPosition;
				double num2 = -1000000.0;
				if (SelectedClamperIndex > 0)
				{
					num2 = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex - 1].XPosition;
				}
				double num3 = xPosition + Value - num2;
				if (num3 > num && xPosition + Value > Clampers[SelectedClamperIndex].MinPositionRange)
				{
					Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex].XPosition = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex].XPosition + Value;
				}
			}
		}
		else
		{
			double xPosition2 = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex].XPosition;
			double num4 = 1000000.0;
			if (SelectedClamperIndex < Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1)
			{
				num4 = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex + 1].XPosition;
			}
			double num5 = num4 - (xPosition2 + Value);
			if (num5 > num && xPosition2 + Value < Clampers[SelectedClamperIndex].MaxPositionRange)
			{
				Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex].XPosition = Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex].XPosition + Value;
			}
		}
		ClamperSetUpdate(Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].ClamperIndex, Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers);
		ClamperUpdate(ClearList: true);
		if (Item != null)
		{
			BasicCollsionControl(ref Item);
		}
		DrawSimulationEntities(activeProfile.FirstItem, activeProfile.SecondItem, buProfileCalc.varProfileRunSettings.activeOPIndex, new List<buEyeBaseVer5.Apps.ProfileClamper>());
		SelectedClamperIndex = selectedClamperIndex;
	}

	public void ClamperEdit()
	{
		buEyeBaseVer5.Apps.ProfileItem curItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (curItem == null || !((SelectedClamperIndex >= 0) & (SelectedClamperIndex <= curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers.Count - 1)))
		{
			return;
		}
		DialogBoxInput dialogBoxInput = new DialogBoxInput();
		dialogBoxInput.FormCaption = "Clamper";
		dialogBoxInput.ValueCaption = "X Position";
		double num = (dialogBoxInput.Value = Convert.ToDouble(curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[SelectedClamperIndex].XPosition));
		dialogBoxInput.Init();
		dialogBoxInput.StartPosition = FormStartPosition.CenterParent;
		dialogBoxInput.ShowDialog();
		if (dialogBoxInput.Result == DialogResult.OK)
		{
			ProfileItemCalc CalcData = curItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex];
			if (frmSim != null)
			{
				frmSim.dgv_clamper.Rows[SelectedClamperIndex].Cells[1].Value = "X: " + dialogBoxInput.Value.ToString("f2");
			}
			ClamperMove(dialogBoxInput.Value - num, SelectedClamperIndex, ref curItem, ref CalcData, ClamperListUpdate: true);
		}
	}

	public void ClamperMove(double dX, int ClampIndex, ref buEyeBaseVer5.Apps.ProfileItem curItem, ref ProfileItemCalc CalcData, bool ClamperListUpdate)
	{
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
		{
			double num = curItem.Length;
			double num2 = 0.0;
			if (!buProfileCalc.varProfileSettings.ClamperCanMoveInsideProfileLength)
			{
				num = buProfileCalc.varProfileSettings.MachineLength;
			}
			if (CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[ClampIndex].XPosition + dX > num)
			{
				dX = num - CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[ClampIndex].XPosition;
			}
			if (CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[ClampIndex].XPosition + dX < num2)
			{
				dX = num2 - CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[ClampIndex].XPosition;
			}
			if (CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[ClampIndex].XPosition + dX <= num && CalcData.calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers[ClampIndex].XPosition + dX >= num2)
			{
