							}
							else
							{
								flag = false;
							}
						}
					}
				}
				else if (clampers.Count >= 1)
				{
					double xPosition4 = clampers[ClampIndex + 1].XPosition;
					if (num3 > xPosition4 - buProfileCalc.varProfileClamperSettings.ClamperWidth - buProfileCalc.varProfileClamperSettings.ClamperSafeDistance)
