	public void ClamperCopy()
	{
		buEyeBaseVer5.Apps.ProfileItem Item = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (Item == null || !((buProfileCalc.varProfileRunSettings.activeOPIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeOPIndex <= Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count - 1)))
		{
			return;
		}
		List<buEyeBaseVer5.Apps.ProfileClamper> CopiedClamper = new List<buEyeBaseVer5.Apps.ProfileClamper>();
		buEyeBaseVer5.Apps.ProfileClamper.Copy(Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex].Clampers, ref CopiedClamper);
		for (int i = buProfileCalc.varProfileRunSettings.activeOPIndex + 1; i <= Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count - 1; i++)
		{
			Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[i].Clampers.Clear();
			for (int j = 0; j <= CopiedClamper.Count - 1; j++)
			{
				Item.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[i].Clampers.Add(new buEyeBaseVer5.Apps.ProfileClamper(CopiedClamper[j]));
			}
		}
		ClamperUpdate(ClearList: true);
		Item.isGCodeCreated = false;
		Item.isGCodeSimMoveCreated = false;
		doCalculateAll(ref Item, Clamper: false, Cam: true, GCodeToSim: true);
		clsInit.appProfile.DrawSimulationEntities(activeProfile.FirstItem, activeProfile.SecondItem, buProfileCalc.varProfileRunSettings.activeOPIndex, new List<buEyeBaseVer5.Apps.ProfileClamper>());
	}

	public void ClamperNewSetPosition()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null || !((profileItem != null) & (buProfileCalc.varProfileRunSettings.activeOPIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeCalcDataIndex >= 0)))
		{
			return;
		}
		GProfileOperation gProfileOperation = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[buProfileCalc.varProfileRunSettings.activeOPIndex];
		if (gProfileOperation.Clampers.Count > 0)
		{
			List<buEyeBaseVer5.Apps.ProfileClamper> CopiedClamper = new List<buEyeBaseVer5.Apps.ProfileClamper>();
			buEyeBaseVer5.Apps.ProfileClamper.Copy(gProfileOperation.Clampers, ref CopiedClamper);
			if (CopiedClamper.Count > 0)
			{
				profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists.Add(CopiedClamper);
				gProfileOperation.Clampers.Clear();
				buEyeBaseVer5.Apps.ProfileClamper.Copy(CopiedClamper, ref gProfileOperation.Clampers);
				gProfileOperation.ClamperIndex = profileItem.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].ClamperLists.Count - 1;
			}
		}
	}

	public void UpdateOperationFromNewClamperSet(int OperationIndex, int NewSetIndex, ref GProfileOperation refOP, ref List<GProfileOperation> OPList)
	{
		if (!((OperationIndex >= 0) & (OperationIndex <= OPList.Count - 1) & (OPList.Count >= 2)))
		{
			return;
		}
		OPList.RemoveAt(OperationIndex);
		int num = -1;
		bool flag = false;
		for (int i = 0; i <= OPList.Count - 1; i++)
		{
			if (OPList[i].ClamperIndex != NewSetIndex)
			{
				if (!flag && num >= 0)
				{
					OPList.Insert(num, refOP);
					flag = true;
					i = OPList.Count;
				}
				continue;
			}
			if (num == -1)
			{
				num = i;
			}
			if (!(refOP.SizePoint.MinPoint.X > OPList[i].SizePoint.MinPoint.X))
			{
				continue;
			}
			if (i != 0)
			{
				if (i != OPList.Count - 1)
				{
					OPList.Insert(i, refOP);
				}
				else
				{
					OPList.Add(refOP);
				}
			}
			else
			{
				OPList.Insert(0, refOP);
			}
			flag = true;
			i = OPList.Count;
		}
		if (!flag && num >= 0)
		{
			OPList.Insert(num, refOP);
			flag = true;
		}
		if (!flag)
		{
			OPList.Insert(0, refOP);
			flag = true;
		}
	}

	public void ClamperSetUpdate(int indexSet, List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = null;
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
		{
			profileItem = activeProfile.FirstItem;
			if (profileItem != null)
			{
				for (int i = 0; i <= profileItem.CalculationData.Count - 1; i++)
				{
					for (int j = 0; j <= profileItem.CalculationData[i].calcOperations.Count - 1; j++)
					{
						if (profileItem.CalculationData[i].calcOperations[j].ClamperIndex == indexSet)
						{
							List<buEyeBaseVer5.Apps.ProfileClamper> CopiedClamper = new List<buEyeBaseVer5.Apps.ProfileClamper>();
							buEyeBaseVer5.Apps.ProfileClamper.Copy(ClamperList, ref CopiedClamper);
							profileItem.CalculationData[i].calcOperations[j].Clampers = CopiedClamper;
						}
					}
				}
				if (activeProfile.SecondItem != null)
				{
					for (int k = 0; k <= activeProfile.SecondItem.CalculationData.Count - 1; k++)
					{
						for (int l = 0; l <= activeProfile.SecondItem.CalculationData[k].calcOperations.Count - 1; l++)
						{
							if (buEyeBaseVer5.Apps.ProfileClamper.isClamperPositionsEqual(ClampersOldPosBeforeMove, activeProfile.SecondItem.CalculationData[k].calcOperations[l].Clampers))
							{
								activeProfile.SecondItem.CalculationData[k].calcOperations[l].Clampers.Clear();
								buEyeBaseVer5.Apps.ProfileClamper.Copy(ClamperList, ref activeProfile.SecondItem.CalculationData[k].calcOperations[l].Clampers);
							}
						}
					}
				}
			}
		}
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex != 1)
		{
			return;
		}
		profileItem = activeProfile.SecondItem;
		if (profileItem == null)
		{
			return;
		}
		for (int m = 0; m <= profileItem.CalculationData.Count - 1; m++)
		{
			for (int n = 0; n <= profileItem.CalculationData[m].calcOperations.Count - 1; n++)
			{
				if (profileItem.CalculationData[m].calcOperations[n].ClamperIndex == indexSet)
				{
					List<buEyeBaseVer5.Apps.ProfileClamper> CopiedClamper2 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
					buEyeBaseVer5.Apps.ProfileClamper.Copy(ClamperList, ref CopiedClamper2);
					profileItem.CalculationData[m].calcOperations[n].Clampers = CopiedClamper2;
				}
			}
		}
		if (activeProfile.FirstItem == null)
		{
			return;
		}
		for (int num = 0; num <= activeProfile.FirstItem.CalculationData.Count - 1; num++)
		{
			for (int num2 = 0; num2 <= activeProfile.FirstItem.CalculationData[num].calcOperations.Count - 1; num2++)
			{
				if (buEyeBaseVer5.Apps.ProfileClamper.isClamperPositionsEqual(ClampersOldPosBeforeMove, activeProfile.FirstItem.CalculationData[num].calcOperations[num2].Clampers))
				{
					activeProfile.FirstItem.CalculationData[num].calcOperations[num2].Clampers.Clear();
					buEyeBaseVer5.Apps.ProfileClamper.Copy(ClamperList, ref activeProfile.FirstItem.CalculationData[num].calcOperations[num2].Clampers);
				}
			}
		}
	}

	public bool CheckClamper(ref buEyeBaseVer5.Apps.ProfileClamper Clamper, double X, List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList, int MaxClamper, int ExceptionClampedIndex)
	{
		string text = "CheckClamper";
		try
		{
			if (!(X < 0.0))
			{
				Clamper = new buEyeBaseVer5.Apps.ProfileClamper();
				Clamper.Width = buProfileCalc.varProfileClamperSettings.ClamperWidth;
				Clamper.XPosition = X;
				Clamper.Used = true;
				Clamper.Enable = true;
				Clamper.GeometrixMaxX = Clamper.XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
				Clamper.GeometrixMinX = Clamper.XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
				bool flag = false;
				bool flag2 = false;
				for (int i = 0; i <= ClamperList.Count - 1; i++)
				{
					bool flag3 = buNumeric5.IsValueInsideMinMaxValues(Clamper.GeometrixMinX, ClamperList[i].GeometrixMinX, ClamperList[i].GeometrixMaxX);
					bool flag4 = buNumeric5.IsValueInsideMinMaxValues(Clamper.GeometrixMaxX, ClamperList[i].GeometrixMinX, ClamperList[i].GeometrixMaxX);
					if (ExceptionClampedIndex < 0 || i != ExceptionClampedIndex)
					{
						flag = flag || flag3;
						flag2 = flag2 || flag4;
					}
					if (Clamper.XPosition <= ClamperList[i].XPosition)
					{
						return false;
					}
				}
				if (!(!flag && !flag2))
				{
					return false;
				}
				int count = ClamperList.Count;
				if (ClamperList.Count <= MaxClamper - 1)
				{
					if (!((Clampers[count].MinPositionRange <= X) & (X <= Clampers[count].MaxPositionRange)))
					{
						return false;
					}
					return true;
				}
				return false;
			}
			return false;
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_1, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
			return false;
		}
	}

	public void OperationPlaneMoved(object Data1, object Data2)
	{
		string text = Data1.ToString();
		double num = Convert.ToDouble(Data2.ToString());
		if (OPData.selectedPlane != null)
		{
			if (text == "movey")
			{
				OPData.selectedPlane.Origin.Y = OPData.selectedPlane.Origin.Y + num;
			}
			if (text == "movez")
			{
				OPData.selectedPlane.Origin.Z = OPData.selectedPlane.Origin.Z + num;
			}
			if (text == "rotate")
			{
				OPData.selectedPlane.Rotate(buConversion5.DegreeToRadian(0.0 - num), Vector3D.AxisX, point3D_3);
			}
			buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane)OPData.selectedPlane.Clone();
			ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg();
			shapeUpdateArg.Finished = false;
			shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			shapeUpdateArg.Tool = new ToolBase5(ccVars.toolActive);
			OnlineOperation(null, shapeUpdateArg, OPData);
		}
	}

