	public void CommandOperation(object Data1, object Data2)
	{
		if (Data1.ToString() == "PlaneSelect")
		{
			cmdPlaneList();
		}
		if (Data1.ToString() == "Locked")
		{
			ToolChangeForced = (bool)Data2;
		}
		if (!(Data1.ToString() == "ToolEdit"))
		{
			return;
		}
		ToolBase5 tool = new ToolBase5(ccVars.toolActive);
		F_Tool f_Tool = new F_Tool();
		CreateModelProperties Properties = new CreateModelProperties();
		clsInit.appCommand.EyeParameterToCreateModelProperties(clsVar.varPreviewViewport, clsVar.varMouse, ref Properties);
		Properties.CoordinateSystemIconVisible = false;
		Properties.ViewCubeIconVisible = false;
		Properties.OrigineCaptionVisible = false;
		Properties.ToolBorVisible = false;
		Properties.OrigineSymbol = originSymbolStyleType.CoordinateSystem;
		Properties.OriginSymbolVisible = true;
		Properties.OrigineSize = 5;
		f_Tool.viewportLayout = clsInit.cVector5.CreateModelControl(clsVar.UnlockKey, Properties);
		f_Tool.viewportLayout.CompileUserInterfaceElements();
		f_Tool.viewportLayout.Entities.Clear();
		f_Tool.Properties.FormCloseMode = FormCloseModeType.Invisible;
		f_Tool.Tool = new ToolBase5(tool);
		f_Tool.Init();
		f_Tool.StartPosition = FormStartPosition.CenterParent;
		f_Tool.ShowDialog();
		if (f_Tool.Properties.Result != DialogResult.OK)
		{
			return;
		}
		if (FrmOperationList != null && FrmOperationList.Visible)
		{
			bool flag = false;
			for (int i = 0; i <= ccVars.Tools.Count - 1; i++)
			{
				for (int j = 0; j <= ccVars.Tools[i].Tools.Count - 1; j++)
				{
					if (ccVars.Tools[i].Tools[j].Data.Name == f_Tool.Tool.Data.Name)
					{
						ccVars.Tools[i].Tools[j] = new ToolBase5(f_Tool.Tool);
						flag = true;
					}
				}
			}
			if (!flag)
			{
				for (int k = 0; k <= ccVars.Tools.Count - 1; k++)
				{
					for (int l = 0; l <= ccVars.Tools[k].Tools.Count - 1; l++)
					{
						if (ccVars.Tools[k].Tools[l].Data.No == f_Tool.Tool.Data.No)
						{
							ccVars.Tools[k].Tools[l] = new ToolBase5(f_Tool.Tool);
							flag = true;
						}
					}
				}
			}
			if (!flag)
			{
				for (int m = 0; m <= ccVars.Tools.Count - 1; m++)
				{
					for (int n = 0; n <= ccVars.Tools[m].Tools.Count - 1; n++)
					{
						if (ccVars.Tools[m].Tools[n].Geometry.Diameter == f_Tool.Tool.Geometry.Diameter && ccVars.Tools[m].Tools[n].Geometry.GeometryType == f_Tool.Tool.Geometry.GeometryType)
						{
							ccVars.Tools[m].Tools[n] = new ToolBase5(f_Tool.Tool);
							flag = true;
						}
					}
				}
			}
			if (flag)
			{
				ccVars.toolActive = new ToolBase5(f_Tool.Tool);
				FrmOperationList.cmb_tools.Items.Clear();
				for (int num = 0; num <= ccVars.Tools.Count - 1; num++)
				{
					for (int num2 = 0; num2 <= ccVars.Tools[num].Tools.Count - 1; num2++)
					{
						FrmOperationList.cmb_tools.Items.Add(buProfileCalc.ToolToString(ccVars.Tools[num].Tools[num2]));
					}
				}
				FrmOperationList.cmb_tools.Text = buProfileCalc.ToolToString(ccVars.toolActive);
			}
		}
		clsVar.varInterface.pathTool = AppPath.Tool;
		clsVar.varInterface.pathToolHolder = AppPath.ToolHolder;
		clsFiles.SaveParameter();
	}

