			List<EntitiesList> list2 = new List<EntitiesList>();
			for (int num9 = 0; num9 <= shapeCreateParameters_0.entitiesCurveList.Count - 1; num9++)
			{
				EntitiesList item = new EntitiesList(shapeCreateParameters_0.entitiesCurveList[num9]);
				list2.Add(item);
			}
			Point3D point3D = new Point3D(shapeUpdateArg.Parameters.pntBase.X, shapeUpdateArg.Parameters.pntBase.Y, shapeUpdateArg.Parameters.pntBase.Z);
			for (int num10 = 0; num10 <= list2.Count - 1; num10++)
			{
				Point3D MinPoint = new Point3D();
				Point3D MidPoint = new Point3D();
				Point3D MaxPoint = new Point3D();
				clsInit.cVector5.BoxSizeCalculate(list2[num10], ref MinPoint, ref MidPoint, ref MaxPoint);
				MinPoint.X += point3D.X;
				MidPoint.X += point3D.X;
				MaxPoint.X += point3D.X;
				MinPoint.Y += point3D.Y;
				MidPoint.Y += point3D.Y;
				MaxPoint.Y += point3D.Y;
				shapeUpdateArg.Parameters.ShapeType = ShapeTypes.FreeDraw;
				if (list2[num10].Entities.Count == 1 && list2[num10].Entities[0] is buCircle)
				{
					ToolBase5 foundTool2 = new ToolBase5();
