					{
						shapeUpdateArg.Parameters.ShapeType = ShapeTypes.Circle;
						shapeUpdateArg.Parameters.CircleRadius = Math.Round(((buCircle)list2[num10].Entities[0]).Radius, 3);
						shapeUpdateArg.Parameters.isTapping = false;
						OPData.CircleData.CircleDiameter = Math.Round(((buCircle)list2[num10].Entities[0]).Radius * 2.0, 3);
					}
					else
					{
						shapeUpdateArg.Parameters.ShapeType = ShapeTypes.Hole;
						shapeUpdateArg.Parameters.HoleDiameter = Math.Round(((buCircle)list2[num10].Entities[0]).Radius * 2.0, 3);
						shapeUpdateArg.Parameters.isTapping = false;
						OPData.HoleData.HoleDiameter = Math.Round(((buCircle)list2[num10].Entities[0]).Radius * 2.0, 3);
						OPData.HoleData.Tapping = false;
					}
				}
				OPData.FreeDrawData.FreeDrawWidth = Math.Round(MaxPoint.X - MinPoint.X, 3);
				OPData.FreeDrawData.FreeDrawHeight = Math.Round(MaxPoint.Y - MinPoint.Y, 3);
				shapeUpdateArg.Parameters.FreeDrawWidth = Math.Round(MaxPoint.X - MinPoint.X, 3);
				shapeUpdateArg.Parameters.FreeDrawHeight = Math.Round(MaxPoint.Y - MinPoint.Y, 3);
