	public bool CreateOnlineOperationShape(actionTypeBU action, ref buEyeBaseVer5.Apps.ProfileOperation OP, ref bool CreateOperationShape)
	{
		if (action == actionTypeBU.profileRectangle)
		{
			if (OPData.RectangleData.RectangleWidth <= 0.001)
			{
				ShowWarningOPMessage(AppLanguage.CadCamMessages[114]);
				AppBool.Started = false;
				return false;
			}
			if (OPData.RectangleData.RectangleHeight <= 0.001)
			{
				ShowWarningOPMessage(AppLanguage.CadCamMessages[115]);
				AppBool.Started = false;
				return false;
			}
			OP = new buEyeBaseVer5.Apps.ProfileOperationRectangle();
			OP.OperationData = new buEyeBaseVer5.Apps.ProfileOperationData(OPData);
			OP.OperationData.XRefFromProfileEnd = OPData.XRefFromProfileEnd;
			CreateOperationShape = true;
		}
		if (action == actionTypeBU.profileCircle)
		{
			if (OPData.CircleData.CircleDiameter <= 0.001)
			{
				ShowWarningOPMessage(AppLanguage.CadCamMessages[116]);
				AppBool.Started = false;
				return false;
			}
			OP = new buEyeBaseVer5.Apps.ProfileOperationCircle();
			OP.OperationData = new buEyeBaseVer5.Apps.ProfileOperationData(OPData);
			CreateOperationShape = true;
		}
		if (action == actionTypeBU.profileEllipse)
		{
			if (OPData.EllipseData.EllipseWidth <= 0.001)
			{
				ShowWarningOPMessage(AppLanguage.CadCamMessages[114]);
				AppBool.Started = false;
				return false;
			}
			if (OPData.EllipseData.EllipseHeight <= 0.001)
			{
				ShowWarningOPMessage(AppLanguage.CadCamMessages[116]);
				AppBool.Started = false;
				return false;
			}
			OP = new buEyeBaseVer5.Apps.ProfileOperationEllipse();
			OP.OperationData = new buEyeBaseVer5.Apps.ProfileOperationData(OPData);
			CreateOperationShape = true;
		}
		if (action == actionTypeBU.profileSlot)
		{
			if (OPData.SlotData.SlotWidth <= 0.001)
			{
				ShowWarningOPMessage(AppLanguage.CadCamMessages[117]);
