	public void DrawDimEntity(buEyeBaseVer5.Apps.ProfileOperation OP, buEyeBaseVer5.Apps.ProfileItem curItem, ShapeDataValueType ValueType, Point3D CornerPoint)
	{
		Design design = null;
		if (OP == null)
		{
			return;
		}
		design = ((OP.OperationData.Action != actionTypeBU.profileNotch) ? FrmOperationList.viewportLayout : FrmNotchList.viewportLayout);
		for (int num = design.Entities.Count - 1; num >= 0; num--)
		{
			if (design.Entities[num].EntityData != null && design.Entities[num].EntityData is CustomData)
			{
				CustomData customData = design.Entities[num].EntityData as CustomData;
				if (customData.typeDefination == entityTypeDefination.Operation)
				{
					design.Entities[num].Selected = true;
				}
			}
			if (design.Entities[num] is Dimension)
			{
				design.Entities.RemoveAt(num);
			}
		}
		Entity dimEntity = null;
		viewType ViewType = viewType.Top;
		Plane viewPlane = OP.OperationData.selectedPlane;
		MaterialBase5 material = new MaterialBase5(new SizeObject(curItem.Length, curItem.Width, curItem.Height));
		clsInit.cProfile.CreateDimensionEntity(OP, curItem, ValueType, material, CornerPoint, ref dimEntity, ref ViewType, ref viewPlane);
		if (dimEntity != null)
		{
			dimEntity.Selected = true;
			design.Entities.Add(dimEntity);
		}
		if (OP.OperationData.selectedPlaneName == planeNames.Free)
		{
			design.SetView(viewPlane.Equation, fit: true);
		}
		else
		{
			design.SetView(ViewType);
		}
		design.ZoomFit(selectedOnly: true);
		design.ZoomOut(10);
		design.Entities.ClearSelection();
		design.Invalidate();
	}

	public bool doCalculateAll(ref buEyeBaseVer5.Apps.ProfileItem Item, bool Clamper, bool Cam, bool GCodeToSim, bool JustCam = false)
	{
		bool flag = false;
		bool flag2 = false;
		if (!JustCam)
		{
			if (activeProfile.FirstItem != null && activeProfile.FirstItem.Enable && activeProfile.FirstItem.Operations.Count > 0)
			{
				flag = true;
			}
			if (activeProfile.SecondItem != null && activeProfile.SecondItem.Enable && activeProfile.SecondItem.Operations.Count > 0)
			{
				flag2 = true;
			}
			if (!(flag && flag2))
			{
				if (!(flag && !flag2))
				{
					if (!flag && flag2)
					{
						buProfileCalc.varTemps.JobItemType = ProfileJobType.Right;
					}
				}
				else
				{
					buProfileCalc.varTemps.JobItemType = ProfileJobType.Left;
				}
			}
			else
			{
				buProfileCalc.varTemps.JobItemType = ProfileJobType.Both;
			}
			int cntProfile = 0;
			clsInit.cProfile.TotalWidthOfProfile(ref Item, ref cntProfile);
			Item.isCollisionOnlineAvailable = false;
			Item.isCollisionOfflineAvailable = false;
		}
		if (Item.Operations.Count <= 0)
		{
			return false;
		}
		buEyeBaseVer5.Apps.ProfileItem Profile = Item;
		if (!JustCam)
		{
			if (Profile.Length > buProfileCalc.varProfileSettings.MachineLength && activeProfile.SecondItem != null)
			{
				buString5.MessageBoxWarning(buProfile.LangProfileMessage[39]);
				return false;
			}
			buProfileCalc.varProfileRunSettings.activeCalcDataIndex = 0;
			if (Clamper)
			{
				Profile.CalculationData.Clear();
				if (!(Profile.Length > buProfileCalc.varProfileSettings.MachineLength))
				{
					if (!clsInit.cProfile.isBottomOperationAvailable(Profile))
					{
						Profile.CalculationData.Clear();
						ProfileItemCalc profileItemCalc = new ProfileItemCalc(Profile, CopyOperations: true);
						profileItemCalc.CalcType = ProfileExcType.Normal;
						Profile.CalculationData.Add(profileItemCalc);
					}
					else
					{
						doGetBottomOperations(Profile, ref Profile.CalculationData);
					}
				}
				else
				{
					bool flag3 = clsInit.cProfile.isAllOperationInsideXLimit(Profile, buProfileCalc.varProfileSettings.MachineLength - 0.0);
					clsInit.cProfile.isBottomOperationAvailable(Profile);
					if (!flag3)
					{
						Profile.CalculationData.Clear();
						ProfileItemCalc profileItemCalc2 = new ProfileItemCalc(Profile, CopyOperations: true);
						profileItemCalc2.CalcType = ProfileExcType.Normal;
						profileItemCalc2.Length = buProfileCalc.varProfileSettings.MachineLength;
						Profile.CalculationData.Add(profileItemCalc2);
					}
					else
					{
						doDevideProfileItemByLength(Profile, buProfileCalc.varProfileSettings.MachineLength - 0.0, ref Profile.CalculationData);
					}
				}
			}
			bool flag4 = buProfileCalc.varProfileSettings.CalculateClamperEveryTime;
			if (!Profile.IsClamperDone)
			{
				flag4 = true;
			}
			if (Profile.CalculationData.Count == 0)
			{
				flag4 = true;
			}
			if (Profile.CalculationData.Count > 0)
			{
				for (int i = 0; i <= Profile.CalculationData.Count - 1; i++)
				{
					if (Profile.CalculationData[i].calcOperations.Count == 0)
					{
						flag4 = true;
					}
					for (int j = 0; j <= Profile.CalculationData[i].calcOperations.Count - 1; j++)
					{
						if (Profile.CalculationData[i].calcOperations[j].Clampers.Count == 0)
						{
							flag4 = true;
						}
					}
				}
			}
			if (flag4 && Clamper)
			{
				Profile.isSupportBlockOffsetAdd = false;
				Profile.isError = false;
				for (int k = 0; k <= Profile.CalculationData.Count - 1; k++)
				{
					ProfileItemCalc ItemCalc = Profile.CalculationData[k];
					ItemCalc.MaxClamperNumber = Profile.MaxClamperNumber;
					doClamperCalculateMode1(ref ItemCalc, Profile, 0, ItemCalc.MaxClamperNumber);
					Profile.IsClamperDone = true;
				}
			}
			if (Profile.CalculationData.Count > 0 && Clamper)
			{
				for (int l = 0; l <= Profile.CalculationData.Count - 1; l++)
				{
					int num = 0;
					Profile.CalculationData[l].ClamperLists.Clear();
					for (int m = 0; m <= Profile.CalculationData[l].calcOperations.Count - 1; m++)
					{
						if (Profile.CalculationData[l].calcOperations[m].ClamperIndex == -1)
						{
							if (m > 0 && !clsInit.cProfile.isClmpersAreSame(Profile.CalculationData[l].calcOperations[m - 1].Clampers, Profile.CalculationData[l].calcOperations[m].Clampers))
							{
								List<buEyeBaseVer5.Apps.ProfileClamper> CopiedClamper = new List<buEyeBaseVer5.Apps.ProfileClamper>();
								buEyeBaseVer5.Apps.ProfileClamper.Copy(Profile.CalculationData[l].calcOperations[m].Clampers, ref CopiedClamper);
								Profile.CalculationData[l].ClamperLists.Add(CopiedClamper);
								num++;
							}
							Profile.CalculationData[l].calcOperations[m].ClamperIndex = num;
							if (Profile.CalculationData[l].ClamperLists.Count == 0)
							{
								List<buEyeBaseVer5.Apps.ProfileClamper> CopiedClamper2 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
								buEyeBaseVer5.Apps.ProfileClamper.Copy(Profile.CalculationData[l].calcOperations[m].Clampers, ref CopiedClamper2);
								Profile.CalculationData[l].ClamperLists.Add(CopiedClamper2);
							}
						}
					}
				}
			}
		}
		if (Cam)
		{
			Profile.isSupportBlockOffsetAdd = false;
			AllOperationToCam(ref Profile);
			doReAnalyseJob(ref Profile);
		}
		if (GCodeToSim)
		{
			doGCodeToSimulation(ref Profile);
			Profile.isGCodeCreated = true;
		}
		ProfileErrorWarningAdd();
		return true;
	}

	public void doClamperCalculateMode1(ref ProfileItemCalc ItemCalc, buEyeBaseVer5.Apps.ProfileItem Item, int ClamperStartIndex, int NumberofClamper)
	{
		double num = ItemCalc.Length;
