							for (int l = 0; l <= calcClampers.Count - 1; l++)
							{
								if (clsInit.cProfile.isClamperInsideOperationRange(sortOP[k], Calc.LeftMinDis - 1.0 - calcClampers[l].Width / 2.0, Calc.RightMinDis - 1.0 - calcClampers[l].Width / 2.0, calcClampers[l].XPosition, calcClampers[l].Width))
								{
									list.Add(l);
									flag2 = true;
								}
							}
						}
						if (flag2)
						{
							if (sortOP[k].Priority > 0)
							{
								GProfileOperation gProfileOperation2 = sortOP[k];
								doSetClamperForThisOperation(Item, ItemCalc, ref sortOP, ref calcClampers, ref gProfileOperation2, k, num2, num3, firstClamperMinRange, ForbiddenAreas, AllowedAreas, num5);
							}
							else
							{
								remainOP.Add(new GProfileOperation(sortOP[k]));
							}
						}
						else
						{
							buEyeBaseVer5.Apps.ProfileClamper.Copy(calcClampers, ref sortOP[k].Clampers);
							sortOP[k].Calculated = true;
							sortOP[k].Used = true;
						}
						if (sortOP[k].Calculated)
						{
							ItemCalc.calcOperations.Add(new GProfileOperation(sortOP[k]));
						}
					}
					if (remainOP.Count > 0)
					{
						for (int m = 0; m <= remainOP.Count - 1; m++)
						{
							GProfileOperation gProfileOperation3 = remainOP[m];
							doSetClamperForThisOperation(Item, ItemCalc, ref remainOP, ref calcClampers, ref gProfileOperation3, m, num2, num3, firstClamperMinRange, ForbiddenAreas, AllowedAreas, num5);
							if (gProfileOperation3.Calculated)
							{
								ItemCalc.calcOperations.Add(new GProfileOperation(gProfileOperation3));
							}
						}
					}
				}
				if (calcClampers.Count != Clampers.Count && ItemCalc.calcOperations.Count > 0)
				{
					buEyeBaseVer5.Apps.ProfileClamper.Copy(ItemCalc.calcOperations[ItemCalc.calcOperations.Count - 1].Clampers, ref calcClampers);
				}
				if (buProfileCalc.varProfileSettings.NotchOperationAlwaysFirst)
				{
					if (NotchOpList.Count > 0)
					{
						for (int n = 0; n <= NotchOpList.Count - 1; n++)
						{
							buEyeBaseVer5.Apps.ProfileClamper.Copy(ItemCalc.calcOperations[0].Clampers, ref NotchOpList[n].Clampers);
							NotchOpList[n].ClamperIndex = ItemCalc.calcOperations[ItemCalc.calcOperations.Count - 1].ClamperIndex;
							NotchOpList[n].Calculated = true;
							NotchOpList[n].Used = true;
							ItemCalc.calcOperations.Insert(n, new GProfileOperation(NotchOpList[n]));
						}
					}
				}
				else if (NotchOpList.Count > 0)
				{
					for (int num10 = 0; num10 <= NotchOpList.Count - 1; num10++)
					{
						buEyeBaseVer5.Apps.ProfileClamper.Copy(calcClampers, ref NotchOpList[num10].Clampers);
						NotchOpList[num10].ClamperIndex = ItemCalc.calcOperations[ItemCalc.calcOperations.Count - 1].ClamperIndex;
						NotchOpList[num10].Calculated = true;
						NotchOpList[num10].Used = true;
						GProfileOperation gProfileOperation4 = NotchOpList[num10];
						doSetClamperForThisOperation(Item, ItemCalc, ref remainOP, ref calcClampers, ref gProfileOperation4, num10, num2, num3, firstClamperMinRange, ForbiddenAreas, AllowedAreas, num5);
						if (gProfileOperation4.Calculated)
						{
							ItemCalc.calcOperations.Add(new GProfileOperation(gProfileOperation4));
						}
					}
				}
			}
			if (ItemCalc.XReferanceLocation == LeftRightType.Right)
			{
				if (!buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
				{
					doClamperMakeItRightAsSame(ref ItemCalc);
				}
				else
				{
					doClamperMakeItRightAsMirror(ref ItemCalc);
				}
			}
		}
		else
		{
			MessageBox.Show(buLangTranslate.preSentencesProfile.NoClamperAvailable);
		}
	}

