	public void doClamperMakeItRightAsSame(ref ProfileItemCalc ItemCalc)
	{
		double num = ItemCalc.Length;
		double num2 = buProfileCalc.varProfileSettings.MachineLength - ItemCalc.Length;
		if ((ItemCalc.CalcType == ProfileExcType.LongSecondPart) | (ItemCalc.CalcType == ProfileExcType.LongSecondBottom))
		{
			num = buProfileCalc.varProfileSettings.MachineLength;
			num2 = 0.0;
		}
		for (int i = 0; i <= ItemCalc.calcOperations.Count - 1; i++)
		{
			List<buEyeBaseVer5.Apps.ProfileClamper> list = new List<buEyeBaseVer5.Apps.ProfileClamper>();
			List<buEyeBaseVer5.Apps.ProfileClamper> list2 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
			for (int j = 0; j <= ItemCalc.calcOperations[i].Clampers.Count - 1; j++)
			{
				if (!(ItemCalc.calcOperations[i].Clampers[j].XPosition > num + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0))
				{
					buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper(ItemCalc.calcOperations[i].Clampers[j]);
					profileClamper.XPosition += num2;
					profileClamper.GeometrixMaxX += num2;
					profileClamper.GeometrixMinX += num2;
					list.Add(profileClamper);
					continue;
				}
				buEyeBaseVer5.Apps.ProfileClamper profileClamper2 = new buEyeBaseVer5.Apps.ProfileClamper(ItemCalc.calcOperations[i].Clampers[j]);
				double num3 = buProfileCalc.varProfileSettings.MachineLength - profileClamper2.XPosition;
				if (num3 < Clampers[0].MinPositionRange)
				{
					num3 = Clampers[0].MinPositionRange;
				}
				profileClamper2.XPosition = num3;
				profileClamper2.GeometrixMaxX = profileClamper2.XPosition + profileClamper2.Width / 2.0;
				profileClamper2.GeometrixMinX = profileClamper2.XPosition - profileClamper2.Width / 2.0;
				list2.Add(profileClamper2);
			}
			if (list2.Count > 0)
			{
				list2.Reverse();
			}
			ItemCalc.calcOperations[i].Clampers = new List<buEyeBaseVer5.Apps.ProfileClamper>();
			for (int k = 0; k <= list2.Count - 1; k++)
			{
				ItemCalc.calcOperations[i].Clampers.Add(list2[k]);
			}
			for (int l = 0; l <= list.Count - 1; l++)
			{
				ItemCalc.calcOperations[i].Clampers.Add(list[l]);
			}
		}
	}

	public void doClamperSetManuelClamper(ProfileItemCalc ItemCalc, double StartOffset, double EndOffset, ref List<buEyeBaseVer5.Apps.ProfileClamper> clamperList, double MinDisClampers)
	{
		double num = EndOffset;
		double num2 = StartOffset;
		double num3 = ItemCalc.Length;
		if ((ItemCalc.CalcType == ProfileExcType.LongSecondPart) | (ItemCalc.CalcType == ProfileExcType.LongSecondBottom))
		{
			num3 = buProfileCalc.varProfileSettings.MachineLength;
		}
		if (num3 >= 300.0 && num3 <= 500.0)
		{
			if (EndOffset > 50.0)
			{
				num = 50.0;
			}
			if (StartOffset > 50.0)
			{
				num2 = 50.0;
			}
		}
		if (num3 < 300.0)
		{
			num = 0.0;
			num2 = 0.0;
		}
		clamperList.Clear();
		clamperList = new List<buEyeBaseVer5.Apps.ProfileClamper>();
		double num4 = 0.0;
		double num5 = 0.0;
		num5 = (num3 - Clampers[0].MinPositionRange - num2 - num) / (double)(ItemCalc.MaxClamperNumber - 1);
		num5 -= 5.0;
		if (num5 < MinDisClampers)
		{
			num5 = MinDisClampers;
		}
		for (int i = 0; i < ItemCalc.MaxClamperNumber; i++)
		{
			if (i != 0)
			{
				num4 += num5;
			}
			else
			{
				num4 += Clampers[0].MinPositionRange;
				if (num4 < num2)
				{
					num4 = num2;
				}
			}
			if (!(num4 < num3 - EndOffset))
			{
				double num6 = buProfileCalc.varProfileSettings.MachineLength - (buProfileCalc.varProfileClamperSettings.ClamperWidth + MinDisClampers) * (double)(ItemCalc.MaxClamperNumber - i + 1);
				double num7 = buProfileCalc.varProfileClamperSettings.ClamperWidth + MinDisClampers;
				double xPosition = num6 + num7;
				buEyeBaseVer5.Apps.ProfileClamper profileClamper = new buEyeBaseVer5.Apps.ProfileClamper();
				profileClamper.XPosition = xPosition;
				profileClamper.Used = true;
				profileClamper.Enable = true;
				profileClamper.GeometrixMaxX = profileClamper.XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
				profileClamper.GeometrixMinX = profileClamper.XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
				clamperList.Add(profileClamper);
			}
			else
			{
				buEyeBaseVer5.Apps.ProfileClamper profileClamper2 = new buEyeBaseVer5.Apps.ProfileClamper();
				profileClamper2.XPosition = num4;
				profileClamper2.Used = true;
				profileClamper2.Enable = true;
				profileClamper2.GeometrixMaxX = profileClamper2.XPosition + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
				profileClamper2.GeometrixMinX = profileClamper2.XPosition - buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
				clamperList.Add(profileClamper2);
			}
		}
	}

	public void doClamperSortOP(ref buEyeBaseVer5.Apps.ProfileItem ItemCalc, ref List<GProfileOperation> sortOP, ProfileSortMethods SortType, bool UsePriority)
	{
		List<GProfileOperation> RefList = new List<GProfileOperation>();
		List<GProfileOperation> RefList2 = new List<GProfileOperation>();
		for (int i = 0; i <= ItemCalc.Operations.Count - 1; i++)
		{
			if (!(ItemCalc.Operations[i].Enable & (ItemCalc.Operations[i].OperationData.OperationType != ProfileOperationTypes.Notch)))
			{
				continue;
			}
			if (SortType == ProfileSortMethods.NoSort)
			{
				GProfileOperation gProfileOperation = new GProfileOperation(ItemCalc.Operations[i]);
				gProfileOperation.Calculated = false;
				RefList2.Add(gProfileOperation);
				continue;
			}
			if (ItemCalc.Operations[i].Priority <= 0)
			{
				GProfileOperation gProfileOperation2 = new GProfileOperation(ItemCalc.Operations[i]);
				gProfileOperation2.Calculated = false;
				RefList2.Add(gProfileOperation2);
			}
			if (ItemCalc.Operations[i].Priority > 0)
			{
				if (!UsePriority)
				{
					GProfileOperation gProfileOperation3 = new GProfileOperation(ItemCalc.Operations[i]);
					gProfileOperation3.Calculated = false;
					RefList2.Add(gProfileOperation3);
				}
				else
				{
					GProfileOperation gProfileOperation4 = new GProfileOperation(ItemCalc.Operations[i]);
					gProfileOperation4.Calculated = false;
					RefList.Add(gProfileOperation4);
				}
			}
		}
		if (RefList.Count > 0)
		{
			if (SortType == ProfileSortMethods.OnlyXDirection)
			{
				clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
			}
			clsInit.cProfile.SortListByPriority(SortDirectionType.Lower, ref RefList);
			for (int j = 0; j <= RefList.Count - 1; j++)
			{
				sortOP.Add(new GProfileOperation(RefList[j]));
			}
		}
		switch (SortType)
		{
		default:
		{
			for (int m = 0; m <= RefList2.Count - 1; m++)
			{
				sortOP.Add(new GProfileOperation(RefList2[m]));
			}
			break;
		}
		case ProfileSortMethods.OnlyXDirection:
		{
			clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList2, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
			for (int n = 0; n <= RefList2.Count - 1; n++)
			{
				sortOP.Add(new GProfileOperation(RefList2[n]));
			}
			break;
		}
		case ProfileSortMethods.OnlyToolUsage:
		{
			List<List<GProfileOperation>> splitedOP = new List<List<GProfileOperation>>();
			clsInit.cProfile.SplitOperationByToolNo(RefList2, ref splitedOP);
			for (int k = 0; k <= splitedOP.Count - 1; k++)
			{
				for (int l = 0; l <= splitedOP[k].Count - 1; l++)
				{
					sortOP.Add(new GProfileOperation(splitedOP[k][l]));
				}
			}
			break;
		}
		}
	}

	public void doClamperSortOP(ref ProfileItemCalc ItemCalc, ref List<GProfileOperation> sortOP, ProfileSortMethods SortType, bool UsePriority)
	{
		List<GProfileOperation> RefList = new List<GProfileOperation>();
		List<GProfileOperation> RefList2 = new List<GProfileOperation>();
		for (int i = 0; i <= ItemCalc.calcOperations.Count - 1; i++)
		{
			if (!(ItemCalc.calcOperations[i].Enable & (ItemCalc.calcOperations[i].OperationData.OperationType != ProfileOperationTypes.Notch)))
			{
				continue;
			}
			if (SortType == ProfileSortMethods.NoSort)
			{
				GProfileOperation gProfileOperation = new GProfileOperation(ItemCalc.calcOperations[i]);
				gProfileOperation.Calculated = false;
				RefList2.Add(gProfileOperation);
				continue;
			}
			if (ItemCalc.calcOperations[i].Priority <= 0)
			{
				GProfileOperation gProfileOperation2 = new GProfileOperation(ItemCalc.calcOperations[i]);
				gProfileOperation2.Calculated = false;
				RefList2.Add(gProfileOperation2);
			}
			if (ItemCalc.calcOperations[i].Priority > 0)
			{
				if (!UsePriority)
				{
					GProfileOperation gProfileOperation3 = new GProfileOperation(ItemCalc.calcOperations[i]);
					gProfileOperation3.Calculated = false;
					RefList2.Add(gProfileOperation3);
				}
				else
				{
					GProfileOperation gProfileOperation4 = new GProfileOperation(ItemCalc.calcOperations[i]);
					gProfileOperation4.Calculated = false;
					RefList.Add(gProfileOperation4);
				}
			}
		}
		if (RefList.Count > 0)
		{
			if (SortType == ProfileSortMethods.OnlyXDirection)
			{
				clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
			}
			clsInit.cProfile.SortListByPriority(SortDirectionType.Lower, ref RefList);
			for (int j = 0; j <= RefList.Count - 1; j++)
			{
				sortOP.Add(new GProfileOperation(RefList[j]));
			}
		}
		switch (SortType)
		{
		default:
		{
			for (int n = 0; n <= RefList2.Count - 1; n++)
			{
				sortOP.Add(new GProfileOperation(RefList2[n]));
			}
			break;
		}
		case ProfileSortMethods.OnlyXDirection:
		{
			clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList2, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
			for (int num3 = 0; num3 <= RefList2.Count - 1; num3++)
			{
				sortOP.Add(new GProfileOperation(RefList2[num3]));
				clsInit.cProfile.CheckDepthAndChangeSequenceIfIntersect(ref sortOP);
			}
			break;
		}
		case ProfileSortMethods.OnlyToolUsage:
		{
			List<List<GProfileOperation>> splitedOP4 = new List<List<GProfileOperation>>();
			clsInit.cProfile.SplitOperationByToolNo(RefList2, ref splitedOP4);
			for (int num4 = 0; num4 <= splitedOP4.Count - 1; num4++)
			{
				List<GProfileOperation> RefList5 = splitedOP4[num4];
				clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList5, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
				for (int num5 = 0; num5 <= RefList5.Count - 1; num5++)
				{
					sortOP.Add(RefList5[num5]);
					clsInit.cProfile.CheckDepthAndChangeSequenceIfIntersect(ref sortOP);
				}
			}
			break;
		}
		case ProfileSortMethods.OnlyPlane:
		{
			List<List<GProfileOperation>> splitedOP3 = new List<List<GProfileOperation>>();
			clsInit.cProfile.SplitOperationByPlane(RefList2, ref splitedOP3);
			for (int num = 0; num <= splitedOP3.Count - 1; num++)
			{
				List<GProfileOperation> RefList4 = splitedOP3[num];
				clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList4, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
				for (int num2 = 0; num2 <= RefList4.Count - 1; num2++)
				{
					sortOP.Add(RefList4[num2]);
					clsInit.cProfile.CheckDepthAndChangeSequenceIfIntersect(ref sortOP);
				}
			}
			break;
		}
		case ProfileSortMethods.ToolUsageThenPlane:
		{
			clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList2, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
			List<List<GProfileOperation>> splitedOP = new List<List<GProfileOperation>>();
			clsInit.cProfile.SplitOperationByToolNo(RefList2, ref splitedOP);
			for (int k = 0; k <= splitedOP.Count - 1; k++)
			{
				List<List<GProfileOperation>> splitedOP2 = new List<List<GProfileOperation>>();
				clsInit.cProfile.SplitOperationByPlane(splitedOP[k], ref splitedOP2);
				for (int l = 0; l <= splitedOP2.Count - 1; l++)
				{
					List<GProfileOperation> RefList3 = splitedOP2[l];
					clsInit.cProfile.SortList(SortDirectionType.Lower, ref RefList3, buProfileCalc.varProfileClamperSettings.SortSequenceAtSamePosition);
					for (int m = 0; m <= RefList3.Count - 1; m++)
					{
						sortOP.Add(RefList3[m]);
					}
					clsInit.cProfile.CheckDepthAndChangeSequenceIfIntersect(ref sortOP);
				}
			}
			break;
		}
		}
	}

	public void doClamperNotchOP(ref ProfileItemCalc ItemCalc, ref List<GProfileOperation> NotchOpList, ref double NotchStartOffset, ref double NotchEndOffset, ref double ProfileStartOffset, ref double ProfileEndOffset)
	{
		NotchOpList = new List<GProfileOperation>();
		for (int num = ItemCalc.calcOperations.Count - 1; num >= 0; num--)
		{
			if (ItemCalc.calcOperations[num].Action == actionTypeBU.profileNotch)
			{
				GProfileOperation gProfileOperation = new GProfileOperation(ItemCalc.calcOperations[num]);
				NotchOpList.Add(gProfileOperation);
				if ((gProfileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side) | (gProfileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical))
				{
					if (ItemCalc.XReferanceLocation != LeftRightType.Left)
					{
						if (gProfileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Right)
						{
							NotchStartOffset = gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
							if (gProfileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
							{
								NotchStartOffset = gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
							}
						}
						if (gProfileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Left)
						{
							NotchEndOffset = gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
							if (gProfileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
							{
								NotchEndOffset = gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
							}
							if (NotchEndOffset < buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + (gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X))
							{
								NotchEndOffset = buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + (gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X) + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
							}
						}
					}
					else
					{
						if (gProfileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Left)
						{
							NotchStartOffset = gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
							if (gProfileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
							{
								NotchStartOffset = gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
							}
						}
						if (gProfileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Right)
						{
							NotchEndOffset = gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
							if (gProfileOperation.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
							{
								NotchEndOffset = gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X + buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
							}
							if (NotchEndOffset < buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + (gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X))
							{
								NotchEndOffset = buProfileCalc.varProfileClamperSettings.OperationTopRightMinDistance + (gProfileOperation.SizePoint.MaxPoint.X - gProfileOperation.SizePoint.MinPoint.X) + buProfileCalc.varProfileClamperSettings.NotchSafeXDistance;
							}
						}
					}
				}
			}
		}
		if (NotchOpList.Count > 0)
		{
			clsInit.cProfile.SortList(SortDirectionType.Lower, ref NotchOpList);
		}
		if ((NotchStartOffset > 0.0) & (NotchStartOffset > ProfileStartOffset))
		{
			ProfileStartOffset = NotchStartOffset;
		}
		if ((NotchEndOffset > 0.0) & (NotchEndOffset > ProfileEndOffset))
		{
			ProfileEndOffset = NotchEndOffset;
		}
	}

	public void doClamperForbiddenAllowedAreas(buEyeBaseVer5.Apps.ProfileItem Item, ProfileItemCalc ItemCalc, List<GProfileOperation> sortOP, double ProfileStartOffset, double ProfileEndOffset, ref List<MinMax> ForbiddenAreas, ref List<MinMax> AllowedAreas)
	{
		ForbiddenAreas.Clear();
		AllowedAreas.Clear();
		double num = 0.0;
		for (int i = 0; i <= sortOP.Count - 1; i++)
		{
			double num2 = 0.0;
			double num3 = 0.0;
			if (sortOP[i].Used)
			{
				continue;
			}
			if (sortOP[i].OperationData.selectedPlaneName == planeNames.Free)
			{
