			if ((sortOP[i].OperationData.selectedPlaneName == planeNames.Top) | (sortOP[i].OperationData.selectedPlaneName == planeNames.Bottom) | ((sortOP[i].OperationData.selectedPlaneName == planeNames.Free) & (num3 <= buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit)))
			{
				num4 = buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
				num5 = buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance + buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0;
