			double num6 = ItemCalc.Length - ForbiddenAreas[0].Max;
			if ((num6 > 0.0) & (num6 > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0))
