		if (ForbiddenAreas.Count > 1)
		{
			List<MinMax> list = new List<MinMax>();
			list.Add(new MinMax(ForbiddenAreas[0]));
			for (int j = 1; j <= ForbiddenAreas.Count - 1; j++)
