					continue;
				}
				for (int num7 = list.Count - 1; num7 >= 0; num7--)
				{
					if (buNumeric5.IsValueInsideMinMaxValues(list[num7].Min, ForbiddenAreas[j].Min, ForbiddenAreas[j].Max) & buNumeric5.IsValueInsideMinMaxValues(list[num7].Max, ForbiddenAreas[j].Min, ForbiddenAreas[j].Max))
					{
						list.RemoveAt(num7);
					}
				}
				list.Add(new MinMax(ForbiddenAreas[j]));
			}
			ForbiddenAreas.Clear();
			for (int l = 0; l <= list.Count - 1; l++)
			{
				ForbiddenAreas.Add(new MinMax(list[l]));
			}
			for (int m = 0; m <= ForbiddenAreas.Count - 1; m++)
			{
				if (ForbiddenAreas[m].Max > num)
				{
					num = ForbiddenAreas[m].Max;
				}
			}
			for (int n = 0; n <= ForbiddenAreas.Count - 1; n++)
			{
				if (n != 0)
				{
					if (n != ForbiddenAreas.Count - 1)
					{
						if (!(ForbiddenAreas[n].Min > ForbiddenAreas[n - 1].Max))
						{
							continue;
						}
						double num8 = ForbiddenAreas[n].Min - ForbiddenAreas[n - 1].Max;
						if ((num8 > 0.0) & (num8 > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0))
						{
							MinMax minMax7 = new MinMax();
