							minMax7.Max = ForbiddenAreas[n].Min;
							if (minMax7.Max > buProfileCalc.varProfileSettings.MachineLength)
							{
								minMax7.Max = buProfileCalc.varProfileSettings.MachineLength;
							}
							if ((minMax7.Min < minMax7.Max) & (minMax7.Max - minMax7.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance))
							{
								AllowedAreas.Add(minMax7);
							}
						}
						continue;
					}
					double num9 = ForbiddenAreas[n].Min - ForbiddenAreas[n - 1].Max;
					if ((num9 > 0.0) & (num9 > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0))
					{
						MinMax minMax8 = new MinMax();
						minMax8.Min = ForbiddenAreas[n - 1].Max;
						minMax8.Max = ForbiddenAreas[n].Min;
						if (minMax8.Max > buProfileCalc.varProfileSettings.MachineLength)
						{
							minMax8.Max = buProfileCalc.varProfileSettings.MachineLength;
						}
						if ((minMax8.Min < minMax8.Max) & (minMax8.Max - minMax8.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance))
						{
							AllowedAreas.Add(minMax8);
						}
					}
					num9 = ItemCalc.Length - num;
					if ((num9 > 0.0) & (num9 > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0))
					{
						MinMax minMax9 = new MinMax();
						minMax9.Min = num;
						minMax9.Max = ItemCalc.Length;
						if (minMax9.Max > buProfileCalc.varProfileSettings.MachineLength)
						{
							minMax9.Max = buProfileCalc.varProfileSettings.MachineLength;
						}
						if ((minMax9.Min < minMax9.Max) & (minMax9.Max - minMax9.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance))
						{
							AllowedAreas.Add(minMax9);
						}
					}
				}
				else if (!((ForbiddenAreas[n].Min > 0.0) & (ForbiddenAreas[n].Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance * 2.0)))
				{
					if ((ForbiddenAreas[n].Min > 0.0) & (Clampers[0].MinPositionRange <= ForbiddenAreas[n].Min))
					{
						MinMax minMax10 = new MinMax();
						minMax10.Min = 0.0;
						minMax10.Max = ForbiddenAreas[n].Min;
						if (minMax10.Max > buProfileCalc.varProfileSettings.MachineLength)
						{
							minMax10.Max = buProfileCalc.varProfileSettings.MachineLength;
						}
						if ((minMax10.Min < minMax10.Max) & (minMax10.Max - minMax10.Min > buProfileCalc.varProfileClamperSettings.ClamperWidth + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance))
						{
							AllowedAreas.Add(minMax10);
						}
					}
				}
				else
				{
					MinMax minMax11 = new MinMax();
					minMax11.Min = 0.0;
					minMax11.Max = ForbiddenAreas[n].Min;
