	}

	public void doClamperOpLeftRightLimits(buEyeBaseVer5.Apps.ProfileItem Item, ProfileItemCalc ItemCalc, GProfileOperation sortOP, ref ClamperLeftRightPars Calc, double ClamperWidth)
	{
		if (Calc == null)
		{
			Calc = new ClamperLeftRightPars();
		}
		Calc.OperationAboveClamper = false;
		double num = 0.0;
		double num2 = 0.0;
		if (sortOP.OperationData.selectedPlaneName == planeNames.Free)
		{
			num = clsInit.cVector5.PointAngle(new Point3D(sortOP.OperationData.selectedPlane.AxisZ.X, sortOP.OperationData.selectedPlane.AxisZ.Y, sortOP.OperationData.selectedPlane.AxisZ.Z), new Point3D(), Plane.YZ);
			num2 = ((num > 90.0) ? (num - 90.0) : (90.0 - num));
		}
		if (clsInit.cProfile.isOperationSafeForClamps(Item, ItemCalc, sortOP, buProfileCalc.varProfileSettings, buProfileCalc.varProfileClamperSettings))
		{
			Calc.LeftMinDis = 0.0;
			Calc.RightMinDis = 0.0;
		}
		else
		{
			if ((sortOP.OperationData.selectedPlaneName == planeNames.Top) | (sortOP.OperationData.selectedPlaneName == planeNames.Bottom) | ((sortOP.OperationData.selectedPlaneName == planeNames.Free) & (num2 <= buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit)))
			{
				Calc.LeftMinDis = buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance + ClamperWidth / 2.0;
				Calc.RightMinDis = buProfileCalc.varProfileClamperSettings.OperationTopLeftMinDistance + ClamperWidth / 2.0;
			}
			if ((sortOP.OperationData.selectedPlaneName == planeNames.Back) | (((sortOP.OperationData.selectedPlaneName == planeNames.Free) & (num2 > buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit)) && num < 90.0))
			{
				Calc.LeftMinDis = buProfileCalc.varProfileClamperSettings.OperationBackLeftMinDistance + ClamperWidth / 2.0;
				Calc.RightMinDis = buProfileCalc.varProfileClamperSettings.OperationBackRightMinDistance + ClamperWidth / 2.0;
			}
			if ((sortOP.OperationData.selectedPlaneName == planeNames.Front) | (((sortOP.OperationData.selectedPlaneName == planeNames.Free) & (num2 > buProfileCalc.varProfileClamperSettings.FreePlaneToBackFrontAngleLimit)) && num > 90.0))
			{
				Calc.LeftMinDis = buProfileCalc.varProfileClamperSettings.OperationFrontLeftMinDistance + ClamperWidth / 2.0;
				Calc.RightMinDis = buProfileCalc.varProfileClamperSettings.OperationFrontRightMinDistance + ClamperWidth / 2.0;
			}
		}
		if (ItemCalc.XReferanceLocation == LeftRightType.Right && buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
		{
			buNumeric5.ExchangeTwoVaues(ref Calc.LeftMinDis, ref Calc.RightMinDis);
		}
		Calc.LeftMinClamperPos = sortOP.SizePoint.MinPoint.X - Calc.LeftMinDis;
		Calc.RightMinClamperPos = sortOP.SizePoint.MaxPoint.X + Calc.RightMinDis;
		if (!(Calc.RightMinClamperPos > ItemCalc.Length))
		{
		}
		double num3 = buProfileCalc.varProfileClamperSettings.ClamperOptimisationLevel;
		if (num3 < 1.0)
		{
			num3 = 1.0;
		}
		if (num3 > 10.0)
		{
			num3 = 10.0;
		}
		if (!(buProfileCalc.varProfileClamperSettings.OperationClamperLeftMaxDistance > Calc.LeftMinDis))
		{
			Calc.LeftMaxDis = Calc.LeftMinDis;
		}
		else
		{
			Calc.LeftMaxDis = Calc.LeftMinDis + (buProfileCalc.varProfileClamperSettings.OperationClamperLeftMaxDistance - Calc.LeftMinDis) * num3 / 10.0;
		}
		if (!(buProfileCalc.varProfileClamperSettings.OperationClamperRightMaxDistance > Calc.RightMinDis))
		{
			Calc.RightMaxDis = Calc.RightMinDis;
		}
		else
		{
			Calc.RightMaxDis = Calc.RightMinDis + (buProfileCalc.varProfileClamperSettings.OperationClamperRightMaxDistance - Calc.RightMinDis) * num3 / 10.0;
		}
		if (Calc.OperationAboveClamper)
		{
			Calc.LeftMaxDis = 0.0;
			Calc.RightMaxDis = 0.0;
		}
		Calc.LeftMaxClamperPos = sortOP.SizePoint.MinPoint.X - Calc.LeftMaxDis;
		Calc.RightMaxClamperPos = sortOP.SizePoint.MaxPoint.X + Calc.RightMaxDis;
		if (sortOP.OperationData.OperationType == ProfileOperationTypes.Notch)
		{
			Calc.LeftMaxClamperPos = Calc.LeftMinClamperPos;
			Calc.RightMaxClamperPos = Calc.RightMinClamperPos;
			if (sortOP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Length)
			{
				Calc.LeftMaxDis = buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0 + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
				Calc.RightMaxDis = buProfileCalc.varProfileClamperSettings.ClamperWidth / 2.0 + buProfileCalc.varProfileClamperSettings.ClamperSafeDistance;
				Calc.LeftMaxClamperPos = sortOP.SizePoint.MinPoint.X - Calc.LeftMaxDis;
				Calc.RightMaxClamperPos = sortOP.SizePoint.MaxPoint.X + Calc.RightMaxDis;
			}
		}
		if (!(Calc.RightMaxClamperPos > ItemCalc.Length))
		{
		}
	}

	public void doClamperCheckMaxDistanceFromLastClamper(double XPosition, ref List<buEyeBaseVer5.Apps.ProfileClamper> ClamperList, double MaxClamperDistance, double MinClamperDistance, int MaxClamperCount, double ActualOPMinX, double ActualOPMaxX, ref double LastClamperX, double MinDisClampers)
	{
		string text = "doClamperCheckMaxDistanceFromLastClamper";
		try
		{
			if (ClamperList.Count <= 0)
			{
				return;
			}
			double num = XPosition - ClamperList[ClamperList.Count - 1].XPosition;
			if (!(num > MaxClamperDistance))
			{
				return;
			}
			int num2 = Convert.ToInt32(buNumeric5.RoundToLower(num / MaxClamperDistance));
			for (int i = 1; i <= num2; i++)
			{
				double num3 = Math.Round((double)i * MaxClamperDistance, 5);
				if (num3 > XPosition || XPosition - num3 < MinClamperDistance)
				{
					num3 = XPosition - MinClamperDistance;
				}
				bool flag = buNumeric5.IsValueInsideMinMaxValues(num3, ActualOPMinX, ActualOPMaxX);
				if (!(num3 > 0.0))
				{
					continue;
				}
				if (flag)
				{
					if (!(ActualOPMinX > ClamperList[ClamperList.Count - 1].GeometrixMaxX + MinDisClampers))
					{
						buEyeBaseVer5.Apps.ProfileClamper Clamper = null;
						CheckClamper(ref Clamper, ActualOPMaxX, ClamperList, MaxClamperCount, -1);
						ClamperList.Add(Clamper);
						LastClamperX = Clamper.XPosition;
					}
					else
					{
						buEyeBaseVer5.Apps.ProfileClamper Clamper2 = null;
						CheckClamper(ref Clamper2, ActualOPMinX, ClamperList, MaxClamperCount, -1);
						ClamperList.Add(Clamper2);
						LastClamperX = Clamper2.XPosition;
					}
				}
				else
				{
					buEyeBaseVer5.Apps.ProfileClamper Clamper3 = null;
					CheckClamper(ref Clamper3, num3, ClamperList, MaxClamperCount, -1);
					ClamperList.Add(Clamper3);
					LastClamperX = Clamper3.XPosition;
				}
			}
		}
		catch (Exception mSException)
		{
			buLogVer5.addToLog(string_1, text, "Error", "", 0.0, 0.0, AddException: true);
			buException.throwException(mSException, text, ShowMessageBox: true, "");
		}
	}

	public void doCreateParabolicMoves(ref buEyeBaseVer5.Apps.ProfileItem Item)
	{
		try
		{
			if (buProfileCalc.varProfileSettings.ProfileSafeDistanceForPlanes == ProfileSafeDistanceMode.G53Mode)
			{
				return;
			}
			bool flag = false;
			new TpPnt9D();
			new TpPnt9D();
			for (int i = 0; i <= Item.CalculationData.Count - 1; i++)
			{
				for (int j = 0; j <= Item.CalculationData[i].Cams.Count - 1; j++)
				{
					flag = false;
					camTp camTp2 = Item.CalculationData[i].Cams[j];
					camTp camTp3 = null;
					if (j > 0)
					{
						camTp3 = Item.CalculationData[i].Cams[j - 1];
					}
					if (j < Item.CalculationData[i].Cams.Count - 1)
					{
						_ = Item.CalculationData[i].Cams[j + 1];
					}
					if (camTp3 != null && camTp2.PlaneName != camTp3.PlaneName)
					{
						flag = true;
					}
					if (!flag)
					{
						continue;
					}
					List<Pnt9D> list = new List<Pnt9D>();
					List<Pnt9D> calculatedPoints = new List<Pnt9D>();
					TpPnt9D tpPnt9D = camTp3.CamPoints[camTp3.CamPoints.Count - 1].Points[camTp3.CamPoints[camTp3.CamPoints.Count - 1].Points.Count - 1];
					TpPnt9D tpPnt9D2 = camTp2.CamPoints[0].Points[0];
					bool flag2 = true;
					double num = 0.0;
					double value = 0.0;
					if (buProfileCalc.varProfileSettings.ParabolicAllowedAxes == ProfileParaolicAxesType.Axes3)
					{
						int num2 = 0;
						double num3 = tpPnt9D.P9.X - tpPnt9D2.P9.X;
						if (!buCompare5.EQ(num3, 0.0))
						{
							num2++;
							num = tpPnt9D2.P9.X;
							value = num3;
						}
						if (num2 > 0)
						{
							TpPnt9D tpPnt9D3 = new TpPnt9D(camTp3.CamPoints[camTp3.CamPoints.Count - 1].Points[camTp3.CamPoints[camTp3.CamPoints.Count - 1].Points.Count - 1]);
							tpPnt9D3.P9.X = tpPnt9D2.P9.X;
							camTp3.CamPoints[camTp3.CamPoints.Count - 1].Points.Add(tpPnt9D3);
							tpPnt9D = camTp3.CamPoints[camTp3.CamPoints.Count - 1].Points[camTp3.CamPoints[camTp3.CamPoints.Count - 1].Points.Count - 1];
						}
					}
					if (!flag2)
					{
						continue;
					}
					OrientationAngle orientation = new OrientationAngle(tpPnt9D.P9.A, 0.0, 0.0);
					Point3D movePoint = new Point3D(tpPnt9D.P9.X, tpPnt9D.P9.Y, tpPnt9D.P9.Z);
					Pnt6D CalcPoint = new Pnt6D();
					clsInit.cKinematic5.ReverseKinematix4Ax(camTp2.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, orientation, movePoint, ref CalcPoint);
					list.Add(new Pnt9D(CalcPoint));
					orientation = new OrientationAngle(tpPnt9D.P9.A, 0.0, 0.0);
					movePoint = new Point3D(tpPnt9D.P9.X, tpPnt9D.P9.Y, tpPnt9D.P9.Z + buProfileCalc.varProfileSettings.ParabolicSafeDistance);
					CalcPoint = new Pnt6D();
					clsInit.cKinematic5.ReverseKinematix4Ax(camTp2.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, orientation, movePoint, ref CalcPoint);
					list.Add(new Pnt9D(CalcPoint));
					orientation = new OrientationAngle(tpPnt9D2.P9.A, 0.0, 0.0);
					movePoint = new Point3D(tpPnt9D2.P9.X, tpPnt9D2.P9.Y, tpPnt9D2.P9.Z + buProfileCalc.varProfileSettings.ParabolicSafeDistance);
					CalcPoint = new Pnt6D();
					clsInit.cKinematic5.ReverseKinematix4Ax(camTp2.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, orientation, movePoint, ref CalcPoint);
					list.Add(new Pnt9D(CalcPoint));
					orientation = new OrientationAngle(tpPnt9D2.P9.A, 0.0, 0.0);
					movePoint = new Point3D(tpPnt9D2.P9.X, tpPnt9D2.P9.Y, tpPnt9D2.P9.Z);
					CalcPoint = new Pnt6D();
					clsInit.cKinematic5.ReverseKinematix4Ax(camTp2.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, orientation, movePoint, ref CalcPoint);
					list.Add(new Pnt9D(CalcPoint));
					clsInit.cVector5.BezeirCurve(list, 0.1, ref calculatedPoints);
					camTpPoint camTpPoint2 = camTp3.CamPoints[camTp3.CamPoints.Count - 1];
					_ = camTp2.CamPoints[0];
					for (int k = 0; k <= calculatedPoints.Count - 1; k++)
					{
						orientation = new OrientationAngle(calculatedPoints[k].A, 0.0, 0.0);
						movePoint = new Point3D(calculatedPoints[k].X, calculatedPoints[k].Y, calculatedPoints[k].Z);
						CalcPoint = new Pnt6D();
						clsInit.cKinematic5.ForwardKinematix4Ax(camTp2.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, orientation, movePoint, ref CalcPoint);
						TpPnt9D tpPnt9D4 = new TpPnt9D(CalcPoint);
						tpPnt9D4.Type = 1;
						tpPnt9D4.Feed = buProfileCalc.varProfileSettings.ParabolicMoveFeed;
						if (ccVars.PostActive.Mode == "KabanMode1" && ((k == 0) & !buCompare5.EQ(value, 0.0)))
						{
							tpPnt9D4.PreCodes.Add("M28 X" + num.ToString("f2") + " F" + buProfileCalc.varProfileSettings.ParabolicMoveFeed);
						}
						camTpPoint2.Points.Add(tpPnt9D4);
					}
				}
			}
		}
		catch (Exception)
		{
		}
	}

	public bool doCheckMoveSafeDistance(GProfileOperation ActualOP, GProfileOperation PreOP)
	{
		bool result = false;
		if (ActualOP.OperationData.selectedPlaneName != planeNames.Front)
		{
			if (ActualOP.OperationData.selectedPlaneName != planeNames.Back)
			{
				if (((ActualOP.OperationData.selectedPlaneName == planeNames.Top) | (ActualOP.OperationData.selectedPlaneName == planeNames.Bottom)) && (((PreOP.OperationData.selectedPlaneName != planeNames.Top) & (PreOP.OperationData.selectedPlaneName != planeNames.Bottom)) | (PreOP.OperationData.OperationType == ProfileOperationTypes.Notch)))
				{
					result = true;
				}
			}
			else if (PreOP.OperationData.selectedPlaneName != planeNames.Back)
			{
				result = true;
			}
		}
		else if (PreOP.OperationData.selectedPlaneName != planeNames.Front)
		{
			result = true;
		}
		if ((ActualOP.OperationData.OperationType == ProfileOperationTypes.Notch) & (PreOP.OperationData.OperationType != ProfileOperationTypes.Notch))
		{
			result = true;
		}
		if ((ActualOP.OperationData.OperationType == ProfileOperationTypes.Notch) & (PreOP.OperationData.OperationType == ProfileOperationTypes.Notch))
		{
			if (ActualOP.OperationData.NotchData.NotchOPType == PreOP.OperationData.NotchData.NotchOPType)
			{
				if ((ActualOP.OperationData.NotchData.NotchLocation != PreOP.OperationData.NotchData.NotchLocation) | (ActualOP.OperationData.NotchData.NotchFrontBack != PreOP.OperationData.NotchData.NotchFrontBack))
				{
					result = true;
				}
			}
			else
			{
				result = true;
			}
		}
		return result;
	}

	public void doCreateCode(buEyeBaseVer5.Apps.ProfileItem Profile, string Mode, ref ArrayList GCodes, int ProfileIndex, bool SecondAvailable, bool CreateGCode = false, bool ShowCode = false)
	{
		if (Profile == null)
		{
			return;
		}
		if (Profile != null && Profile.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
		{
			Profile.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
		}
		if (Mode == "YilmazMode1")
		{
			if (!Profile.IsClamperDone && !doCalculateAll(ref Profile, Clamper: true, Cam: true, GCodeToSim: false))
			{
				return;
			}
			string GCodeStr = "";
			if (!CreateGCode)
			{
				doCreateJobYilmazMode1(ref Profile, ref GCodeStr, ProfileIndex, SecondAvailable, CreateGCode);
			}
			else
			{
				buEyeBaseVer5.Apps.ProfileItem Item = new buEyeBaseVer5.Apps.ProfileItem(Profile);
				doAddSupportBlockOffsets(ref Item);
				doCreateJobYilmazMode1(ref Item, ref GCodeStr, ProfileIndex, SecondAvailable, CreateGCode);
			}
			buString5.SplitStringByNewLine(GCodeStr, ref GCodes);
			GCodes.Insert(0, "<GCodes>");
			GCodes.Add("</GCodes>");
			if (!ShowCode)
			{
				ArrayList AL = new ArrayList();
				SaveProfileJobFile(activeProfile, ref AL);
				GCodes.Add(" ");
				GCodes.Add("<ProfileCode>");
				GCodes.AddRange(AL);
				GCodes.Add("</ProfileCode>");
			}
		}
		if (Profile == null)
		{
			return;
		}
		if (Mode == "KabanMode1")
		{
			if (!Profile.IsClamperDone && !doCalculateAll(ref Profile, Clamper: true, Cam: true, GCodeToSim: false))
			{
				return;
			}
			string GCodeStr2 = "";
			ProfileTempVars.LastClampers.Clear();
			if (!CreateGCode)
			{
				doCreateJobKabanMode1(ref Profile, ref GCodeStr2, ProfileIndex, SecondAvailable, CreateGCode);
			}
			else
			{
				buEyeBaseVer5.Apps.ProfileItem Item2 = new buEyeBaseVer5.Apps.ProfileItem(Profile);
				doAddSupportBlockOffsets(ref Item2);
				doCreateJobKabanMode1(ref Item2, ref GCodeStr2, ProfileIndex, SecondAvailable, CreateGCode);
			}
			buString5.SplitStringByNewLine(GCodeStr2, ref GCodes);
			if (buProfileCalc.varProfileSettings.ParabolicMoveBetweenPlanes)
			{
				for (int num = GCodes.Count - 1; num >= 0; num--)
				{
					if (num > 0 && GCodes[num].ToString().IndexOf("M28") >= 0 && GCodes[num - 1].ToString().IndexOf("M28") >= 0)
					{
						if (GCodes[num - 1].ToString().IndexOf("X") < 0)
						{
							GCodes.RemoveAt(num - 1);
						}
						else
						{
							GCodes.RemoveAt(num);
						}
					}
				}
			}
			ArrayList AL2 = new ArrayList();
			SaveProfileJobFile(activeProfile, ref AL2);
		}
		if (Mode == "KabanMode2")
		{
			if (!Profile.IsClamperDone && !doCalculateAll(ref Profile, Clamper: true, Cam: true, GCodeToSim: false))
			{
				return;
			}
			string GCodeStr3 = "";
			if (!CreateGCode)
			{
				doCreateJobKabanMode2(ref Profile, ref GCodeStr3, ProfileIndex, SecondAvailable, CreateGCode);
			}
			else
			{
				buEyeBaseVer5.Apps.ProfileItem Item3 = new buEyeBaseVer5.Apps.ProfileItem(Profile);
				doAddSupportBlockOffsets(ref Item3);
				doCreateJobKabanMode2(ref Item3, ref GCodeStr3, ProfileIndex, SecondAvailable, CreateGCode);
			}
			buString5.SplitStringByNewLine(GCodeStr3, ref GCodes);
			ArrayList AL3 = new ArrayList();
			SaveProfileJobFile(activeProfile, ref AL3);
		}
		if (Profile == null)
		{
			return;
		}
		if (Profile != null && Profile.MaxClamperNumber != buProfileCalc.varProfileSettings.ProfileMaxClamper)
		{
			Profile.MaxClamperNumber = buProfileCalc.varProfileSettings.ProfileMaxClamper;
		}
		if (Mode == "InfiniteMode1" && (Profile.IsClamperDone || doCalculateAll(ref Profile, Clamper: true, Cam: true, GCodeToSim: false)))
		{
			string GCodeStr4 = "";
			if (!CreateGCode)
			{
				doCreateJobInfiniteMode1(ref Profile, ref GCodeStr4, ProfileIndex, SecondAvailable, CreateGCode);
			}
			else
			{
				buEyeBaseVer5.Apps.ProfileItem Item4 = new buEyeBaseVer5.Apps.ProfileItem(Profile);
				doAddSupportBlockOffsets(ref Item4);
				doCreateJobInfiniteMode1(ref Item4, ref GCodeStr4, ProfileIndex, SecondAvailable, CreateGCode);
			}
			buString5.SplitStringByNewLine(GCodeStr4, ref GCodes);
			GCodes.Insert(0, "<GCodes>");
			GCodes.Add("</GCodes>");
			if (!ShowCode)
			{
				ArrayList AL4 = new ArrayList();
				SaveProfileJobFile(activeProfile, ref AL4);
				GCodes.Add(" ");
				GCodes.Add("<ProfileCode>");
				GCodes.AddRange(AL4);
				GCodes.Add("</ProfileCode>");
			}
		}
	}

	public void doSetMissingClampers(ref buEyeBaseVer5.Apps.ProfileItem FirstItem, ref buEyeBaseVer5.Apps.ProfileItem SecondItem, bool GCodeSim = true)
	{
		if ((FirstItem != null) & (SecondItem != null))
		{
			List<buEyeBaseVer5.Apps.ProfileClamper> list = new List<buEyeBaseVer5.Apps.ProfileClamper>();
			if (FirstItem.CalculationData.Count > 0)
			{
				ProfileItemCalc profileItemCalc = FirstItem.CalculationData[FirstItem.CalculationData.Count - 1];
				if (profileItemCalc.calcOperations.Count > 0)
				{
					GProfileOperation gProfileOperation = profileItemCalc.calcOperations[profileItemCalc.calcOperations.Count - 1];
					if (gProfileOperation.Clampers.Count > 0)
					{
						for (int i = 0; i <= gProfileOperation.Clampers.Count - 1; i++)
						{
							list.Add(new buEyeBaseVer5.Apps.ProfileClamper(gProfileOperation.Clampers[i]));
						}
					}
				}
			}
			List<buEyeBaseVer5.Apps.ProfileClamper> list2 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
			if (SecondItem.CalculationData.Count > 0)
			{
				ProfileItemCalc profileItemCalc2 = SecondItem.CalculationData[0];
				if (profileItemCalc2.calcOperations.Count > 0)
				{
					GProfileOperation gProfileOperation2 = profileItemCalc2.calcOperations[0];
					if (gProfileOperation2.Clampers.Count > 0)
					{
						for (int j = 0; j <= gProfileOperation2.Clampers.Count - 1; j++)
						{
							list2.Add(new buEyeBaseVer5.Apps.ProfileClamper(gProfileOperation2.Clampers[j]));
						}
					}
				}
			}
			for (int k = 0; k <= FirstItem.CalculationData.Count - 1; k++)
			{
				for (int l = 0; l <= FirstItem.CalculationData[k].calcOperations.Count - 1; l++)
				{
					GProfileOperation gProfileOperation3 = FirstItem.CalculationData[k].calcOperations[l];
					for (int m = 0; m <= list2.Count - 1; m++)
					{
						if (gProfileOperation3.Clampers.Count < buProfileCalc.varProfileSettings.ProfileMaxClamper)
						{
							gProfileOperation3.Clampers.Add(new buEyeBaseVer5.Apps.ProfileClamper(list2[m]));
							FirstItem.isGCodeSimMoveCreated = false;
							SecondItem.isGCodeSimMoveCreated = false;
						}
					}
				}
			}
			for (int n = 0; n <= SecondItem.CalculationData.Count - 1; n++)
			{
				for (int num = 0; num <= SecondItem.CalculationData[n].calcOperations.Count - 1; num++)
				{
					GProfileOperation gProfileOperation4 = SecondItem.CalculationData[n].calcOperations[num];
					for (int num2 = 0; num2 <= list.Count - 1; num2++)
					{
						if (gProfileOperation4.Clampers.Count < buProfileCalc.varProfileSettings.ProfileMaxClamper)
						{
							gProfileOperation4.Clampers.Insert(num2, new buEyeBaseVer5.Apps.ProfileClamper(list[num2]));
							FirstItem.isGCodeSimMoveCreated = false;
							SecondItem.isGCodeSimMoveCreated = false;
						}
					}
				}
			}
		}
		if (GCodeSim)
		{
			if (FirstItem != null && FirstItem.CalculationData.Count > 0 && !FirstItem.isGCodeSimMoveCreated)
			{
				doGCodeToSimulation(ref FirstItem);
			}
			if (SecondItem != null && SecondItem.CalculationData.Count > 0 && !SecondItem.isGCodeSimMoveCreated)
			{
				doGCodeToSimulation(ref SecondItem);
			}
		}
	}

	public void doCreateOperation(actionTypeBU Action, ToolBase5 Tool, bool OnlyDrawing, bool AutoTool, ref buEyeBaseVer5.Apps.ProfileOperation OP)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		if (OP.Tool == null)
		{
			OP.Tool = new ToolBase5(Tool);
		}
		bool flag = true;
		bool flag2 = true;
		double freePlaneYSing = 1.0;
		Point3D point3D = buVector5.ToPoint3D(OP.OperationData.Position);
		if (buProfileCalc.varProfileSettings.XDirRefType == LeftRightType.Right)
		{
			point3D.X = profileItem.Length - OP.OperationData.Position.X;
			if (!buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
			{
				point3D.X = OP.OperationData.Position.X;
			}
		}
		if (OP.OperationData.selectedPlaneName == planeNames.Top)
		{
			OP.OperationData.selectedPlane = Plane.XY;
			OP.OperationData.selectedPlane.Translate(OP.OperationData.movePlanePoint.X, OP.OperationData.movePlanePoint.Y, OP.OperationData.movePlanePoint.Z);
		}
		if (OP.OperationData.selectedPlaneName == planeNames.Front)
		{
			OP.OperationData.selectedPlane = Plane.XZ;
			OP.OperationData.selectedPlane.Translate(OP.OperationData.movePlanePoint.X, 0.0, OP.OperationData.movePlanePoint.Z);
		}
		if (OP.OperationData.selectedPlaneName == planeNames.Back)
		{
			OP.OperationData.selectedPlane = Plane.XZ;
			OP.OperationData.selectedPlane.Translate(OP.OperationData.movePlanePoint.X, OP.OperationData.movePlanePoint.Y, OP.OperationData.movePlanePoint.Z);
		}
		if (OP.OperationData.selectedPlaneName == planeNames.Bottom)
		{
			OP.OperationData.selectedPlane = Plane.XY;
			OP.OperationData.selectedPlane.Translate(OP.OperationData.movePlanePoint.X, OP.OperationData.movePlanePoint.Y, OP.OperationData.movePlanePoint.Z);
		}
		OP.OperationData.OperationType = clsInit.cProfile.ProfileActionToOperationType(Action);
		OP.Tool = new ToolBase5(Tool);
		OP.EntityMultiCam = new List<buEntity>();
		OP.EntityMultiContour = new List<buEntity>();
		OP.EntityMultiSolidDepth = new List<Entity>();
		OP.EntityMultiXYPlane = new List<buEntity>();
		OP.EntityDimension = new List<DimensionGroup>();
		List<buEntity> copiedEntities = new List<buEntity>();
		List<buEntity> list = new List<buEntity>();
		List<List<buEntity>> entCam = new List<List<buEntity>>();
		if (ProfileTempVars.CamAssinged)
		{
			OP.CamAssinged = true;
		}
		camTp Cam = new camTp();
		MWCalculationOptions mWCalculationOptions = new MWCalculationOptions();
		if (!OnlyDrawing)
		{
			clsMW.CamEntities.Clear();
			clsMW.CamEntities = new List<Entity>();
			mWCalculationOptions.NumberofAxis = 3;
			mWCalculationOptions.CamWireframeType = CamWireFrameType.Contour;
			mWCalculationOptions.Mode = CamMode.WireFrame;
			mWCalculationOptions.DontApplyReset = true;
			mWCalculationOptions.isBuWireframeCalculation = false;
			mWCalculationOptions.AddToCamListInMWCalculation = false;
			mWCalculationOptions.DontShowDialogBox = true;
			mWCalculationOptions.isBuSort = false;
			mWCalculationOptions.UseStartPoint = false;
			mWCalculationOptions.UseConstantStartPoint = false;
			mWCalculationOptions.StartPointX = 0.0;
			mWCalculationOptions.StartPointY = 0.0;
			mWCalculationOptions.ShowProgressForm = false;
			clsInit.cMwCalc.Settings.ShowProgressForm = false;
		}
		buEntity buEntity2 = null;
		buEntity buEntity3 = null;
		if (Action == actionTypeBU.profileRectangle)
		{
			if (!((OP.OperationData.RectangleData.RectangleRadius == 0.0) & (OP.OperationData.RectangleData.RectangleChamfer == 0.0)))
			{
				if (OP.OperationData.RectangleData.RectangleRadius > 0.0)
				{
					buEntity2 = buEntity.Copy(CompositeCurve.CreateRoundedRectangle(OP.OperationData.selectedPlane, 0.0, 0.0, OP.OperationData.RectangleData.RectangleWidth, OP.OperationData.RectangleData.RectangleHeight, OP.OperationData.RectangleData.RectangleRadius, buConversion5.DegreeToRadian(OP.OperationData.RectangleData.RectangleAngle), centered: true));
					buEntity3 = buEntity.Copy(CompositeCurve.CreateRoundedRectangle(Plane.XY, 0.0, 0.0, OP.OperationData.RectangleData.RectangleWidth, OP.OperationData.RectangleData.RectangleHeight, OP.OperationData.RectangleData.RectangleRadius, buConversion5.DegreeToRadian(OP.OperationData.RectangleData.RectangleAngle), centered: true));
				}
			}
			else
			{
				buEntity2 = buEntity.Copy(CompositeCurve.CreateRectangle(OP.OperationData.selectedPlane, 0.0, 0.0, OP.OperationData.RectangleData.RectangleWidth, OP.OperationData.RectangleData.RectangleHeight, buConversion5.DegreeToRadian(OP.OperationData.RectangleData.RectangleAngle), centered: true));
				buEntity3 = buEntity.Copy(CompositeCurve.CreateRectangle(Plane.XY, 0.0, 0.0, OP.OperationData.RectangleData.RectangleWidth, OP.OperationData.RectangleData.RectangleHeight, buConversion5.DegreeToRadian(OP.OperationData.RectangleData.RectangleAngle), centered: true));
			}
		}
		if (Action == actionTypeBU.profileSlot && ((OP.OperationData.SlotData.SlotWidth > 0.0) & (OP.OperationData.SlotData.SlotDiameter > 0.0)))
		{
			buEntity2 = buEntity.Copy(CompositeCurve.CreateSlot(OP.OperationData.selectedPlane, 0.0, 0.0, OP.OperationData.SlotData.SlotWidth - OP.OperationData.SlotData.SlotDiameter, OP.OperationData.SlotData.SlotDiameter / 2.0, buConversion5.DegreeToRadian(OP.OperationData.SlotData.SlotAngle), centered: true));
			buEntity3 = buEntity.Copy(CompositeCurve.CreateSlot(Plane.XY, 0.0, 0.0, OP.OperationData.SlotData.SlotWidth - OP.OperationData.SlotData.SlotDiameter, OP.OperationData.SlotData.SlotDiameter / 2.0, buConversion5.DegreeToRadian(OP.OperationData.SlotData.SlotAngle), centered: true));
		}
		if (Action == actionTypeBU.profileCut)
		{
			buEntity2 = buEntity.Copy(CompositeCurve.CreateRectangle(OP.OperationData.selectedPlane, 0.0, 0.0, OP.OperationData.CutData.CutWidth, OP.OperationData.CutData.CutHeigth, buConversion5.DegreeToRadian(OP.OperationData.CutData.CutAngle), centered: true));
			buEntity3 = buEntity.Copy(CompositeCurve.CreateRectangle(Plane.XY, 0.0, 0.0, OP.OperationData.CutData.CutWidth, OP.OperationData.CutData.CutHeigth, buConversion5.DegreeToRadian(OP.OperationData.CutData.CutAngle), centered: true));
		}
		if (Action == actionTypeBU.profileCircle && OP.OperationData.CircleData.CircleDiameter > 0.0)
		{
			Circle refEntity = new Circle(OP.OperationData.selectedPlane, OP.OperationData.CircleData.CircleDiameter / 2.0);
			buEntity2 = buEntity.Copy(refEntity);
			buEntity3 = new buCircle(Plane.XY, OP.OperationData.CircleData.CircleDiameter / 2.0);
		}
		if (Action == actionTypeBU.profilePolygon)
		{
			if (OP.OperationData.selectedPlaneName == planeNames.Free)
			{
				List<Point3D> Vertices = new List<Point3D>();
				clsInit.cVector5.PolygonCenter(new Point3D(), OP.OperationData.PolygonData.PolygonDiameter / 2.0, OP.OperationData.PolygonData.PolygonSide, Plane.XY, ref Vertices);
				clsInit.cVector5.Rotate(new Point3D(), OP.OperationData.PolygonData.PolygonAngle, Plane.XY, ref Vertices);
				buLinearPath item = new buLinearPath(Vertices);
				list.Add(item);
				Vertices = new List<Point3D>();
				clsInit.cVector5.PolygonCenter(new Point3D(), OP.OperationData.PolygonData.PolygonDiameter / 2.0, OP.OperationData.PolygonData.PolygonSide, Plane.XY, ref Vertices);
				clsInit.cVector5.Rotate(new Point3D(), OP.OperationData.PolygonData.PolygonAngle, Plane.XY, ref Vertices);
				item = new buLinearPath(OP.OperationData.selectedPlane, Vertices);
				copiedEntities.Add(item);
			}
			else
			{
				List<Point3D> Vertices2 = new List<Point3D>();
				clsInit.cVector5.PolygonCenter(new Point3D(), OP.OperationData.PolygonData.PolygonDiameter / 2.0, OP.OperationData.PolygonData.PolygonSide, OP.OperationData.selectedPlane, ref Vertices2);
				LinearPath linearPath = new LinearPath(Vertices2);
				linearPath.Rotate(buConversion5.DegreeToRadian(OP.OperationData.PolygonData.PolygonAngle), OP.OperationData.selectedPlane.AxisZ);
				List<ICurve> list2 = new List<ICurve>();
				list2.Add(linearPath);
				CompositeCurve refEntity2 = new CompositeCurve(list2);
				buEntity2 = buEntity.Copy(refEntity2);
				Vertices2 = new List<Point3D>();
				clsInit.cVector5.PolygonCenter(new Point3D(), OP.OperationData.PolygonData.PolygonDiameter / 2.0, OP.OperationData.PolygonData.PolygonSide, Plane.XY, ref Vertices2);
				linearPath = new LinearPath(Vertices2);
				linearPath.Rotate(buConversion5.DegreeToRadian(OP.OperationData.PolygonData.PolygonAngle), Vector3D.AxisZ);
				list2 = new List<ICurve>();
				list2.Add(linearPath);
				refEntity2 = new CompositeCurve(list2);
				buEntity3 = buEntity.Copy(refEntity2);
			}
		}
		if (Action == actionTypeBU.profileEllipse)
		{
			Ellipse ellipse = new Ellipse(OP.OperationData.selectedPlane, OP.OperationData.EllipseData.EllipseWidth / 2.0, OP.OperationData.EllipseData.EllipseHeight / 2.0);
			ellipse.Regen(0.01);
			ellipse.Rotate(buConversion5.DegreeToRadian(OP.OperationData.EllipseData.EllipseAngle), OP.OperationData.selectedPlane.AxisZ, ellipse.Center);
			buEntity2 = buEntity.Copy(ellipse);
			buEntity3 = new buEllipse(Plane.XY, OP.OperationData.EllipseData.EllipseWidth / 2.0, OP.OperationData.EllipseData.EllipseHeight / 2.0);
			buEntity3.Rotate(OP.OperationData.EllipseData.EllipseAngle, new Vector3D(0.0, 0.0, 1.0));
		}
		if (Action == actionTypeBU.profileBarrel)
		{
			eArc HeadArc = new eArc();
			eArc TaleArc = new eArc();
