						clsInit.cProfile.OperationStepCalculation(OP.OperationData, OP.OperationData.Depth, OP.OperationData.CamParMilling.Steps, ref calcDepth);
					}
				}
				else if (!OP.OperationData.CamParMilling.Steps.Enable)
				{
					for (int num10 = 0; num10 <= OP.OperationData.DepthValues.Count - 1; num10++)
					{
						calcDepth.Add(new DepthPositions(OP.OperationData.DepthValues[num10]));
					}
					OP.EntityMultiCam = new List<buEntity>();
					OP.EntityMultiContour = new List<buEntity>();
					OP.EntityMultiSolidDepth = new List<Entity>();
				}
				else
				{
					for (int num11 = 0; num11 <= OP.OperationData.DepthValues.Count - 1; num11++)
					{
						clsInit.cProfile.OperationStepCalculation(OP.OperationData, OP.OperationData.DepthValues[num11], OP.OperationData.CamParMilling.Steps, ref calcDepth);
					}
				}
			}
			else if (!OP.OperationData.CamParMilling.Steps.Enable)
			{
				calcDepth.Add(new DepthPositions(OP.OperationData.DepthValues[0]));
			}
			else
			{
				for (int num12 = 0; num12 <= OP.OperationData.DepthValues.Count - 1; num12++)
				{
					clsInit.cProfile.OperationStepCalculation(OP.OperationData, OP.OperationData.DepthValues[num12], OP.OperationData.CamParMilling.Steps, ref calcDepth);
				}
			}
			if (OP.OperationData.ManuelZEnable)
			{
				calcDepth.Clear();
				if (OP.OperationData.selectedPlaneName != planeNames.Back)
				{
					if (OP.OperationData.selectedPlaneName != planeNames.Front)
					{
						if (OP.OperationData.selectedPlaneName != planeNames.Bottom)
						{
							DepthPositions depthPositions2 = new DepthPositions();
							depthPositions2.TopPosition = OP.OperationData.ManuelZVal;
							depthPositions2.BottomPosition = OP.OperationData.ManuelZVal - (OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth);
							depthPositions2.Depth = depthPositions2.BottomPosition - depthPositions2.TopPosition;
							calcDepth.Add(depthPositions2);
						}
						else
						{
							DepthPositions depthPositions3 = new DepthPositions();
							depthPositions3.TopPosition = OP.OperationData.ManuelZVal;
							depthPositions3.BottomPosition = OP.OperationData.ManuelZVal + (OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth);
							depthPositions3.Depth = OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth;
							calcDepth.Add(depthPositions3);
						}
					}
					else
					{
						DepthPositions depthPositions4 = new DepthPositions();
						depthPositions4.TopPosition = OP.OperationData.ManuelZVal;
						depthPositions4.BottomPosition = OP.OperationData.ManuelZVal + (OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth);
						depthPositions4.Depth = OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth;
						calcDepth.Add(depthPositions4);
					}
				}
				else
				{
					DepthPositions depthPositions5 = new DepthPositions();
					depthPositions5.TopPosition = OP.OperationData.ManuelZVal;
					depthPositions5.BottomPosition = OP.OperationData.ManuelZVal - (OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth);
					depthPositions5.Depth = 0.0 - (OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth);
					calcDepth.Add(depthPositions5);
				}
				OP.OperationData.Depth = new DepthPositions(calcDepth[calcDepth.Count - 1]);
				if (OP.OperationData.CamParMilling.Steps.Enable)
				{
					calcDepth.Clear();
					clsInit.cProfile.OperationStepCalculation(OP.OperationData, OP.OperationData.Depth, OP.OperationData.CamParMilling.Steps, ref calcDepth);
				}
			}
		}
		if (!flag2)
		{
			NotchToCam(ref OP, profileItem, entCam);
		}
		else
		{
			int num13 = 1;
			int num14 = 1;
			double num15 = 0.0;
			double num16 = 0.0;
			if (OP.OperationData.Array.LineerEnable)
			{
				num13 = OP.OperationData.Array.LineerXCount;
				num15 = OP.OperationData.Array.LineerXDistance;
				num14 = OP.OperationData.Array.LineerYCount;
				num16 = OP.OperationData.Array.LineerYDistance;
				if ((OP.OperationData.selectedPlaneName == planeNames.Top) | (OP.OperationData.selectedPlaneName == planeNames.Bottom))
				{
					if ((OP.OperationData.Corner == CornerLocation.LeftTop) | (OP.OperationData.Corner == CornerLocation.TopCenter) | (OP.OperationData.Corner == CornerLocation.RightTop))
					{
						num16 = 0.0 - num16;
					}
					if ((OP.OperationData.Corner == CornerLocation.RightBottom) | (OP.OperationData.Corner == CornerLocation.RightCenter) | (OP.OperationData.Corner == CornerLocation.RightTop))
					{
						num15 = 0.0 - num15;
					}
				}
				if ((OP.OperationData.selectedPlaneName == planeNames.Front) | (OP.OperationData.selectedPlaneName == planeNames.Back))
				{
					if ((OP.OperationData.Corner == CornerLocation.LeftTop) | (OP.OperationData.Corner == CornerLocation.TopCenter) | (OP.OperationData.Corner == CornerLocation.RightTop))
					{
						num16 = 0.0 - num16;
					}
					if ((OP.OperationData.Corner == CornerLocation.RightBottom) | (OP.OperationData.Corner == CornerLocation.RightCenter) | (OP.OperationData.Corner == CornerLocation.RightTop))
					{
						num15 = 0.0 - num15;
					}
				}
			}
			new Point3D();
			Point3D pntLastMoved = new Point3D();
			if (!OP.OperationData.Array.CircularEnable)
			{
				int num17 = 0;
				for (int num18 = 0; num18 < num14; num18++)
				{
					double disMoveY = (double)num18 * num16;
					double disMoveZ = (double)num18 * num16;
					if ((OP.OperationData.selectedPlaneName == planeNames.Top) | (OP.OperationData.selectedPlaneName == planeNames.Bottom))
					{
						disMoveZ = 0.0;
					}
					if ((OP.OperationData.selectedPlaneName == planeNames.Front) | (OP.OperationData.selectedPlaneName == planeNames.Back))
					{
						disMoveY = 0.0;
					}
					if (OP.OperationData.selectedPlaneName == planeNames.Free)
					{
						disMoveZ = 0.0;
					}
					for (int num19 = 0; num19 < num13; num19++)
					{
						double disMoveX = (double)num19 * num15;
						double totDepth = 0.0;
						if (copiedEntities.Count <= 0)
						{
							if (ccVars.entitiesContour.Count > 0)
							{
								for (int num20 = 0; num20 <= ccVars.entitiesContour.Count - 1; num20++)
								{
									List<buEntity> list4 = new List<buEntity>();
									for (int num21 = 0; num21 <= ccVars.entitiesContour[num20].Entities.Count - 1; num21++)
									{
										buEntity copiedEntity3 = null;
										buEntity.Copy(ccVars.entitiesContour[num20].Entities[num21], ref copiedEntity3);
										if (copiedEntity3 != null)
										{
											list4.Add(copiedEntity3);
										}
									}
									doCreateOperationDraw3D(list4, profileItem, totDepth, freePlaneYSing, point3D, disMoveX, disMoveY, disMoveZ, calcDepth, num17, ref pntLastMoved, ref entCam, ref OP);
								}
								for (int num22 = 0; num22 <= entCam.Count - 1; num22++)
								{
									List<buEntity> list5 = new List<buEntity>();
									list5.AddRange(entCam[num22]);
									for (int num23 = 0; num23 <= calcDepth.Count - 1; num23++)
									{
										Vector3D VecTranslate = null;
										Vector3D VecDepth = null;
										doVectorCalculate(OP, num23, ref VecTranslate, ref VecDepth, calcDepth, point3D, freePlaneYSing);
										OperationToCam(ref OP, profileItem, list5, calcDepth, num23, VecTranslate, VecDepth, disMoveX, disMoveY, disMoveZ, MoveSmallSafe: true, num17, ref pntLastMoved);
									}
								}
							}
						}
						else
						{
							doCreateOperationDraw3D(copiedEntities, profileItem, totDepth, freePlaneYSing, point3D, disMoveX, disMoveY, disMoveZ, calcDepth, num17, ref pntLastMoved, ref entCam, ref OP);
							for (int num24 = 0; num24 <= entCam.Count - 1; num24++)
							{
								List<buEntity> list6 = new List<buEntity>();
								list6.AddRange(entCam[num24]);
								for (int num25 = 0; num25 <= calcDepth.Count - 1; num25++)
								{
									Vector3D VecTranslate2 = null;
									Vector3D VecDepth2 = null;
									doVectorCalculate(OP, num25, ref VecTranslate2, ref VecDepth2, calcDepth, point3D, freePlaneYSing);
									OperationToCam(ref OP, profileItem, list6, calcDepth, num25, VecTranslate2, VecDepth2, disMoveX, disMoveY, disMoveZ, MoveSmallSafe: true, num17, ref pntLastMoved);
								}
							}
						}
						if (Action == actionTypeBU.profileWireText)
						{
							OP.EntityMultiSolidDepth.Clear();
						}
						num17++;
					}
				}
			}
		}
		if (OP.EntityMultiSolidDepth == null || OP.EntityMultiSolidDepth.Count <= 0)
		{
			if (OP.EntityMultiContour != null && OP.EntityMultiContour.Count > 0)
			{
				clsInit.cVector5.BoxSizeCalculate(OP.EntityMultiContour, ref OP.MinPoint, ref OP.MaxPoint);
				clsInit.cProfile.OperationDimensionEntities(ref OP, profileItem, buProfileCalc.varProfileRunSettings.selectedFreePlaneLength);
				if (profileItem.XReferanceLocation == LeftRightType.Right && buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
