					double x = OP.MinPoint.X;
					double x2 = OP.MaxPoint.X;
					OP.MinPoint.X = Math.Round(profileItem.Length - x2, 3);
					OP.MaxPoint.X = Math.Round(profileItem.Length - x, 3);
				}
			}
		}
		else
		{
			clsInit.cVector5.BoxSizeCalculate(OP.EntityMultiSolidDepth, ref OP.MinPoint, ref OP.MaxPoint);
			clsInit.cProfile.OperationDimensionEntities(ref OP, profileItem, buProfileCalc.varProfileRunSettings.selectedFreePlaneLength);
			if (profileItem.XReferanceLocation == LeftRightType.Right && buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
			{
				double x3 = OP.MinPoint.X;
				double x4 = OP.MaxPoint.X;
				OP.MinPoint.X = Math.Round(profileItem.Length - x4, 3);
				OP.MaxPoint.X = Math.Round(profileItem.Length - x3, 3);
			}
		}
		OP.Action = Action;
		cntCreateOperation++;
	}

	public void doVectorCalculate(buEyeBaseVer5.Apps.ProfileOperation OP, int indexCalcDepth, ref Vector3D VecTranslate, ref Vector3D VecDepth, List<DepthPositions> calcDepth, Point3D Pos, double FreePlaneYSing)
	{
		VecTranslate = OP.OperationData.selectedPlane.AxisY * Pos.Y;
		if (OP.OperationData.selectedPlaneName == planeNames.Free)
		{
			VecTranslate = OP.OperationData.selectedPlane.AxisY * (Pos.Y * FreePlaneYSing);
		}
		VecDepth = OP.OperationData.selectedPlane.AxisZ * calcDepth[indexCalcDepth].Depth;
		if (OP.OperationData.selectedPlaneName == planeNames.Front)
		{
			VecDepth = OP.OperationData.selectedPlane.AxisZ * (0.0 - calcDepth[indexCalcDepth].Depth);
		}
		if (OP.OperationData.selectedPlaneName == planeNames.Back)
		{
			VecDepth = OP.OperationData.selectedPlane.AxisZ * (0.0 - calcDepth[indexCalcDepth].Depth);
		}
	}

	public void doCreateOperationDraw3D(List<buEntity> entContour, buEyeBaseVer5.Apps.ProfileItem curItem, double totDepth, double FreePlaneYSing, Point3D Pos, double disMoveX, double disMoveY, double disMoveZ, List<DepthPositions> calcDepth, int IndexRepeat, ref Point3D pntLastMoved, ref List<List<buEntity>> entCam, ref buEyeBaseVer5.Apps.ProfileOperation OP)
	{
		for (int i = 0; i <= calcDepth.Count - 1; i++)
		{
			List<Point3D> Points = new List<Point3D>();
