			if (OP.OperationData.selectedPlaneName == planeNames.Free)
			{
				point3D_3 = OP.OperationData.selectedPlane.PointAt(new Point2D(Pos.X + disMoveX, 0.0 - (VecTranslate.Y + disMoveY)));
				VecDepth = OP.OperationData.selectedPlane.AxisZ * totDepth;
				if (entContour != null)
				{
					for (int j = 0; j <= entContour.Count - 1; j++)
					{
						buEntity buEntity2 = buVector5.CopyEntities(entContour[j]);
						buEntity2.Translate(Pos.X + disMoveX, VecTranslate.Y + disMoveY, VecTranslate.Z + disMoveZ);
						buEntity2.Translate(0.0, VecDepth.Y, VecDepth.Z);
						buEntity2.Info.CamID = IndexRepeat;
