						{
							if (entContour.Count > 1)
							{
								List<Point3D> Points2 = new List<Point3D>();
								clsInit.cVector5.EntitiesToPointsWithCamDirection(entContour[j], 0.01, ref Points2);
								Points.AddRange(Points2);
								if ((j == entContour.Count - 1) & (Points.Count > 2))
								{
									clsInit.cVector5.CheckDuplicatedPointsWithPrevious(ref Points);
									LinearPath outer = new LinearPath(Points);
									devDept.Eyeshot.Entities.Region region = new devDept.Eyeshot.Entities.Region(outer, OP.OperationData.selectedPlane, true);
									Entity entity = region.ExtrudeAsBrep(1.0 * VecDepth);
									entity.Translate(Pos.X + disMoveX, VecTranslate.Y + disMoveY, VecTranslate.Z + disMoveZ);
									OP.EntityMultiSolidDepth.Add(entity);
								}
							}
						}
						else
						{
							devDept.Eyeshot.Entities.Region region2 = new devDept.Eyeshot.Entities.Region((ICurve)copiedEntity, OP.OperationData.selectedPlane, true);
