	{
		for (int i = 0; i <= calcDepth.Count - 1; i++)
		{
			List<Point3D> Points = new List<Point3D>();
			_ = calcDepth[i].BottomPosition;
			Vector3D vector3D = OP.OperationData.selectedPlane.AxisY * Pos.Y;
			_ = OP.OperationData.selectedPlane.AxisZ * calcDepth[i].TopPosition;
			if (OP.OperationData.selectedPlaneName == planeNames.Free)
			{
				vector3D = OP.OperationData.selectedPlane.AxisY * (Pos.Y * FreePlaneYSing);
			}
			Vector3D vector3D2 = OP.OperationData.selectedPlane.AxisZ * calcDepth[i].Depth;
			if (OP.OperationData.selectedPlaneName == planeNames.Front)
			{
				vector3D2 = OP.OperationData.selectedPlane.AxisZ * (0.0 - calcDepth[i].Depth);
			}
			if (OP.OperationData.selectedPlaneName == planeNames.Back)
			{
				vector3D2 = OP.OperationData.selectedPlane.AxisZ * (0.0 - calcDepth[i].Depth);
			}
			if (OP.OperationData.selectedPlaneName == planeNames.Bottom)
			{
				OP.CamInsideVector = OP.OperationData.selectedPlane.AxisZ * 1.0;
