					double num12 = ccVars.Tools[num10].Tools[num11].Geometry.Diameter / 2.0;
					if (((buCompare5.GE(num3, num12) && num12 > num9) & ((num4 == 0.0) | buCompare5.LE(num12, num4))) && ccVars.Tools[num10].Tools[num11].Geometry.GeometryType != ToolType.Saw && ((ccVars.Tools[num10].Tools[num11].Purpose == ToolPurpose.Milling) | (ccVars.Tools[num10].Tools[num11].Purpose == ToolPurpose.General) | (ccVars.Tools[num10].Tools[num11].Purpose == ToolPurpose.Cutting)))
