	public void doCreateOperationCam(buEyeBaseVer5.Apps.ProfileItem curItem, bool OnlyDrawing, MWCalculationOptions MWCalcoptions, actionTypeBU Action, List<buEntity> entContour, List<buEntity> entContourXY, ref buEyeBaseVer5.Apps.ProfileOperation OP, ref List<List<buEntity>> entCam, ref camTp Cam)
	{
		bool g1Original = false;
		if ((OP.OperationData.selectedPlaneName == planeNames.Top) | (OP.OperationData.selectedPlaneName == planeNames.Bottom))
		{
			g1Original = true;
		}
		if (buProfileCalc.varProfileSettings.AllGCodeAsG1)
		{
			g1Original = false;
		}
		if (OP.OperationData.OperationType != ProfileOperationTypes.Notch)
		{
			if (OP.OperationData.OperationType != ProfileOperationTypes.Tapping)
			{
				if (OP.Tool == null)
				{
					return;
				}
			}
			else if ((OP.Tool == null) | (OP.ToolAux == null))
			{
				return;
			}
		}
		else if (OP.ToolNotch == null)
		{
			return;
		}
		if (OnlyDrawing || entContourXY == null)
		{
			return;
		}
		switch (Action)
		{
		case actionTypeBU.profileHole:
			if (entContourXY.Count > 0 && entContour[0] is buCircle)
			{
				buCircle buCircle2 = entContour[0] as buCircle;
				buEntity buEntity2 = new buPoint(buCircle2.Center);
				buEntity2.typeDefination = entityTypeDefination.CamDrill;
				List<buEntity> list2 = new List<buEntity>();
				list2.Add(buEntity2);
				entCam.Add(list2);
			}
			return;
		case actionTypeBU.profileTapping:
			if (entContourXY.Count > 0 && entContour[0] is buCircle)
			{
				buCircle buCircle3 = entContour[0] as buCircle;
				buEntity buEntity4 = new buPoint(buCircle3.Center);
				buEntity4.typeDefination = entityTypeDefination.CamDrill;
				List<buEntity> list4 = new List<buEntity>();
				list4.Add(buEntity4);
				entCam.Add(list4);
			}
			return;
		case actionTypeBU.profileCut:
			if (entContour.Count > 0)
			{
				Point3D EndPnt = new Point3D();
				Point3D EndPnt2 = new Point3D();
				clsInit.cVector5.LineWithLengthAndAngle(new Point3D(0.0, 0.0, 0.0), OP.OperationData.CutData.CutHeigth / 2.0, OP.OperationData.CutData.CutAngle + 90.0, ref EndPnt);
				clsInit.cVector5.LineWithLengthAndAngle(new Point3D(0.0, 0.0, 0.0), OP.OperationData.CutData.CutHeigth / 2.0, OP.OperationData.CutData.CutAngle - 90.0, ref EndPnt2);
				buEntity buEntity3 = new buLine(OP.OperationData.selectedPlane, EndPnt2, EndPnt);
				buEntity3.typeDefination = entityTypeDefination.CamG1;
				List<buEntity> list3 = new List<buEntity>();
				list3.Add(buEntity3);
				entCam.Add(list3);
			}
			return;
		case actionTypeBU.profileNotch:
		{
			clsInit.cProfile.NotchCalc(ref OP, ref Cam, curItem, ccVars.Tools[0].Tools, buProfileCalc.varProfileSettings);
			List<buEntity> list = new List<buEntity>();
			TpPnt9D tpPnt9D = new TpPnt9D();
			for (int i = 0; i <= OP.CamCalculation.Count - 1; i++)
			{
				list = new List<buEntity>();
				double x = 0.0;
				double y = 0.0;
				double z = 0.0;
				if (OP.CamCalculation[i].Tool.Geometry.GeometryType == ToolType.Saw)
				{
					if (OP.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Left)
					{
						x = OP.CamCalculation[i].Tool.Geometry.Diameter / 2.0;
					}
					if (OP.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Right)
					{
						x = (0.0 - OP.CamCalculation[i].Tool.Geometry.Diameter) / 2.0;
					}
					if (OP.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Front)
					{
						y = OP.CamCalculation[i].Tool.Geometry.Diameter / 2.0;
					}
					if (OP.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Back)
					{
						y = (0.0 - OP.CamCalculation[i].Tool.Geometry.Diameter) / 2.0;
					}
				}
				if (((i == OP.CamCalculation.Count - 1) & (OP.OperationData.CamParNotch.Notch.NotchCutType == ProfileNotchCutType.BySawAndMilling)) && ((OP.OperationData.NotchData.NotchUpDown == UpDownLocationType.Up) & (OP.OperationData.NotchData.NotchStart == 0.0)))
				{
					x = 0.0;
					y = 0.0;
				}
				if (OP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal)
				{
					x = 0.0;
					if (OP.CamCalculation[i].Tool.Geometry.GeometryType == ToolType.Saw)
					{
						z = (0.0 - OP.ToolNotch.Geometry.Diameter) / 2.0;
					}
				}
				for (int j = 0; j <= OP.CamCalculation[i].CamPoints.Count - 1; j++)
				{
					for (int k = 1; k <= OP.CamCalculation[i].CamPoints[j].Points.Count - 1; k++)
					{
						buLine buLine2 = null;
						TpPnt9D tpPnt9D2 = OP.CamCalculation[i].CamPoints[j].Points[k - 1];
						TpPnt9D tpPnt9D3 = OP.CamCalculation[i].CamPoints[j].Points[k];
