							buLine2 = new buLine(new Point3D(tpPnt9D.P9.X, tpPnt9D.P9.Y, tpPnt9D.P9.Z), new Point3D(tpPnt9D2.P9.X, tpPnt9D2.P9.Y, tpPnt9D2.P9.Z));
							buLine2.Orientation.A = tpPnt9D2.P9.A;
							buLine2.typeDefination = entityTypeDefination.CamG0;
							buLine2.Info.Offset = new Point3D(x, y, z);
							list.Add(buLine2);
						}
						if (tpPnt9D3.MoveType != CamMoveType.G0)
						{
							if (tpPnt9D3.MoveType != CamMoveType.G1)
							{
								if (tpPnt9D3.MoveType != CamMoveType.Plunge)
								{
									if (tpPnt9D3.MoveType != CamMoveType.Leave)
									{
										if (!buCompare5.EQ(tpPnt9D2, tpPnt9D3))
										{
											buLine2 = new buLine(new Point3D(tpPnt9D2.P9.X, tpPnt9D2.P9.Y, tpPnt9D2.P9.Z), new Point3D(tpPnt9D3.P9.X, tpPnt9D3.P9.Y, tpPnt9D3.P9.Z));
											buLine2.Orientation.A = tpPnt9D2.P9.A;
											buLine2.typeDefination = entityTypeDefination.CamOther;
											buLine2.Info.Offset = new Point3D(x, y, z);
											list.Add(buLine2);
											tpPnt9D = new TpPnt9D(OP.CamCalculation[i].CamPoints[j].Points[k]);
										}
									}
									else if (!buCompare5.EQ(tpPnt9D2, tpPnt9D3))
									{
										buLine2 = new buLine(new Point3D(tpPnt9D2.P9.X, tpPnt9D2.P9.Y, tpPnt9D2.P9.Z), new Point3D(tpPnt9D3.P9.X, tpPnt9D3.P9.Y, tpPnt9D3.P9.Z));
										buLine2.Orientation.A = tpPnt9D2.P9.A;
										buLine2.typeDefination = entityTypeDefination.CamLeave;
										buLine2.Info.CamLeaveAxis = "X";
										if (!buCompare5.EQ(tpPnt9D3.P9.Z, tpPnt9D2.P9.Z) & buCompare5.EQ(tpPnt9D3.P9.X, tpPnt9D2.P9.X))
										{
											buLine2.Info.CamLeaveAxis = "Z";
										}
										buLine2.Info.Offset = new Point3D(x, y, z);
										list.Add(buLine2);
										tpPnt9D = new TpPnt9D(OP.CamCalculation[i].CamPoints[j].Points[k]);
									}
								}
								else if (!buCompare5.EQ(tpPnt9D2, tpPnt9D3))
								{
									buLine2 = new buLine(new Point3D(tpPnt9D2.P9.X, tpPnt9D2.P9.Y, tpPnt9D2.P9.Z), new Point3D(tpPnt9D3.P9.X, tpPnt9D3.P9.Y, tpPnt9D3.P9.Z));
									buLine2.Orientation.A = tpPnt9D2.P9.A;
									buLine2.typeDefination = entityTypeDefination.CamPlunge;
									buLine2.Info.CamPlungeAxis = "X";
									if (!buCompare5.EQ(tpPnt9D3.P9.Z, tpPnt9D2.P9.Z) & buCompare5.EQ(tpPnt9D3.P9.X, tpPnt9D2.P9.X))
									{
										buLine2.Info.CamPlungeAxis = "Z";
									}
									buLine2.Info.Offset = new Point3D(x, y, z);
									list.Add(buLine2);
									tpPnt9D = new TpPnt9D(OP.CamCalculation[i].CamPoints[j].Points[k]);
								}
							}
							else if (!buCompare5.EQ(tpPnt9D2, tpPnt9D3))
							{
								buLine2 = new buLine(new Point3D(tpPnt9D2.P9.X, tpPnt9D2.P9.Y, tpPnt9D2.P9.Z), new Point3D(tpPnt9D3.P9.X, tpPnt9D3.P9.Y, tpPnt9D3.P9.Z));
								buLine2.Orientation.A = tpPnt9D2.P9.A;
								buLine2.typeDefination = entityTypeDefination.CamG1;
								buLine2.Info.Offset = new Point3D(x, y, z);
								list.Add(buLine2);
								tpPnt9D = new TpPnt9D(OP.CamCalculation[i].CamPoints[j].Points[k]);
							}
						}
						else if (!buCompare5.EQ(tpPnt9D2, tpPnt9D3))
						{
							buLine2 = new buLine(new Point3D(tpPnt9D2.P9.X, tpPnt9D2.P9.Y, tpPnt9D2.P9.Z), new Point3D(tpPnt9D3.P9.X, tpPnt9D3.P9.Y, tpPnt9D3.P9.Z));
							buLine2.Orientation.A = tpPnt9D2.P9.A;
							buLine2.typeDefination = entityTypeDefination.CamG0;
