			calcEntities = new CamEntitiesTobuEntities();
			clsInit.appMW.CamEntitesTobuEntities(Cam, new CamEntitiesToEntitiesOption(G0: false, G1: true, Leave: true, Plunge: true, g1Original), ref calcEntities);
			for (int num3 = 0; num3 <= calcEntities.LeadInEntities.Count - 1; num3++)
