	public void doOperationMoveDown()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem != null && ((profileItem.Operations.Count > 0) & (buProfileCalc.varProfileRunSettings.activeOPIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeOPIndex <= profileItem.Operations.Count - 2)))
		{
			bUndoBuffer = true;
			buEyeBaseVer5.Apps.ProfileOperation item = profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex];
			profileItem.Operations.RemoveAt(buProfileCalc.varProfileRunSettings.activeOPIndex);
			buProfileCalc.varProfileRunSettings.activeOPIndex++;
			profileItem.Operations.Insert(buProfileCalc.varProfileRunSettings.activeOPIndex, item);
			ProfileTreeUpdate();
		}
	}

	public void doOperationMoveUp()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem != null && ((profileItem.Operations.Count >= 0) & (buProfileCalc.varProfileRunSettings.activeOPIndex > 0) & (buProfileCalc.varProfileRunSettings.activeOPIndex <= profileItem.Operations.Count - 1)))
		{
			bUndoBuffer = true;
			buEyeBaseVer5.Apps.ProfileOperation item = profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex];
			profileItem.Operations.RemoveAt(buProfileCalc.varProfileRunSettings.activeOPIndex);
			buProfileCalc.varProfileRunSettings.activeOPIndex--;
			profileItem.Operations.Insert(buProfileCalc.varProfileRunSettings.activeOPIndex, item);
			ProfileTreeUpdate();
		}
	}

	public void doAddSelectedOperations()
	{
		string callMethod = "doAddSelectedOperations";
		try
		{
			ProfileTempVars.SelectedOperations.Clear();
			if ((buProfileCalc.varProfileRunSettings.activeProfileIndex == 0) & (activeProfile.FirstItem != null))
			{
				for (int i = 0; i <= activeProfile.FirstItem.Operations.Count - 1; i++)
				{
					if (activeProfile.FirstItem.Operations[i].Selected)
					{
						ProfileTempVars.SelectedOperations.Add(activeProfile.FirstItem.Operations[i]);
					}
				}
			}
			if ((buProfileCalc.varProfileRunSettings.activeProfileIndex == 1) & (activeProfile.SecondItem != null))
			{
				for (int j = 0; j <= activeProfile.SecondItem.Operations.Count - 1; j++)
				{
					if (activeProfile.SecondItem.Operations[j].Selected)
					{
						ProfileTempVars.SelectedOperations.Add(activeProfile.SecondItem.Operations[j]);
					}
				}
			}
			ProfileTempVars.MultiSelectedProps.AllSamePlane = false;
			ProfileTempVars.MultiSelectedProps.AllSameShape = false;
			ProfileTempVars.MultiSelectedProps.AllSameSize = false;
			if (ProfileTempVars.SelectedOperations.Count < 2)
			{
				return;
			}
			ProfileTempVars.MultiSelectedProps.AllSamePlane = true;
			ProfileTempVars.MultiSelectedProps.AllSameShape = true;
			for (int k = 0; k <= ProfileTempVars.SelectedOperations.Count - 1; k++)
			{
				for (int l = k + 1; l <= ProfileTempVars.SelectedOperations.Count - 1; l++)
				{
					if (ProfileTempVars.SelectedOperations[k].OperationData.selectedPlaneName != ProfileTempVars.SelectedOperations[l].OperationData.selectedPlaneName)
					{
						ProfileTempVars.MultiSelectedProps.AllSamePlane = false;
					}
					if (ProfileTempVars.SelectedOperations[k].OperationData.OperationType != ProfileTempVars.SelectedOperations[l].OperationData.OperationType)
					{
						ProfileTempVars.MultiSelectedProps.AllSameShape = false;
					}
				}
			}
			if (!ProfileTempVars.MultiSelectedProps.AllSameShape)
			{
				return;
			}
			ProfileTempVars.MultiSelectedProps.AllSameSize = true;
			ProfileOperationTypes operationType = ProfileTempVars.SelectedOperations[0].OperationData.OperationType;
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			if (operationType != ProfileOperationTypes.Rectangle)
			{
				if (operationType != ProfileOperationTypes.Circle)
				{
					if (operationType != ProfileOperationTypes.Ellipse)
					{
						if (operationType != ProfileOperationTypes.Slot)
						{
							if (operationType != ProfileOperationTypes.Hole)
							{
								if (operationType != ProfileOperationTypes.Polygon)
								{
									if (operationType != ProfileOperationTypes.Barrel)
									{
										if (operationType != ProfileOperationTypes.Cut)
										{
											ProfileTempVars.MultiSelectedProps.AllSameSize = false;
										}
										else
										{
											num = ProfileTempVars.SelectedOperations[0].OperationData.CutData.CutWidth;
											num2 = ProfileTempVars.SelectedOperations[0].OperationData.CutData.CutHeigth;
										}
									}
									else
									{
										num = ProfileTempVars.SelectedOperations[0].OperationData.BarelData.BarrelLength;
										num2 = ProfileTempVars.SelectedOperations[0].OperationData.BarelData.BarrelWidth;
										num3 = ProfileTempVars.SelectedOperations[0].OperationData.BarelData.BarrelDiameter;
									}
								}
								else
								{
									num = ProfileTempVars.SelectedOperations[0].OperationData.PolygonData.PolygonDiameter;
								}
							}
							else
							{
								num = ProfileTempVars.SelectedOperations[0].OperationData.HoleData.HoleDiameter;
							}
						}
						else
						{
							num = ProfileTempVars.SelectedOperations[0].OperationData.SlotData.SlotWidth;
							num2 = ProfileTempVars.SelectedOperations[0].OperationData.SlotData.SlotDiameter;
						}
					}
					else
					{
						num = ProfileTempVars.SelectedOperations[0].OperationData.EllipseData.EllipseWidth;
						num2 = ProfileTempVars.SelectedOperations[0].OperationData.EllipseData.EllipseHeight;
					}
				}
				else
				{
					num = ProfileTempVars.SelectedOperations[0].OperationData.CircleData.CircleDiameter;
				}
			}
			else
			{
				num = ProfileTempVars.SelectedOperations[0].OperationData.RectangleData.RectangleWidth;
				num2 = ProfileTempVars.SelectedOperations[0].OperationData.RectangleData.RectangleHeight;
			}
			for (int m = 1; m <= ProfileTempVars.SelectedOperations.Count - 1; m++)
			{
				switch (operationType)
				{
				default:
					ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					break;
				case ProfileOperationTypes.Rectangle:
					if ((num != ProfileTempVars.SelectedOperations[m].OperationData.RectangleData.RectangleWidth) | (num2 != ProfileTempVars.SelectedOperations[m].OperationData.RectangleData.RectangleHeight))
					{
						ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					}
					break;
				case ProfileOperationTypes.Circle:
					if (num != ProfileTempVars.SelectedOperations[m].OperationData.CircleData.CircleDiameter)
					{
						ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					}
					break;
				case ProfileOperationTypes.Ellipse:
					if ((num != ProfileTempVars.SelectedOperations[m].OperationData.EllipseData.EllipseWidth) | (num2 != ProfileTempVars.SelectedOperations[m].OperationData.EllipseData.EllipseHeight))
					{
						ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					}
					break;
				case ProfileOperationTypes.Slot:
					if ((num != ProfileTempVars.SelectedOperations[m].OperationData.SlotData.SlotWidth) | (num2 != ProfileTempVars.SelectedOperations[m].OperationData.SlotData.SlotDiameter))
					{
						ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					}
					break;
				case ProfileOperationTypes.Hole:
					if (num != ProfileTempVars.SelectedOperations[m].OperationData.HoleData.HoleDiameter)
					{
						ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					}
					break;
				case ProfileOperationTypes.Polygon:
					if (num != ProfileTempVars.SelectedOperations[m].OperationData.PolygonData.PolygonDiameter)
					{
						ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					}
					break;
				case ProfileOperationTypes.Barrel:
					if ((num != ProfileTempVars.SelectedOperations[m].OperationData.BarelData.BarrelLength) | (num2 != ProfileTempVars.SelectedOperations[m].OperationData.BarelData.BarrelWidth) | (num3 != ProfileTempVars.SelectedOperations[m].OperationData.BarelData.BarrelDiameter))
					{
						ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					}
					break;
				case ProfileOperationTypes.Cut:
					if ((num != ProfileTempVars.SelectedOperations[m].OperationData.CutData.CutWidth) | (num2 != ProfileTempVars.SelectedOperations[m].OperationData.CutData.CutHeigth))
					{
						ProfileTempVars.MultiSelectedProps.AllSameSize = false;
					}
					break;
				}
			}
		}
		catch (Exception mSException)
		{
			buException.throwException(mSException, string_1, callMethod, ShowMessageBox: false, "");
		}
	}

	public void doDeletePlaneOperation(int ProfileIndex, planeNames PlaneName)
	{
		if (ProfileIndex < 0)
		{
			return;
		}
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		bUndoBuffer = true;
		for (int num = profileItem.Operations.Count - 1; num >= 0; num--)
		{
			if (profileItem.Operations[num].OperationData.selectedPlaneName == PlaneName)
			{
				profileItem.Operations.RemoveAt(num);
			}
		}
		DrawActiveProfile();
		ResetAllCalculationFlags();
		ProfileTreeUpdate();
		DrawPreview(new List<Entity>());
	}

	public void doDeleteOperation(int ProfileIndex, string OperationName)
	{
		if (!((ProfileIndex >= 0) & (OperationName.Length > 0)))
		{
			return;
		}
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		bUndoBuffer = true;
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			CustomData entityCustomData = clsInit.cVector5.GetEntityCustomData(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]);
			if (entityCustomData.typeDefination != entityTypeDefination.ProfileOperation)
			{
				if (entityCustomData.ActionName == OperationName)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				}
			}
			else if (entityCustomData.ActionName == OperationName)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
		{
			for (int num = profileItem.Operations.Count - 1; num >= 0; num--)
			{
				if (profileItem.Operations[num].Name == OperationName)
				{
					profileItem.Operations.RemoveAt(num);
				}
			}
		}
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
		{
			for (int num2 = activeProfile.SecondItem.Operations.Count - 1; num2 >= 0; num2--)
			{
				if (activeProfile.SecondItem.Operations[num2].Name == OperationName)
				{
					activeProfile.SecondItem.Operations.RemoveAt(num2);
				}
			}
		}
		ResetAllCalculationFlags();
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
		ProfileTreeUpdate();
		DrawPreview(new List<Entity>());
	}

	public void doDeleteAllOperations(int ProfileIndex)
	{
		if (ProfileIndex < 0)
		{
			return;
		}
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		bUndoBuffer = true;
		profileItem.Operations.Clear();
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			if ((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData != null) & (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData is CustomData))
			{
				CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
				if (customData.EntityName == profileItem.ItemName && ((customData.typeDefination == entityTypeDefination.ProfileSeperator) | (customData.typeDefination == entityTypeDefination.ProfileOperation)))
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Selected = true;
				}
			}
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.DeleteSelected();
		profileItem.Operations.Clear();
		if (profileItem.auxEntities != null)
		{
			profileItem.auxEntities.Clear();
		}
		DrawActiveProfile();
		ResetAllCalculationFlags();
		ProfileTreeUpdate();
		DrawPreview(new List<Entity>());
	}

	public void doDeleteSelecredOperations(int ProfileIndex)
	{
		if (ProfileIndex < 0)
		{
			return;
		}
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		bUndoBuffer = true;
		if (profileItem == null)
		{
			return;
		}
		if (!buProfileCalc.varProfileRunSettings.SelectMode || clsInit.cProfile.GetSelectedOperationCount(profileItem) != 0)
