	public void doEditOperation(int ProfileIndex, string OperationName, ToolBase5 Tool = null)
	{
		buProfileCalc.varProfileRunSettings.IncrementalMode = false;
		if (activeProfile != null && ProfileIndex >= 0)
		{
			if (buProfileCalc.varProfileSettings.MultipleEdit)
			{
				doAddSelectedOperations();
			}
			if (ProfileIndex == 0)
			{
				doEditOperation(ref activeProfile.FirstItem, OperationName, Tool);
			}
			if (ProfileIndex == 1)
			{
				doEditOperation(ref activeProfile.SecondItem, OperationName, Tool);
			}
		}
	}

	public void doEditOperation(ref buEyeBaseVer5.Apps.ProfileItem Item, string OperationName, ToolBase5 Tool = null)
	{
		if (Item.Operations.Count <= 0)
		{
			return;
		}
		bUndoBuffer = true;
		for (int i = 0; i <= Item.Operations.Count - 1; i++)
		{
			if (!(Item.Operations[i].Name == OperationName))
			{
				continue;
			}
			buProfileCalc.varProfileRunSettings.OPData = new buEyeBaseVer5.Apps.ProfileOperationData(Item.Operations[i].OperationData);
			clsInit.cProfile.OperationDataToShapeRunTime(buProfileCalc.varProfileRunSettings.OPData, ref buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			operationEditIndex = i;
			ToolChangeForced = Item.Operations[i].Locked;
			ProfileTempVars.OperationEditing = true;
			if (Tool != null)
			{
				Item.Operations[i].Tool = new ToolBase5(Tool);
			}
			ProfileTempVars.OperationDepths.Clear();
			ProfileTempVars.DepthForced = false;
			if (buProfileCalc.varProfileRunSettings.OPData.DepthForced)
			{
				DepthPositions.Copy(buProfileCalc.varProfileRunSettings.OPData.DepthValues, ref ProfileTempVars.OperationDepths);
				ProfileTempVars.DepthForced = true;
			}
			if (Item.Operations[i].Tool != null && ((Item.Operations[i].Tool.CamData.SpindleSpeed < buProfileCalc.varProfileSettings.MinSpindleSpeed) | (Item.Operations[i].Tool.CamData.FeedSpeed <= 0.0) | (Item.Operations[i].Tool.CamData.PlungeSpeed <= 0.0)))
			{
				ToolBase5 foundTool = null;
				clsInit.cVector5.FindToolWithToolName(ccVars.Tools, Item.Operations[i].Tool.Data.Name, ref foundTool);
				if (foundTool != null)
				{
					Item.Operations[i].Tool = foundTool;
				}
			}
			ccVars.toolActive = new ToolBase5(Item.Operations[i].Tool);
			clsInit.cProfile.OperationDataToShapeRunTime(buProfileCalc.varProfileRunSettings.OPData, ref buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			OPPriority = Item.Operations[i].Priority;
			if (buProfileCalc.varProfileRunSettings.OPData.Action == actionTypeBU.profileNotch)
			{
				cmdOperation(Item.Operations[i].OperationData.Action, NewOperation: false, Item.Operations[i].OperationData.NotchData.NotchOPType);
			}
			else
			{
				cmdOperation(Item.Operations[i].OperationData.Action);
			}
		}
	}

	public void doEnableDisableOperation(int indexOP, bool Status)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem != null && !((indexOP == -1) | (profileItem.Operations.Count == 0)))
		{
			bUndoBuffer = true;
			profileItem.Operations[indexOP].Enable = Status;
			TreeNodeSettings treeNodeSettings = clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP] as TreeNodeSettings;
			if (!profileItem.Operations[indexOP].Enable)
			{
				clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP].ImageIndex = 26;
				clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP].SelectedImageIndex = 26;
			}
			else
			{
				clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP].ImageIndex = treeNodeSettings.OldImageIndex;
				clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[indexOP].SelectedImageIndex = treeNodeSettings.OldImageIndex;
			}
			profileItem.IsClamperDone = false;
		}
	}

	public void doAddExternalEntities(List<buEntity> refEntities, bool Template, bool FileOpen)
	{
		if (refEntities.Count == 0)
		{
			return;
		}
		shapeCreateParameters_0.entitiesCurveList = new List<EntitiesList>();
		List<buEntity> SortedEntities = new List<buEntity>();
		List<List<buEntity>> SplitedEntitites = new List<List<buEntity>>();
		SortbuSettings settings = new SortbuSettings();
		clsInit.cVector5.SortEntitiesByRefPoint(refEntities[0].StartPoint, ref refEntities, settings, ref SortedEntities);
		clsInit.cVector5.EntitiesSplitByUpperLine(SortedEntities, ref SplitedEntitites);
		Point3D MinPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		clsInit.cVector5.BoxSizeCalculate(refEntities, ref MinPoint, ref MaxPoint);
		Point3D point3D = null;
		Point3D point3D2 = null;
		if (buProfileCalc.varProfileSettings.DontAddLineFromExternalFile)
		{
			for (int i = 0; i <= SplitedEntitites.Count - 1; i++)
			{
				if (clsInit.cVector5.isEntitiesClosed(SplitedEntitites[i]))
				{
					continue;
				}
				for (int num = SplitedEntitites[i].Count - 1; num >= 0; num--)
				{
					if (!(SplitedEntitites[i][num].GetType() == typeof(buLine)))
					{
						if (SplitedEntitites[i][num].GetType() == typeof(buLinearPath))
						{
							buLinearPath buLinearPath2 = SplitedEntitites[i][num] as buLinearPath;
							if (((buLinearPath2.Vertices.Count == 2) & buCompare5.EQ(buLinearPath2.Vertices[0].X, buLinearPath2.Vertices[buLinearPath2.Vertices.Count - 1].X)) && (buCompare5.EQ(buLinearPath2.Vertices[0].X, MinPoint.X) | buCompare5.EQ(buLinearPath2.Vertices[0].X, MaxPoint.X)))
							{
								SplitedEntitites[i].RemoveAt(num);
							}
						}
					}
					else
					{
						buLine buLine2 = SplitedEntitites[i][num] as buLine;
						if (buCompare5.EQ(buLine2.StartPoint.X, buLine2.EndPoint.X) && (buCompare5.EQ(buLine2.StartPoint.X, MinPoint.X) | buCompare5.EQ(buLine2.StartPoint.X, MaxPoint.X)))
						{
							if (buCompare5.EQ(buLine2.StartPoint.X, MinPoint.X))
							{
								point3D = new Point3D(MinPoint.X, 0.0, 0.0);
							}
							if (buCompare5.EQ(buLine2.StartPoint.X, MaxPoint.X))
							{
								point3D2 = new Point3D(MaxPoint.X, 0.0, 0.0);
							}
							SplitedEntitites[i].RemoveAt(num);
						}
					}
				}
			}
		}
		if (!FileOpen)
		{
			clsInit.appEditor.SaveEditorFile();
		}
		clsInit.cVector5.BoxSizeCalculate(SplitedEntitites, ref MinPoint, ref MaxPoint);
		if (point3D != null && point3D2 != null)
		{
			ProfileTempVars.PatternDxfOperation = true;
			ProfileTempVars.PntPatternDxf.X = MinPoint.X;
			ProfileTempVars.PntPatternDxf.Y = MinPoint.Y;
		}
		buProfileCalc.varProfileRunSettings.ShapeDataParameters.FreeDrawWidth = MaxPoint.X - MinPoint.X;
		buProfileCalc.varProfileRunSettings.ShapeDataParameters.FreeDrawHeight = MaxPoint.Y - MinPoint.Y;
		new List<buEntity>();
		if (SplitedEntitites.Count <= 0)
		{
			return;
		}
		for (int j = 0; j <= SplitedEntitites.Count - 1; j++)
		{
			EntitiesList entitiesList = new EntitiesList();
			if (SplitedEntitites[j].Count <= 1)
			{
				if (SplitedEntitites[j].Count > 0 && buCompare5.EQ(SplitedEntitites[j][0].StartPoint, SplitedEntitites[j][0].EndPoint))
				{
					entitiesList.Entities.Add(SplitedEntitites[j][0]);
				}
			}
			else
			{
				List<Point3D> Points = new List<Point3D>();
				clsInit.cVector5.EntitiesToPointsWithCamDirection(SplitedEntitites[j], 0.01, ref Points);
				buLinearPath buLinearPath3 = new buLinearPath(Points);
				if (buCompare5.EQ(buLinearPath3.StartPoint, buLinearPath3.EndPoint))
				{
					entitiesList.Entities.Add(buLinearPath3);
				}
			}
			if (entitiesList.Entities.Count > 0)
			{
				shapeCreateParameters_0.entitiesCurveList.Add(entitiesList);
			}
		}
		if (shapeCreateParameters_0.entitiesCurveList.Count > 0 && !FileOpen)
		{
			cmdShapes(actionTypeBU.profileFreeDraw);
		}
	}

	public void doOperationCheckWarnings(ref buEyeBaseVer5.Apps.ProfileOperation OP)
	{
		bool isToolLenShort = false;
		bool isToolCutLenShort = false;
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		OP.Error = false;
		OP.errorList.Clear();
		OP.warningList.Clear();
		OP.infoList.Clear();
		if (FrmNotchList != null && OP.Action == actionTypeBU.profileNotch)
		{
			FrmNotchList.dgv_list.Rows.Clear();
			FrmNotchList.dgv_list.Visible = false;
		}
		if (FrmOperationList != null && OP.Action != actionTypeBU.profileNotch)
		{
			FrmOperationList.dgv_list.Rows.Clear();
			FrmOperationList.dgv_list.Visible = false;
		}
		if (OP.Action != actionTypeBU.profileNotch)
		{
			clsInit.cProfile.CheckToolLength(OP, OP.Tool, buProfileCalc.varProfileSettings.ToolHolderLength, ref isToolLenShort, ref isToolCutLenShort);
		}
		else
		{
			clsInit.cProfile.CheckToolLength(OP, OP.ToolNotch, buProfileCalc.varProfileSettings.ToolHolderLength, ref isToolLenShort, ref isToolCutLenShort);
		}
		if (isToolLenShort)
		{
			clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(AppLanguage.CadCamMessages[102]), ref OP);
		}
		if (isToolCutLenShort)
		{
			if (OP.OperationData.OperationType != ProfileOperationTypes.Notch)
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(AppLanguage.CadCamMessages[103]), ref OP);
			}
			else
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.ToolDiameterLowerThanNotchDepth), ref OP);
			}
		}
		if (OP.Action != actionTypeBU.profileNotch)
		{
			if ((OP.OperationData.selectedPlaneName == planeNames.Top) | (OP.OperationData.selectedPlaneName == planeNames.Bottom))
			{
				double num = OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth;
				if (num > profileItem.ProfileMaxPoint.Z - profileItem.ProfileMinPoint.Z + buProfileCalc.varProfileSettings.ProfileSizeExceedDepthLimit)
				{
					clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.TotalDepthisHigherthenProfileSize), ref OP);
				}
			}
			if ((OP.OperationData.selectedPlaneName == planeNames.Front) | (OP.OperationData.selectedPlaneName == planeNames.Back))
			{
				double num2 = OP.OperationData.ExternalDepth + OP.OperationData.ExtraDepth;
				if (num2 > profileItem.ProfileMaxPoint.Y - profileItem.ProfileMinPoint.Y + buProfileCalc.varProfileSettings.ProfileSizeExceedDepthLimit)
				{
					clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.TotalDepthisHigherthenProfileSize), ref OP);
				}
			}
			if (OP.MaxPoint.X > profileItem.Length + buProfileCalc.varProfileSettings.ProfileEndAllowedPositiveDistance)
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.OperationPositionOutoffromProfileSize + " - X: " + OP.MaxPoint.X.ToString("f2") + " > " + profileItem.Length), ref OP);
			}
			if (OP.MinPoint.X > profileItem.Length + buProfileCalc.varProfileSettings.ProfileEndAllowedPositiveDistance)
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.OperationPositionOutoffromProfileSize + " - X: " + OP.MinPoint.X.ToString("f2") + " > " + profileItem.Length), ref OP);
			}
			if (OP.MaxPoint.X < buProfileCalc.varProfileSettings.ProfileStartAllowedNegativeDistance)
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.OperationPositionOutoffromProfileSize + " - X: " + OP.MaxPoint.X.ToString("f2") + " < " + profileItem.Length), ref OP);
			}
			if (OP.MinPoint.X < buProfileCalc.varProfileSettings.ProfileStartAllowedNegativeDistance)
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.OperationPositionOutoffromProfileSize + " - X: " + OP.MinPoint.X.ToString("f2") + " < " + profileItem.Length), ref OP);
			}
			if (OP.OperationData.ExternalDepth <= 0.0)
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.DepthCantbeZero), ref OP);
			}
		}
		if (OP.Action == actionTypeBU.profileTapping && OP.Tool != null && OP.Tool.Purpose != ToolPurpose.Tapping)
		{
			clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.ToolMustBeTapping), ref OP);
		}
		if (OP.Action == actionTypeBU.profileTapping && OP.Tool != null && !buCompare5.EQ(OP.Tool.Data.TappingInfo, OP.OperationData.HoleData.TappingPitch))
		{
			clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.TappingPitchNotSuitable), ref OP);
		}
		if (((OP.Action == actionTypeBU.profileHole) & buProfileCalc.varProfileSettings.UseDrillToolForDrill) && OP.Tool != null && ((OP.Tool.Purpose != ToolPurpose.Drilling) & (OP.Tool.Purpose != ToolPurpose.Hole)))
		{
			clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.ToolMustBeDrill), ref OP);
		}
		if (OP.Action == actionTypeBU.profileHole && !buProfileCalc.varProfileSettings.alarmIfToolDiaDifferentThenHoleDia)
		{
			if (OP.Tool != null && buCompare5.GT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole)OP).Diameter))
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterGreaterForThisOperation), ref OP);
			}
			if (OP.Tool != null && buCompare5.LT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole)OP).Diameter))
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterLowerForThisOperation), ref OP);
			}
		}
		if (OP.Action == actionTypeBU.profileTapping)
		{
			if (OP.ToolAux != null && buCompare5.GT(OP.ToolAux.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole)OP).Diameter))
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterGreaterForThisOperation), ref OP);
			}
			if (OP.ToolAux != null && buCompare5.LT(OP.ToolAux.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole)OP).Diameter))
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterLowerForThisOperation), ref OP);
			}
			if (OP.Tool != null && buCompare5.GT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole)OP).OperationData.HoleData.TappingDiameter))
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterGreaterForThisOperation), ref OP);
			}
			if (OP.Tool != null && buCompare5.LT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole)OP).OperationData.HoleData.TappingDiameter))
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentences.ToolDiameterLowerForThisOperation), ref OP);
			}
		}
		if (OP.Action == actionTypeBU.profileCircle && OP.OperationData.CircleData.CircleDiameter < OP.Tool.Geometry.Diameter)
		{
			clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.OperationDiamterLowerThenToolDiameter), ref OP);
		}
		if (OP.Action == actionTypeBU.profileRectangle && ((OP.OperationData.RectangleData.RectangleRadius > 0.0) & (OP.OperationData.RectangleData.RectangleRadius < OP.Tool.Geometry.Diameter / 2.0)))
		{
			clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.ToolRadiusIsHigherOperationRadius), ref OP);
		}
		if (OP.Action == actionTypeBU.profileNotch)
		{
			if (OP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Length && OP.OperationData.NotchData.NotchWidth < OP.ToolNotch.Geometry.Diameter + 4.0)
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.NotchWidthTooSmall), ref OP);
			}
			if (OP.OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal && profileItem.ProfileMaxPoint.Z + profileItem.SupportBlock.SupportBlockZHeight < buProfileCalc.varProfileClamperSettings.ClamperMaxHeight)
			{
				clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.ProfileHeightIsLowerThenFixtureForThisOperation), ref OP);
			}
		}
		if (OP.Tool != null)
		{
			if (OP.OperationData.selectedPlaneName == planeNames.Back)
			{
				if ((profileItem.SupportBlock.SupportBlockY2BackWidth > 0.0) & (profileItem.SupportBlock.SupportBlockY2BackWidth > OP.Tool.Geometry.Length - Math.Abs(OP.OperationData.Depth.Depth)))
				{
					clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preDef.Back + " " + buLangTranslate.preSentencesProfile.SupportBlockWidthTooHigh), ref OP);
				}
				if ((profileItem.SupportBlock.SupportBlockY2BackHeight > 0.0) & (OP.MinPoint.Z < profileItem.SupportBlock.SupportBlockY2BackHeight))
				{
					clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preDef.Back + " " + buLangTranslate.preSentencesProfile.SupportBlockWidthTooHigh), ref OP);
				}
			}
			if (OP.OperationData.selectedPlaneName == planeNames.Front)
			{
				if ((profileItem.SupportBlock.SupportBlockY1FrontWidth > 0.0) & (profileItem.SupportBlock.SupportBlockY1FrontWidth > OP.Tool.Geometry.Length - Math.Abs(OP.OperationData.Depth.Depth)))
				{
					clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preDef.Front + " " + buLangTranslate.preSentencesProfile.SupportBlockWidthTooHigh), ref OP);
				}
				if ((profileItem.SupportBlock.SupportBlockY1FrontHeight > 0.0) & (OP.MinPoint.Z < profileItem.SupportBlock.SupportBlockY1FrontHeight))
				{
					clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preDef.Front + " " + buLangTranslate.preSentencesProfile.SupportBlockWidthTooHigh), ref OP);
				}
			}
		}
		if (OP.OperationData.EachLayer & (OP.OperationData.DepthValues.Count == 0) & (OP.OperationData.selectedPlaneName != planeNames.Free))
		{
			clsInit.cProfile.AddWarningToOperation(ShowWarningOPMessage(buLangTranslate.preSentencesProfile.NoCalculatedDepths), ref OP);
		}
		List<string> Messages = new List<string>();
		if (!clsInit.cProfile.isToolSuitableForOperation(OP, ref Messages))
		{
			if (Messages.Count == 0)
			{
				clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentencesProfile.ToolisnotSuitableforthisOperation), ref OP);
			}
			for (int i = 0; i <= Messages.Count - 1; i++)
			{
				clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(Messages[i]), ref OP);
			}
		}
		if (OP.Action == actionTypeBU.profileHole && buProfileCalc.varProfileSettings.alarmIfToolDiaDifferentThenHoleDia)
		{
			if (OP.Tool != null && buCompare5.GT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole)OP).Diameter))
			{
				clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentences.ToolDiameterGreaterForThisOperation), ref OP);
			}
			if (OP.Tool != null && buCompare5.LT(OP.Tool.Geometry.Diameter, ((buEyeBaseVer5.Apps.ProfileOperationHole)OP).Diameter))
			{
				clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentences.ToolDiameterLowerForThisOperation), ref OP);
			}
		}
		if (OP.EntityMultiCam.Count == 0)
		{
			clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentencesProfile.NoToolPathAvailableCheckYourToolDataorParameters), ref OP);
		}
		if ((ccVars.CharLibList.Count == 0) & (OP.Action == actionTypeBU.profileWireText))
		{
			clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentences.NoWireframeLibraryCharsAvailable), ref OP);
		}
		if (OP.Tool != null && OP.Tool.CamData.SpindleSpeed <= 0.0)
		{
			clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentences.SpindleSpeedIsZero), ref OP);
		}
		if (OP.Tool != null && ((OP.Tool.CamData.SpindleSpeed > 0.0) & (OP.Tool.CamData.SpindleSpeed <= buProfileCalc.varProfileSettings.MinSpindleSpeed)))
		{
			clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentences.SpindleSpeedLowerThenMinLimit), ref OP);
		}
		if (((OP.OperationData.OperationType == ProfileOperationTypes.Notch) & buProfileCalc.varProfileSettings.NotchVerticalForbiddenAtSide) && OPData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
		{
			if ((profileItem.XReferanceLocation == LeftRightType.Left) & (OPData.NotchData.NotchLocation == ProfileNotchLocationType.Left))
			{
				clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentencesProfile.YouCantAddThisNotchOperationThisSide), ref OP);
				return;
			}
			if ((profileItem.XReferanceLocation == LeftRightType.Right) & (OPData.NotchData.NotchLocation == ProfileNotchLocationType.Right))
			{
				clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentencesProfile.YouCantAddThisNotchOperationThisSide), ref OP);
				return;
			}
		}
		if (OP.OperationData.selectedPlaneName == planeNames.Free)
		{
			double num3 = clsInit.cVector5.PointAngle(new Point3D(OP.OperationData.selectedPlane.Equation.X, OP.OperationData.selectedPlane.Equation.Y, OP.OperationData.selectedPlane.Equation.Z), new Point3D(), Plane.YZ);
			if (num3 < 0.0 || num3 > 180.0)
			{
				clsInit.cProfile.AddErrorToOperation(ShowErrorOPMessage(buLangTranslate.preSentencesProfile.ThisPlaneIsNotSuitable), ref OP);
			}
		}
		if (OP.Action == actionTypeBU.profileNotch && ((OP.warningList.Count > 0) | (OP.infoList.Count > 0) | (OP.errorList.Count > 0)))
		{
			FrmNotchList.dgv_list.Visible = true;
		}
		if (OP.Action != actionTypeBU.profileNotch && ((OP.warningList.Count > 0) | (OP.infoList.Count > 0) | (OP.errorList.Count > 0)))
		{
			FrmOperationList.dgv_list.Visible = true;
		}
	}

	public void doGetBottomOperations(buEyeBaseVer5.Apps.ProfileItem refItem, ref List<ProfileItemCalc> devidedItems)
	{
		devidedItems.Clear();
		devidedItems = new List<ProfileItemCalc>();
		ProfileItemCalc profileItemCalc = new ProfileItemCalc(refItem, CopyOperations: true);
		profileItemCalc.CalcType = ProfileExcType.Normal;
		for (int num = profileItemCalc.calcOperations.Count - 1; num >= 0; num--)
		{
			if (profileItemCalc.calcOperations[num].OperationData.selectedPlaneName == planeNames.Bottom)
			{
				profileItemCalc.calcOperations.RemoveAt(num);
			}
		}
		devidedItems.Add(profileItemCalc);
		ProfileItemCalc profileItemCalc2 = new ProfileItemCalc(refItem, CopyOperations: true);
		profileItemCalc2.CalcType = ProfileExcType.NormalBottom;
		for (int num2 = profileItemCalc2.calcOperations.Count - 1; num2 >= 0; num2--)
		{
			if ((profileItemCalc2.calcOperations[num2].OperationData.selectedPlaneName == planeNames.Top) | (profileItemCalc2.calcOperations[num2].OperationData.selectedPlaneName == planeNames.Front) | (profileItemCalc2.calcOperations[num2].OperationData.selectedPlaneName == planeNames.Back) | (profileItemCalc2.calcOperations[num2].OperationData.selectedPlaneName == planeNames.Free))
			{
				profileItemCalc2.calcOperations.RemoveAt(num2);
			}
		}
		devidedItems.Add(profileItemCalc2);
	}

	public void doSetPriority()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		if (!buProfileCalc.varProfileRunSettings.SelectMode || clsInit.cProfile.GetSelectedOperationCount(profileItem) != 0)
		{
			if (!((buProfileCalc.varProfileRunSettings.activeOPIndex >= 0) & (buProfileCalc.varProfileRunSettings.activeOPIndex <= profileItem.Operations.Count - 1)))
			{
				return;
			}
			F_ProfilePriority f_ProfilePriority = new F_ProfilePriority();
			f_ProfilePriority.Priority = profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].Priority;
			f_ProfilePriority.Init();
			f_ProfilePriority.ShowDialog();
			if (f_ProfilePriority.Properties.Result != DialogResult.OK)
			{
				return;
			}
			bUndoBuffer = true;
			if (buProfileCalc.varProfileRunSettings.SelectMode)
			{
				for (int num = profileItem.Operations.Count - 1; num >= 0; num--)
				{
					if (profileItem.Operations[num].Selected)
					{
						profileItem.Operations[num].Priority = f_ProfilePriority.Priority;
					}
				}
			}
			else
			{
				profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].Priority = f_ProfilePriority.Priority;
			}
			ProfileTreeUpdate();
		}
		else
		{
			buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.SelectionModeActiveNoOperationSelected);
		}
	}

	public void doSetActiveProfileOP(int ProfileIndex, int OperationIndex)
	{
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
		selectedEntities.Clear();
		buProfileCalc.varProfileRunSettings.activeOPIndex = OperationIndex;
		if (ProfileIndex == 0 && OperationIndex >= 0 && activeProfile.FirstItem != null && OperationIndex <= activeProfile.FirstItem.Operations.Count - 1)
		{
			doSetActiveProfileOP(activeProfile.FirstItem, OperationIndex);
		}
		if (ProfileIndex == 1 && OperationIndex >= 0 && activeProfile.SecondItem != null && OperationIndex <= activeProfile.SecondItem.Operations.Count - 1)
		{
			doSetActiveProfileOP(activeProfile.SecondItem, OperationIndex);
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
	}

	public void doSetActiveProfileOP(buEyeBaseVer5.Apps.ProfileItem Item, int OperationIndex)
	{
		if (ccVars.Action == actionTypeBU.None)
		{
			buProfileCalc.varProfileRunSettings.activeOPIndex = OperationIndex;
		}
		buProfileCalc.varProfileRunSettings.activeOPName = Item.Operations[OperationIndex].Name;
		activeOP = new buEyeBaseVer5.Apps.ProfileOperation();
		buEyeBaseVer5.Apps.ProfileOperation.Copy(Item.Operations[OperationIndex], ref activeOP);
		for (int i = 0; i <= ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count - 1; i++)
		{
			CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].EntityData as CustomData;
			if (customData.typeDefination == entityTypeDefination.ProfileOperation)
			{
				ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].ColorMethod = colorMethodType.byLayer;
				if (!clsInit.cProfile.isOperationEnableFromName(Item, customData.ActionName))
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].ColorMethod = colorMethodType.byEntity;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Color = buProfileCalc.varProfileVisualSettings.OperationDisableColor;
				}
				if (customData.ActionName == activeOP.Name)
				{
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].ColorMethod = colorMethodType.byEntity;
					ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i].Color = buProfileCalc.varProfileVisualSettings.OperationSelectedColor;
					selectedEntities.Add(buVector5.CopyEntities(ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[i]));
				}
			}
		}
	}

	public void doOperationFromFile()
	{
		OpenFileDialog openFileDialog = new OpenFileDialog();
		openFileDialog.InitialDirectory = buProfileCalc.varProfileRunSettings.pathSaveProfiles;
		openFileDialog.Filter = "Profile Files (*.buprofile)|*.buprofile";
		openFileDialog.FilterIndex = 1;
		if (openFileDialog.ShowDialog() == DialogResult.OK)
		{
			buProfileCalc.varProfileRunSettings.pathSaveProfiles = buFile5.GetPath(openFileDialog.FileName);
			new buEyeBaseVer5.Apps.ProfileItem();
			ArrayList StringList = new ArrayList();
			buFile5.OpenFromFile(openFileDialog.FileName, ref StringList);
			List<string> CalcList = new List<string>();
			List<string> CalcList2 = new List<string>();
			buStatics.ListToSpecificList("<FirstItem>", "</FirstItem>", AddStartEndKey: true, StringList, ref CalcList);
			buStatics.ListToSpecificList("<SecondItem>", "</SecondItem>", AddStartEndKey: true, StringList, ref CalcList2);
			if ((buProfileCalc.varProfileRunSettings.activeProfileIndex == 0) & (activeProfile.FirstItem != null))
			{
				doOperationFromFile(CalcList, CalcList2, LeftRightType.Left, ref activeProfile.FirstItem);
			}
			if ((buProfileCalc.varProfileRunSettings.activeProfileIndex == 1) & (activeProfile.SecondItem != null))
			{
				doOperationFromFile(CalcList, CalcList2, LeftRightType.Right, ref activeProfile.SecondItem);
			}
			clsInit.appCommand.cmdViewZoomFit();
		}
	}

	public void doOperationFromFile(List<string> SLFirst, List<string> SLSecond, LeftRightType LeftRight, ref buEyeBaseVer5.Apps.ProfileItem Item)
	{
		if (SLFirst.Count <= 0)
		{
			if (SLSecond.Count <= 0)
			{
				return;
			}
			for (int i = 0; i <= SLSecond.Count - 1; i++)
			{
				if (SLFirst[i].IndexOf("XReferanceLocation") >= 0)
				{
					SLFirst[i] = SLFirst[i].Replace("Right", "Left");
					i = SLFirst.Count;
				}
			}
			buFile5.SaveToFile(SLSecond, AppPath.Base + "\\temp.job");
			Item.XReferanceLocation = LeftRight;
			bool jobOpenClearAllProfiles = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
			buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
			OpenProfileJobFile(AppPath.Base + "\\temp.job", AddOperations: true, CreateProfile: true, OnlyDrawing: false, ref Item, AddRecent: false);
			buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = jobOpenClearAllProfiles;
			ProfileTreeUpdate();
		}
		else
		{
			buFile5.SaveToFile(SLFirst, AppPath.Base + "\\temp.job");
			Item.XReferanceLocation = LeftRight;
			bool jobOpenClearAllProfiles2 = buProfileCalc.varProfileSettings.JobOpenClearAllProfiles;
			buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = false;
			OpenProfileJobFile(AppPath.Base + "\\temp.job", AddOperations: true, CreateProfile: true, OnlyDrawing: false, ref Item, AddRecent: false);
			buProfileCalc.varProfileSettings.JobOpenClearAllProfiles = jobOpenClearAllProfiles2;
			ProfileTreeUpdate();
		}
	}

	public void doGCodeToSimulation(ref buEyeBaseVer5.Apps.ProfileItem Item)
	{
		if (Item == null)
		{
			return;
		}
		Item.isGCodeSimMoveCreated = false;
		ArrayList GCodes = new ArrayList();
		clsInit.appProfile.doCreateCode(Item, ccVars.PostActive.Mode, ref GCodes, 0, SecondAvailable: false);
		GCodeToSimulationConversionSettings gCodeToSimulationConversionSettings = new GCodeToSimulationConversionSettings();
		gCodeToSimulationConversionSettings.AddMCodes = true;
		gCodeToSimulationConversionSettings.ClamperCount = Item.MaxClamperNumber;
		gCodeToSimulationConversionSettings.G53Positions.Z = buProfileCalc.varProfileSettings.ParkPositionZ;
		gCodeToSimulationConversionSettings.StartPositions = new Pnt6D(buProfileCalc.varProfileSettings.ParkPositionX, buProfileCalc.varProfileSettings.ParkPositionY, buProfileCalc.varProfileSettings.ParkPositionZ, 0.0, 0.0, 0.0);
		gCodeToSimulationConversionSettings.UseStartPosition = true;
		if (Item.XReferanceLocation == LeftRightType.Left && buProfileCalc.varProfileSettings.ChangeG2G3DirForLeftRefProfile)
		{
			gCodeToSimulationConversionSettings.ReverseG2 = true;
			gCodeToSimulationConversionSettings.ReverseG3 = true;
		}
		if (Item.XReferanceLocation == LeftRightType.Right)
		{
			gCodeToSimulationConversionSettings.StartPositions = new Pnt6D(0.0 - (buProfileCalc.varProfileSettings.MachineLength - buProfileCalc.varProfileSettings.ParkPositionX), buProfileCalc.varProfileSettings.ParkPositionY, buProfileCalc.varProfileSettings.ParkPositionZ, 0.0, 0.0, 0.0);
			if (buProfileCalc.varProfileSettings.ChangeG2G3DirForRightRefProfile)
			{
				gCodeToSimulationConversionSettings.ReverseG2 = true;
				gCodeToSimulationConversionSettings.ReverseG3 = true;
			}
			gCodeToSimulationConversionSettings.CommandList = new List<string>();
			gCodeToSimulationConversionSettings.CommandList.Add("RightProfile");
		}
		buString5.ListToSpecificList("<GCodes>", "</GCodes>", AddStartEndKey: false, GCodes, ref Item.GCodeList);
		if ((Item.GCodeList.Count == 0) & (GCodes.Count > 0))
		{
			for (int i = 0; i <= GCodes.Count - 1; i++)
			{
				Item.GCodeList.Add(GCodes[i].ToString());
			}
		}
		List<Pnt6DSimMove> list = new List<Pnt6DSimMove>();
		if (ccVars.PostActive.Mode == "YilmazMode1")
		{
			method_0(ref Item, gCodeToSimulationConversionSettings, ref lastSimTool);
		}
		if (ccVars.PostActive.Mode == "KabanMode1")
		{
			gCodeToSimulationConversionSettings.CommentChar = "(";
			GCodeToSimulationKabanMode1(ref Item, gCodeToSimulationConversionSettings, ref lastSimTool);
		}
		if (ccVars.PostActive.Mode == "KabanMode2")
		{
			gCodeToSimulationConversionSettings.CommentChar = "(";
			GCodeToSimulationKabanMode2(ref Item, gCodeToSimulationConversionSettings, ref lastSimTool);
		}
		if (ccVars.PostActive.Mode == "InfiniteMode1")
		{
			gCodeToSimulationConversionSettings.CommentChar = "(";
			GCodeToSimulationInfiniteMode1(ref Item, gCodeToSimulationConversionSettings, ref lastSimTool);
		}
		if (Item.XReferanceLocation == LeftRightType.Right && activeProfile.FirstItem != null && activeProfile.FirstItem.Enable)
		{
			List<ProfileItemCalc> calculationData = activeProfile.FirstItem.CalculationData;
			if (calculationData.Count > 0 && calculationData[calculationData.Count - 1].SimMoves.Count > 0)
			{
				Pnt6DSimMove pnt6DSimMove = new Pnt6DSimMove(calculationData[calculationData.Count - 1].SimMoves[calculationData[calculationData.Count - 1].SimMoves.Count - 1]);
				pnt6DSimMove.X -= buProfileCalc.varProfileSettings.MachineLength - Item.Length;
				list.Insert(0, pnt6DSimMove);
			}
		}
		Item.isGCodeSimMoveCreated = true;
	}

	public void doSimulationDevidedMoves(List<Pnt6DSimMove> tempSimMoves, int indexCalcData, ref buEyeBaseVer5.Apps.ProfileItem Item)
	{
		clsInit.cCam5.DevideSimPoints(ReverseCircular: false, ref tempSimMoves);
		list_4.Clear();
		if (!((Item.CalculationData.Count > 0 && indexCalcData >= 0) & (indexCalcData <= Item.CalculationData.Count - 1)))
		{
			return;
		}
		Item.CalculationData[indexCalcData].SimMoves.Clear();
		for (int i = 0; i <= tempSimMoves.Count - 1; i++)
		{
			bool flag = false;
			if (tempSimMoves[i].Clampers != null && ((tempSimMoves[i].Clampers.Count > 0) & (list_4.Count > 0)) && tempSimMoves[i].Clampers.Count == list_4.Count)
			{
				for (int j = 0; j <= tempSimMoves[i].Clampers.Count - 1; j++)
				{
					if (!buCompare5.EQ(tempSimMoves[i].Clampers[j], list_4[j].XPosition, 0.01))
					{
						flag = true;
					}
				}
			}
			if (flag)
			{
				double[,] array = new double[tempSimMoves[i].Clampers.Count, 10];
				for (int k = 0; k <= tempSimMoves[i].Clampers.Count - 1; k++)
				{
					List<double> Values = new List<double>();
					buNumeric5.DevideMinMaxValueByNumber(list_4[k].XPosition, tempSimMoves[i].Clampers[k], 10, ref Values);
					for (int l = 0; l <= Values.Count - 1; l++)
					{
						array[k, l] = Values[l];
					}
				}
				if (array.Length > 0)
				{
					for (int m = 0; m < 10; m++)
					{
						Pnt6DSimMove pnt6DSimMove = new Pnt6DSimMove(tempSimMoves[i - 1]);
						if (pnt6DSimMove.Clampers == null)
						{
							pnt6DSimMove.Clampers = new List<double>();
						}
						else
						{
							pnt6DSimMove.Clampers.Clear();
						}
						new List<buEyeBaseVer5.Apps.ProfileClamper>();
						for (int n = 0; n <= tempSimMoves[i].Clampers.Count - 1; n++)
						{
							pnt6DSimMove.Clampers.Add(array[n, m]);
						}
						if (pnt6DSimMove.Clampers.Count > 0)
						{
							Item.CalculationData[indexCalcData].SimMoves.Add(pnt6DSimMove);
						}
					}
				}
			}
			if (tempSimMoves[i].Clampers != null && tempSimMoves[i].Clampers.Count > 0)
			{
				list_4 = new List<buEyeBaseVer5.Apps.ProfileClamper>();
				for (int num = 0; num <= tempSimMoves[i].Clampers.Count - 1; num++)
				{
					list_4.Add(new buEyeBaseVer5.Apps.ProfileClamper(tempSimMoves[i].Clampers[num]));
				}
			}
			Item.CalculationData[indexCalcData].SimMoves.Add(new Pnt6DSimMove(tempSimMoves[i]));
		}
	}

	public void doWireframeContour(MWCalculationOptions MWCalcoptions, camParameters5 OPCamParameter, ToolBase5 Tool, ref camTp Cam)
	{
		if (Cam == null)
		{
			Cam = new camTp();
		}
		MWCalcoptions.ShowProgressForm = buProfileCalc.varTemps.ShowProgressCam;
		OPCamParameter.Distances.EntryAndExit = OPCamParameter.Distances.Rapid;
		buMWProfileVars.varCamContour.mwPar = buMWCalcs.ConvertFromBuCamParToMwCamPar(buMWProfileVars.varCamContour.mwPar, OPCamParameter);
		buMWProfileVars.varCamContour.mwPar.MachParam.LinkParams.FirstEntry.LeadController.IsUsed = OPCamParameter.LeadIn.Enable;
		buMWProfileVars.varCamContour.mwPar.MachParam.LinkParams.FirstEntry.LeadController.LeadParams.ArcDiaOverToolDia = 40.0;
		buMWProfileVars.varCamContour.mwPar.MachParam.LinkParams.LastExit.LeadController.IsUsed = OPCamParameter.LeadOut.Enable;
		buMWProfileVars.varCamContour.mwPar.MachParam.LinkParams.LastExit.LeadController.LeadParams.ArcDiaOverToolDia = 40.0;
		buMWProfileVars.varCamContour.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.EndHeight = 0.0;
		buMWProfileVars.varCamContour.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.StartHeight = 0.0;
		buMWProfileVars.varCamContour.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
		buMWProfileVars.varCamContour.buPar = new camParameters5(OPCamParameter);
		buMWProfileVars.varCamContour.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.SharedMiscParams.OverlapLength = OPCamParameter.Operations.Overlap;
		buMWProfileVars.varCamContour.mwPar.MachParam.CutTolerance = buProfileCalc.varProfileSettings.CutQuality;
		clsMW.varMWCamWFContourPars = buMWCalcs.CopyCamParameter(buMWProfileVars.varCamContour.mwPar, buMWProfileVars.varCamContour.buPar, out clsMW.varbuCamWFContourPars);
		camResult Result = null;
		int num = 0;
		if (MWCalcoptions.AllowIntercetionCurve)
		{
			List<Entity> copiedEnt = new List<Entity>();
			buVector5.CopyEntities(clsMW.CamEntities, ref copiedEnt);
			num = 1;
			for (int i = 0; i <= copiedEnt.Count - 1; i++)
			{
				clsMW.CamEntities.Clear();
				Entity copiedEntity = null;
				buEntity.Copy(copiedEnt[i], ref copiedEntity);
				clsMW.CamEntities.Add(copiedEntity);
				camTp Cam2 = new camTp();
				int num2 = clsInit.appMW.doWireframeContour(MWCalcoptions, Tool, ref Cam2, ref Result);
				if (i != 0)
				{
					for (int j = 0; j <= Cam2.CamPoints.Count - 1; j++)
					{
						Cam.CamPoints.Add(Cam2.CamPoints[j]);
					}
					for (int k = 0; k <= Cam2.EntitiesG0.Count - 1; k++)
					{
						Entity copiedEntity2 = null;
						buEntity.Copy(Cam2.EntitiesG0[k], ref copiedEntity2);
						Cam.EntitiesG0.Add(copiedEntity2);
					}
					for (int l = 0; l <= Cam2.EntitiesG1.Count - 1; l++)
					{
						Entity copiedEntity3 = null;
						buEntity.Copy(Cam2.EntitiesG1[l], ref copiedEntity3);
						Cam.EntitiesG1.Add(copiedEntity3);
					}
					for (int m = 0; m <= Cam2.EntitiesLeadIn.Count - 1; m++)
					{
						Entity copiedEntity4 = null;
						buEntity.Copy(Cam2.EntitiesLeadIn[m], ref copiedEntity4);
						Cam.EntitiesLeadIn.Add(copiedEntity4);
					}
					for (int n = 0; n <= Cam2.EntitiesLeadOut.Count - 1; n++)
					{
						Entity copiedEntity5 = null;
						buEntity.Copy(Cam2.EntitiesLeadOut[n], ref copiedEntity5);
						Cam.EntitiesLeadOut.Add(copiedEntity5);
					}
					for (int num3 = 0; num3 <= Cam2.EntitiesPlunge.Count - 1; num3++)
					{
						Entity copiedEntity6 = null;
						buEntity.Copy(Cam2.EntitiesPlunge[num3], ref copiedEntity6);
						Cam.EntitiesPlunge.Add(copiedEntity6);
					}
					for (int num4 = 0; num4 <= Cam2.EntitiesLeave.Count - 1; num4++)
					{
						Entity copiedEntity7 = null;
						buEntity.Copy(Cam2.EntitiesLeave[num4], ref copiedEntity7);
						Cam.EntitiesLeave.Add(copiedEntity7);
					}
					for (int num5 = 0; num5 <= Cam2.EntitiesOther.Count - 1; num5++)
					{
						Entity copiedEntity8 = null;
						buEntity.Copy(Cam2.EntitiesOther[num5], ref copiedEntity8);
						Cam.EntitiesOther.Add(copiedEntity8);
					}
					for (int num6 = 0; num6 <= Cam2.EntitiesMark.Count - 1; num6++)
					{
						Entity copiedEntity9 = null;
						buEntity.Copy(Cam2.EntitiesMark[num6], ref copiedEntity9);
						Cam.EntitiesMark.Add(copiedEntity9);
					}
				}
				else
				{
					Cam = new camTp(Cam2);
				}
				if (num2 < 1)
				{
					num = -1;
				}
			}
		}
		else
		{
			num = clsInit.appMW.doWireframeContour(MWCalcoptions, Tool, ref Cam, ref Result);
		}
		buMWProfileVars.varCamContour.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamWFContourPars, clsMW.varbuCamWFContourPars, out buMWProfileVars.varCamContour.buPar);
		if (num < 1)
		{
			buString5.MessageBoxError(AppLanguage.CadCamMessages[93]);
			if (!MWCalcoptions.DontApplyReset)
			{
				clsInit.appCommand.Reset();
			}
		}
	}

	public void doWireframeRough(MWCalculationOptions MWCalcoptions, camParameters5 OPCamParameter, ToolBase5 Tool, ref camTp Cam)
	{
		if (Cam == null)
		{
			Cam = new camTp();
		}
		MWCalcoptions.ShowProgressForm = buProfileCalc.varTemps.ShowProgressCam;
		OPCamParameter.Distances.EntryAndExit = OPCamParameter.Distances.Rapid;
		buMWProfileVars.varCamRough.buPar = new camParameters5(OPCamParameter);
		buMWProfileVars.varCamRough.mwPar.MachParam.CutTolerance = buProfileCalc.varProfileSettings.CutQuality;
		if (OPCamParameter.Operations.AreaClearanceDirection != InToOutType.OutToIn)
		{
			buMWProfileVars.varCamRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.ReverseCuttingOrderFlg = true;
		}
		else
		{
			buMWProfileVars.varCamRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.ReverseCuttingOrderFlg = false;
		}
		buMWProfileVars.varCamRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.RoughType = (WireframeBasedTpCalcParamsRoughType)Convert.ToInt32(OPCamParameter.Pockets.PocketType);
		buMWProfileVars.varCamRough.mwPar.MachParam.CutTolerance = buProfileCalc.varProfileSettings.CutQuality;
		buMWProfileVars.varCamRough.mwPar.MachParam.LinkParams.AirMoveSafetyDistance = 0.0;
		if (OPCamParameter.Operations.Direction != ClockDirectionType.CCW)
		{
			buMWProfileVars.varCamRough.mwPar.MachParam.MachDirForOneWay = MachiningParamsDirection.DirConventional;
		}
		else
		{
			buMWProfileVars.varCamRough.mwPar.MachParam.MachDirForOneWay = MachiningParamsDirection.DirClimb;
		}
		buMWProfileVars.varCamRough.mwPar = buMWCalcs.ConvertFromBuCamParToMwCamPar(buMWProfileVars.varCamRough.mwPar, OPCamParameter);
		buMWProfileVars.varCamRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.EndHeight = 0.0;
		buMWProfileVars.varCamRough.mwPar.MachParam.TpCalculationMethodsParams.WireframeBasedTpCalcParams.MachiningAreaHeightsParams.StartHeight = 0.0;
		buMWProfileVars.varCamRough.mwPar.MachParam.MaxStepoverDistance = Math.Round(OPCamParameter.Pockets.StepOverPersentage / 100.0 * Tool.Geometry.Diameter, 3);
		buMWProfileVars.varCamRough.mwPar.MachParam.TpCalculationMethodsParams.TriangleMeshBasedTpCalcParams.RemoveCornerPegsFlg = true;
		clsMW.varMWCamWFPocketPars = buMWCalcs.CopyCamParameter(buMWProfileVars.varCamRough.mwPar, buMWProfileVars.varCamRough.buPar, out clsMW.varbuCamWFPocketPars);
		camResult Result = null;
		int num = clsInit.appMW.doWireframeContour(MWCalcoptions, Tool, ref Cam, ref Result);
		buMWProfileVars.varCamRough.mwPar = buMWCalcs.CopyCamParameter(clsMW.varMWCamWFPocketPars, clsMW.varbuCamWFPocketPars, out buMWProfileVars.varCamRough.buPar);
		if (num < 1)
		{
			buString5.MessageBoxError(AppLanguage.CadCamMessages[93]);
			clsInit.appCommand.Reset();
		}
	}

