	public void doJobListDelete(int Index)
	{
		if (((Index >= 0) & (Index <= Jobs.Count - 1)) && buString5.MessageBoxQuestion(buProfile.LangProfileMessage[19]) == DialogResult.Yes)
		{
			Jobs.RemoveAt(Index);
			frmERPList.lst_items.Items.RemoveAt(Index);
			Index--;
