	public void doJobListOpen(string Filename)
	{
		ArrayList StringList = new ArrayList();
		buFile5.OpenFromFile(Filename, ref StringList);
		buSystem.Cancel = false;
		if (StringList.Count <= 0)
		{
			return;
		}
		buProfileCalc.varProfileRunSettings.pathJobList = frmERPList.pathString;
		SaveByTick = true;
		buEyeBaseVer5.Apps.ProfileItem firstItem = null;
		buEyeBaseVer5.Apps.ProfileItem secondItem = null;
		if (activeProfile.FirstItem != null)
		{
			firstItem = new buEyeBaseVer5.Apps.ProfileItem(activeProfile.FirstItem);
		}
		if (activeProfile.SecondItem != null)
		{
			secondItem = new buEyeBaseVer5.Apps.ProfileItem(activeProfile.SecondItem);
		}
		frmERPList.Visible = false;
		buProfileCalc.varTemps.ShowProgressCam = false;
		if (clsItem.FrmProgress == null)
		{
			calculationEventArg_0 = new CalculationEventArg();
			clsItem.FrmProgress = new F_ProgressCalculation();
		}
		clsItem.FrmProgress.TopMost = true;
		clsItem.FrmProgress.Show();
		clsItem.FrmMain.Show();
		clsItem.FrmMain.Focus();
		Jobs.Clear();
		List<List<string>> CalcList = new List<List<string>>();
		buStatics.ListToSpecificList("<JobList>", "</JobList>", AddStartEndKey: false, StringList, ref CalcList);
		for (int i = 0; i <= CalcList.Count - 1; i++)
		{
			if (!buSystem.Cancel)
			{
				calculationEventArg_0.OverallProgressPercentage = Convert.ToDouble(i + 1) / Convert.ToDouble(CalcList.Count) * 100.0;
				clsInit.appCommand.CalculationInProgressCmd(calculationEventArg_0);
				ArrayList arrayList = new ArrayList();
				arrayList.AddRange(CalcList[i]);
				buEyeBaseVer5.Apps.ProfileItem Item = new buEyeBaseVer5.Apps.ProfileItem();
				buEyeBaseVer5.Apps.ProfileItem.Decode(arrayList, ref Item);
				OpenProfileJobFile("", AddOperations: true, CreateProfile: true, OnlyDrawing: false, ref Item, AddRecent: false, ShowProgress: false);
				Jobs.Add(Item);
				continue;
			}
			clsItem.FrmProgress.Visible = false;
			buSystem.Cancel = false;
			return;
		}
		activeProfile.FirstItem = firstItem;
		activeProfile.SecondItem = secondItem;
		DrawActiveProfile();
		DrawPreview(new List<Entity>());
		ProfileTreeUpdate();
		clsItem.FrmProgress.Visible = false;
		buProfileCalc.varTemps.ShowProgressCam = true;
		calculationEventArg_0 = new CalculationEventArg();
		frmERPList.Visible = true;
		cmdJobList();
	}

	public void doCreateProfile(ref buEyeBaseVer5.Apps.ProfileItem Profile, bool isNewProfile)
	{
		if (Profile == null)
		{
			return;
		}
		if (!buProfileCalc.varProfileSettings.RightProfileActive)
		{
			activeProfile.SecondItem = null;
		}
		Point3D MinPoint = new Point3D();
		Point3D MidPoint = new Point3D();
		Point3D MaxPoint = new Point3D();
		ProfileOffsetCalculation(ref Profile.ProfileOffset, Profile);
		clsInit.cProfile.BoxSizeProfile(Profile, ref MinPoint, ref MidPoint, ref MaxPoint);
		clsInit.cProfile.CreateProfileFromDrawing(ref Profile, Plane.YZ, Profile.ProfileOffset, isNewProfile, buProfileCalc.varProfileSettings, buProfileCalc.varProfileVisualSettings, buProfileCalc.varProfileSettings.ProfileDrawingRefThickness, buProfileCalc.varProfileSettings.MinProfileFilterLength);
		if (Profile.Drawings.Count != 0 && Profile.Drawings[0].SolidEntity != null)
		{
			Profile.TotalOffset.Z = Profile.SupportBlock.SupportBlockZHeight;
			Profile.TotalOffset.Y = 0.0 - Profile.SupportBlock.SupportBlockY2BackWidth;
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Clear();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.RegenAllCurved();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Regen();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			MinPoint = new Point3D();
			MidPoint = new Point3D();
			MaxPoint = new Point3D();
			clsInit.cProfile.BoxSizeProfile(Profile, ref MinPoint, ref MidPoint, ref MaxPoint);
			Profile.ProfileCenterPoint = buVector5.ToPoint3D(MidPoint);
			Profile.ProfileMinPoint = buVector5.ToPoint3D(MinPoint);
			Profile.ProfileMaxPoint = buVector5.ToPoint3D(MaxPoint);
			Profile.ProfileMaxPoint.X = Profile.Length;
			if (Profile.ItemName.Trim().Length == 0)
			{
				Profile.ItemName = "ProfileItem" + counterProfile;
				counterProfile++;
			}
			for (int i = 0; i <= Profile.Drawings.Count - 1; i++)
			{
				Entity copiedEntity = null;
				buEntity.Copy(Profile.Drawings[i].SolidEntity, ref copiedEntity);
				CreateProfileEntity(ref copiedEntity, Profile.TextureName, Profile.ItemName, Profile.Enable, Profile.colorProfile);
			}
			if ((Profile.LeftAngleEntity != null) & buProfileCalc.varProfileSettings.ShowProfileAngleDrawing)
			{
				CreateProfileEntity(ref Profile.LeftAngleEntity, Profile.TextureName, Profile.ItemName, Profile.Enable, Profile.colorProfile);
			}
			if ((Profile.RightAngleEntity != null) & buProfileCalc.varProfileSettings.ShowProfileAngleDrawing)
			{
				CreateProfileEntity(ref Profile.RightAngleEntity, Profile.TextureName, Profile.ItemName, Profile.Enable, Profile.colorProfile);
			}
			if (Profile.ProfileReferanceEntity != null)
			{
				CreateProfileEntity(ref Profile.ProfileReferanceEntity, Profile.TextureName, Profile.ItemName, Profile.Enable, Profile.colorProfile);
			}
			if (Profile.XReferanceLocation == LeftRightType.Left)
			{
				activeProfile.FirstItem = new buEyeBaseVer5.Apps.ProfileItem(Profile);
				buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
				activeItem = activeProfile.FirstItem;
			}
			if (Profile.XReferanceLocation == LeftRightType.Right)
			{
				activeProfile.SecondItem = new buEyeBaseVer5.Apps.ProfileItem(Profile);
				buProfileCalc.varProfileRunSettings.activeProfileIndex = 1;
				activeItem = activeProfile.SecondItem;
			}
			bUndoBuffer = true;
			ProfileTreeUpdate();
			ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Invalidate();
			if (buProfileCalc.varProfileRunSettings.activeProfileIndex == -1)
			{
				buProfileCalc.varProfileRunSettings.activeProfileIndex = 0;
			}
		}
	}

	public void doSetActiveProfile(int ItemIndex)
	{
		if (ccVars.Pages.Count == 0 || (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.Count > 0 && ItemIndex == buProfileCalc.varProfileRunSettings.activeProfileIndex && clsItem.ModelMainPreview.Entities.Count > 0))
		{
			return;
		}
		ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities.ClearSelection();
		selectedEntities.Clear();
		if (!(ItemIndex >= 0 && ItemIndex <= 1))
		{
			return;
		}
		buProfileCalc.varProfileRunSettings.activeProfileIndex = ItemIndex;
		DrawActiveProfile();
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 0)
		{
			activeItem = activeProfile.FirstItem;
			DrawPreview(activeProfile.FirstItem, new List<Entity>());
			if (activeProfile.FirstItem != null)
			{
				for (int i = 0; i <= activeProfile.FirstItem.Drawings.Count - 1; i++)
				{
					selectedEntities.Add(buVector5.CopyEntities(activeProfile.FirstItem.Drawings[i].SolidEntity));
				}
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailWidth = activeProfile.FirstItem.Length;
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailHeight = activeProfile.FirstItem.Width;
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailDepth = activeProfile.FirstItem.Height;
			}
			clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[0].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
		}
		if (buProfileCalc.varProfileRunSettings.activeProfileIndex == 1)
		{
			if (activeProfile.SecondItem != null)
			{
				activeItem = activeProfile.SecondItem;
				DrawPreview(activeProfile.SecondItem, new List<Entity>());
				for (int j = 0; j <= activeProfile.SecondItem.Drawings.Count - 1; j++)
				{
					selectedEntities.Add(buVector5.CopyEntities(activeProfile.SecondItem.Drawings[j].SolidEntity));
				}
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailWidth = activeProfile.SecondItem.Length;
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailHeight = activeProfile.SecondItem.Width;
				buProfileCalc.varProfileRunSettings.ShapeDataParameters.SizeMaterailDepth = activeProfile.SecondItem.Height;
			}
			clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[1].ForeColor = buProfileCalc.varProfileVisualSettings.TreeItemSelectedColor;
		}
		clsItem.ModelMainPreview.ZoomFit();
		clsItem.ModelMainPreview.Invalidate();
		activeOP = null;
	}

