	public void doEditProfile(buEyeBaseVer5.Apps.ProfileItem Item)
	{
		bUndoBuffer = true;
		List<buEyeBaseVer5.Apps.ProfileOperation> CopiedOperation = new List<buEyeBaseVer5.Apps.ProfileOperation>();
		buEyeBaseVer5.Apps.ProfileOperation.Copy(Item.Operations, ref CopiedOperation);
		bool boxProfile = false;
		if (Item.ProfileType != ProfileNewType.Drawing)
		{
			boxProfile = true;
		}
		if (!cmdAddProfile(Item, boxProfile))
		{
			return;
		}
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		for (int i = 0; i <= CopiedOperation.Count - 1; i++)
		{
			ToolChangeForced = true;
			clsInit.cProfile.ProfileCamDataToCamParameter(CopiedOperation[i].CamOPData, ref CopiedOperation[i].OperationData.CamParMilling);
			buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane)CopiedOperation[i].OperationData.selectedPlane.Clone();
			ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg();
			shapeUpdateArg.Finished = true;
			shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			shapeUpdateArg.ToolName = CopiedOperation[i].Tool.Data.Name;
			shapeUpdateArg.ToolChangeForced = true;
			shapeUpdateArg.Parameters.Priority = CopiedOperation[i].Priority;
			shapeUpdateArg.Tool = new ToolBase5(CopiedOperation[i].Tool);
			OPPriority = CopiedOperation[i].Priority;
			SizeObject size = new SizeObject(profileItem.Length, profileItem.Width, profileItem.Height);
			buShape Item2 = new buShape();
			Item2.BasePoint = new Point3D(CopiedOperation[i].OperationData.basePosition.X, Math.Abs(CopiedOperation[i].OperationData.basePosition.Y), CopiedOperation[i].OperationData.basePosition.Z);
			if (buCompare5.EQ(Item2.BasePoint.X, 0.0) & buCompare5.EQ(Item2.BasePoint.Y, 0.0) & buCompare5.EQ(Item2.BasePoint.Y, 0.0))
			{
				Item2.BasePoint.X = CopiedOperation[i].OperationData.Position.X;
				Item2.BasePoint.Y = CopiedOperation[i].OperationData.Position.Y;
				Item2.BasePoint.Z = CopiedOperation[i].OperationData.Position.Z;
				Item2.Corner = CornerLocation.LeftTop;
			}
			clsInit.cVector5.CoordinateFromPlaneAndCorner(size, CopiedOperation[i].OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(CopiedOperation[i].OperationData.selectedPlaneName), ref Item2, ref CopiedOperation[i].OperationData.Position, shapeCreateParameters_0.SingX, shapeCreateParameters_0.SingY);
			buShape Item3 = new buShape();
			Item3.BasePoint = new Point3D(CopiedOperation[i].OperationData.basePosition.X, CopiedOperation[i].OperationData.basePosition.Y, CopiedOperation[i].OperationData.basePosition.Z);
			clsInit.cVector5.CoordinateFromPlaneAndCorner(size, CopiedOperation[i].OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(CopiedOperation[i].OperationData.selectedPlaneName), ref Item3, ref CopiedOperation[i].OperationData.Position, shapeCreateParameters_0.SingX, shapeCreateParameters_0.SingY);
			OnlineOperation(null, shapeUpdateArg, CopiedOperation[i].OperationData);
		}
		RearrangeOperationID();
		ProfileTreeUpdate();
		ToolChangeForced = false;
	}

