	public void doGetProfileAndOperationFrom3D(List<Entity> EL)
	{
		new List<Circle>();
		new clsDrill();
		if (EL.Count <= 0)
		{
			return;
		}
		bool flag = false;
		bool flag2 = false;
		if (!(EL[0] is Brep))
		{
			if (EL[0] is ICurve)
			{
				flag = true;
			}
		}
		else
		{
			flag2 = true;
		}
		if (!flag2)
		{
			if (!flag)
			{
				buString5.MessageBoxWarning(buDrillCalc.LangDrillMessage[38]);
			}
		}
		else
		{
			if (!(EL[0] is Brep))
			{
				return;
			}
			Brep brep = EL[0] as Brep;
			brep.Regen(0.01);
			brep.Translate(0.0 - brep.BoxMin.X, 0.0 - brep.BoxMin.Y, 0.0 - brep.BoxMin.Z);
			brep.Regen(0.01);
			double num = 1.0;
			if ((brep.BoxMax.Z > 0.0) & (brep.BoxMax.Z < 1.0))
			{
				double num2 = 10.0 / brep.BoxMax.Z;
				if (num2 > 1.0 && num2 <= 10.0)
				{
					num = 10.0;
				}
				if (num2 > 10.0 && num2 <= 100.0)
				{
					num = 100.0;
				}
				if (num2 > 100.0 && num2 <= 1000.0)
				{
					num = 1000.0;
				}
			}
			if (num > 1.0)
			{
				brep.Scale(num);
				brep.Regen(0.01);
			}
			for (int i = 0; i <= brep.Faces.Length - 1; i++)
			{
