	public void doDevideProfileItemByLength(buEyeBaseVer5.Apps.ProfileItem refItem, double DevideLength, ref List<ProfileItemCalc> devidedItems)
	{
		ProfileItemCalc profileItemCalc = null;
		ProfileItemCalc profileItemCalc2 = null;
		ProfileItemCalc profileItemCalc3 = null;
		devidedItems.Clear();
		devidedItems = new List<ProfileItemCalc>();
		double num = DevideLength;
		if (!(DevideLength < refItem.Length))
		{
			return;
		}
		for (int i = 0; i <= refItem.Operations.Count - 1; i++)
		{
			if ((refItem.Operations[i].MinPoint.X < DevideLength) & (DevideLength < refItem.Operations[i].MaxPoint.X))
			{
				num = refItem.Operations[i].MinPoint.X - 50.0;
			}
		}
		profileItemCalc = new ProfileItemCalc(refItem);
		profileItemCalc.Length = DevideLength;
		profileItemCalc.SimMoves = new List<Pnt6DSimMove>();
		profileItemCalc.OriginalIsLongProfile = true;
		profileItemCalc3 = new ProfileItemCalc(refItem);
		profileItemCalc3.XReferanceLocation = LeftRightType.Right;
		profileItemCalc3.Length = refItem.Length - DevideLength;
		profileItemCalc3.SimMoves = new List<Pnt6DSimMove>();
		profileItemCalc3.OriginalIsLongProfile = true;
		for (int j = 0; j <= refItem.Operations.Count - 1; j++)
		{
			if ((refItem.Operations[j].MinPoint.X < num) & (refItem.Operations[j].MaxPoint.X < num))
			{
				GProfileOperation gProfileOperation = new GProfileOperation(refItem.Operations[j]);
				if (gProfileOperation.OperationData.selectedPlaneName == planeNames.Bottom)
				{
					if (profileItemCalc2 == null)
					{
						profileItemCalc2 = new ProfileItemCalc(refItem);
						profileItemCalc2.Length = num;
						profileItemCalc2.SimMoves = new List<Pnt6DSimMove>();
					}
					clsInit.cVector5.Rotate(new Point3D(0.0, (0.0 - refItem.Width) / 2.0, refItem.Height / 2.0), 180.0, Vector3D.AxisX, ref gProfileOperation.EntityMultiCam);
					profileItemCalc2.calcOperations.Add(gProfileOperation);
					profileItemCalc2.CalcType = ProfileExcType.NormalBottom;
				}
				else
				{
					profileItemCalc.calcOperations.Add(gProfileOperation);
				}
			}
			if (!((refItem.Operations[j].MinPoint.X > num) & (refItem.Operations[j].MaxPoint.X > num)))
			{
				continue;
			}
			GProfileOperation gProfileOperation2 = new GProfileOperation(refItem.Operations[j]);
			double num2 = 0.0;
			double num3 = 0.0;
			num3 = gProfileOperation2.SizePoint.MaxPoint.X - gProfileOperation2.OperationData.Position.X;
			num2 = gProfileOperation2.SizePoint.MinPoint.X - gProfileOperation2.OperationData.Position.X;
			gProfileOperation2.XReferanceLocation = LeftRightType.Right;
			if ((gProfileOperation2.OperationData.Corner == CornerLocation.LeftBottom) | (gProfileOperation2.OperationData.Corner == CornerLocation.LeftCenter) | (gProfileOperation2.OperationData.Corner == CornerLocation.LeftTop))
			{
				gProfileOperation2.OperationData.Corner = CornerLocation.LeftTop;
				gProfileOperation2.OperationData.Position.X = refItem.Length - gProfileOperation2.OperationData.Position.X;
				gProfileOperation2.OperationData.basePosition.X = refItem.Length - gProfileOperation2.OperationData.basePosition.X;
			}
			if (gProfileOperation2.OperationData.Corner == CornerLocation.RightTop)
			{
				gProfileOperation2.OperationData.Corner = CornerLocation.LeftTop;
				gProfileOperation2.OperationData.Position.X = gProfileOperation2.OperationData.basePosition.X;
			}
			if (gProfileOperation2.OperationData.Corner == CornerLocation.RightBottom)
			{
				gProfileOperation2.OperationData.Corner = CornerLocation.LeftBottom;
				gProfileOperation2.OperationData.Position.X = gProfileOperation2.OperationData.basePosition.X;
			}
			if (gProfileOperation2.OperationData.Corner == CornerLocation.RightTop)
			{
				gProfileOperation2.OperationData.Corner = CornerLocation.LeftTop;
				gProfileOperation2.OperationData.Position.X = gProfileOperation2.OperationData.basePosition.X;
			}
			clsInit.cVector5.Move(0.0 - DevideLength, 0.0, 0.0, ref gProfileOperation2.EntityMultiCam);
			gProfileOperation2.SizePoint.MinPoint.X = gProfileOperation2.OperationData.Position.X + num2;
			gProfileOperation2.SizePoint.MaxPoint.X = gProfileOperation2.OperationData.Position.X + num3;
			if (gProfileOperation2.OperationData.OperationType == ProfileOperationTypes.Notch)
			{
				for (int k = 0; k <= gProfileOperation2.CamCalculation.Count - 1; k++)
				{
					for (int l = 0; l <= gProfileOperation2.CamCalculation[k].CamPoints.Count - 1; l++)
					{
						for (int m = 0; m <= gProfileOperation2.CamCalculation[k].CamPoints[l].Points.Count - 1; m++)
						{
							TpPnt9D tpPnt9D = gProfileOperation2.CamCalculation[k].CamPoints[l].Points[m];
							tpPnt9D.P9.X = tpPnt9D.P9.X - DevideLength;
						}
					}
				}
			}
			profileItemCalc3.calcOperations.Add(gProfileOperation2);
		}
		if (profileItemCalc != null && profileItemCalc3 != null)
		{
			profileItemCalc3.CalcType = ProfileExcType.LongSecondPart;
			profileItemCalc3.XReferanceLocation = LeftRightType.Right;
			profileItemCalc3.LongProfileFirstPartLength = profileItemCalc.Length;
			devidedItems.Add(profileItemCalc);
			if (profileItemCalc2 != null)
			{
				devidedItems.Add(profileItemCalc2);
			}
			devidedItems.Add(profileItemCalc3);
		}
	}

	public void doDevideProfileItemByLength(buEyeBaseVer5.Apps.ProfileItem refItem, double DevideLength, ref buEyeBaseVer5.Apps.ProfileItem firstItem, ref buEyeBaseVer5.Apps.ProfileItem secondItem)
	{
		double num = DevideLength;
		if (!(DevideLength < refItem.Length))
		{
			return;
		}
		for (int i = 0; i <= refItem.Operations.Count - 1; i++)
		{
			if ((refItem.Operations[i].MinPoint.X < DevideLength) & (DevideLength < refItem.Operations[i].MaxPoint.X))
			{
				num = refItem.Operations[i].MinPoint.X - 50.0;
			}
		}
		firstItem = new buEyeBaseVer5.Apps.ProfileItem(refItem);
		firstItem.Operations.Clear();
		firstItem.Length = DevideLength;
		secondItem = new buEyeBaseVer5.Apps.ProfileItem(refItem);
		secondItem.Operations.Clear();
		secondItem.XReferanceLocation = LeftRightType.Right;
		secondItem.Length = refItem.Length - DevideLength;
		for (int j = 0; j <= refItem.Operations.Count - 1; j++)
		{
			if ((refItem.Operations[j].MinPoint.X < num) & (refItem.Operations[j].MaxPoint.X < num))
			{
				buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
				buEyeBaseVer5.Apps.ProfileOperation.Copy(refItem.Operations[j], ref CopiedOperation);
				firstItem.Operations.Add(CopiedOperation);
			}
			if ((refItem.Operations[j].MinPoint.X > num) & (refItem.Operations[j].MaxPoint.X > num))
			{
				buEyeBaseVer5.Apps.ProfileOperation CopiedOperation2 = new buEyeBaseVer5.Apps.ProfileOperation();
				buEyeBaseVer5.Apps.ProfileOperation.Copy(refItem.Operations[j], ref CopiedOperation2);
				double num2 = refItem.Length - DevideLength;
				clsInit.cVector5.Move(0.0 - DevideLength, 0.0, 0.0, ref CopiedOperation2.EntityMultiCam);
				double num3 = CopiedOperation2.OperationData.Position.X - num2;
				CopiedOperation2.OperationData.Position.X = num2;
				CopiedOperation2.MinPoint.X = CopiedOperation2.MinPoint.X - num3;
				CopiedOperation2.MaxPoint.X = CopiedOperation2.MaxPoint.X - num3;
				secondItem.Operations.Add(CopiedOperation2);
			}
		}
	}

	public void doAddSupportBlockOffsets(ref buEyeBaseVer5.Apps.ProfileItem Item)
	{
		for (int i = 0; i <= Item.CalculationData.Count - 1; i++)
		{
			for (int j = 0; j <= Item.CalculationData[i].calcOperations.Count - 1; j++)
			{
				for (int k = 0; k <= Item.CalculationData[i].calcOperations[j].CamCalculation.Count - 1; k++)
				{
					camTp camTp2 = Item.CalculationData[i].calcOperations[j].CamCalculation[k];
					for (int l = 0; l <= camTp2.CamPoints.Count - 1; l++)
					{
						for (int m = 0; m <= camTp2.CamPoints[l].Points.Count - 1; m++)
						{
							Pnt9D p = camTp2.CamPoints[l].Points[m].P9;
							p.Z += Item.SupportBlock.SupportBlockZHeight;
							if (p.Z > buProfileCalc.varProfileSettings.MaxZMove)
							{
								p.Z = buProfileCalc.varProfileSettings.MaxZMove;
							}
							p.Y -= Item.SupportBlock.SupportBlockY2BackWidth;
						}
					}
				}
			}
		}
	}

