	public void doCheckProfileWarnings(ref buEyeBaseVer5.Apps.ProfileItem Item)
	{
		if (Item != null)
		{
			Item.warningAllList.Clear();
		}
		clsInit.cProfile.AddOperationListsToProfileLists(ref Item);
		if (!Item.isCollisionControlDone)
		{
			clsInit.cProfile.AddWarningToProfile(buLangTranslate.preSentencesProfile.NoCollisionControlDone, ref Item);
		}
		if (!Item.isSimulationDone)
		{
			clsInit.cProfile.AddWarningToProfile(buLangTranslate.preSentencesProfile.NoSimulationDone, ref Item);
		}
		if (!Item.IsClamperDone)
		{
			clsInit.cProfile.AddWarningToProfile(buLangTranslate.preSentencesProfile.NoClamperCalculationDone, ref Item);
		}
	}

	public void doCheckProfileError()
	{
		if (activeProfile.FirstItem != null)
		{
			activeProfile.FirstItem.errorAllList.Clear();
		}
		if (activeProfile.SecondItem != null)
		{
			activeProfile.SecondItem.errorAllList.Clear();
		}
		bool flag = false;
		bool flag2 = false;
		if (activeProfile.FirstItem != null && activeProfile.FirstItem.Enable)
		{
			flag = true;
			if (activeProfile.FirstItem.isCollisionOnlineAvailable)
			{
				clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.OnlineCollisionDetected, ref activeProfile.FirstItem);
			}
			if (activeProfile.FirstItem.isCollisionOfflineAvailable)
			{
				clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.OfflineCollisionDetected, ref activeProfile.FirstItem);
			}
		}
		if (activeProfile.SecondItem != null && activeProfile.SecondItem.Enable)
		{
			flag2 = true;
			if (activeProfile.SecondItem.isCollisionOnlineAvailable)
			{
				clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.OnlineCollisionDetected, ref activeProfile.SecondItem);
			}
			if (activeProfile.SecondItem.isCollisionOfflineAvailable)
			{
				clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.OfflineCollisionDetected, ref activeProfile.SecondItem);
			}
		}
		if (!(flag && flag2))
		{
			if (!(flag && !flag2))
			{
				if (!flag && flag2 && activeProfile.SecondItem.Length > buProfileCalc.varProfileSettings.MachineLength * 2.0)
				{
					clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.ProfileLengthisBiggerThenLimit, ref activeProfile.SecondItem);
				}
			}
			else if (activeProfile.FirstItem.Length > buProfileCalc.varProfileSettings.MachineLength * 2.0)
			{
				clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.ProfileLengthisBiggerThenLimit, ref activeProfile.FirstItem);
			}
		}
		else if (activeProfile.FirstItem.Length + activeProfile.SecondItem.Length > buProfileCalc.varProfileSettings.MachineLength)
		{
			clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.BothProfileLengthCanNotBeBiggerThenMachineOperationLength, ref activeProfile.FirstItem);
			clsInit.cProfile.AddErrorToProfile(buLangTranslate.preSentencesProfile.BothProfileLengthCanNotBeBiggerThenMachineOperationLength, ref activeProfile.SecondItem);
		}
	}

