	public void doGeneralTick(int TickCount)
	{
		if (TickCount % 300 == 0 && SaveByTick)
		{
			SaveProfileFile();
			SaveByTick = false;
		}
		if ((1u & (buProfileCalc.varProfileSettings.AutoSave ? 1u : 0u)) == 0)
		{
			return;
		}
		DateTime dateTime = default(DateTime);
		if (!((DateTime.Now.Subtract(lastDate).TotalSeconds > (double)buProfileCalc.varProfileSettings.AutoSaveTimeSec) & (ccVars.Action == actionTypeBU.None)))
		{
			return;
		}
		if (cntAutoSave > buProfileCalc.varProfileSettings.AutoSaveMaxCount)
		{
			cntAutoSave = 1;
		}
		DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Base + "\\AutoSave");
		if (!directoryInfo.Exists)
		{
			directoryInfo.Create();
		}
		if (!((activeProfile.FirstItem != null) | (activeProfile.SecondItem != null)))
		{
			return;
		}
		int num = 0;
		if (activeProfile.FirstItem != null)
		{
			num += activeProfile.FirstItem.Operations.Count;
		}
		if (activeProfile.SecondItem != null)
		{
			num += activeProfile.SecondItem.Operations.Count;
		}
		if (num > 0)
		{
			string text = "";
			if (buProfileCalc.varProfileSettings.AutoSaveWithTimeFileName)
			{
				text = "_H" + DateTime.Now.Hour.ToString("D2") + "M" + DateTime.Now.Minute.ToString("D2") + "S" + DateTime.Now.Second.ToString("D2");
			}
			SaveProfileJobFile(directoryInfo.FullName + "\\AutoSave" + cntAutoSave + text + ".buprofile", AddRecent: false);
			cntAutoSave++;
		}
		lastDate = DateTime.Now;
	}

	public void ProgramClosing()
	{
		if (!buProfileCalc.varProfileSettings.SaveCurrentProfilesWhileProgramClosing)
		{
			return;
		}
		DirectoryInfo directoryInfo = new DirectoryInfo(AppPath.Base + "\\AutoSave");
		if (!directoryInfo.Exists)
		{
			directoryInfo.Create();
		}
		if ((activeProfile.FirstItem != null) | (activeProfile.SecondItem != null))
		{
			int num = 0;
			if (activeProfile.FirstItem != null)
			{
				num += activeProfile.FirstItem.Operations.Count;
			}
			if (activeProfile.SecondItem != null)
			{
				num += activeProfile.SecondItem.Operations.Count;
			}
			if (num > 0)
			{
				SaveProfileJobFile(AppPath.Base + "\\AutoSave\\LastJobOperations.buprofile", AddRecent: false);
			}
		}
	}

