	public void doFindPlane(Brep.Face face, bool RunOperation, bool AddList)
	{
		if (face == null)
		{
			return;
		}
		Surface[] array = face.ConvertToSurface();
		if (array != null && array.Length != 0 && array[0] is TabulatedSurface)
		{
			TabulatedSurface tabulatedSurface = array[0] as TabulatedSurface;
			if (tabulatedSurface.BoxMax == null)
			{
				tabulatedSurface.Regen(0.1);
			}
			double length = tabulatedSurface.BoxMax.X - tabulatedSurface.BoxMin.X;
			ICurve directrix = tabulatedSurface.Directrix;
			double height = Point3D.Distance(directrix.StartPoint, directrix.EndPoint);
			Point3D Val = new Point3D(0.0, directrix.StartPoint.Y, directrix.StartPoint.Z);
			Point3D Val2 = new Point3D(0.0, directrix.EndPoint.Y, directrix.EndPoint.Z);
			if (Val2.Z < Val.Z)
			{
				Val = new Point3D(0.0, directrix.EndPoint.Y, directrix.EndPoint.Z);
				Val2 = new Point3D(0.0, directrix.StartPoint.Y, directrix.StartPoint.Z);
			}
			double num = clsInit.cVector5.PointAngle(Val2, Val, Plane.YZ);
			double num2 = num;
			if (num > 90.0)
			{
				num2 = 90.0 - num;
				buEyeShotFunctions.ExchangeTwoVaues(ref Val, ref Val2);
			}
			Plane plane = new Plane(Val, Vector3D.AxisX, Vector3D.AxisY);
			plane.Rotate(buConversion5.DegreeToRadian(num2), Vector3D.AxisX, Val);
			SelectedPlaneInfo P = new SelectedPlaneInfo();
			clsInit.cVector5.PlaneCreate(ProfilePlaneDef.None, -1, Create: true, Val, num2, length, height, buProfileCalc.varProfileSettings.PlaneThickness, buProfileCalc.varUCSData, ref P);
			buProfileCalc.varProfileRunSettings.selectedFreePlaneLength = directrix.Length();
			if (AddList)
			{
				DialogBoxText dialogBoxText = new DialogBoxText();
				dialogBoxText.Caption = AppLanguage.CadCamDynamic[43] + " " + AppLanguage.CadCamDynamic[40];
				dialogBoxText.Text = AppLanguage.CadCamDynamic[43] + " " + AppLanguage.CadCamDynamic[40];
				dialogBoxText.Init("");
				dialogBoxText.ShowDialog();
				if (dialogBoxText.Result == DialogResult.OK)
				{
					P.Explanation = dialogBoxText.Value;
					if (selectedPlanes.Count != 0)
					{
						bool flag = false;
						for (int i = 0; i <= selectedPlanes.Count - 1; i++)
						{
							if (clsInit.cVector5.isPlanesSame(selectedPlanes[i].refPlane, plane))
							{
								flag = true;
							}
						}
						if (!flag)
						{
							AddPlane(P);
						}
						ccVars.selectedFace = null;
					}
					else
					{
						AddPlane(P);
						ccVars.selectedFace = null;
					}
				}
				if (RunOperation)
				{
					buProfileCalc.varProfileRunSettings.OPData.selectedPlaneName = planeNames.Free;
					buProfileCalc.varProfileRunSettings.OPData.selectedPlane = plane;
					buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = P;
					planeLastSelected = (Plane)plane.Clone();
					buProfileCalc.varProfileRunSettings.OPData.Position.Y = 0.0;
					cmdOperationMenu();
				}
			}
			else
			{
				if (RunOperation)
				{
					activeProfile.FirstItem.selectedFreePlanes.Clear();
				}
				if (activeProfile.FirstItem.selectedFreePlanes.Count != 0)
				{
					bool flag2 = false;
					for (int j = 0; j <= activeProfile.FirstItem.selectedFreePlanes.Count - 1; j++)
					{
						if (clsInit.cVector5.isPlanesSame(activeProfile.FirstItem.selectedFreePlanes[j].refPlane, plane))
						{
							flag2 = true;
						}
					}
					if (!flag2)
					{
						activeProfile.FirstItem.selectedFreePlanes.Add(P);
					}
					ccVars.selectedFace = null;
				}
				else
				{
					activeProfile.FirstItem.selectedFreePlanes.Add(P);
					ccVars.selectedFace = null;
				}
				if (RunOperation)
				{
					buProfileCalc.varProfileRunSettings.OPData.selectedPlaneName = planeNames.Free;
					buProfileCalc.varProfileRunSettings.OPData.selectedPlane = plane;
					buProfileCalc.varProfileRunSettings.OPData.selectedPlaneInfo = P;
					planeLastSelected = (Plane)plane.Clone();
					buProfileCalc.varProfileRunSettings.OPData.Position.Y = 0.0;
					cmdOperationMenu();
				}
			}
		}
		if (!RunOperation)
		{
			clsInit.appCommand.Reset();
		}
	}

	public void doUndoRedoGetBack(UndoV5 undo)
	{
