	public void doSelectedEntities(int[] EntityList)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null || !((EntityList != null) & (EntityList.Length != 0)))
		{
			return;
		}
		for (int i = 0; i <= EntityList.Length - 1; i++)
		{
			_ = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityList[i]];
			if (!((ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityList[i]].EntityData != null) & (ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityList[i]].EntityData is CustomData)))
			{
				continue;
			}
			CustomData customData = ccVars.Pages[ccVars.PageIndex].Form.viewportcad.Entities[EntityList[i]].EntityData as CustomData;
			if (customData.typeDefination != entityTypeDefination.ProfileOperation)
			{
				continue;
			}
			for (int j = 0; j <= profileItem.Operations.Count - 1; j++)
			{
				if (customData.ID == profileItem.Operations[j].ID)
				{
					clsItem.FrmProfileJob.tree_jobs.SelectedNode = null;
					clsItem.FrmProfileJob.tree_jobs.SelectedNode = clsItem.FrmProfileJob.tree_jobs.Nodes[0].Nodes[buProfileCalc.varProfileRunSettings.activeProfileIndex].Nodes[j];
					clsItem.FrmProfileJob.tree_jobs.Focus();
				}
			}
		}
	}

	public void doCopyClamperPositionToNextIfSame(buEyeBaseVer5.Apps.ProfileItem Profile, List<buEyeBaseVer5.Apps.ProfileClamper> OldClampersPos, List<buEyeBaseVer5.Apps.ProfileClamper> NewClampersPos, int indexOperation)
	{
		for (int i = indexOperation + 1; i <= Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations.Count - 1; i++)
		{
			bool flag = true;
			if (OldClampersPos.Count != Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[i].Clampers.Count)
			{
				flag = false;
			}
			for (int j = 0; j <= OldClampersPos.Count - 1; j++)
			{
				if (j <= Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[i].Clampers.Count - 1)
				{
					double value = Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[i].Clampers[j].XPosition + Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[i].Clampers[j].XOffset;
					double value2 = OldClampersPos[j].XPosition + OldClampersPos[j].XOffset;
					if (!buCompare5.EQ(value, value2))
					{
						flag = false;
					}
				}
			}
			if (flag)
			{
				for (int k = 0; k <= NewClampersPos.Count - 1; k++)
				{
					Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[i].Clampers[k].XPosition = NewClampersPos[k].XPosition;
					Profile.CalculationData[buProfileCalc.varProfileRunSettings.activeCalcDataIndex].calcOperations[i].Clampers[k].XOffset = NewClampersPos[k].XOffset;
				}
			}
		}
	}

	public void doPatternCopy()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null)
		{
			return;
		}
		bUndoBuffer = true;
		if (profileItem != null && ((buProfileCalc.varProfileRunSettings.PatternCopyCount > 0) & (buProfileCalc.varProfileRunSettings.PatternCopyDistance > 0.0)))
		{
			int count = profileItem.Operations.Count;
			double num = 0.0;
			double x = buProfileCalc.varProfileRunSettings.OPData.Position.X;
			for (int i = 1; i <= buProfileCalc.varProfileRunSettings.PatternCopyCount; i++)
			{
				for (int j = 0; j <= count - 1; j++)
				{
					UndoDontProfile = true;
					buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
					buEyeBaseVer5.Apps.ProfileOperation.Copy(profileItem.Operations[j], ref CopiedOperation);
					double num2 = (buProfileCalc.varProfileRunSettings.PatternCopyDistance + buProfileCalc.varProfileRunSettings.PatternCopyCutSpace) * (double)i;
					CopiedOperation.OperationData.Position.X = CopiedOperation.OperationData.Position.X + num2;
					buProfileCalc.varProfileRunSettings.OPData.selectedPlane = (Plane)CopiedOperation.OperationData.selectedPlane.Clone();
					new ProfileOnlineOpOptions();
					if (i < buProfileCalc.varProfileRunSettings.PatternCopyCount)
					{
						ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg();
						shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
						shapeUpdateArg.Finished = true;
						shapeUpdateArg.Tool = new ToolBase5(CopiedOperation.Tool);
						OnlineOperation(null, shapeUpdateArg, CopiedOperation.OperationData);
					}
				}
				num = ((i == 1) ? (buProfileCalc.varProfileRunSettings.PatternCopyDistance + buProfileCalc.varProfileRunSettings.PatternCopyCutSpace / 2.0) : (num + buProfileCalc.varProfileRunSettings.PatternCopyDistance + buProfileCalc.varProfileRunSettings.PatternCopyCutSpace));
				Point3D centerPoint = new Point3D(num, (0.0 - profileItem.Width) / 2.0, profileItem.Height / 2.0);
				Mesh entMesh = null;
				if (!(buProfileCalc.varProfileRunSettings.PatternCopyCutSpace > 0.0))
				{
					continue;
				}
				buEyeShotFunctions.CreateBoxWithCenter(centerPoint, buProfileCalc.varProfileRunSettings.PatternCopyCutSpace, profileItem.Width, profileItem.Height, isZCenter: true, ref entMesh);
				if (entMesh != null)
				{
					if (profileItem.auxEntities == null)
					{
						profileItem.auxEntities = new List<Entity>();
					}
					CustomData customData = new CustomData();
					customData.typeDefination = entityTypeDefination.ProfileSeperator;
					customData.ID = profileItem.Operations[0].ID;
					customData.EntityName = profileItem.Operations[0].ProfileName;
					customData.ActionName = profileItem.Operations[0].Name;
					entMesh.EntityData = customData;
					profileItem.auxEntities.Add(entMesh);
				}
			}
			RearrangeOperationID();
			clsInit.appCommand.Reset();
			DrawPreview(profileItem, new List<Entity>());
			DrawActiveProfile();
			buProfileCalc.varProfileRunSettings.OPData.Position.X = x;
		}
		UndoDontProfile = false;
	}

	public void doCopy()
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (profileItem == null || profileItem == null)
		{
			return;
		}
		if (!buProfileCalc.varProfileRunSettings.SelectMode || clsInit.cProfile.GetSelectedOperationCount(profileItem) != 0)
		{
			F_ProfileCopy f_ProfileCopy = new F_ProfileCopy();
			f_ProfileCopy.Profile = new buEyeBaseVer5.Apps.ProfileItem(profileItem);
			f_ProfileCopy.UseOriginalPlane = buProfileCalc.varProfileRunSettings.CopyMoveUseOriginalePlane;
			f_ProfileCopy.Count = buProfileCalc.varProfileRunSettings.CopyCount;
			f_ProfileCopy.DistanceHor = buProfileCalc.varProfileRunSettings.CopyDistanceHor;
			f_ProfileCopy.DistanceVer = buProfileCalc.varProfileRunSettings.CopyDistanceVer;
			f_ProfileCopy.UseDistance = buProfileCalc.varProfileRunSettings.CopyUseDistance;
			f_ProfileCopy.selectedPlanes.Clear();
			for (int i = 0; i <= selectedPlanes.Count - 1; i++)
			{
				f_ProfileCopy.selectedPlanes.Add(new SelectedPlaneInfo(selectedPlanes[i]));
			}
			f_ProfileCopy.OperationData = new buEyeBaseVer5.Apps.ProfileOperationData(profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].OperationData);
			f_ProfileCopy.Init();
			f_ProfileCopy.ShowDialog();
			if (f_ProfileCopy.Properties.Result != DialogResult.OK)
			{
				return;
			}
			SaveByTick = true;
			buProfileCalc.varProfileRunSettings.CopyCount = f_ProfileCopy.Count;
			buProfileCalc.varProfileRunSettings.CopyDistanceHor = f_ProfileCopy.DistanceHor;
			buProfileCalc.varProfileRunSettings.CopyDistanceVer = f_ProfileCopy.DistanceVer;
			buProfileCalc.varProfileRunSettings.CopyUseDistance = f_ProfileCopy.UseDistance;
			buProfileCalc.varProfileRunSettings.CopyMoveUseOriginalePlane = f_ProfileCopy.UseOriginalPlane;
			bUndoBuffer = true;
			ToolChangeForced = true;
			int activeOPIndex = buProfileCalc.varProfileRunSettings.activeOPIndex;
			double num = f_ProfileCopy.OperationData.basePosition.X - profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].OperationData.basePosition.X;
			double num2 = f_ProfileCopy.OperationData.basePosition.Y - profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].OperationData.basePosition.Y;
			if (buProfileCalc.varProfileRunSettings.CopyUseDistance)
			{
				num = buProfileCalc.varProfileRunSettings.CopyDistanceHor;
				num2 = buProfileCalc.varProfileRunSettings.CopyDistanceVer;
			}
			List<buEyeBaseVer5.Apps.ProfileOperation> list = new List<buEyeBaseVer5.Apps.ProfileOperation>();
			if (buProfileCalc.varProfileRunSettings.SelectMode)
			{
				for (int j = 0; j <= profileItem.Operations.Count - 1; j++)
				{
					if (profileItem.Operations[j].Selected)
					{
						list.Add(profileItem.Operations[j]);
					}
				}
			}
			else
			{
				list.Add(profileItem.Operations[activeOPIndex]);
			}
			double num3 = 1.0;
			ProfileTempVars.SelectedOperations.Clear();
			for (int k = 1; k <= buProfileCalc.varProfileRunSettings.CopyCount; k++)
			{
				for (int l = 0; l <= list.Count - 1; l++)
				{
					buEyeBaseVer5.Apps.ProfileOperationData profileOperationData = new buEyeBaseVer5.Apps.ProfileOperationData(list[l].OperationData);
					buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
					buEyeBaseVer5.Apps.ProfileOperation.Copy(list[l], ref CopiedOperation);
					if (CopiedOperation.OperationData.ManuelZEnable)
					{
						clsInit.cProfile.ManuelZValueFromPlaneChange(profileItem, CopiedOperation, profileOperationData.selectedPlaneName, f_ProfileCopy.OperationData.ManuelZVal, ref CopiedOperation.OperationData.ManuelZVal);
						profileOperationData.ManuelZVal = CopiedOperation.OperationData.ManuelZVal;
					}
					CopiedOperation.OperationData.ManuelZVal = 0.0;
					f_ProfileCopy.OperationData.ManuelZVal = 0.0;
					profileOperationData.basePosition.X = profileOperationData.basePosition.X + num * num3;
					profileOperationData.basePosition.Y = profileOperationData.basePosition.Y + num2 * num3;
					if (!buProfileCalc.varProfileRunSettings.CopyMoveUseOriginalePlane)
					{
						profileOperationData.selectedPlaneName = f_ProfileCopy.OperationData.selectedPlaneName;
					}
					if (profileOperationData.selectedPlaneName != CopiedOperation.OperationData.selectedPlaneName)
					{
						profileOperationData.DepthForced = false;
					}
					else
					{
						profileOperationData.DepthForced = true;
					}
					if (!buCompare5.EQ(num, 0.0) | !buCompare5.EQ(num2, 0.0) | (CopiedOperation.OperationData.selectedPlaneName != profileOperationData.selectedPlaneName))
					{
						doCopyApply(CopiedOperation, profileOperationData);
					}
				}
				num3 += 1.0;
			}
		}
		else
		{
			buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.SelectionModeActiveNoOperationSelected);
		}
	}

	public void doCopyApply(buEyeBaseVer5.Apps.ProfileOperation OP, buEyeBaseVer5.Apps.ProfileOperationData OPData)
	{
		buEyeBaseVer5.Apps.ProfileItem profileItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
