		ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg();
		shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
		shapeUpdateArg.Parameters.selectedPlane = buConversion5.PlaneNamesToPlaneBoxNames(OPData.selectedPlaneName);
		shapeUpdateArg.Finished = true;
		shapeUpdateArg.ToolFound = true;
		shapeUpdateArg.Tool = new ToolBase5(OP.Tool);
		shapeUpdateArg.Parameters.Priority = OP.Priority;
		ProfileTempVars.OperationDepths.Clear();
		DepthPositions.Copy(OP.OperationData.DepthValues, ref ProfileTempVars.OperationDepths);
		OnlineOperation(null, shapeUpdateArg, OP.OperationData);
	}

