				return;
			}
			SaveByTick = true;
			buProfileCalc.varProfileRunSettings.CopyDistanceHor = f_ProfileCopy.DistanceHor;
			buProfileCalc.varProfileRunSettings.CopyDistanceVer = f_ProfileCopy.DistanceVer;
			buProfileCalc.varProfileRunSettings.CopyUseDistance = f_ProfileCopy.UseDistance;
			buProfileCalc.varProfileRunSettings.CopyMoveUseOriginalePlane = f_ProfileCopy.UseOriginalPlane;
			bUndoBuffer = true;
			ToolChangeForced = true;
			int activeOPIndex = buProfileCalc.varProfileRunSettings.activeOPIndex;
			double num = f_ProfileCopy.OperationData.basePosition.X - profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].OperationData.basePosition.X;
			double num2 = f_ProfileCopy.OperationData.basePosition.Y - profileItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].OperationData.basePosition.Y;
			if (buProfileCalc.varProfileRunSettings.CopyUseDistance)
			{
				num = buProfileCalc.varProfileRunSettings.CopyDistanceHor;
				num2 = buProfileCalc.varProfileRunSettings.CopyDistanceVer;
			}
			List<buEyeBaseVer5.Apps.ProfileOperation> list = new List<buEyeBaseVer5.Apps.ProfileOperation>();
			List<int> list2 = new List<int>();
			if (buProfileCalc.varProfileRunSettings.SelectMode)
			{
				for (int j = 0; j <= profileItem.Operations.Count - 1; j++)
				{
					if (profileItem.Operations[j].Selected)
					{
						list.Add(profileItem.Operations[j]);
						list2.Add(j);
					}
				}
			}
			else
			{
				list.Add(profileItem.Operations[activeOPIndex]);
				list2.Add(activeOPIndex);
			}
			ProfileTempVars.SelectedOperations.Clear();
			ProfileTempVars.MultiOperationStarted = true;
			ProfileTempVars.OperationEditing = true;
			for (int k = 0; k <= list.Count - 1; k++)
			{
				buEyeBaseVer5.Apps.ProfileOperationData profileOperationData = new buEyeBaseVer5.Apps.ProfileOperationData(list[k].OperationData);
				buEyeBaseVer5.Apps.ProfileOperation CopiedOperation = new buEyeBaseVer5.Apps.ProfileOperation();
				buEyeBaseVer5.Apps.ProfileOperation.Copy(list[k], ref CopiedOperation);
				if (CopiedOperation.OperationData.ManuelZEnable)
				{
					clsInit.cProfile.ManuelZValueFromPlaneChange(profileItem, CopiedOperation, profileOperationData.selectedPlaneName, f_ProfileCopy.OperationData.ManuelZVal, ref CopiedOperation.OperationData.ManuelZVal);
					profileOperationData.ManuelZVal = CopiedOperation.OperationData.ManuelZVal;
				}
				CopiedOperation.OperationData.ManuelZVal = 0.0;
				f_ProfileCopy.OperationData.ManuelZVal = 0.0;
				profileOperationData.basePosition.X = profileOperationData.basePosition.X + num;
				if (!((CopiedOperation.OperationData.selectedPlaneName == planeNames.Top) | (CopiedOperation.OperationData.selectedPlaneName == planeNames.Bottom) | (CopiedOperation.OperationData.selectedPlaneName == planeNames.Free)))
				{
					profileOperationData.basePosition.Y = profileOperationData.basePosition.Z + num2;
					profileOperationData.basePosition.Z = profileOperationData.basePosition.Z + num2;
				}
				else
				{
					profileOperationData.basePosition.Y = profileOperationData.basePosition.Y + num2;
				}
				if (!buProfileCalc.varProfileRunSettings.CopyMoveUseOriginalePlane)
				{
					profileOperationData.selectedPlaneName = f_ProfileCopy.OperationData.selectedPlaneName;
				}
				if (profileOperationData.selectedPlaneName != CopiedOperation.OperationData.selectedPlaneName)
				{
					profileOperationData.DepthForced = false;
				}
				else
				{
					profileOperationData.DepthForced = true;
				}
				if (!buCompare5.EQ(num, 0.0) | !buCompare5.EQ(num2, 0.0) | (CopiedOperation.OperationData.selectedPlaneName != profileOperationData.selectedPlaneName))
				{
					doMoveApply(CopiedOperation, profileOperationData, list2[k]);
				}
			}
			OperationDataCancel();
			ProfileTempVars.MultiOperationStarted = false;
			if (buProfileCalc.varProfileSettings.MultipleEdit)
			{
				doAddSelectedOperations();
			}
		}
		else
		{
			buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.SelectionModeActiveNoOperationSelected);
		}
	}

