		DepthPositions.Copy(OPData.DepthValues, ref ProfileTempVars.OperationDepths);
		OPPriority = OP.Priority;
		OnlineOperation(null, shapeUpdateArg, OPData);
	}

	public void doMirror(ProfileMirror MirrorData)
	{
		buEyeBaseVer5.Apps.ProfileOperation profileOperation = null;
		buEyeBaseVer5.Apps.ProfileItem curItem = clsInit.cProfile.SelectActiveProfile(activeProfile.FirstItem, activeProfile.SecondItem, ref buProfileCalc.varProfileRunSettings.activeProfileIndex);
		if (curItem == null)
		{
			return;
		}
		if (!buProfileCalc.varProfileRunSettings.SelectMode || clsInit.cProfile.GetSelectedOperationCount(curItem) != 0)
		{
			ProfileTempVars.SelectedOperations.Clear();
			if (!(curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex] is buEyeBaseVer5.Apps.ProfileOperationNotch))
			{
				if (buProfileCalc.varProfileRunSettings.SelectMode)
				{
					for (int i = 0; i <= curItem.Operations.Count - 1; i++)
					{
						if (curItem.Operations[i].Selected)
						{
							profileOperation = new buEyeBaseVer5.Apps.ProfileOperation();
							buEyeBaseVer5.Apps.ProfileOperation.Copy(curItem.Operations[i], ref profileOperation);
							doMirrorApply(MirrorData, profileOperation, ref curItem);
						}
					}
				}
				else
				{
					profileOperation = new buEyeBaseVer5.Apps.ProfileOperation();
					buEyeBaseVer5.Apps.ProfileOperation.Copy(curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex], ref profileOperation);
					doMirrorApply(MirrorData, profileOperation, ref curItem);
				}
				return;
			}
			profileOperation = new buEyeBaseVer5.Apps.ProfileOperation();
			buEyeBaseVer5.Apps.ProfileOperation.Copy(curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex], ref profileOperation);
			ShapeUpdateArg shapeUpdateArg = new ShapeUpdateArg();
			shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			shapeUpdateArg.Finished = true;
			shapeUpdateArg.Tool = new ToolBase5(curItem.Operations[buProfileCalc.varProfileRunSettings.activeOPIndex].ToolNotch);
			shapeUpdateArg.Parameters.NotchSideLocation = ProfileNotchLocationType.Right;
			profileOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Right;
			if (profileOperation.OperationData.NotchData.NotchLocation != ProfileNotchLocationType.Left)
			{
				if (profileOperation.OperationData.NotchData.NotchLocation != ProfileNotchLocationType.Right)
				{
					if (profileOperation.OperationData.NotchData.NotchLocation != ProfileNotchLocationType.Front)
					{
						if (profileOperation.OperationData.NotchData.NotchLocation == ProfileNotchLocationType.Back)
						{
							profileOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Front;
						}
					}
					else
					{
						profileOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Back;
					}
				}
				else
				{
					profileOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Left;
				}
			}
			else
			{
				profileOperation.OperationData.NotchData.NotchLocation = ProfileNotchLocationType.Right;
			}
			OnlineOperation(null, shapeUpdateArg, profileOperation.OperationData);
			ProfileTempVars.MultiOperationStarted = false;
		}
		else
		{
			buString5.MessageBoxWarning(buLangTranslate.preSentencesProfile.SelectionModeActiveNoOperationSelected);
		}
	}

	public void doMirrorApply(ProfileMirror MirrorData, buEyeBaseVer5.Apps.ProfileOperation mirroredOP, ref buEyeBaseVer5.Apps.ProfileItem curItem)
	{
		try
		{
			if (MirrorData.MirrorAxis != MirrorAxisXYType.X)
			{
				if (buProfileCalc.varProfileSettings.OperationFrontBackMirrorYDirToAnotherPlane)
				{
					if ((mirroredOP.OperationData.selectedPlaneName == planeNames.Top) | (mirroredOP.OperationData.selectedPlaneName == planeNames.Bottom) | (mirroredOP.OperationData.selectedPlaneName == planeNames.Free))
					{
						clsInit.cVector5.MirrorCornerLocation(mirroredOP.OperationData.Corner, VectorXYType.XVector, ref mirroredOP.OperationData.Corner);
					}
				}
				else
				{
					clsInit.cVector5.MirrorCornerLocation(mirroredOP.OperationData.Corner, VectorXYType.XVector, ref mirroredOP.OperationData.Corner);
				}
			}
			else
			{
				clsInit.cVector5.MirrorCornerLocation(mirroredOP.OperationData.Corner, VectorXYType.YVector, ref mirroredOP.OperationData.Corner);
			}
			Point3D point3D = new Point3D();
			Plane planeMirror = Plane.XY;
			double num = MirrorData.MirrorDistance;
			point3D = Point3D.MidPoint(mirroredOP.MinPoint, mirroredOP.MaxPoint);
			Point3D point3D2 = new Point3D(mirroredOP.MinPoint.X, mirroredOP.MinPoint.Y, mirroredOP.MinPoint.Z);
			Point3D point3D3 = new Point3D(mirroredOP.MinPoint.X, mirroredOP.MinPoint.Y, mirroredOP.MinPoint.Z);
			if (MirrorData.MirrorLocation == MinCenterMaxType.Max)
			{
				point3D2 = new Point3D(mirroredOP.MaxPoint.X, mirroredOP.MaxPoint.Y, mirroredOP.MaxPoint.Z);
				point3D3 = new Point3D(mirroredOP.MaxPoint.X, mirroredOP.MaxPoint.Y, mirroredOP.MaxPoint.Z);
			}
			if (MirrorData.MirrorLocation == MinCenterMaxType.Center)
			{
				point3D2 = new Point3D(point3D.X, point3D.Y, point3D.Z);
				point3D3 = new Point3D(point3D.X, point3D.Y, point3D.Z);
			}
			if (mirroredOP.OperationData.selectedPlaneName == planeNames.Front)
			{
				planeMirror = Plane.XZ;
			}
			if (mirroredOP.OperationData.selectedPlaneName == planeNames.Back)
			{
				planeMirror = Plane.XZ;
			}
			if (MirrorData.Mode == MirrorModeType.FromCenter)
			{
				num = 0.0;
				if (mirroredOP.OperationData.selectedPlaneName == planeNames.Top)
				{
					point3D2 = new Point3D(curItem.Length / 2.0, (0.0 - curItem.Width) / 2.0, curItem.Height);
					point3D3 = new Point3D(curItem.Length / 2.0, (0.0 - curItem.Width) / 2.0, curItem.Height);
				}
				if (mirroredOP.OperationData.selectedPlaneName == planeNames.Front)
				{
					point3D2 = new Point3D(curItem.Length / 2.0, 0.0 - curItem.Width, curItem.Height / 2.0);
					point3D3 = new Point3D(curItem.Length / 2.0, 0.0 - curItem.Width, curItem.Height / 2.0);
				}
				if (mirroredOP.OperationData.selectedPlaneName == planeNames.Back)
				{
					point3D2 = new Point3D(curItem.Length / 2.0, 0.0, curItem.Height / 2.0);
					point3D3 = new Point3D(curItem.Length / 2.0, 0.0, curItem.Height / 2.0);
				}
			}
			if (MirrorData.MirrorAxis == MirrorAxisXYType.X)
			{
				if (mirroredOP.OperationData.selectedPlaneName == planeNames.Top)
				{
					point3D3.Y += 10.0;
					point3D3.X += num;
					point3D2.X += num;
				}
				if ((mirroredOP.OperationData.selectedPlaneName == planeNames.Front) | (mirroredOP.OperationData.selectedPlaneName == planeNames.Back))
				{
					point3D3.Z += 10.0;
					point3D3.X += num;
					point3D2.X += num;
				}
			}
			if (MirrorData.MirrorAxis == MirrorAxisXYType.Y)
			{
				if (mirroredOP.OperationData.selectedPlaneName == planeNames.Top)
				{
					point3D3.X += 10.0;
					point3D3.Y += num;
					point3D2.Y += num;
				}
				if ((mirroredOP.OperationData.selectedPlaneName == planeNames.Front) | (mirroredOP.OperationData.selectedPlaneName == planeNames.Back))
				{
					point3D3.X += 10.0;
					point3D3.Z += num;
					point3D2.Z += num;
				}
			}
			mirroredOP.OperationData.DepthForced = true;
			if (!((MirrorData.Mode == MirrorModeType.FromCenter) & ((mirroredOP.OperationData.selectedPlaneName == planeNames.Front) | (mirroredOP.OperationData.selectedPlaneName == planeNames.Back)) & (MirrorData.MirrorAxis == MirrorAxisXYType.Y) & buProfileCalc.varProfileSettings.OperationFrontBackMirrorYDirToAnotherPlane))
			{
				Point3D mirrorPoint = new Point3D();
				clsInit.cVector5.Mirror(point3D2, point3D3, planeMirror, mirroredOP.OperationData.Position, ref mirrorPoint);
				mirroredOP.OperationData.Position = buVector5.ToPoint3D(mirrorPoint);
				if (mirroredOP.OperationData.OperationType == ProfileOperationTypes.Barrel && MirrorData.MirrorAxis == MirrorAxisXYType.X)
				{
					mirroredOP.OperationData.BarelData.BarrelAngle = mirroredOP.OperationData.BarelData.BarrelAngle + 180.0;
					if (mirroredOP.OperationData.BarelData.BarrelAngle > 360.0)
					{
						mirroredOP.OperationData.BarelData.BarrelAngle = mirroredOP.OperationData.BarelData.BarrelAngle - 360.0;
					}
				}
				if (mirroredOP.OperationData.OperationType == ProfileOperationTypes.FreeDraw)
				{
					shapeCreateParameters_0.entitiesCurveList.Clear();
					for (int i = 0; i <= mirroredOP.EntityMultiXYPlane.Count - 1; i++)
					{
