			if (buCompare5.EQ(Item.BasePoint.X, 0.0) & buCompare5.EQ(Item.BasePoint.Y, 0.0) & buCompare5.EQ(Item.BasePoint.Y, 0.0))
			{
				Item.BasePoint.X = mirroredOP.OperationData.Position.X;
				Item.BasePoint.Y = mirroredOP.OperationData.Position.Y;
				Item.BasePoint.Z = mirroredOP.OperationData.Position.Z;
				Item.Corner = CornerLocation.LeftTop;
