			clsInit.cVector5.CoordinateFromPlaneAndCorner(new SizeObject(curItem.Length, curItem.Width, curItem.Height), mirroredOP.OperationData.Corner, buConversion5.PlaneNamesToPlaneBoxNames(mirroredOP.OperationData.selectedPlaneName), ref Item, ref mirroredOP.OperationData.Position, shapeCreateParameters_0.SingX, shapeCreateParameters_0.SingY);
