			shapeUpdateArg.Parameters = new ShapeRuntimeData(buProfileCalc.varProfileRunSettings.ShapeDataParameters);
			shapeUpdateArg.Parameters.selectedPlane = buConversion5.PlaneNamesToPlaneBoxNames(mirroredOP.OperationData.selectedPlaneName);
