	public void doCalculateCamPointsKabanMode1(ref camTp C, ref buEyeBaseVer5.Apps.ProfileItem Item, ref GProfileOperation OP, ref TpPnt9D lastCamP9, int i, int y, bool ToolMilling, double ZParkPosAfterKinematic, bool CreateGCode)
	{
		if (!ToolMilling)
		{
			for (int j = 0; j <= C.CamPoints.Count - 1; j++)
			{
				for (int k = 0; k <= C.CamPoints[j].Points.Count - 1; k++)
				{
					if ((Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side) | (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Length))
					{
						Pnt9D pnt9D = new Pnt9D(C.CamPoints[j].Points[k].P9);
						double num = ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength;
						pnt9D.Z += num;
						C.CamPoints[j].Points[k].PlungeAxis = "X";
						C.CamPoints[j].Points[k].P9 = new Pnt9D(pnt9D);
					}
					if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
					{
						Pnt9D pnt9D2 = new Pnt9D(C.CamPoints[j].Points[k].P9);
						if ((Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front) | (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back))
						{
							double num2 = (ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength) * Math.Sin(buConversion5.DegreeToRadian(pnt9D2.A));
							pnt9D2.Y -= num2;
							C.CamPoints[j].Points[k].PlungeAxis = "X";
						}
						if (k == C.CamPoints[j].Points.Count - 1)
						{
							pnt9D2.Z = ZParkPosAfterKinematic;
						}
						C.CamPoints[j].Points[k].P9 = new Pnt9D(pnt9D2);
					}
					if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal)
					{
						Pnt9D pnt9D3 = new Pnt9D(C.CamPoints[j].Points[k].P9);
						double num3 = (ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength) * Math.Sin(buConversion5.DegreeToRadian(pnt9D3.A));
						pnt9D3.Y -= num3;
						C.CamPoints[j].Points[k].PlungeAxis = "Z";
						C.CamPoints[j].Points[k].P9 = new Pnt9D(pnt9D3);
					}
				}
			}
		}
		else
		{
			for (int l = 0; l <= C.CamPoints.Count - 1; l++)
			{
				for (int m = 0; m <= C.CamPoints[l].Points.Count - 1; m++)
				{
					Pnt9D pnt9D4 = new Pnt9D(C.CamPoints[l].Points[m].P9);
					OrientationAngle orientationAngle = new OrientationAngle(C.CamPoints[l].Points[m].P9.A, 0.0, 0.0);
					if (((Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front) | (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back)) && (buCompare5.EQ(orientationAngle.A, 0.0) & C.CamPoints[l].Points[m].EnableAxes.Y))
					{
						if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back)
						{
							orientationAngle.A = -90.0;
						}
						if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front)
						{
							orientationAngle.A = 90.0;
						}
					}
					Point3D movePoint = new Point3D(C.CamPoints[l].Points[m].P9.X, C.CamPoints[l].Points[m].P9.Y, C.CamPoints[l].Points[m].P9.Z);
					Pnt6D CalcPoint = new Pnt6D();
					clsInit.cKinematic5.ForwardKinematix4Ax(C.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, orientationAngle, movePoint, ref CalcPoint);
					pnt9D4 = new Pnt9D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z, CalcPoint.A, CalcPoint.B, CalcPoint.C);
					if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Top)
					{
						C.CamPoints[l].Points[m].PlungeAxis = "Z";
					}
					if ((Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front) | (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back))
					{
						C.CamPoints[l].Points[m].PlungeAxis = "Y";
					}
					if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Free)
					{
						C.CamPoints[l].Points[m].PlungeAxis = "";
					}
					if (OP.OperationData.OperationType == ProfileOperationTypes.Tapping && C.CamPoints[l].Points[m].PlungeAxisMovement)
					{
						C.CamPoints[l].Points[m].Type = 0;
						double num4 = OP.OperationData.HoleData.TappingDepth;
						if (OP.OperationData.selectedPlaneName == planeNames.Top && m > 0)
						{
							num4 = C.CamPoints[l].Points[m - 1].P9.Z - pnt9D4.Z;
						}
						if (((OP.OperationData.selectedPlaneName == planeNames.Front) | (OP.OperationData.selectedPlaneName == planeNames.Back)) && m > 0)
						{
							num4 = Math.Abs(C.CamPoints[l].Points[m - 1].P9.Y - pnt9D4.Y);
						}
						C.CamPoints[l].Points[m].OverWriteString = "M80 X" + OP.OperationData.HoleData.TappingPitch.ToString("f2") + " Y" + (0.0 - num4).ToString("f2") + " Z" + OP.Tool.CamData.SpindleSpeed.ToString("");
					}
					C.CamPoints[l].Points[m].P9 = new Pnt9D(pnt9D4);
				}
			}
			lastCamP9 = C.CamPoints[C.CamPoints.Count - 1].Points[C.CamPoints[C.CamPoints.Count - 1].Points.Count - 1];
		}
		if (Item.CalculationData[y].XReferanceLocation == LeftRightType.Right && CreateGCode)
		{
			for (int n = 0; n <= C.CamPoints.Count - 1; n++)
			{
				for (int num5 = 0; num5 <= C.CamPoints[n].Points.Count - 1; num5++)
				{
					Pnt9D p = C.CamPoints[n].Points[num5].P9;
					if (!buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
					{
						p.X = buProfileCalc.varProfileSettings.MachineLength - Item.CalculationData[y].Length + p.X;
					}
					else
					{
						p.X -= Item.CalculationData[y].Length;
					}
					if (!buProfileCalc.varProfileSettings.ChangeG2G3DirForRightRefProfile)
					{
						continue;
					}
					if (C.CamPoints[n].Points[num5].Type != 2)
					{
						if (C.CamPoints[n].Points[num5].Type == 3)
						{
							C.CamPoints[n].Points[num5].Type = 2;
						}
					}
					else
					{
						C.CamPoints[n].Points[num5].Type = 3;
					}
				}
			}
		}
		if (Item.CalculationData[y].XReferanceLocation == LeftRightType.Left && CreateGCode)
		{
			for (int num6 = 0; num6 <= C.CamPoints.Count - 1; num6++)
			{
				for (int num7 = 0; num7 <= C.CamPoints[num6].Points.Count - 1; num7++)
				{
					_ = C.CamPoints[num6].Points[num7].P9;
					if (!buProfileCalc.varProfileSettings.ChangeG2G3DirForLeftRefProfile)
					{
						continue;
					}
					if (C.CamPoints[num6].Points[num7].Type != 2)
					{
						if (C.CamPoints[num6].Points[num7].Type == 3)
						{
							C.CamPoints[num6].Points[num7].Type = 2;
						}
					}
					else
					{
						C.CamPoints[num6].Points[num7].Type = 3;
					}
				}
			}
		}
		Item.CalculationData[y].Cams.Add(C);
	}

	public void doSaveGcodeKabanMode1(bool ShowCode)
	{
		try
		{
			if (!clsVar.appModes_0.DemoMode)
			{
				if (ccVars.Pages.Count > 0)
				{
					if (!((activeProfile.FirstItem == null) & (activeProfile.SecondItem == null)))
					{
						if (!(!activeProfile.isSimulationDone & (AppSecurity.PasswordLevel == 0)))
						{
							bool flag = false;
							bool flag2 = false;
							if (activeProfile.FirstItem != null && activeProfile.FirstItem.Enable && activeProfile.FirstItem.Operations.Count > 0)
							{
								flag = true;
							}
							if (activeProfile.SecondItem != null && activeProfile.SecondItem.Enable && activeProfile.SecondItem.Operations.Count > 0)
							{
								flag2 = true;
							}
							if (!flag || !activeProfile.FirstItem.isError)
							{
								if (!flag2 || !activeProfile.SecondItem.isError)
								{
									SaveFileDialog saveFileDialog = new SaveFileDialog();
									saveFileDialog.InitialDirectory = clsVar.varInterface.pathGCode;
									saveFileDialog.Filter = ccVars.PostActive.FileExplanation + " (" + ccVars.PostActive.FileExtension + ")|" + ccVars.PostActive.FileExtension;
									saveFileDialog.FilterIndex = 1;
									DialogResult dialogResult = DialogResult.None;
									if (!ShowCode)
									{
										dialogResult = saveFileDialog.ShowDialog();
									}
									if (dialogResult == DialogResult.OK || ShowCode)
									{
										string fileName = buFile5.GetPath(saveFileDialog.FileName) + "\\" + buFile5.getFileNameWithoutExtension(saveFileDialog.FileName) + ".stl";
										if (buProfileCalc.varProfileSettings.SaveStlFileWhileCreatingCode)
										{
											buFile5.SaveStl(ccVars.Pages[ccVars.PageIndex].Form.viewportcad, fileName);
										}
										if (buProfileCalc.varProfileSettings.SaveImageFileWhileCreatingCode)
										{
											string filePath = buFile5.GetPath(saveFileDialog.FileName) + "\\" + buFile5.getFileNameWithoutExtension(saveFileDialog.FileName) + ".png";
											ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WriteToFileRaster((float)buProfileCalc.varProfileSettings.ImageScaleFactor, filePath, ImageFormat.Png);
										}
										ArrayList GCodes = new ArrayList();
										ArrayList GCodes2 = new ArrayList();
										int num = 0;
										buProfileCalc.varTemps.LastGCodeLine = 0;
										ccVars.PostActive.NumberDef.Start = 10.0;
										ProfileTempVars.LastClampers.Clear();
										if (flag)
										{
											doCreateCode(activeProfile.FirstItem, ccVars.PostActive.Mode, ref GCodes, 0, flag2, CreateGCode: true, ShowCode);
											num++;
										}
										if (flag2)
										{
											doCreateCode(activeProfile.SecondItem, ccVars.PostActive.Mode, ref GCodes2, 1, SecondAvailable: false, CreateGCode: true, ShowCode);
										}
										if (!(flag && flag2))
										{
											GCodes.AddRange(GCodes2);
										}
										else
										{
											ArrayList CalcList = new ArrayList();
											ArrayList CalcList2 = new ArrayList();
											ArrayList CalcList3 = new ArrayList();
											ArrayList CalcList4 = new ArrayList();
											buString5.ListToSpecificList("<GCodes>", "</GCodes>", AddStartEndKey: false, GCodes, ref CalcList);
											buString5.ListToSpecificList("<GCodes>", "</GCodes>", AddStartEndKey: false, GCodes2, ref CalcList2);
											buString5.ListToSpecificList("<ProfileCode>", "</ProfileCode>", AddStartEndKey: false, GCodes, ref CalcList3);
											buString5.ListToSpecificList("<ProfileCode>", "</ProfileCode>", AddStartEndKey: false, GCodes2, ref CalcList4);
											GCodes.AddRange(GCodes2);
										}
										if (activeProfile.GCodes == null)
										{
											activeProfile.GCodes = new ArrayList();
										}
										activeProfile.GCodes.Clear();
										activeProfile.GCodes = buString5.Copy(GCodes);
										clsVar.varInterface.pathGCode = buFile5.GetPath(saveFileDialog.FileName);
										if (ShowCode)
										{
											F_Notepad f_Notepad = new F_Notepad();
											f_Notepad.Init(GCodes);
											f_Notepad.Show();
										}
										else
										{
											buFile5.SaveToFile(GCodes, saveFileDialog.FileName);
										}
										GCodes.Clear();
										clsFiles.SaveParameter();
									}
								}
								else
								{
									buString5.MessageBoxWarning(buLangTranslate.preDef.Second + " " + buLangTranslate.preDef.Profile + " " + buProfile.LangProfileMessage[14]);
								}
							}
							else
							{
								buString5.MessageBoxWarning(buLangTranslate.preDef.First + " " + buLangTranslate.preDef.Profile + " " + buProfile.LangProfileMessage[14]);
							}
						}
						else
						{
							buString5.MessageBoxWarning(buProfile.LangProfileMessage[13]);
						}
					}
					else
					{
						buString5.MessageBoxWarning(buProfile.LangProfileMessage[12]);
					}
				}
				else
				{
					buString5.MessageBoxWarning(AppLanguage.Messages[9]);
				}
			}
			else
			{
				MessageBox.Show(buLangTranslate.preSentences.NotAvailableDemoMode);
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

