								text9 = " = " + (buProfileCalc.varProfileSettings.MachineLength - (Item.CalculationData[i].Length - C.CamPoints[0].Points[0].P9.X));
							}
						}
						if (Item.CalculationData[j].XReferanceLocation != LeftRightType.Left)
						{
							if (Item.CalculationData[j].XReferanceLocation == LeftRightType.Right)
							{
								C.ToolPreCodes.Add("M192");
							}
						}
						else
						{
							C.ToolPreCodes.Add("M191");
						}
						C.ToolPreCodes.Add("#810" + text9 + " #5221");
						C.ToolPreCodes.Add("#820=" + zParkPosAfterKinematic.ToString("f2"));
						C.ToolAfterCodes.Add("G90 G54(because M6 switch G91 on)");
						C.ToolAfterCodes.Add("G53 Z0");
						C.ToolAfterCodes.Add("G90 G54 G59");
						C.ToolAfterCodes.Add("G0 Z" + zParkPosAfterKinematic.ToString("f1") + " Y" + buProfileCalc.varProfileSettings.ParkPositionY.ToString("f1"));
						C.SpindleAfterCodes.Add("#809=" + C.Tool.CamData.SpindleSpeed);
						C.SpindleAfterCodes.Add("#5241 = 0     (delete to G55)");
						C.SpindleAfterCodes.Add("G90 G54(absolut positioning on and set zero point)");
					}
					buEyeBaseVer5.Apps.ProfileClamper.Copy(Item.CalculationData[i].calcOperations[j].Clampers, ref ProfileTempVars.LastClampers);
					bool toolMilling = true;
					if (Item.CalculationData[i].calcOperations[j].OperationData.OperationType == ProfileOperationTypes.Notch && C.Tool.Geometry.GeometryType == ToolType.Saw)
					{
						toolMilling = false;
					}
					doCalculateCamPointsKabanMode2(ref C, ref Item, ref OP, ref lastCamP, j, i, toolMilling, zParkPosAfterKinematic, CreateGCode);
					if (Item.CalculationData.Count <= 1)
					{
						if (j != Item.CalculationData[i].calcOperations.Count - 1)
						{
							continue;
						}
						switch (ProfileIndex)
						{
						case 1:
							C.AfterCodes.Add("M05 ( Stop Spindle )");
							C.AfterCodes.Add("G0 Z" + zParkPosAfterKinematic.ToString("f2") + " ( go Z-save )");
							C.AfterCodes.Add("G0 X" + buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2") + " Y" + buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2") + " G0 A0  ( X Y A Go Park Position )");
							C.AfterCodes.Add("M40 M41 M42 M43");
							C.AfterCodes.Add("M44 M45");
							C.AfterCodes.Add("M30");
							break;
						case 0:
							if (!SecondAvailable)
							{
								C.AfterCodes.Add("M05 ( Stop Spindle )");
								C.AfterCodes.Add("G0 Z" + zParkPosAfterKinematic.ToString("f2") + " ( go Z-save )");
								C.AfterCodes.Add("G0 X" + buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2") + " Y" + buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2") + " G0 A0  ( X Y A Go Park Position )");
								C.AfterCodes.Add("M40 M41 M42 M43");
								C.AfterCodes.Add("M44 M45");
								C.AfterCodes.Add("M30");
							}
							else
							{
								C.AfterCodes.Add("M05 ( Stop Spindle )");
								C.AfterCodes.Add("G0 Z" + zParkPosAfterKinematic.ToString("f2") + " ( go Z-save )");
								C.AfterCodes.Add("G0 X" + buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2") + " Y" + buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2") + " G0 A0  ( X Y A Go Park Position )");
							}
							break;
						}
					}
					else
					{
						if (j != Item.CalculationData[i].calcOperations.Count - 1)
						{
							continue;
						}
						if (i >= Item.CalculationData.Count - 1)
						{
							switch (ProfileIndex)
							{
							case 1:
								C.AfterCodes.Add("M05 ( Stop Spindle )");
								C.AfterCodes.Add("G0 Z" + zParkPosAfterKinematic.ToString("f2") + " ( go Z-save )");
								C.AfterCodes.Add("G0 X" + buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2") + " Y" + buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2") + " G0 A0  ( X Y A Go Park Position )");
								C.AfterCodes.Add("M40 M41 M42 M43");
								C.AfterCodes.Add("M44 M45");
								C.AfterCodes.Add("M30");
								break;
							case 0:
								if (!SecondAvailable)
								{
									C.AfterCodes.Add("M05 ( Stop Spindle )");
									C.AfterCodes.Add("G0 Z" + zParkPosAfterKinematic.ToString("f2") + " ( go Z-save )");
									C.AfterCodes.Add("G0 X" + buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2") + " Y" + buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2") + " G0 A0  ( X Y A Go Park Position )");
									C.AfterCodes.Add("M40 M41 M42 M43");
									C.AfterCodes.Add("M44 M45");
									C.AfterCodes.Add("M30");
								}
								else
								{
									C.AfterCodes.Add("M05 ( Stop Spindle )");
									C.AfterCodes.Add("G0 Z" + zParkPosAfterKinematic.ToString("f2") + " ( go Z-save )");
									C.AfterCodes.Add("G0 X" + buProfileCalc.varProfileSettings.ParkPositionX.ToString("f2") + " Y" + buProfileCalc.varProfileSettings.ParkPositionY.ToString("f2") + " G0 A0  ( X Y A Go Park Position )");
								}
								break;
							}
						}
						else
						{
							C.AfterCodes.Add("M05 ( Stop Spindle )");
							C.AfterCodes.Add("G0 Z" + zParkPosAfterKinematic.ToString("f2") + " ( go Z-save )");
						}
					}
				}
			}
			if (buProfileCalc.varProfileSettings.AutoCloseWater)
			{
				List<string> waterOn = new List<string> { "M8", "M159" };
				List<string> waterOff = new List<string> { "M9", "M160" };
				clsInit.cProfile.SetWaterOnAdnOffToCam(ref Item.CalculationData[i].Cams, waterOn, waterOff);
			}
			else
			{
				Item.CalculationData[i].Cams[Item.CalculationData[i].Cams.Count - 1].CamPoints[Item.CalculationData[i].Cams[Item.CalculationData[i].Cams.Count - 1].CamPoints.Count - 1].AfterCodes.Add("M9 (Cooler Off)");
			}
		}
		if (buProfileCalc.varProfileSettings.ParabolicMoveBetweenPlanes)
		{
			doCreateParabolicMoves(ref Item);
		}
		PostProcessor tempPost = new PostProcessor(ccVars.PostActive);
		doAddInfoCodeKabanMode2(ref Item, ref tempPost, ProfileIndex, zParkPosAfterKinematic, addToolInfo);
		if (SecondAvailable)
		{
			tempPost.EndLines.Clear();
		}
		GCodeStr = "";
		new ArrayList();
		tempPost.PositionDef.PositionType = PositionPostType.G90;
		if (buProfileCalc.varProfileSettings.G91Mode)
		{
			tempPost.PositionDef.PositionType = PositionPostType.G91AfterG0;
			tempPost.PositionDef.G90Def.Clear();
			tempPost.PositionDef.G90Def.Add("G90");
			tempPost.PositionDef.G91Def.Clear();
			tempPost.PositionDef.G91Def.Add("G91");
		}
		for (int num8 = 0; num8 <= Item.CalculationData.Count - 1; num8++)
		{
			if (num8 > 0)
			{
				tempPost.StartLines.Clear();
			}
			Item.CalculationData[num8].GCodesItem.Clear();
			for (int num9 = 0; num9 <= Item.CalculationData[num8].Cams.Count - 1; num9++)
			{
				Item.CalculationData[num8].Cams[num9].ToolPreCodes.Add("( Tool No : " + Item.CalculationData[num8].Cams[num9].Tool.Data.No + " - " + Item.CalculationData[num8].Cams[num9].Tool.Data.Name + " )");
				Item.CalculationData[num8].Cams[num9].SpindlePreCodes.Clear();
				Item.CalculationData[num8].Cams[num9].SpindlePreCodes.Add("( Start Spindle : " + Item.CalculationData[num8].Cams[num9].Tool.CamData.SpindleSpeed + " Rpm )");
			}
			string Lines = "";
			tempPost.NumberDef.Start = buProfileCalc.varTemps.LastGCodeLine + 10;
			if (tempPost.NumberDef.Start < 10.0)
			{
				tempPost.NumberDef.Start = 10.0;
			}
			clsInit.cGcodeCreate.CreatGCode(Item.CalculationData[num8].Cams, tempPost, ref Lines);
			buString5.StringToListByNewLine(Lines, ref Item.CalculationData[num8].GCodesItem);
			if (Item.CalculationData[num8].GCodesItem.Count > 1)
			{
				if (Item.CalculationData[num8].GCodesItem[Item.CalculationData[num8].GCodesItem.Count - 1].ToString().Trim().Length == 0)
				{
					Item.CalculationData[num8].GCodesItem.RemoveAt(Item.CalculationData[num8].GCodesItem.Count - 1);
				}
				if (Item.CalculationData[num8].GCodesItem[Item.CalculationData[num8].GCodesItem.Count - 1].ToString().Trim().Length == 0)
				{
					Item.CalculationData[num8].GCodesItem.RemoveAt(Item.CalculationData[num8].GCodesItem.Count - 1);
				}
			}
			if (Item.CalculationData[num8].GCodesItem.Count <= 1)
			{
				continue;
			}
			double Value = 0.0;
			if (Item.CalculationData[num8].GCodesItem[Item.CalculationData[num8].GCodesItem.Count - 1].ToString().Trim().Length <= 0)
			{
				if (Item.CalculationData[num8].GCodesItem[Item.CalculationData[num8].GCodesItem.Count - 2].ToString().Trim().Length > 0)
				{
					buString5.ReadCharValue(Item.CalculationData[num8].GCodesItem[Item.CalculationData[num8].GCodesItem.Count - 2].ToString(), "N", ref Value);
					buProfileCalc.varTemps.LastGCodeLine = (int)Value;
				}
			}
			else
			{
				buString5.ReadCharValue(Item.CalculationData[num8].GCodesItem[Item.CalculationData[num8].GCodesItem.Count - 1].ToString(), "N", ref Value);
				buProfileCalc.varTemps.LastGCodeLine = (int)Value;
			}
			if (GCodeStr.Length <= 0)
			{
				GCodeStr = buString5.StringListToString(Item.CalculationData[num8].GCodesItem, NewLineEnable: true);
			}
			else
			{
				GCodeStr = GCodeStr + Environment.NewLine + buString5.StringListToString(Item.CalculationData[num8].GCodesItem, NewLineEnable: true);
			}
		}
		if (clsItem.FrmProgress != null)
		{
			clsItem.FrmProgress.Visible = false;
		}
	}

	public void doCalculateCamPointsKabanMode2(ref camTp C, ref buEyeBaseVer5.Apps.ProfileItem Item, ref GProfileOperation OP, ref TpPnt9D lastCamP9, int i, int y, bool ToolMilling, double ZParkPosAfterKinematic, bool CreateGCode)
	{
		if (!ToolMilling)
		{
			for (int j = 0; j <= C.CamPoints.Count - 1; j++)
			{
				for (int k = 0; k <= C.CamPoints[j].Points.Count - 1; k++)
				{
					if ((Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Side) | (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Length))
					{
						Pnt9D pnt9D = new Pnt9D(C.CamPoints[j].Points[k].P9);
						double num = ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength;
						pnt9D.Z += num;
						C.CamPoints[j].Points[k].PlungeAxis = "X";
						C.CamPoints[j].Points[k].P9 = new Pnt9D(pnt9D);
					}
					if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Vertical)
					{
						Pnt9D pnt9D2 = new Pnt9D(C.CamPoints[j].Points[k].P9);
						if ((Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front) | (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back))
						{
							double num2 = (ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength) * Math.Sin(buConversion5.DegreeToRadian(pnt9D2.A));
							pnt9D2.Y -= num2;
							C.CamPoints[j].Points[k].PlungeAxis = "X";
						}
						if (k == C.CamPoints[j].Points.Count - 1)
						{
							pnt9D2.Z = ZParkPosAfterKinematic;
						}
						C.CamPoints[j].Points[k].P9 = new Pnt9D(pnt9D2);
					}
					if (Item.CalculationData[y].calcOperations[i].OperationData.NotchData.NotchOPType == ProfileNotchOperationType.Horizontal)
					{
						Pnt9D pnt9D3 = new Pnt9D(C.CamPoints[j].Points[k].P9);
						double num3 = (ccVars.KinematicOrjinal.RotateCenterOffsetOfA.Z + C.Tool.Geometry.TotalLength) * Math.Sin(buConversion5.DegreeToRadian(pnt9D3.A));
						pnt9D3.Y -= num3;
						C.CamPoints[j].Points[k].PlungeAxis = "Z";
						C.CamPoints[j].Points[k].P9 = new Pnt9D(pnt9D3);
					}
				}
			}
		}
		else
		{
			for (int l = 0; l <= C.CamPoints.Count - 1; l++)
			{
				for (int m = 0; m <= C.CamPoints[l].Points.Count - 1; m++)
				{
					Pnt9D pnt9D4 = new Pnt9D(C.CamPoints[l].Points[m].P9);
					OrientationAngle orientation = new OrientationAngle(C.CamPoints[l].Points[m].P9.A, 0.0, 0.0);
					Point3D movePoint = new Point3D(C.CamPoints[l].Points[m].P9.X, C.CamPoints[l].Points[m].P9.Y, C.CamPoints[l].Points[m].P9.Z);
					Pnt6D CalcPoint = new Pnt6D();
					clsInit.cKinematic5.ForwardKinematix4Ax(C.Tool.Geometry.TotalLength, ccVars.KinematicOrjinal, VectorType.XVector, orientation, movePoint, ref CalcPoint);
					pnt9D4 = new Pnt9D(CalcPoint.X, CalcPoint.Y, CalcPoint.Z, CalcPoint.A, CalcPoint.B, CalcPoint.C);
					if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Top)
					{
						C.CamPoints[l].Points[m].PostOffsets.Z = 0.0 - Item.ProfileMaxPoint.Z;
						if (l == 0 && m == 0)
						{
							C.CamPoints[l].PreCodes.Add("G68.2 P1 X0 Y0 Z" + Item.ProfileMaxPoint.Z + " I0 J0 K0                 (side transformation on)");
							C.CamPoints[l].PreCodes.Add("#800=0");
							C.CamPoints[l].PreCodes.Add("#801=0");
							C.CamPoints[l].PreCodes.Add("#802=" + Item.ProfileMaxPoint.Z.ToString("f2"));
							C.CamPoints[l].PreCodes.Add("#803=0");
							C.CamPoints[l].PreCodes.Add("#804=0");
							C.CamPoints[l].PreCodes.Add("#805=0");
							C.CamPoints[l].PreCodes.Add("G53.1 P2");
							C.CamPoints[l].PreCodes.Add("806=2");
							C.CamPoints[l].PreCodes.Add("G43 H1");
							C.CamPoints[l].PreCodes.Add("#807=1");
						}
						C.CamPoints[l].Points[m].PlungeAxis = "Z";
					}
					if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Front)
					{
						C.CamPoints[l].Points[m].PostOffsets.Z = Item.ProfileMaxPoint.Z;
						C.CamPoints[l].Points[m].YChar = "Z";
						C.CamPoints[l].Points[m].ZChar = "Y";
						if (l == 0 && m == 0)
						{
							C.CamPoints[l].PreCodes.Add("G68.2 P1 X0 Y0 Z" + Item.ProfileMaxPoint.Z + " I90 J0 K0                 (side transformation on)");
							C.CamPoints[l].PreCodes.Add("#800=0");
							C.CamPoints[l].PreCodes.Add("#801=0");
							C.CamPoints[l].PreCodes.Add("#802=" + Item.ProfileMaxPoint.Z.ToString("f2"));
							C.CamPoints[l].PreCodes.Add("#803=90");
							C.CamPoints[l].PreCodes.Add("#804=0");
							C.CamPoints[l].PreCodes.Add("#805=0");
							C.CamPoints[l].PreCodes.Add("G53.1 P2");
							C.CamPoints[l].PreCodes.Add("806=2");
							C.CamPoints[l].PreCodes.Add("G43 H1");
							C.CamPoints[l].PreCodes.Add("#807=1");
						}
						C.CamPoints[l].Points[m].PlungeAxis = "Y";
					}
					if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Back)
					{
						C.CamPoints[l].Points[m].PostOffsets.Z = Item.ProfileMaxPoint.Z;
						C.CamPoints[l].Points[m].YChar = "Z";
						C.CamPoints[l].Points[m].ZChar = "Y";
						if (l == 0 && m == 0)
						{
							C.CamPoints[l].PreCodes.Add("G68.2 P1 X0 Y0 Z" + Item.ProfileMaxPoint.Z + " I-90 J0 K0                 (side transformation on)");
							C.CamPoints[l].PreCodes.Add("#800=0");
							C.CamPoints[l].PreCodes.Add("#801=0");
							C.CamPoints[l].PreCodes.Add("#802=" + Item.ProfileMaxPoint.Z.ToString("f2"));
							C.CamPoints[l].PreCodes.Add("#803=-90");
							C.CamPoints[l].PreCodes.Add("#804=0");
							C.CamPoints[l].PreCodes.Add("#805=0");
							C.CamPoints[l].PreCodes.Add("G53.1 P2");
							C.CamPoints[l].PreCodes.Add("806=2");
							C.CamPoints[l].PreCodes.Add("G43 H1");
							C.CamPoints[l].PreCodes.Add("#807=1");
						}
						C.CamPoints[l].Points[m].PlungeAxis = "Y";
					}
					if (Item.CalculationData[y].calcOperations[i].OperationData.selectedPlaneName == planeNames.Free)
					{
						C.CamPoints[l].Points[m].PlungeAxis = "";
					}
					if (OP.OperationData.OperationType == ProfileOperationTypes.Tapping && C.CamPoints[l].Points[m].PlungeAxisMovement)
					{
						C.CamPoints[l].Points[m].Type = 0;
						double num4 = OP.OperationData.HoleData.TappingDepth;
						if (OP.OperationData.selectedPlaneName == planeNames.Top && m > 0)
						{
							num4 = C.CamPoints[l].Points[m - 1].P9.Z - pnt9D4.Z;
						}
						if (((OP.OperationData.selectedPlaneName == planeNames.Front) | (OP.OperationData.selectedPlaneName == planeNames.Back)) && m > 0)
						{
							num4 = Math.Abs(C.CamPoints[l].Points[m - 1].P9.Y - pnt9D4.Y);
						}
						C.CamPoints[l].Points[m].OverWriteString = "M80 X" + OP.OperationData.HoleData.TappingPitch.ToString("f2") + " Y" + (0.0 - num4).ToString("f2") + " Z" + OP.Tool.CamData.SpindleSpeed.ToString("");
					}
					C.CamPoints[l].Points[m].P9 = new Pnt9D(pnt9D4);
					if ((l == C.CamPoints.Count - 1) & (m == C.CamPoints[l].Points.Count - 1))
					{
						C.CamPoints[l].Points[m].PreCodes.Add("G90");
						C.CamPoints[l].Points[m].PreCodes.Add("G69");
						C.CamPoints[l].Points[m].PreCodes.Add("G05 P0");
						C.CamPoints[l].Points[m].PreCodes.Add("G49");
					}
				}
			}
			lastCamP9 = C.CamPoints[C.CamPoints.Count - 1].Points[C.CamPoints[C.CamPoints.Count - 1].Points.Count - 1];
		}
		if (Item.CalculationData[y].XReferanceLocation == LeftRightType.Right && CreateGCode)
		{
			for (int n = 0; n <= C.CamPoints.Count - 1; n++)
			{
				for (int num5 = 0; num5 <= C.CamPoints[n].Points.Count - 1; num5++)
				{
					Pnt9D p = C.CamPoints[n].Points[num5].P9;
					if (!buProfileCalc.varProfileSettings.RightProfileMakeAsMirror)
					{
						p.X = buProfileCalc.varProfileSettings.MachineLength - Item.CalculationData[y].Length + p.X;
					}
					else
					{
						p.X -= Item.CalculationData[y].Length;
					}
					if (!buProfileCalc.varProfileSettings.ChangeG2G3DirForRightRefProfile)
					{
						continue;
					}
					if (C.CamPoints[n].Points[num5].Type != 2)
					{
						if (C.CamPoints[n].Points[num5].Type == 3)
						{
							C.CamPoints[n].Points[num5].Type = 2;
						}
					}
					else
					{
						C.CamPoints[n].Points[num5].Type = 3;
					}
				}
			}
		}
		if (Item.CalculationData[y].XReferanceLocation == LeftRightType.Left && CreateGCode)
		{
			for (int num6 = 0; num6 <= C.CamPoints.Count - 1; num6++)
			{
				for (int num7 = 0; num7 <= C.CamPoints[num6].Points.Count - 1; num7++)
				{
					_ = C.CamPoints[num6].Points[num7].P9;
					if (!buProfileCalc.varProfileSettings.ChangeG2G3DirForLeftRefProfile)
					{
						continue;
					}
					if (C.CamPoints[num6].Points[num7].Type != 2)
					{
						if (C.CamPoints[num6].Points[num7].Type == 3)
						{
							C.CamPoints[num6].Points[num7].Type = 2;
						}
					}
					else
					{
						C.CamPoints[num6].Points[num7].Type = 3;
					}
				}
			}
		}
		Item.CalculationData[y].Cams.Add(C);
	}

	public void doSaveGcodeKabanMode2(bool ShowCode)
	{
		try
		{
			if (!clsVar.appModes_0.DemoMode)
			{
				if (ccVars.Pages.Count > 0)
				{
					if (!((activeProfile.FirstItem == null) & (activeProfile.SecondItem == null)))
					{
						if (!(!activeProfile.isSimulationDone & (AppSecurity.PasswordLevel == 0)))
						{
							bool flag = false;
							bool flag2 = false;
							if (activeProfile.FirstItem != null && activeProfile.FirstItem.Enable && activeProfile.FirstItem.Operations.Count > 0)
							{
								flag = true;
							}
							if (activeProfile.SecondItem != null && activeProfile.SecondItem.Enable && activeProfile.SecondItem.Operations.Count > 0)
							{
								flag2 = true;
							}
							if (!flag || !activeProfile.FirstItem.isError)
							{
								if (!flag2 || !activeProfile.SecondItem.isError)
								{
									SaveFileDialog saveFileDialog = new SaveFileDialog();
									saveFileDialog.InitialDirectory = clsVar.varInterface.pathGCode;
									saveFileDialog.Filter = ccVars.PostActive.FileExplanation + " (" + ccVars.PostActive.FileExtension + ")|" + ccVars.PostActive.FileExtension;
									saveFileDialog.FilterIndex = 1;
									DialogResult dialogResult = DialogResult.None;
									if (!ShowCode)
									{
										dialogResult = saveFileDialog.ShowDialog();
									}
									if (dialogResult == DialogResult.OK || ShowCode)
									{
										string fileName = buFile5.GetPath(saveFileDialog.FileName) + "\\" + buFile5.getFileNameWithoutExtension(saveFileDialog.FileName) + ".stl";
										if (buProfileCalc.varProfileSettings.SaveStlFileWhileCreatingCode)
										{
											buFile5.SaveStl(ccVars.Pages[ccVars.PageIndex].Form.viewportcad, fileName);
										}
										if (buProfileCalc.varProfileSettings.SaveImageFileWhileCreatingCode)
										{
											string filePath = buFile5.GetPath(saveFileDialog.FileName) + "\\" + buFile5.getFileNameWithoutExtension(saveFileDialog.FileName) + ".png";
											ccVars.Pages[ccVars.PageIndex].Form.viewportcad.WriteToFileRaster((float)buProfileCalc.varProfileSettings.ImageScaleFactor, filePath, ImageFormat.Png);
										}
										ArrayList GCodes = new ArrayList();
										ArrayList GCodes2 = new ArrayList();
										int num = 0;
										buProfileCalc.varTemps.LastGCodeLine = 0;
										ccVars.PostActive.NumberDef.Start = 10.0;
										ProfileTempVars.LastClampers.Clear();
										if (flag)
										{
											doCreateCode(activeProfile.FirstItem, ccVars.PostActive.Mode, ref GCodes, 0, flag2, CreateGCode: true, ShowCode);
											num++;
										}
										if (flag2)
										{
											doCreateCode(activeProfile.SecondItem, ccVars.PostActive.Mode, ref GCodes2, 1, SecondAvailable: false, CreateGCode: true, ShowCode);
										}
										if (!(flag && flag2))
										{
											GCodes.AddRange(GCodes2);
										}
										else
										{
											ArrayList CalcList = new ArrayList();
											ArrayList CalcList2 = new ArrayList();
											ArrayList CalcList3 = new ArrayList();
											ArrayList CalcList4 = new ArrayList();
											buString5.ListToSpecificList("<GCodes>", "</GCodes>", AddStartEndKey: false, GCodes, ref CalcList);
											buString5.ListToSpecificList("<GCodes>", "</GCodes>", AddStartEndKey: false, GCodes2, ref CalcList2);
											buString5.ListToSpecificList("<ProfileCode>", "</ProfileCode>", AddStartEndKey: false, GCodes, ref CalcList3);
											buString5.ListToSpecificList("<ProfileCode>", "</ProfileCode>", AddStartEndKey: false, GCodes2, ref CalcList4);
											GCodes.AddRange(GCodes2);
										}
										if (activeProfile.GCodes == null)
										{
											activeProfile.GCodes = new ArrayList();
										}
										activeProfile.GCodes.Clear();
										activeProfile.GCodes = buString5.Copy(GCodes);
										clsVar.varInterface.pathGCode = buFile5.GetPath(saveFileDialog.FileName);
										if (ShowCode)
										{
											F_Notepad f_Notepad = new F_Notepad();
											f_Notepad.Init(GCodes);
											f_Notepad.Show();
										}
										else
										{
											buFile5.SaveToFile(GCodes, saveFileDialog.FileName);
										}
										GCodes.Clear();
										clsFiles.SaveParameter();
									}
								}
								else
								{
									buString5.MessageBoxWarning(buLangTranslate.preDef.Second + " " + buLangTranslate.preDef.Profile + " " + buProfile.LangProfileMessage[14]);
								}
							}
							else
							{
								buString5.MessageBoxWarning(buLangTranslate.preDef.First + " " + buLangTranslate.preDef.Profile + " " + buProfile.LangProfileMessage[14]);
							}
						}
						else
						{
							buString5.MessageBoxWarning(buProfile.LangProfileMessage[13]);
						}
					}
					else
					{
						buString5.MessageBoxWarning(buProfile.LangProfileMessage[12]);
					}
				}
				else
				{
					buString5.MessageBoxWarning(AppLanguage.Messages[9]);
				}
			}
			else
			{
				MessageBox.Show(buLangTranslate.preSentences.NotAvailableDemoMode);
			}
		}
		catch (Exception mSException)
		{
			buLog.addLog("", "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: true, "");
		}
	}

	public void doAddInfoCodeKabanMode2(ref buEyeBaseVer5.Apps.ProfileItem Item, ref PostProcessor tempPost, int ProfileIndex, double ZParkPosAfterKinematic, bool AddToolInfo)
	{
		if (ProfileIndex == 0)
		{
			if (buProfileCalc.varProfileSettings.ShowSupportBlockInfoAtGCode)
			{
				clsInit.cProfile.InsertSupportBlockInfoToGCode(Item, 1, ref tempPost, "(", ")");
			}
			if (buProfileCalc.varProfileSettings.ShowProfileInfoAtGCode)
			{
				clsInit.cProfile.InsertProfileInfoToGCode(Item, 1, ref tempPost, "(", ")");
			}
			string text = "Left";
			if (!((activeProfile.FirstItem != null) & (activeProfile.SecondItem != null)))
			{
				if ((activeProfile.FirstItem == null) & (activeProfile.SecondItem != null))
				{
					text = "Right";
				}
			}
			else
			{
				text = "Left/Right";
			}
			tempPost.StartLines.Insert(1, "(Stoper Side = " + text + " )");
			tempPost.StartLines.Add("G0 Z" + ZParkPosAfterKinematic.ToString("f2"));
		}
		if (ProfileIndex == 1)
		{
			if (activeProfile.FirstItem == null)
			{
				string text2 = "Right";
				tempPost.StartLines.Insert(1, "(Stoper Side = " + text2 + " )");
				tempPost.StartLines.Add("G0 Z" + ZParkPosAfterKinematic.ToString("f2"));
			}
			else
			{
				tempPost.StartLines.Clear();
			}
			if (buProfileCalc.varProfileSettings.ShowSupportBlockInfoAtGCode)
			{
				clsInit.cProfile.InsertSupportBlockInfoToGCode(Item, 1, ref tempPost, "(", ")");
			}
			if (buProfileCalc.varProfileSettings.ShowProfileInfoAtGCode)
			{
				clsInit.cProfile.InsertProfileInfoToGCode(Item, 1, ref tempPost, "(", ")");
			}
			if (buProfileCalc.varTemps.LastGCodeLine > 0)
			{
				tempPost.NumberDef.Start = (double)buProfileCalc.varTemps.LastGCodeLine + tempPost.NumberDef.Step;
			}
		}
		if (!AddToolInfo)
		{
			return;
		}
		tempPost.StartLines.Insert(1, "#820=" + Item.Width.ToString("f2"));
		tempPost.StartLines.Insert(2, "#821=" + Item.Height.ToString("f2"));
		int num = 3;
		List<ToolBase5> list = new List<ToolBase5>();
		for (int i = 0; i <= Item.Operations.Count - 1; i++)
		{
			bool flag = false;
			if (Item.Operations[i].OperationData.OperationType == ProfileOperationTypes.Notch)
			{
				for (int j = 0; j <= ccVars.Tools[0].Tools.Count - 1; j++)
				{
					if (ccVars.Tools[0].Tools[j].Data.Name == Item.Operations[i].ToolNotch.Data.Name)
					{
						flag = true;
						j = ccVars.Tools[0].Tools.Count;
					}
				}
				if (flag)
				{
					if (list.Count != 0)
					{
						bool flag2 = false;
						for (int k = 0; k <= list.Count - 1; k++)
						{
							if (list[k].Data.Name == Item.Operations[i].Tool.Data.Name)
							{
								flag2 = true;
							}
						}
						if (!flag2)
						{
							list.Add(Item.Operations[i].Tool);
						}
					}
					else
					{
						list.Add(Item.Operations[i].Tool);
					}
				}
				flag = false;
			}
			for (int l = 0; l <= ccVars.Tools[0].Tools.Count - 1; l++)
			{
				if (ccVars.Tools[0].Tools[l].Data.Name == Item.Operations[i].Tool.Data.Name)
				{
					flag = true;
					l = ccVars.Tools[0].Tools.Count;
				}
			}
			if (!flag)
			{
				continue;
			}
			if (list.Count != 0)
			{
				bool flag3 = false;
				for (int m = 0; m <= list.Count - 1; m++)
				{
					if (list[m].Data.Name == Item.Operations[i].Tool.Data.Name)
					{
						flag3 = true;
					}
				}
				if (!flag3)
				{
					list.Add(Item.Operations[i].Tool);
				}
			}
			else
			{
				list.Add(Item.Operations[i].Tool);
			}
		}
		for (int n = 0; n <= list.Count - 1; n++)
		{
			if (list[n].Data.No > 0)
			{
				tempPost.StartLines.Insert(num, "#71" + list[n].Data.No + "=" + list[n].Geometry.TotalLength.ToString("f2"));
				num++;
			}
		}
		for (int num2 = 0; num2 <= list.Count - 1; num2++)
		{
			if (list[num2].Data.No > 0)
			{
				tempPost.StartLines.Insert(num, "#1600" + list[num2].Data.No + "=" + list[num2].Geometry.Diameter.ToString("f2"));
				num++;
			}
		}
		tempPost.StartLines.Insert(num, "G90 G59 G49 (delete tool length Hx correction and zero point)");
		num++;
		tempPost.StartLines.Insert(num, "G54 G91 G28 Z0(go_Z_max, G28 reference pos)");
		num++;
		tempPost.StartLines.Insert(num, "G90 G59");
		num++;
		tempPost.StartLines.Insert(num, "M153");
		num++;
	}

