								{
									pnt6DSimMove.A = Value6 - list[list.Count - 1].A;
								}
							}
							else
							{
								pnt6DSimMove.A = Settings.G53Positions.A;
							}
						}
					}
					if (text.ToLower().IndexOf("f") >= 0)
					{
						double Value7 = 0.0;
						if (buString5.ReadStringValue("F", text, ref Value7))
						{
							pnt6DSimMove.FeedRate = Value7;
						}
					}
				}
				if (((pnt6DSimMove.GCode == 2) | (pnt6DSimMove.GCode == 3)) && text.ToLower().IndexOf("r") >= 0)
				{
					double Value8 = 0.0;
					if (buString5.ReadStringValue("R", text, ref Value8))
					{
						pnt6DSimMove.R = Value8;
					}
				}
				if (!(flag4 || flag5 || flag6 || flag7 || flag8 || flag9 || flag3))
				{
					continue;
				}
				if (list.Count != 0)
				{
					if (buCompare5.EQ(list[list.Count - 1], pnt6DSimMove, 0.01))
					{
						continue;
					}
					Pnt6DSimMove pnt6DSimMove3 = new Pnt6DSimMove(pnt6DSimMove);
					pnt6DSimMove3.X = pnt6DSimMove.X + Settings.OffsetPositions.X;
					pnt6DSimMove3.Y = buProfileCalc.varProfileSettings.SimYAxisDirection * pnt6DSimMove.Y + Settings.OffsetPositions.Y;
					pnt6DSimMove3.Z = pnt6DSimMove.Z + Settings.OffsetPositions.Z;
					pnt6DSimMove3.A = buProfileCalc.varProfileSettings.SimAAxisDirection * pnt6DSimMove.A + Settings.OffsetPositions.A;
					pnt6DSimMove3.Aux1 = num4;
					pnt6DSimMove3.Aux2 = num5;
					pnt6DSimMove3.ToolName = pnt6DSimMove.ToolName;
					pnt6DSimMove3.ToolNo = pnt6DSimMove.ToolNo;
					if ((profileItemCalc.XReferanceLocation == LeftRightType.Right) & ((profileItemCalc.CalcType == ProfileExcType.LongSecondPart) | (profileItemCalc.CalcType == ProfileExcType.LongSecondBottom)))
					{
						double num7 = buProfileCalc.varProfileSettings.MachineLength - profileItemCalc.Length + pnt6DSimMove3.X;
						if (num7 > buProfileCalc.varProfileSettings.MachineLength)
						{
							pnt6DSimMove3.X -= num7 - buProfileCalc.varProfileSettings.MachineLength;
						}
					}
					pnt6DSimMove2 = new Pnt6DSimMove(pnt6DSimMove3);
					pnt6DSimMove2.Index = j + num3;
					list.Add(pnt6DSimMove2);
					pnt6DSimMove.Clampers = null;
				}
				else
				{
					pnt6DSimMove2 = new Pnt6DSimMove(pnt6DSimMove);
					pnt6DSimMove2.Index = j + num3;
					list.Add(pnt6DSimMove2);
					pnt6DSimMove = new Pnt6DSimMove(pnt6DSimMove);
					pnt6DSimMove.Clampers = null;
				}
			}
			if (!(profileItemCalc.XReferanceLocation == LeftRightType.Right && i > 0))
			{
			}
			doSimulationDevidedMoves(list, i, ref Item);
		}
	}

